const RECORDS = [{"id":"azimuth","name":"Azimuth reference mapping","kind":"tool","layer":"adjacent","categories":["clustering-annotation","integration"],"side":"neutral","tier":"standard","summary":"Maps query cells onto annotated Seurat references (PBMC, lung, kidney and others) by supervised PCA and anchors, returning labels at several levels with prediction and mapping scores","gain_source":"none","requires":["filtered-matrix","reference"],"caveats":"Labels and resolution are those of the reference; query-only states map to the nearest reference type, so the mapping score should be checked. No independent peer-reviewed benchmark found.","url":"https://azimuth.hubmapconsortium.org","repo_url":"https://github.com/satijalab/azimuth","language":"multiple","doi":"10.1016/j.cell.2021.04.048","pmid":"34062119","cite_title":"Integrated analysis of multimodal single-cell data.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cell.2021.04.048","publication_url":"https://doi.org/10.1016/j.cell.2021.04.048","publication_title":"Integrated analysis of multimodal single-cell data.","publication_venue":"Cell","citations":15447,"repo_stars":151,"repo_pushed":"2026-05-22","review":"21-concepts-preprocessing#azimuth","tags":["reference-mapping","seurat","web"],"site":"https://azimuth.hubmapconsortium.org"},{"id":"seurat-wnn","name":"Seurat weighted nearest neighbours (WNN)","kind":"method","layer":"adjacent","categories":["multimodal","clustering-annotation"],"side":"neutral","tier":"benchmarked-sota","summary":"Learns per-cell weights for each modality from how well it predicts its neighbours, and builds one weighted nearest-neighbour graph for joint clustering, UMAP and reference mapping of CITE-seq or multiome data","gain":"Hu 2024: Seurat, MOJITOO and scAI led vertical (same-cell) integration across 47 datasets (abstract); the Seurat run there was WNN (FindMultiModalNeighbors in Seurat 4.3.0.1 for RNA+ADT and RNA+ATAC, per the authors' code); Hao 2021 built a 211,000-cell, 228-antibody PBMC reference with it (self-reported)","gain_source":"independent","requires":["protein","filtered-matrix"],"caveats":"Modality weights reflect neighbourhood consistency, so a noisy, unnormalised ADT panel or ATAC with few fragments simply gets down-weighted rather than flagged","url":"https://satijalab.org/seurat/articles/weighted_nearest_neighbor_analysis","repo_url":"https://github.com/satijalab/seurat","language":"R","doi":"10.1016/j.cell.2021.04.048","pmid":"34062119","cite_title":"Integrated analysis of multimodal single-cell data.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cell.2021.04.048","publication_url":"https://doi.org/10.1016/j.cell.2021.04.048","publication_title":"Integrated analysis of multimodal single-cell data.","publication_venue":"Cell","citations":15447,"repo_stars":2807,"repo_pushed":"2026-10-23","benchmarks":["hu-2024-multiomics-benchmark"],"benchmark_refs":[{"id":"hu-2024-multiomics-benchmark","name":"Hu et al. 2024, multi-omics prediction and integration benchmark","url":"https://doi.org/10.1038/s41592-024-02429-w"}],"review":"22-concepts-downstream#seurat-wnn","tags":["cite-seq","multiome","seurat"],"site":"https://satijalab.org/seurat/articles/weighted_nearest_neighbor_analysis"},{"id":"seurat-integration","name":"Seurat anchor integration (CCA and RPCA)","kind":"tool","layer":"adjacent","categories":["integration","clustering-annotation"],"side":"subtractive","tier":"benchmarked-sota","summary":"Identifies anchor pairs of mutual nearest neighbours in a shared canonical correlation (or reciprocal PCA) space and uses them to correct expression or transfer labels between datasets","gain":"Tran 2020: Seurat 3 among the three recommended methods of 14 (with Harmony and LIGER)","gain_source":"independent","requires":["filtered-matrix"],"caveats":"scIB ranked Seurat v3 CCA and RPCA below scANVI, Scanorama, scVI and scGen on atlas tasks; the same anchor framework underlies Azimuth label transfer.","url":"https://satijalab.org/seurat/articles/integration_introduction","repo_url":"https://github.com/satijalab/seurat","language":"R","doi":"10.1016/j.cell.2019.05.031","pmid":"31178118","cite_title":"Comprehensive Integration of Single-Cell Data.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cell.2019.05.031","publication_url":"https://doi.org/10.1016/j.cell.2019.05.031","publication_title":"Comprehensive Integration of Single-Cell Data.","publication_venue":"Cell","citations":15402,"repo_stars":2807,"repo_pushed":"2026-10-23","benchmarks":["tran-2020-batch-benchmark","luecken-2022-scib-benchmark"],"benchmark_refs":[{"id":"tran-2020-batch-benchmark","name":"Tran et al. 2020, batch-effect correction benchmark","url":"https://doi.org/10.1186/s13059-019-1850-9"},{"id":"luecken-2022-scib-benchmark","name":"Luecken et al. 2022 (scIB), atlas-level integration benchmark","url":"https://doi.org/10.1038/s41592-021-01336-8"}],"review":"21-concepts-preprocessing#seurat-integration","tags":["seurat","anchors","cca"],"site":"https://satijalab.org/seurat/articles/integration_introduction"},{"id":"empirical-bayes-moderation","name":"Empirical Bayes moderation (limma, edgeR QL, DESeq2/apeglm)","kind":"method","layer":"core","categories":["low-cell-stats","de-pseudobulk"],"side":"additive","tier":"standard","summary":"Shrink gene-wise variances, dispersions or fold changes toward a trend estimated across all genes, so tests with 2-3 replicates borrow residual degrees of freedom from the whole transcriptome","recovers":"Stable variance and effect estimates when each condition has very few replicates","gain_source":"none","requires":["replicates"],"caveats":"Borrows across genes, not across conditions or drugs; assumes most genes follow a shared variance trend. It cannot create replication: with zero residual degrees of freedom there is nothing to moderate. edgeR v4 revised the quasi-likelihood treatment for small counts, relevant to pseudobulks of few cells.","url":"https://bioconductor.org/packages/limma","language":"R","doi":"10.2202/1544-6115.1027","pmid":"16646809","cite_title":"Linear models and empirical bayes methods for assessing differential expression in microarray experiments.","year":"2004","verified":true,"citation_check":"verified","publication":"doi:10.2202/1544-6115.1027","publication_url":"https://doi.org/10.2202/1544-6115.1027","publication_title":"Linear models and empirical bayes methods for assessing differential expression in microarray experiments.","publication_venue":"Statistical Applications in Genetics and Molecular Biology","citations":11827,"citations_total":55079,"citations_papers":4,"review":"03-low-cell-stats#empirical-bayes-moderation","tags":["shrinkage","limma","edgeR","DESeq2"],"site":"https://bioconductor.org/packages/limma"},{"id":"harmony","name":"Harmony","kind":"tool","layer":"adjacent","categories":["integration"],"side":"subtractive","tier":"benchmarked-sota","summary":"Iteratively clusters cells in PCA space and applies cluster-specific linear corrections that maximise batch diversity within clusters, returning a corrected embedding","gain":"Tran 2020: recommended first among 14 methods (with LIGER and Seurat 3) for its accuracy and much shorter runtime; scIB: among the best four on the human immune task and effective on scATAC-seq","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Returns an embedding, not corrected counts; scIB found it weaker than scANVI, Scanorama and scVI on complex atlas tasks.","url":"https://portals.broadinstitute.org/harmony","repo_url":"https://github.com/immunogenomics/harmony","language":"multiple","doi":"10.1038/s41592-019-0619-0","pmid":"31740819","cite_title":"Fast, sensitive and accurate integration of single-cell data with Harmony.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-019-0619-0","publication_url":"https://doi.org/10.1038/s41592-019-0619-0","publication_title":"Fast, sensitive and accurate integration of single-cell data with Harmony.","publication_venue":"Nature Methods","citations":10417,"repo_stars":676,"repo_pushed":"2026-10-15","benchmarks":["tran-2020-batch-benchmark","luecken-2022-scib-benchmark"],"benchmark_refs":[{"id":"tran-2020-batch-benchmark","name":"Tran et al. 2020, batch-effect correction benchmark","url":"https://doi.org/10.1186/s13059-019-1850-9"},{"id":"luecken-2022-scib-benchmark","name":"Luecken et al. 2022 (scIB), atlas-level integration benchmark","url":"https://doi.org/10.1038/s41592-021-01336-8"}],"review":"21-concepts-preprocessing#harmony","tags":["embedding","linear"],"site":"https://portals.broadinstitute.org/harmony"},{"id":"lisi","name":"LISI (local inverse Simpson's index)","kind":"tool","layer":"core","categories":["batch-and-plate-effects","integration"],"side":"neutral","tier":"standard","summary":"Effective number of batches (iLISI) or cell types (cLISI) in each cell's neighbourhood, introduced with Harmony","gain_source":"none","requires":["filtered-matrix"],"caveats":"Like kBET, cannot tell batch effect from batch-specific cell types without labels; one of the scIB metrics.","url":"https://github.com/immunogenomics/LISI","repo_url":"https://github.com/immunogenomics/LISI","language":"R","doi":"10.1038/s41592-019-0619-0","pmid":"31740819","cite_title":"Fast, sensitive and accurate integration of single-cell data with Harmony","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-019-0619-0","publication_url":"https://doi.org/10.1038/s41592-019-0619-0","publication_title":"Fast, sensitive and accurate integration of single-cell data with Harmony","publication_venue":"Nature Methods","citations":10417,"repo_stars":82,"repo_pushed":"2021-09-02","review":"12-doublets-stress-batch#lisi","tags":["metric","diagnostic","harmony"]},{"id":"cellranger","name":"Cell Ranger (cellranger count / multi)","kind":"tool","layer":"core","categories":["alignment-quantification","cell-calling"],"side":"neutral","tier":"standard","summary":"10x Genomics pipeline that aligns reads with STAR, corrects barcodes and UMIs against the kit whitelist, counts UMIs per gene and calls cells, producing the raw and filtered matrices most 10x analyses start from","recovers":"a reproducible, vendor-supported count matrix; low-RNA cells through its EmptyDrops-style second calling step","gain":"You 2021 (10 workflows, mixtures with known labels): performance \"consistently high and relatively stable\", among the top 3 on one downstream ranking; Bruning 2022: gene sets similar to STARsolo and alevin-fry","gain_source":"independent","requires":["fastq"],"caveats":"Slowest of the common pipelines (STARsolo, alevin and kallisto >= 3x faster, kallisto 4-6x, Bruning 2022). Counts only sense reads confidently assigned to one gene, so gene-ambiguous reads are dropped. Calls cells by an order-of-magnitude UMI cut (m/10 of the 99th percentile of the expected top barcodes) followed by EmptyDrops for low-RNA barcodes, with a bounded candidate set (see [[emptydrops]]). Intronic reads counted by default from v7.0, which changes counts and calls compared with earlier versions. Outside human and mouse its extra cells were mostly low quality (Shainer 2021).","url":"https://www.10xgenomics.com/support/software/cell-ranger","repo_url":"https://github.com/10XGenomics/cellranger","language":"multiple","doi":"10.1038/ncomms14049","pmid":"28091601","cite_title":"Massively parallel digital transcriptional profiling of single cells","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1038/ncomms14049","publication_url":"https://doi.org/10.1038/ncomms14049","publication_title":"Massively parallel digital transcriptional profiling of single cells","publication_venue":"Nature Communications","citations":7329,"citations_total":7459,"citations_papers":4,"repo_stars":481,"repo_pushed":"2026-08-17","benchmarks":["bruning-2022-aligner-benchmark","you-2021-preprocessing-benchmark","shainer-2021-kallisto-cellranger"],"benchmark_refs":[{"id":"bruning-2022-aligner-benchmark","name":"Brüning et al. 2022, single-cell aligner comparison","url":"https://doi.org/10.1093/gigascience/giac001"},{"id":"you-2021-preprocessing-benchmark","name":"You et al. 2021, UMI preprocessing workflow benchmark","url":"https://doi.org/10.1186/s13059-021-02552-3"},{"id":"shainer-2021-kallisto-cellranger","name":"Shainer & Stemmer 2021, kallisto versus Cell Ranger across organisms","url":"https://doi.org/10.1186/s12864-021-07930-6"}],"review":"11-quant-calling-ambient#cellranger","tags":["10x","droplet","best-practice","nuclei"],"site":"https://www.10xgenomics.com/support/software/cell-ranger"},{"id":"leiden","name":"Leiden community detection","kind":"tool","layer":"adjacent","categories":["clustering-annotation"],"side":"neutral","tier":"standard","summary":"Graph community detection that refines Louvain partitions so every community is guaranteed to be internally connected; the default clustering on the kNN graph in scanpy and an option in Seurat","gain":"In the authors' tests up to 25% of Louvain communities were badly connected and up to 16% disconnected; Leiden guarantees connected communities and ran faster (self-reported, benchmark and real-world networks, not single-cell data)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Resolution sets the number of clusters; no independent single-cell benchmark of Leiden against Louvain was found.","url":"https://leidenalg.readthedocs.io","repo_url":"https://github.com/vtraag/leidenalg","language":"Python","doi":"10.1038/s41598-019-41695-z","pmid":"30914743","cite_title":"From Louvain to Leiden: guaranteeing well-connected communities.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41598-019-41695-z","publication_url":"https://doi.org/10.1038/s41598-019-41695-z","publication_title":"From Louvain to Leiden: guaranteeing well-connected communities.","publication_venue":"Scientific Reports","citations":5604,"repo_stars":802,"repo_pushed":"2026-10-19","review":"21-concepts-preprocessing#leiden","tags":["graph-clustering","scanpy"],"site":"https://leidenalg.readthedocs.io"},{"id":"singler","name":"SingleR","kind":"tool","layer":"adjacent","categories":["clustering-annotation"],"side":"neutral","tier":"benchmarked","summary":"Labels each cell by Spearman correlation with bulk or single-cell reference profiles over marker genes, iteratively fine-tuning among the top-scoring labels","gain":"Abdelaal 2019: among the top five of 22 classifiers at the deeper brain annotation and in unaligned pancreas inter-dataset tests, with almost no unlabelled cells; SVM was best overall","gain_source":"independent","requires":["filtered-matrix","reference"],"caveats":"No rejection option in the version tested; slowest method in Abdelaal 2019 (over 39 h on Zheng 68K with SingleR 0.2.2; the later Bioconductor reimplementation is much faster).","url":"https://bioconductor.org/packages/SingleR","repo_url":"https://github.com/LTLA/SingleR","language":"R","doi":"10.1038/s41590-018-0276-y","pmid":"30643263","cite_title":"Reference-based analysis of lung single-cell sequencing reveals a transitional profibrotic macrophage.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41590-018-0276-y","publication_url":"https://doi.org/10.1038/s41590-018-0276-y","publication_title":"Reference-based analysis of lung single-cell sequencing reveals a transitional profibrotic macrophage.","publication_venue":"Nature Immunology","citations":4963,"repo_stars":205,"repo_pushed":"2026-09-10","benchmarks":["abdelaal-2019-annotation-benchmark"],"benchmark_refs":[{"id":"abdelaal-2019-annotation-benchmark","name":"Abdelaal et al. 2019, automatic cell identification benchmark","url":"https://doi.org/10.1186/s13059-019-1795-z"}],"review":"21-concepts-preprocessing#singler","tags":["reference","correlation","bioconductor"],"site":"https://bioconductor.org/packages/SingleR"},{"id":"seurat-cell-cycle-scoring","name":"Seurat CellCycleScoring / scanpy score_genes_cell_cycle","kind":"method","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"standard","summary":"Scores S and G2/M marker sets (Tirosh 2016 lists) against control genes and assigns each cell to G1, S or G2M by the larger score; the default in Seurat and scanpy tutorials","gain":"Guo & Chen 2024: no method consistently best across four datasets with experimental phase labels; marker-gene scoring accurate only when the marker list suits the data","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Always assigns every cell to a phase, so non-cycling cells are forced into G1, S or G2M (Guo & Chen 2024); CycleMix authors report it labels mature neurons as cycling on droplet data; human gene lists need conversion for mouse.","url":"https://satijalab.org/seurat/articles/cell_cycle_vignette.html","repo_url":"https://github.com/satijalab/seurat","language":"multiple","doi":"10.1126/science.aad0501","pmid":"27124452","cite_title":"Dissecting the multicellular ecosystem of metastatic melanoma by single-cell RNA-seq","year":"2016","verified":true,"citation_check":"verified","publication":"doi:10.1126/science.aad0501","publication_url":"https://doi.org/10.1126/science.aad0501","publication_title":"Dissecting the multicellular ecosystem of metastatic melanoma by single-cell RNA-seq","publication_venue":"Science","citations":4926,"citations_total":18068,"citations_papers":3,"repo_stars":2807,"repo_pushed":"2026-10-23","benchmarks":["guo-2024-cell-cycle-comparison"],"benchmark_refs":[{"id":"guo-2024-cell-cycle-comparison","name":"Guo and Chen 2024, cell-cycle phase identification comparison","url":"https://doi.org/10.1093/bib/bbad517"}],"review":"12-doublets-stress-batch#seurat-cell-cycle-scoring","tags":["seurat","scanpy","marker-genes"],"site":"https://satijalab.org/seurat/articles/cell_cycle_vignette.html"},{"id":"doubletfinder","name":"DoubletFinder","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked-sota","summary":"Scores each cell by the fraction of artificial doublets (averaged random cell pairs) among its nearest neighbours in PC space, with a parameter sweep (pK) chosen from the data","recovers":"cleaner clusters and DE results; singlets otherwise lost to a high-UMI cap","gain":"Xi & Li 2021: highest mean AUPRC (0.537) on 16 real datasets with annotated doublets, top method on the most datasets and across simulated settings, among the most robust at removing spurious clusters; Ttoouli 2025: among the top three by clustering quality after removal","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Slower than cxds or Scrublet and less stable across subsamples (Xi & Li 2021); misclassified more singlets than scds, scDblFinder or Scrublet in pooled PBMC data (Demuxafy 2024); mean AUPRC 0.13-0.34 for all detectors on lineage-barcoded cell-line data (singletCode 2024); targets heterotypic doublets and needs the expected doublet rate as input.","url":"https://github.com/chris-mcginnis-ucsf/DoubletFinder","repo_url":"https://github.com/chris-mcginnis-ucsf/DoubletFinder","language":"R","doi":"10.1016/j.cels.2019.03.003","pmid":"30954475","cite_title":"DoubletFinder: Doublet Detection in Single-Cell RNA Sequencing Data Using Artificial Nearest Neighbors","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2019.03.003","publication_url":"https://doi.org/10.1016/j.cels.2019.03.003","publication_title":"DoubletFinder: Doublet Detection in Single-Cell RNA Sequencing Data Using Artificial Nearest Neighbors","publication_venue":"Cell Systems","citations":4486,"repo_stars":574,"repo_pushed":"2025-03-21","benchmarks":["xi-li-2021-doublet-benchmark","xi-li-2021-doublet-protocol","neavin-2024-demuxafy-benchmark","zhang-2024-singletcode","ttoouli-2025-multiplets"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"xi-li-2021-doublet-protocol","name":"Xi and Li 2021, doublet-detection benchmark protocol (scDblFinder added)","url":"https://doi.org/10.1016/j.xpro.2021.100699"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"zhang-2024-singletcode","name":"Zhang et al. 2024 (singletCode), doublet detectors on barcoded ground truth","url":"https://doi.org/10.1016/j.xgen.2024.100592"},{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"}],"review":"12-doublets-stress-batch#doubletfinder","tags":["seurat","artificial-doublets","knn"]},{"id":"sci-rna-seq3","name":"sci-RNA-seq3","kind":"design","layer":"core","categories":["demux-combinatorial"],"side":"additive","tier":"published-unbenchmarked","summary":"Three-level single-cell combinatorial indexing of fixed nuclei (reverse-transcription, ligation and PCR barcodes) that scales exponentially with plate size","recovers":"cells per experiment at a reagent cost near one cent per cell; reverse-transcription wells act as sample barcodes","gain":"About 2 million nuclei from 61 mouse embryos in one experiment (2019); optimised protocol (Martin 2023): reagent cost about 1 cent per cell or less, DSP/methanol fixation gives more UMIs than paraformaldehyde, and new buffers reduce nuclei loss during washes","gain_source":"self-reported","requires":["fastq"],"caveats":"Historically lower sensitivity than droplet kits; collision rate is set by nuclei per final well; nuclear input under-represents cytoplasmic transcripts; lab protocol that needs liquid handling and optimisation","doi":"10.1038/s41586-019-0969-x","pmid":"30787437","cite_title":"The single-cell transcriptional landscape of mammalian organogenesis","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41586-019-0969-x","publication_url":"https://doi.org/10.1038/s41586-019-0969-x","publication_title":"The single-cell transcriptional landscape of mammalian organogenesis","publication_venue":"Nature","citations":4465,"citations_total":4598,"citations_papers":2,"review":"04-screen-design#sci-rna-seq3","tags":["combinatorial-indexing","nuclei","fixed"]},{"id":"sctransform","name":"sctransform","kind":"tool","layer":"adjacent","categories":["normalisation","feature-selection"],"side":"neutral","tier":"benchmarked-sota","summary":"Regularised negative binomial regression of each gene on sequencing depth whose Pearson residuals replace log-normalised values and rank variable genes","gain":"pipeComp: best separability of subpopulations and the strongest removal of library-size and detection-rate effects among normalisations tested; Ahlmann-Eltze 2023: Pearson residuals as good as, not better than, the shifted log","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Lause 2021 showed the original model is overspecified and its per-gene overdispersion biased; v2 (Choudhary and Satija 2022) changed the overdispersion handling. Its residual-based regression of covariates such as mito fraction inherits pipeComp's finding that regressing out covariates hurt clustering.","url":"https://satijalab.org/seurat/articles/sctransform_vignette","repo_url":"https://github.com/satijalab/sctransform","language":"R","doi":"10.1186/s13059-019-1874-1","pmid":"31870423","cite_title":"Normalization and variance stabilization of single-cell RNA-seq data using regularized negative binomial regression.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1874-1","publication_url":"https://doi.org/10.1186/s13059-019-1874-1","publication_title":"Normalization and variance stabilization of single-cell RNA-seq data using regularized negative binomial regression.","publication_venue":"Genome biology","citations":4462,"citations_total":5094,"citations_papers":2,"repo_stars":272,"repo_pushed":"2026-01-10","benchmarks":["germain-2020-pipecomp","ahlmann-eltze-2023-transformation-benchmark","ge-2025-normalisation-benchmark"],"benchmark_refs":[{"id":"germain-2020-pipecomp","name":"Germain et al. 2020 (pipeComp), preprocessing pipeline benchmark","url":"https://doi.org/10.1186/s13059-020-02136-7"},{"id":"ahlmann-eltze-2023-transformation-benchmark","name":"Ahlmann-Eltze and Huber 2023, transformation benchmark","url":"https://doi.org/10.1038/s41592-023-01814-1"},{"id":"ge-2025-normalisation-benchmark","name":"Ge et al. 2025, normalisation benchmark","url":"https://doi.org/10.1371/journal.pone.0335102"}],"review":"21-concepts-preprocessing#sctransform","tags":["seurat","pearson-residuals"],"site":"https://satijalab.org/seurat/articles/sctransform_vignette"},{"id":"velocyto","name":"velocyto (RNA velocity)","kind":"tool","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"standard","summary":"Introduced RNA velocity: counts spliced and unspliced reads per gene and fits a steady-state model of splicing kinetics to predict each cell's future state","gain":"Wu 2026 recommended Velocyto among five methods balancing core performance and scalability; Luo 2026 found its agreement declined significantly in downsamples","gain_source":"independent","requires":["bam","spliced-unspliced"],"caveats":"The steady-state assumption fails for transient states (motivation for scVelo's dynamical model); results depend on how reads are assigned to spliced, unspliced and ambiguous (Soneson 2021)","url":"http://velocyto.org","repo_url":"https://github.com/velocyto-team/velocyto.py","language":"multiple","doi":"10.1038/s41586-018-0414-6","pmid":"30089906","cite_title":"RNA velocity of single cells.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41586-018-0414-6","publication_url":"https://doi.org/10.1038/s41586-018-0414-6","publication_title":"RNA velocity of single cells.","publication_venue":"Nature","citations":4097,"repo_stars":177,"repo_pushed":"2025-10-07","benchmarks":["wu-2026-velocity-benchmark","luo-2026-velocity-benchmark"],"benchmark_refs":[{"id":"wu-2026-velocity-benchmark","name":"Wu et al. 2026, RNA velocity benchmark (30 methods)","url":"https://doi.org/10.1186/s13059-026-04182-z"},{"id":"luo-2026-velocity-benchmark","name":"Luo et al. 2026, RNA velocity benchmark (15 methods, 17 datasets)","url":"https://doi.org/10.1016/j.crmeth.2026.101367"}],"review":"22-concepts-downstream#velocyto","tags":["rna-velocity"],"site":"http://velocyto.org"},{"id":"dose-response-modelling","name":"Dose-response modelling across doses","kind":"method","layer":"core","categories":["low-cell-stats","perturbation-models"],"side":"additive","tier":"published-unbenchmarked","summary":"Model each gene or program score as a function of dose (a log-dose term in a GLM, or sigmoid and benchmark-dose curves) so all doses of a drug inform one trend instead of being tested one at a time","recovers":"Power from doses that are individually underpowered; potency summaries (EC50-like) per drug","gain":"sci-Plex: generalized linear regression on dose found 6,238 genes with dose-dependent expression in at least one of three cell lines (FDR < 5%) at a median of 100-200 cells per condition","gain_source":"self-reported","requires":["doses-or-time","multiple-conditions"],"caveats":"A monotone or log-linear dose term misses non-monotone responses; TRADE found perturbations whose responses differ qualitatively across dose levels. Cell-level dose regression is still pseudoreplicated unless doses are crossed with replicate wells. Bulk comparison in sci-Plex showed weaker agreement for small effects. See [[sci-plex]].","url":"https://CRAN.R-project.org/package=drc","language":"R","doi":"10.1371/journal.pone.0146021","pmid":"26717316","cite_title":"Dose-Response Analysis Using R.","year":"2015","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pone.0146021","publication_url":"https://doi.org/10.1371/journal.pone.0146021","publication_title":"Dose-Response Analysis Using R.","publication_venue":"PLoS ONE","citations":3686,"citation_note":"1 listed paper(s) had no citation count","citations_total":4187,"citations_papers":3,"review":"03-low-cell-stats#dose-response-modelling","tags":["dose-response","drug-screen","sci-plex"],"site":"https://CRAN.R-project.org/package=drc"},{"id":"slingshot","name":"Slingshot","kind":"tool","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"benchmarked-sota","summary":"Infers branching lineages by fitting a minimum spanning tree over clusters and then simultaneous principal curves, returning one pseudotime per lineage","gain":"Saelens 2019: highest overall accuracy score of all evaluated methods (0.706, then PAGA Tree 0.695 and SCORPIUS 0.672) in the authors' results data from February 2019, two months before publication, where it was also first on the combined accuracy, scalability, stability and usability score; in the 29-method preprint it was the only method good across most trajectory types","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Works on a reduced dimension and a clustering supplied by the user, so cluster-level artefacts (doublet clusters, stress clusters) become lineage nodes; doublets created spurious branches in Xi and Li 2021. The Saelens rank is read from the authors' results file (github dynverse/dynbenchmark_results, 08-summary/results.rds) because the published text is paywalled","url":"https://bioconductor.org/packages/slingshot","repo_url":"https://github.com/kstreet13/slingshot","language":"R","doi":"10.1186/s12864-018-4772-0","pmid":"29914354","cite_title":"Slingshot: cell lineage and pseudotime inference for single-cell transcriptomics.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-018-4772-0","publication_url":"https://doi.org/10.1186/s12864-018-4772-0","publication_title":"Slingshot: cell lineage and pseudotime inference for single-cell transcriptomics.","publication_venue":"BMC Genomics","citations":3137,"repo_stars":348,"repo_pushed":"2024-04-23","benchmarks":["saelens-2019-ti-benchmark"],"benchmark_refs":[{"id":"saelens-2019-ti-benchmark","name":"Saelens et al. 2019, trajectory inference benchmark (dynverse)","url":"https://doi.org/10.1038/s41587-019-0071-9"}],"review":"22-concepts-downstream#slingshot","tags":["pseudotime","lineage"],"site":"https://bioconductor.org/packages/slingshot"},{"id":"scvelo","name":"scVelo","kind":"tool","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"standard","summary":"Python RNA velocity toolkit with steady-state, stochastic and likelihood-based dynamical models of splicing kinetics, plus latent time and velocity graphs; the scverse default for velocity","gain":"Wu 2026: scVelo (stochastic) among five methods recommended for core performance and scalability, while scVelo (dynamical) ranked 14th, below veloVI (8th); Luo 2026: scVelo-sto among methods recommended for million-cell atlases and among those with highest agreement","gain_source":"independent","requires":["spliced-unspliced"],"caveats":"Velocity estimates change with the spliced/unspliced quantification pipeline (Soneson 2021; Wu 2026 found only three of 22 methods robust to it); Bergen 2021 reviews its limitations and pitfalls","url":"https://scvelo.org","repo_url":"https://github.com/theislab/scvelo","language":"Python","doi":"10.1038/s41587-020-0591-3","pmid":"32747759","cite_title":"Generalizing RNA velocity to transient cell states through dynamical modeling.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-020-0591-3","publication_url":"https://doi.org/10.1038/s41587-020-0591-3","publication_title":"Generalizing RNA velocity to transient cell states through dynamical modeling.","publication_venue":"Nature Biotechnology","citations":2934,"citations_total":3205,"citations_papers":2,"repo_stars":513,"repo_pushed":"2026-02-25","benchmarks":["wu-2026-velocity-benchmark","luo-2026-velocity-benchmark"],"benchmark_refs":[{"id":"wu-2026-velocity-benchmark","name":"Wu et al. 2026, RNA velocity benchmark (30 methods)","url":"https://doi.org/10.1186/s13059-026-04182-z"},{"id":"luo-2026-velocity-benchmark","name":"Luo et al. 2026, RNA velocity benchmark (15 methods, 17 datasets)","url":"https://doi.org/10.1016/j.crmeth.2026.101367"}],"review":"22-concepts-downstream#scvelo","tags":["rna-velocity","scverse"],"site":"https://scvelo.org"},{"id":"scrublet","name":"Scrublet","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked-sota","summary":"Simulates doublets from the data and scores each barcode with a nearest-neighbour classifier, without needing clusters; the default doublet step in scanpy and many Python pipelines","recovers":"singlets that a high-UMI cap would discard; cleaner clusters","gain":"Ttoouli 2025 (hashing truth): most accurate tool by AUROC; Demuxafy 2024: with scDblFinder, classified the most doublets correctly in pools of 16 donors or fewer; Xi & Li 2021: strong in simulations and one of two methods whose HVGs beat the negative control at all doublet rates","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Threshold is set between two modes of the simulated score distribution, which are often not bimodal; among the detectors most affected by simulated ambient RNA (Demuxafy 2024); still missed most hashing multiplets (Ttoouli 2025).","url":"https://github.com/swolock/scrublet","repo_url":"https://github.com/swolock/scrublet","language":"Python","doi":"10.1016/j.cels.2018.11.005","pmid":"30954476","cite_title":"Scrublet: Computational Identification of Cell Doublets in Single-Cell Transcriptomic Data","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2018.11.005","publication_url":"https://doi.org/10.1016/j.cels.2018.11.005","publication_title":"Scrublet: Computational Identification of Cell Doublets in Single-Cell Transcriptomic Data","publication_venue":"Cell Systems","citations":2733,"repo_stars":184,"repo_pushed":"2020-12-29","benchmarks":["xi-li-2021-doublet-benchmark","xi-li-2021-doublet-protocol","neavin-2024-demuxafy-benchmark","zhang-2024-singletcode","ttoouli-2025-multiplets"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"xi-li-2021-doublet-protocol","name":"Xi and Li 2021, doublet-detection benchmark protocol (scDblFinder added)","url":"https://doi.org/10.1016/j.xpro.2021.100699"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"zhang-2024-singletcode","name":"Zhang et al. 2024 (singletCode), doublet detectors on barcoded ground truth","url":"https://doi.org/10.1016/j.xgen.2024.100592"},{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"}],"review":"12-doublets-stress-batch#scrublet","tags":["scanpy","artificial-doublets","knn"]},{"id":"scvi-tools","name":"scvi-tools (scVI, scANVI)","kind":"tool","layer":"adjacent","categories":["integration","clustering-annotation"],"side":"subtractive","tier":"benchmarked-sota","summary":"Variational autoencoders on raw counts with batch as a covariate (scVI), and a semi-supervised variant that uses cell labels (scANVI), giving a batch-corrected latent space and label transfer","gain":"scIB: scANVI, Scanorama, scVI and scGen performed best overall, especially on complex atlas tasks","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Primary paper is scVI (Lopez 2018) and scANVI (Xu 2021) is listed in papers, both independent of scIB. scIB shares an author (F. J. Theis) with the scvi-tools library paper (Gayoso 2022), not with the scVI paper it evaluated; Zappia 2025 shares him too. totalVI, from the same library, has its own record [[totalvi]]. Needs raw counts and benefits from a GPU.","url":"https://scvi-tools.org","repo_url":"https://github.com/scverse/scvi-tools","language":"Python","doi":"10.1038/s41592-018-0229-2","pmid":"30504886","cite_title":"Deep generative modeling for single-cell transcriptomics.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-018-0229-2","publication_url":"https://doi.org/10.1038/s41592-018-0229-2","publication_title":"Deep generative modeling for single-cell transcriptomics.","publication_venue":"Nature Methods","citations":2522,"citations_total":4023,"citations_papers":3,"repo_stars":1717,"repo_pushed":"2026-10-22","benchmarks":["luecken-2022-scib-benchmark"],"benchmark_refs":[{"id":"luecken-2022-scib-benchmark","name":"Luecken et al. 2022 (scIB), atlas-level integration benchmark","url":"https://doi.org/10.1038/s41592-021-01336-8"}],"review":"21-concepts-preprocessing#scvi-tools","tags":["deep-learning","gpu","label-transfer"],"site":"https://scvi-tools.org"},{"id":"fastmnn","name":"MNN correction and fastMNN (batchelor)","kind":"tool","layer":"adjacent","categories":["integration"],"side":"subtractive","tier":"benchmarked","summary":"Corrects batches by pairing mutual nearest neighbour cells across batches and subtracting locally estimated batch vectors, in expression space (MNN) or PCA space (fastMNN)","gain":"scIB: FastMNN embedding among the best four on the human immune task; MNN conserved cell-cycle variance well; not among the overall top methods in scIB or Tran 2020","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Assumes at least one shared population between batches; MNN in full expression space is slow, which fastMNN addresses.","url":"https://bioconductor.org/packages/batchelor","repo_url":"https://github.com/LTLA/batchelor","language":"R","doi":"10.1038/nbt.4091","pmid":"29608177","cite_title":"Batch effects in single-cell RNA-sequencing data are corrected by matching mutual nearest neighbors.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/nbt.4091","publication_url":"https://doi.org/10.1038/nbt.4091","publication_title":"Batch effects in single-cell RNA-sequencing data are corrected by matching mutual nearest neighbors.","publication_venue":"Nature Biotechnology","citations":2405,"repo_stars":19,"repo_pushed":"2026-04-09","benchmarks":["tran-2020-batch-benchmark","luecken-2022-scib-benchmark"],"benchmark_refs":[{"id":"tran-2020-batch-benchmark","name":"Tran et al. 2020, batch-effect correction benchmark","url":"https://doi.org/10.1186/s13059-019-1850-9"},{"id":"luecken-2022-scib-benchmark","name":"Luecken et al. 2022 (scIB), atlas-level integration benchmark","url":"https://doi.org/10.1038/s41592-021-01336-8"}],"review":"21-concepts-preprocessing#fastmnn","tags":["mnn","bioconductor"],"site":"https://bioconductor.org/packages/batchelor"},{"id":"luecken-theis-2019","name":"Luecken & Theis 2019 best-practice tutorial","kind":"evidence","layer":"core","categories":["qc-benchmarks"],"side":"neutral","tier":"standard","summary":"Tutorial and review that sets out a scRNA-seq workflow from QC to downstream analysis with recommendations drawn from independent comparison studies, applied to a public dataset","gain":"recommended permissive, per-sample QC thresholds judged jointly on counts, genes and mito, and revisiting QC after clustering","gain_source":"none","caveats":"Superseded for most steps by the 2023 scverse guide ([[heumos-2023]]); fixed example thresholds in the case study are often copied without the joint-inspection advice.","url":"https://github.com/theislab/single-cell-tutorial","repo_url":"https://github.com/theislab/single-cell-tutorial","doi":"10.15252/msb.20188746","pmid":"31217225","cite_title":"Current best practices in single-cell RNA-seq analysis: a tutorial","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.15252/msb.20188746","publication_url":"https://doi.org/10.15252/msb.20188746","publication_title":"Current best practices in single-cell RNA-seq analysis: a tutorial","publication_venue":"Molecular Systems Biology","citations":2221,"repo_stars":1597,"repo_pushed":"2022-12-11","review":"13-metrics-guides-multimodal#luecken-theis-2019","tags":["guide","best-practice","scanpy"]},{"id":"umi-tools","name":"UMI-tools","kind":"tool","layer":"core","categories":["alignment-quantification"],"side":"neutral","tier":"published-unbenchmarked","summary":"Barcode whitelisting, read tagging and network-based UMI deduplication that merges UMIs differing by sequencing errors, used inside many custom single-cell pipelines","recovers":"accurate molecule counts where UMI errors would otherwise inflate counts","gain":"network-based handling of UMI errors improved quantification accuracy on simulated data and on real iCLIP and scRNA-seq data, and improved scRNA-seq clustering (self-reported)","gain_source":"self-reported","requires":["bam"],"caveats":"Slow on large droplet datasets compared with integrated pipelines; its whitelist step is a knee on read counts, not a cell caller; not in any independent single-cell workflow benchmark found.","url":"https://umi-tools.readthedocs.io","repo_url":"https://github.com/CGATOxford/UMI-tools","language":"Python","doi":"10.1101/gr.209601.116","pmid":"28100584","cite_title":"UMI-tools: modeling sequencing errors in Unique Molecular Identifiers to improve quantification accuracy","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1101/gr.209601.116","publication_url":"https://doi.org/10.1101/gr.209601.116","publication_title":"UMI-tools: modeling sequencing errors in Unique Molecular Identifiers to improve quantification accuracy","publication_venue":"Genome Research","citations":2150,"repo_stars":549,"repo_pushed":"2026-10-04","review":"11-quant-calling-ambient#umi-tools","tags":["umi","plate"],"site":"https://umi-tools.readthedocs.io"},{"id":"mad-adaptive-qc","name":"MAD-based adaptive QC thresholds (scater/scuttle isOutlier, scanpy)","kind":"method","layer":"core","categories":["qc-metrics-thresholds"],"side":"both","tier":"standard","summary":"Flags cells whose log counts, log genes, top-gene share or mito fraction lie several median absolute deviations from the median of their batch, instead of using fixed cut-offs","recovers":"cells that fixed thresholds remove in samples or cell types with atypical baselines","gain":"pipeComp: most clustering benefit is reached without stringent filtering; lenient rules (5 MADs, or 3 MADs on at least 2 metrics) limit loss of whole subpopulations","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Computed on a mixed population it removes cell types with extreme but healthy values (pipeComp); thresholds computed per treatment follow the treatment. sc-best-practices uses 5 MADs plus mito > 3 MADs and > 8%. isOutlier and perCellQCMetrics now live in scuttle [[scuttle]]. Regressing out mito fraction or detected genes later is no substitute for QC, since in pipeComp it nearly always raised correlation with those covariates and lowered clustering accuracy.","url":"https://bioconductor.org/packages/scuttle","repo_url":"https://github.com/alanocallaghan/scater","language":"multiple","doi":"10.1093/bioinformatics/btw777","pmid":"28088763","cite_title":"Scater: pre-processing, quality control, normalization and visualization of single-cell RNA-seq data in R","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btw777","publication_url":"https://doi.org/10.1093/bioinformatics/btw777","publication_title":"Scater: pre-processing, quality control, normalization and visualization of single-cell RNA-seq data in R","publication_venue":"Bioinformatics","citations":1846,"citations_total":3981,"citations_papers":4,"repo_stars":94,"repo_pushed":"2026-10-23","benchmarks":["germain-2020-pipecomp"],"benchmark_refs":[{"id":"germain-2020-pipecomp","name":"Germain et al. 2020 (pipeComp), preprocessing pipeline benchmark","url":"https://doi.org/10.1186/s13059-020-02136-7"}],"review":"02-calling-qc-damaged#mad-adaptive-qc","tags":["best-practice","per-sample","scanpy","bioconductor"],"site":"https://bioconductor.org/packages/scuttle"},{"id":"scuttle","name":"scuttle (per-cell QC metrics, Bioconductor)","kind":"tool","layer":"core","categories":["qc-metrics-thresholds"],"side":"both","tier":"standard","summary":"Bioconductor package that computes per-cell and per-feature QC metrics (library size, detected genes, subset percentages such as mito) and flags outliers with MAD rules via perCellQCMetrics, isOutlier and quickPerCellQC","recovers":"cells kept by batch-aware MAD thresholds instead of fixed cut-offs (see mad-adaptive-qc)","gain":"none of its own; it is the implementation the OSCA book and many Bioconductor pipelines use for adaptive QC","gain_source":"none","requires":["filtered-matrix"],"caveats":"Split out of scater in 2020 and has no paper of its own, so the scater paper is cited; outlier calls inherit the MAD caveats of [[mad-adaptive-qc]] (whole cell types with extreme healthy values can be removed if run on a mixed population without a batch or type block).","url":"https://bioconductor.org/packages/scuttle","repo_url":"https://github.com/LTLA/scuttle","language":"R","doi":"10.1093/bioinformatics/btw777","pmid":"28088763","cite_title":"Scater: pre-processing, quality control, normalization and visualization of single-cell RNA-seq data in R","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btw777","publication_url":"https://doi.org/10.1093/bioinformatics/btw777","publication_title":"Scater: pre-processing, quality control, normalization and visualization of single-cell RNA-seq data in R","publication_venue":"Bioinformatics","citations":1846,"citations_total":2789,"citations_papers":2,"repo_stars":10,"repo_pushed":"2026-08-27","review":"13-metrics-guides-multimodal#scuttle","tags":["bioconductor","best-practice","mad"],"site":"https://bioconductor.org/packages/scuttle"},{"id":"atac-qc-metrics","name":"scATAC per-cell QC metrics (TSS enrichment, fragments, FRiP, nucleosome signal, blacklist fraction)","kind":"method","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"both","tier":"standard","summary":"Filters scATAC and multiome barcodes on unique fragment count, TSS enrichment, fraction of fragments in peaks, nucleosome signal and blacklist fraction, the ATAC equivalents of counts, complexity and mito fraction","recovers":"cells whose low fragment counts are biology (small or quiescent nuclei) when TSS enrichment is still high","gain":"none measured as cells retained; the metrics are the basis of ArchR, Signac, SnapATAC2 and Cell Ranger ARC QC","gain_source":"none","requires":["bam"],"caveats":"Thresholds are fixed by convention (ArchR default TSS enrichment >= 4 and >= 1,000 fragments) and vary by protocol, since TSS enrichment and FRiP differ systematically between scATAC methods ([[de-rop-2024]]); FRiP needs a peak set, which genome-bin pipelines do not build ([[chromap-qc]]).","url":"https://stuartlab.org/signac/articles/pbmc_vignette","doi":"10.1038/s41592-021-01282-5","pmid":"34725479","cite_title":"Single-cell chromatin state analysis with Signac","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-021-01282-5","publication_url":"https://doi.org/10.1038/s41592-021-01282-5","publication_title":"Single-cell chromatin state analysis with Signac","publication_venue":"Nature Methods","citations":1756,"citations_total":3199,"citations_papers":3,"review":"13-metrics-guides-multimodal#atac-qc-metrics","tags":["atac","multiome","best-practice"],"site":"https://stuartlab.org/signac/articles/pbmc_vignette"},{"id":"signac","name":"Signac","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"both","tier":"standard","summary":"Seurat-compatible R toolkit for single-cell chromatin data that computes nucleosome signal, TSS enrichment, fragments in peaks and blacklist ratio for QC, then runs LSI, clustering and integration with RNA","recovers":"none specific; standard QC entry point for 10x multiome in R","gain":"scaled to over 700,000 cells (self-reported); Luo 2024: its LSI embedding was outperformed on clustering by SnapATAC, SnapATAC2 and aggregation, and correlated 0.5-0.75 with library size after removing the first component","gain_source":"independent","requires":["bam"],"caveats":"QC thresholds are user-chosen from vignette defaults; depth leaks into LSI components beyond the first, so fragment-count differences between conditions can drive clusters.","url":"https://stuartlab.org/signac/","repo_url":"https://github.com/stuart-lab/signac","language":"R","doi":"10.1038/s41592-021-01282-5","pmid":"34725479","cite_title":"Single-cell chromatin state analysis with Signac","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-021-01282-5","publication_url":"https://doi.org/10.1038/s41592-021-01282-5","publication_title":"Single-cell chromatin state analysis with Signac","publication_venue":"Nature Methods","citations":1756,"repo_stars":431,"repo_pushed":"2026-09-11","benchmarks":["luo-2024-chromatin-benchmark"],"benchmark_refs":[{"id":"luo-2024-chromatin-benchmark","name":"Luo et al. 2024, scATAC feature-engineering benchmark","url":"https://doi.org/10.1186/s13059-024-03356-x"}],"review":"13-metrics-guides-multimodal#signac","tags":["atac","multiome","seurat"],"site":"https://stuartlab.org/signac/"},{"id":"saelens-2019","name":"Saelens et al. 2019: trajectory inference benchmark (dynverse)","kind":"evidence","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"standard","summary":"Benchmark of 45 trajectory inference methods on 110 real and 229 synthetic datasets for cellular ordering, topology, scalability and usability, with guidelines for choosing a method by dataset size and expected topology","gain":"No method best for every topology; the method choice should depend mostly on dataset dimensions and trajectory topology. In the authors' results data (February 2019), Slingshot had the highest overall accuracy (0.706), then PAGA Tree (0.695) and SCORPIUS (0.672); in the 29-method preprint, Slingshot, TSCAN and Monocle DDRTree clearly outperformed the rest","gain_source":"independent","caveats":"Accuracy is scored against reference trajectories; QC choices were not varied. The published paper is paywalled: rankings are from the authors' results file (github dynverse/dynbenchmark_results, 08-summary/results.rds; the February and September 2019 versions agree on the top three by accuracy, but the September update puts SCORPIUS first on the combined score) and the preprint","url":"https://benchmark.dynverse.org","repo_url":"https://github.com/dynverse/dynbenchmark","language":"R","doi":"10.1038/s41587-019-0071-9","pmid":"30936559","cite_title":"A comparison of single-cell trajectory inference methods.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-019-0071-9","publication_url":"https://doi.org/10.1038/s41587-019-0071-9","publication_title":"A comparison of single-cell trajectory inference methods.","publication_venue":"Nature Biotechnology","citations":1663,"repo_stars":223,"repo_pushed":"2023-08-30","review":"22-concepts-downstream#saelens-2019","tags":["benchmark","pseudotime"],"site":"https://benchmark.dynverse.org"},{"id":"soupx","name":"SoupX","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"standard","summary":"Estimates a per-channel ambient (soup) profile from empty droplets and a contamination fraction from genes that should be absent, then subtracts the soup from each cell","recovers":"specificity of marker and response genes in kept cells, so cells need not be dropped for ambient-driven mixed profiles","gain":"Nie 2026: second-lowest error and smallest variance for absolute contamination across contamination levels; Cargnelli 2026: reduced mode (filtered matrix only) is one of three recommended methods and less prone than CellBender or DecontX to over-correct samples without ambient RNA; Schroeder 2026 (preprint): reliable removal with minimal count distortion","gain_source":"independent","requires":["raw-matrix"],"caveats":"One contamination fraction per channel by design, so it underestimates and cannot capture cell-to-cell variation (Janssen 2023: Slc34a1 outside PT only 60% -> 54%); automated mode can miss strong contaminating genes (scCDC 2024). Running it before doublet detection lowered doublet recall (Meier 2026, preprint).","url":"https://github.com/constantAmateur/SoupX","repo_url":"https://github.com/constantAmateur/SoupX","language":"R","doi":"10.1093/gigascience/giaa151","pmid":"33367645","cite_title":"SoupX removes ambient RNA contamination from droplet-based single-cell RNA sequencing data","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1093/gigascience/giaa151","publication_url":"https://doi.org/10.1093/gigascience/giaa151","publication_title":"SoupX removes ambient RNA contamination from droplet-based single-cell RNA sequencing data","publication_venue":"GigaScience","citations":1629,"citations_total":2740,"citations_papers":7,"repo_stars":345,"repo_pushed":"2022-11-01","benchmarks":["janssen-2023-background-noise","cargnelli-2026-ambient-benchmark","nie-2026-ambient-benchmark","schroeder-2026-ambient-benchmark","meier-2026-ambient-doublet-order"],"benchmark_refs":[{"id":"janssen-2023-background-noise","name":"Janssen et al. 2023, background noise and its removal","url":"https://doi.org/10.1186/s13059-023-02978-x"},{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"},{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"},{"id":"meier-2026-ambient-doublet-order","name":"Meier et al. 2026, ambient correction order and doublet detection (preprint)","url":"https://doi.org/10.64898/2026.10.13.758369"}],"review":"02-calling-qc-damaged#soupx","tags":["droplet","best-practice"]},{"id":"doubletcells","name":"doubletCells / computeDoubletDensity (scran, scDblFinder)","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked","summary":"Scores each cell by the local density of simulated doublets relative to real cells in a reduced space; moved from scran's doubletCells to scDblFinder's computeDoubletDensity","gain":"Xi & Li 2021: the only method that did not beat the library-size and gene-count baselines on a majority of the 16 datasets, and the only one that left spurious trajectory branches","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Superseded by scDblFinder's classifier in the same package; retained in OSCA as a cluster-free score.","url":"https://bioconductor.org/packages/scDblFinder","repo_url":"https://github.com/plger/scDblFinder","language":"R","doi":"10.12688/f1000research.9501.2","pmid":"27909575","cite_title":"A step-by-step workflow for low-level analysis of single-cell RNA-seq data with Bioconductor","year":"2016","verified":true,"citation_check":"verified","publication":"doi:10.12688/f1000research.9501.2","publication_url":"https://doi.org/10.12688/f1000research.9501.2","publication_title":"A step-by-step workflow for low-level analysis of single-cell RNA-seq data with Bioconductor","publication_venue":"F1000Research","citations":1586,"repo_stars":274,"repo_pushed":"2026-10-18","benchmarks":["xi-li-2021-doublet-benchmark","xi-li-2021-doublet-protocol","ttoouli-2025-multiplets"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"xi-li-2021-doublet-protocol","name":"Xi and Li 2021, doublet-detection benchmark protocol (scDblFinder added)","url":"https://doi.org/10.1016/j.xpro.2021.100699"},{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"}],"review":"12-doublets-stress-batch#doubletcells","tags":["bioconductor","osca"],"site":"https://bioconductor.org/packages/scDblFinder"},{"id":"rctd-doublet-mode-droplets","name":"RCTD doublet mode applied to droplet doublets","kind":"hypothesis","layer":"core","categories":["discarded-data","doublets"],"side":"additive","tier":"hypothesis","summary":"Proposes decomposing droplet doublets with RCTD doublet mode, which fits the best one or two reference cell types per Slide-seq pixel, to assign both partners and their mixing proportion","recovers":"partner identities and proportions for doublets that would otherwise be discarded","requires":["filtered-matrix","reference"],"caveats":"untested on droplet doublets; in RCTD's own simulations transcriptionally similar pairs were called singlets 87.0% of the time; models platform effects, not ambient RNA or interaction-induced expression","url":"https://github.com/dmcable/spacexr","repo_url":"https://github.com/dmcable/spacexr","language":"R","doi":"10.1038/s41587-021-00830-w","pmid":"33603203","cite_title":"Robust decomposition of cell type mixtures in spatial transcriptomics","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-021-00830-w","publication_url":"https://doi.org/10.1038/s41587-021-00830-w","publication_title":"Robust decomposition of cell type mixtures in spatial transcriptomics","publication_venue":"Nature Biotechnology","citations":1472,"repo_stars":489,"repo_pushed":"2026-01-22","review":"05-discarded-data#rctd-doublet-mode-droplets","tags":["doublet-deconvolution","spatial-method-reuse"]},{"id":"luecken-2022-scib","name":"Luecken et al. 2022, scIB atlas-level integration benchmark","kind":"evidence","layer":"adjacent","categories":["integration","feature-selection"],"side":"neutral","tier":"standard","summary":"Benchmark of 16 integration methods in 68 method and preprocessing combinations on 13 atlas-level tasks (85 batches, over 1.2 million cells) with 14 metrics for batch removal and biological conservation","gain":"scANVI, Scanorama, scVI and scGen best overall; HVG selection improved 74% of comparisons; scaling raised batch removal in 79% and lowered bio-conservation in 72%; cell-cycle and trajectory conservation favoured the full gene set","gain_source":"independent","caveats":"40/60 weighting of batch removal against bio-conservation is a choice; label-based metrics depend on the annotation they are given.","url":"https://github.com/theislab/scib","repo_url":"https://github.com/theislab/scib","language":"Python","doi":"10.1038/s41592-021-01336-8","pmid":"34949812","cite_title":"Benchmarking atlas-level data integration in single-cell genomics.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-021-01336-8","publication_url":"https://doi.org/10.1038/s41592-021-01336-8","publication_title":"Benchmarking atlas-level data integration in single-cell genomics.","publication_venue":"Nature Methods","citations":1430,"repo_stars":435,"repo_pushed":"2026-04-27","review":"21-concepts-preprocessing#luecken-2022-scib","tags":["benchmark","atlas","metrics"]},{"id":"split-seq-parse","name":"SPLiT-seq / Parse Evercode","kind":"design","layer":"core","categories":["demux-combinatorial","screen-design"],"side":"additive","tier":"benchmarked","summary":"Fixed cells or nuclei are barcoded in situ through rounds of split-pool ligation in plates, so the first-round well doubles as a sample barcode without hashing","recovers":"samples per run (96-384 per commercial kit, vendor-reported) and storage of fixed cells; fewer stressed cells than unfixed droplet capture in one organoid comparison","gain":"Independent: about 2x genes per cell against 10x 3' on mouse thymocytes (Filippov 2024); post-QC retention 95.6% against 87.2% and fewer stressed cells than 10x CellPlex on cerebellar organoids (Sarieva 2026); self-reported: 0.1% mouse-human collisions and about $0.01 per cell library preparation (2018)","gain_source":"independent","requires":["fastq","multiple-conditions"],"caveats":"Lower recovery from input: about 27% against 53% for 10x on PBMCs, 16.5% against 42.7% on organoids; about 80-85% of reads carry valid barcodes against 97-98% for 10x; collisions rise with cells per experiment (2.5% expected for 150,000 nuclei in the original 4-round design); vendor pipeline split-pipe is not open source","url":"https://www.parsebiosciences.com","doi":"10.1126/science.aam8999","pmid":"29545511","cite_title":"Single-cell profiling of the developing mouse brain and spinal cord with split-pool barcoding","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1126/science.aam8999","publication_url":"https://doi.org/10.1126/science.aam8999","publication_title":"Single-cell profiling of the developing mouse brain and spinal cord with split-pool barcoding","publication_venue":"Science","citations":1422,"citations_total":1473,"citations_papers":4,"benchmarks":["de-simone-2025-kit-comparison","abrf-2026-preservation-multisite","xie-2024-parse-vs-10x","sarieva-2026-parse-vs-cellplex","filippov-2024-thymocyte-platforms","brown-2024-multiplexing-reagents"],"benchmark_refs":[{"id":"de-simone-2025-kit-comparison","name":"De Simone et al. 2025, nine commercial scRNA-seq kits","url":"https://doi.org/10.1093/nar/gkae1186"},{"id":"abrf-2026-preservation-multisite","name":"ABRF multisite preservation study 2026 (Kolling et al.)","url":"https://doi.org/10.7171/001c.162768"},{"id":"xie-2024-parse-vs-10x","name":"Xie et al. 2024, Parse versus 10x on PBMCs","url":"https://doi.org/10.3390/ijms25073828"},{"id":"sarieva-2026-parse-vs-cellplex","name":"Sarieva et al. 2026, Parse versus 10x CellPlex on organoids","url":"https://doi.org/10.1016/j.isci.2026.114780"},{"id":"filippov-2024-thymocyte-platforms","name":"Filippov et al. 2024, 10x versus Parse on thymocytes","url":"https://doi.org/10.1186/s12864-024-10976-x"},{"id":"brown-2024-multiplexing-reagents","name":"Brown et al. 2024, multiplexing reagents and fixed kits","url":"https://doi.org/10.1016/j.ygeno.2024.110793"}],"review":"04-screen-design#split-seq-parse","tags":["split-pool","fixed","combinatorial-indexing","kit"],"site":"https://www.parsebiosciences.com"},{"id":"archr","name":"ArchR","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal","doublets"],"side":"both","tier":"standard","summary":"R suite for scATAC analysis whose arrow-file creation step computes per-cell TSS enrichment and fragment counts, applies QC thresholds, and scores doublets by projecting synthetic doublets, before clustering and integration","recovers":"none specific; standard QC entry point for scATAC","gain":"analysed over 1.2 million cells in 8 h on a laptop (self-reported); Luo 2024: with SnapATAC2 the most scalable of five feature-engineering methods, but its iterative LSI embedding stayed correlated 0.5-0.75 with library size","gain_source":"independent","requires":["bam"],"caveats":"Default thresholds (TSS enrichment >= 4, >= 1,000 fragments) are protocol-dependent; its doublet scores are an RNA-free method distinct from AMULET; last code push February 2025. Doublet scoring is simulation-based and heterotypic only; on simulated PBMC multiplets recall was 0.25 and 0.23 against 0.80 and 0.90 for AMULET, though ArchR was higher (0.68 vs 0.37) on one low-depth islet sample (AMULET paper, a competitor comparison).","url":"https://www.archrproject.com","repo_url":"https://github.com/GreenleafLab/ArchR","language":"R","doi":"10.1038/s41588-021-00790-6","pmid":"33633365","cite_title":"ArchR is a scalable software package for integrative single-cell chromatin accessibility analysis","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41588-021-00790-6","publication_url":"https://doi.org/10.1038/s41588-021-00790-6","publication_title":"ArchR is a scalable software package for integrative single-cell chromatin accessibility analysis","publication_venue":"Nature Genetics","citations":1385,"repo_stars":467,"repo_pushed":"2025-02-18","benchmarks":["luo-2024-chromatin-benchmark"],"benchmark_refs":[{"id":"luo-2024-chromatin-benchmark","name":"Luo et al. 2024, scATAC feature-engineering benchmark","url":"https://doi.org/10.1186/s13059-024-03356-x"}],"review":"13-metrics-guides-multimodal#archr","tags":["atac","multiome","doublets"],"site":"https://www.archrproject.com"},{"id":"celltypist","name":"CellTypist","kind":"tool","layer":"adjacent","categories":["clustering-annotation"],"side":"neutral","tier":"standard","summary":"Logistic regression classifiers trained on curated immune and tissue references that label each cell, with optional majority voting over over-clustered neighbourhoods","gain_source":"none","requires":["filtered-matrix","reference"],"caveats":"Labels are limited to the model's training types; no independent peer-reviewed benchmark including it was found. Paper is a cross-tissue immune atlas, so the human immune models are the best-supported ones.","url":"https://www.celltypist.org","repo_url":"https://github.com/Teichlab/celltypist","language":"Python","doi":"10.1126/science.abl5197","pmid":"35549406","cite_title":"Cross-tissue immune cell analysis reveals tissue-specific features in humans.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1126/science.abl5197","publication_url":"https://doi.org/10.1126/science.abl5197","publication_title":"Cross-tissue immune cell analysis reveals tissue-specific features in humans.","publication_venue":"Science","citations":1172,"repo_stars":515,"repo_pushed":"2026-05-22","review":"21-concepts-preprocessing#celltypist","tags":["label-transfer","immune","reference"],"site":"https://www.celltypist.org"},{"id":"concept-clustering-annotation","name":"Clustering and cell-type annotation","kind":"concept","layer":"adjacent","categories":["clustering-annotation"],"side":"neutral","tier":"standard","summary":"Grouping cells into communities on a neighbour graph and naming them, by marker genes, by classifiers trained on references, or by mapping onto an annotated atlas","caveats":"Cluster number depends on resolution and on every upstream step; automatic annotators lose accuracy for overlapping classes and deep annotation levels (Abdelaal 2019).","doi":"10.1038/s41576-018-0088-9","pmid":"30617341","cite_title":"Challenges in unsupervised clustering of single-cell RNA-seq data.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41576-018-0088-9","publication_url":"https://doi.org/10.1038/s41576-018-0088-9","publication_title":"Challenges in unsupervised clustering of single-cell RNA-seq data.","publication_venue":"Nature Reviews Genetics","citations":1167,"citations_total":3910,"citations_papers":4,"review":"21-concepts-preprocessing#concept-clustering-annotation","tags":["concept","clustering","annotation"]},{"id":"demuxlet","name":"demuxlet / freemuxlet (popscle)","kind":"tool","layer":"core","categories":["demux-genotype","doublets"],"side":"both","tier":"standard","summary":"Reference-genotype demultiplexer (popscle suite, with freemuxlet as its genotype-free mode) that scores each droplet's SNP reads against every donor and donor pair","recovers":"donor labels and between-donor doublets from SNP reads","gain":"Self-reported: in simulation 50 SNPs per cell assigned 97% of singlets and detected 92% of doublets in pools of up to 64; with genotypes for 8 pooled samples over 99% of singlets were assigned correctly","gain_source":"self-reported","requires":["bam","genotypes"],"caveats":"Default doublet threshold gave nearly 40% false-positive doublets in a synthetic test (souporcell authors); in pooled tumours only 31.9% of its doublet calls were true (Weber 2021); high memory use (Demuxafy); needs a VCF of the pooled donors","url":"https://github.com/statgen/popscle","repo_url":"https://github.com/statgen/popscle","language":"C++","doi":"10.1038/nbt.4042","pmid":"29227470","cite_title":"Multiplexed droplet single-cell RNA-sequencing using natural genetic variation.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/nbt.4042","publication_url":"https://doi.org/10.1038/nbt.4042","publication_title":"Multiplexed droplet single-cell RNA-sequencing using natural genetic variation.","publication_venue":"Nature Biotechnology","citations":1143,"repo_stars":59,"repo_pushed":"2021-05-05","benchmarks":["fu-2025-snrna-genetic-benchmark","weber-2021-cancer-genetic-demux","neavin-2024-demuxafy-benchmark","curion-2024-hadge-comparison","fiorini-2025-ensemblex-benchmark"],"benchmark_refs":[{"id":"fu-2025-snrna-genetic-benchmark","name":"Fu et al. 2025, genetic demultiplexing for snRNA-seq","url":"https://doi.org/10.1093/bib/bbaf371"},{"id":"weber-2021-cancer-genetic-demux","name":"Weber et al. 2021, genetic demultiplexing in cancer","url":"https://doi.org/10.1093/gigascience/giab062"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"},{"id":"fiorini-2025-ensemblex-benchmark","name":"Fiorini et al. 2025 (Ensemblex), genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-025-03643-1"}],"review":"01-demux-recovery#demuxlet","tags":["genotype","reference-genotypes"]},{"id":"sclvm","name":"scLVM","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Latent variable model that estimates a cell-cycle covariance from annotated genes and removes it, exposing hidden subpopulations (successor f-scLVM handles many gene sets)","gain":"revealed T helper 2 differentiation stages hidden by cell-cycle variation (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Built for hundreds of cells; superseded and not maintained.","repo_url":"https://github.com/PMBio/scLVM","language":"multiple","doi":"10.1038/nbt.3102","pmid":"25599176","cite_title":"Computational analysis of cell-to-cell heterogeneity in single-cell RNA-sequencing data reveals hidden subpopulations of cells","year":"2015","verified":true,"citation_check":"verified","publication":"doi:10.1038/nbt.3102","publication_url":"https://doi.org/10.1038/nbt.3102","publication_title":"Computational analysis of cell-to-cell heterogeneity in single-cell RNA-sequencing data reveals hidden subpopulations of cells","publication_venue":"Nature Biotechnology","citations":1135,"repo_stars":112,"repo_pushed":"2022-12-16","review":"12-doublets-stress-batch#sclvm","tags":["latent-variable","unmaintained"]},{"id":"tran-2020","name":"Tran et al. 2020, batch-effect correction benchmark","kind":"evidence","layer":"adjacent","categories":["integration"],"side":"neutral","tier":"standard","summary":"Benchmark of 14 batch-correction methods on ten datasets in five scenarios (identical cell types across technologies, non-identical cell types, multiple batches, big data, simulated DE) with kBET, LISI, ASW and ARI","gain":"Harmony, LIGER and Seurat 3 recommended; Harmony first because of its much shorter runtime","gain_source":"independent","caveats":"Simpler tasks than scIB; scVI was not among the methods tested.","url":"https://doi.org/10.1186/s13059-019-1850-9","doi":"10.1186/s13059-019-1850-9","pmid":"31948481","cite_title":"A benchmark of batch-effect correction methods for single-cell RNA sequencing data.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1850-9","publication_url":"https://doi.org/10.1186/s13059-019-1850-9","publication_title":"A benchmark of batch-effect correction methods for single-cell RNA sequencing data.","publication_venue":"Genome biology","citations":1111,"review":"21-concepts-preprocessing#tran-2020","tags":["benchmark"],"site":"https://doi.org/10.1186/s13059-019-1850-9"},{"id":"scran-pooling","name":"scran pooled size factors (deconvolution)","kind":"tool","layer":"adjacent","categories":["normalisation"],"side":"neutral","tier":"standard","summary":"Sums counts over pools of similar cells to estimate pool size factors, then deconvolves them into per-cell size factors that are robust to many zero counts","gain":"More accurate cell-specific size factors than library size or bulk methods on simulations (self-reported); pipeComp rated most normalisations, scran included, as fair","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Pools are formed within quickCluster groups by default, so cells are pooled with similar cells; the default in the Bioconductor OSCA workflow. Applying QC filters within quickCluster groups in pipeComp removed almost no cells, unlike global filters.","url":"https://bioconductor.org/packages/scran","repo_url":"https://github.com/MarioniLab/scran","language":"R","doi":"10.1186/s13059-016-0947-7","pmid":"27122128","cite_title":"Pooling across cells to normalize single-cell RNA sequencing data with many zero counts.","year":"2016","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-016-0947-7","publication_url":"https://doi.org/10.1186/s13059-016-0947-7","publication_title":"Pooling across cells to normalize single-cell RNA sequencing data with many zero counts.","publication_venue":"Genome biology","citations":1106,"repo_stars":48,"repo_pushed":"2026-05-20","benchmarks":["germain-2020-pipecomp","ge-2025-normalisation-benchmark"],"benchmark_refs":[{"id":"germain-2020-pipecomp","name":"Germain et al. 2020 (pipeComp), preprocessing pipeline benchmark","url":"https://doi.org/10.1186/s13059-020-02136-7"},{"id":"ge-2025-normalisation-benchmark","name":"Ge et al. 2025, normalisation benchmark","url":"https://doi.org/10.1371/journal.pone.0335102"}],"review":"21-concepts-preprocessing#scran-pooling","tags":["bioconductor","size-factors"],"site":"https://bioconductor.org/packages/scran"},{"id":"emptydrops","name":"EmptyDrops (DropletUtils)","kind":"tool","layer":"core","categories":["cell-calling","ambient-rna"],"side":"additive","tier":"standard","summary":"Calls cells by testing each barcode's profile against the ambient RNA profile estimated from low-count barcodes, so small low-RNA cells that differ from the soup are kept","recovers":"low-RNA cells and whole cell types that a total-UMI knee threshold discards","gain":"retained a putative interneuron cluster in ~900 brain cells and putative monocytes in placenta that the Cell Ranger v2 knee discarded; FDR among retained barcodes controlled at 0.1% (self-reported, simulations and real data)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Cell Ranger >= 3 runs an EmptyDrops-like second step, but its candidate set is bounded (the STARsolo EmptyDrops_CR emulation hard-codes umiMin 500 and umiMinFracMedian 0.01 as Cell Ranger values), so very low-RNA barcodes are never tested; DropletUtils defaults to lower = 100. In high-ambient samples it keeps empty and damaged droplets that need post-filtering (DropletQC found 0.4-9.5% cell-free droplets among EmptyDrops calls). Its result depends on the quantifier; on zUMIs and kallisto bustools output for a ~3,000-cell mixture it called ~60,000 cells (You 2021). In snRNA-seq of adipose tissue 87.9% of its passing droplets were nuclear against 95.7% for DIEM, and it removed 1,038 and 782 nuclear droplets in two samples (DIEM paper, competitor); hashing-labelled AUROC 79.87% in the EmptyNN paper (competitor).","url":"https://bioconductor.org/packages/DropletUtils","repo_url":"https://github.com/MarioniLab/DropletUtils","language":"R","doi":"10.1186/s13059-019-1662-y","pmid":"30902100","cite_title":"EmptyDrops: distinguishing cells from empty droplets in droplet-based single-cell RNA sequencing data","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1662-y","publication_url":"https://doi.org/10.1186/s13059-019-1662-y","publication_title":"EmptyDrops: distinguishing cells from empty droplets in droplet-based single-cell RNA sequencing data","publication_venue":"Genome biology","citations":1105,"citations_total":1283,"citations_papers":4,"repo_stars":68,"repo_pushed":"2026-09-24","review":"02-calling-qc-damaged#emptydrops","tags":["droplet","10x","low-rna","starsolo","cellranger"],"site":"https://bioconductor.org/packages/DropletUtils"},{"id":"decoupler","name":"decoupler / decoupleR (PROGENy, DoRothEA footprints)","kind":"tool","layer":"core","categories":["low-cell-stats","perturbation-models"],"side":"additive","tier":"standard","summary":"Framework that scores pathway and transcription-factor activities from prior-knowledge footprint gene sets (PROGENy, DoRothEA/CollecTRI) with methods such as univariate and multivariate linear models, on cells or on pseudobulk contrast statistics","recovers":"One activity per pathway or regulator, pooling evidence from many weakly changed genes into a test with fewer comparisons","gain":"decoupleR benchmark: simple linear models and a consensus score best predicted perturbed regulators; Holland 2020: footprint gene sets worked on simulated and CRISPR scRNA-seq comparably to bulk and partly better than SCENIC/AUCell and metaVIPER; PROGENy AUROC fell from 0.724 to 0.636 as gene coverage dropped","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Performance depends more on the gene sets than on the statistic. Footprints come from bulk perturbation data in other contexts. Run on replicate-level contrast statistics to keep inference honest; cell-level scores inherit pseudoreplication. Benchmarks are from the same lab.","url":"https://decoupler.readthedocs.io/","repo_url":"https://github.com/scverse/decoupler","language":"multiple","doi":"10.1093/bioadv/vbac016","pmid":"36699385","cite_title":"decoupleR: ensemble of computational methods to infer biological activities from omics data.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioadv/vbac016","publication_url":"https://doi.org/10.1093/bioadv/vbac016","publication_title":"decoupleR: ensemble of computational methods to infer biological activities from omics data.","publication_venue":"Bioinformatics Advances","citations":1085,"citations_total":4018,"citations_papers":5,"repo_stars":300,"repo_pushed":"2026-10-24","review":"03-low-cell-stats#decoupler","tags":["signatures","pathways","transcription-factors","drug-screen"],"site":"https://decoupler.readthedocs.io/"},{"id":"van-den-brink-2017","name":"van den Brink et al. 2017 dissociation-induced expression","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress","damaged-cells"],"side":"neutral","tier":"published-unbenchmarked","summary":"Showed that enzymatic dissociation at 37 C induces immediate-early and heat-shock genes in subpopulations of cells, which can then appear as a distinct state","gain":"none (cautionary finding)","gain_source":"none","caveats":"Muscle stem cells; a stress cluster is a technical state to model or score, not necessarily a set of cells to remove.","doi":"10.1038/nmeth.4437","pmid":"28960196","cite_title":"Single-cell sequencing reveals dissociation-induced gene expression in tissue subpopulations","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1038/nmeth.4437","publication_url":"https://doi.org/10.1038/nmeth.4437","publication_title":"Single-cell sequencing reveals dissociation-induced gene expression in tissue subpopulations","publication_venue":"Nature Methods","citations":1065,"review":"02-calling-qc-damaged#van-den-brink-2017","tags":["dissociation","stress-signature"]},{"id":"cell-hashing","name":"Cell Hashing (antibody hashtags)","kind":"design","layer":"core","categories":["screen-design","demux-hashing","doublets"],"side":"additive","tier":"standard","summary":"Oligo-tagged antibodies against ubiquitous surface proteins label each sample before pooling, so samples share one lane and cross-sample multiplets become identifiable","recovers":"cells per lane through superloading, and doublets that RNA-only methods miss","gain":"8-donor PBMC pool superloaded for about 20,000 singlets: modelled unresolved multiplet rate 3.1%, against about 4,000 singlets at the same rate without hashing (described as about 400% more cells for the same cost); observed 14,002 singlets and 2,974 identifiable multiplets","gain_source":"self-reported","requires":["tag-counts","filtered-matrix"],"caveats":"Needs surface epitopes, so weaker on nuclei (antibody nuclei hashing OCA 0.51-0.65 against 0.84 for cholesterol oligos in Mylka 2022); same-sample doublets stay invisible; calling with [[htodemux]], [[multiseqdemux]] or other T1 tools","doi":"10.1186/s13059-018-1603-1","pmid":"30567574","cite_title":"Cell Hashing with barcoded antibodies enables multiplexing and doublet detection for single cell genomics","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-018-1603-1","publication_url":"https://doi.org/10.1186/s13059-018-1603-1","publication_title":"Cell Hashing with barcoded antibodies enables multiplexing and doublet detection for single cell genomics","publication_venue":"Genome biology","citations":1045,"benchmarks":["mylka-2022-hashing-comparison","brown-2024-multiplexing-reagents"],"benchmark_refs":[{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022, antibody versus lipid hashing","url":"https://doi.org/10.1186/s13059-022-02628-8"},{"id":"brown-2024-multiplexing-reagents","name":"Brown et al. 2024, multiplexing reagents and fixed kits","url":"https://doi.org/10.1016/j.ygeno.2024.110793"}],"review":"04-screen-design#cell-hashing","tags":["hashing","superloading","doublets","antibody"]},{"id":"htodemux","name":"HTODemux (Seurat)","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"standard","summary":"Seurat function that CLR-normalises hashtag counts, clusters droplets with k-medoids, fits a negative binomial to each tag's lowest cluster and calls the tag positive above that background's 0.99 quantile","recovers":"sample labels for hashed cells; flags cross-sample doublets and tagless negatives","gain":"Lowering positive.quantile from 0.99 to 0.9 raised overall classification accuracy from 0.54 to 0.65 on antibody-hashed nuclei of four cell lines (Mylka 2022); mean F 0.892, 0.794 and 0.742 on three BAL batches against vireo genotype truth, with under 20% of genetic doublets called singlets (Howitt 2023)","gain_source":"independent","requires":["tag-counts","filtered-matrix"],"caveats":"The vignette's per-tag CLR ignores per-cell tag depth, which Sayed 2025 found costs negatives; recall fell to 52% in a 30-sample imbalanced simulation and it errored on low-cell PDX batches (both reported by deMULTIplex2 authors)","url":"https://satijalab.org/seurat/articles/hashing_vignette","repo_url":"https://github.com/satijalab/seurat","language":"R","doi":"10.1186/s13059-018-1603-1","pmid":"30567574","cite_title":"Cell Hashing with barcoded antibodies enables multiplexing and doublet detection for single cell genomics.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-018-1603-1","publication_url":"https://doi.org/10.1186/s13059-018-1603-1","publication_title":"Cell Hashing with barcoded antibodies enables multiplexing and doublet detection for single cell genomics.","publication_venue":"Genome biology","citations":1045,"repo_stars":2807,"repo_pushed":"2026-10-23","benchmarks":["howitt-2023-hto-benchmark","mylka-2022-hashing-comparison","sayed-2025-hashtag-benchmark","curion-2024-hadge-comparison","brown-2024-multiplexing-reagents"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022, antibody versus lipid hashing","url":"https://doi.org/10.1186/s13059-022-02628-8"},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"},{"id":"brown-2024-multiplexing-reagents","name":"Brown et al. 2024, multiplexing reagents and fixed kits","url":"https://doi.org/10.1016/j.ygeno.2024.110793"}],"review":"01-demux-recovery#htodemux","tags":["hashing","antibody","seurat","default"],"site":"https://satijalab.org/seurat/articles/hashing_vignette"},{"id":"heumos-2023","name":"Heumos et al. 2023 scverse best practices across modalities","kind":"evidence","layer":"core","categories":["qc-benchmarks","multimodal"],"side":"neutral","tier":"standard","summary":"Review and online book (sc-best-practices.org) that summarises independent benchmarks into recommended workflows for scRNA-seq, scATAC-seq, CITE-seq, immune repertoire and spatial data","gain":"QC defaults of 5 MADs on log counts, log genes and top-20-gene share, mito flagged only when > 3 MADs and > 8%; SoupX for ambient RNA; scDblFinder for doublets; for ATAC, TSS enrichment, fragment counts and nucleosome signal","gain_source":"none","caveats":"Where no independent benchmark exists the guide contrasts popular tools rather than ranking them; QC thresholds are defaults, not tested on treated or stressed cells.","url":"https://www.sc-best-practices.org","repo_url":"https://github.com/theislab/single-cell-best-practices","doi":"10.1038/s41576-023-00586-w","pmid":"37002403","cite_title":"Best practices for single-cell analysis across modalities","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41576-023-00586-w","publication_url":"https://doi.org/10.1038/s41576-023-00586-w","publication_title":"Best practices for single-cell analysis across modalities","publication_venue":"Nature Reviews Genetics","citations":1044,"repo_stars":1289,"repo_pushed":"2026-10-23","review":"13-metrics-guides-multimodal#heumos-2023","tags":["guide","best-practice","scverse","scanpy"],"site":"https://www.sc-best-practices.org"},{"id":"pseudobulk-de","name":"Pseudobulk differential expression","kind":"method","layer":"core","categories":["low-cell-stats","de-pseudobulk"],"side":"additive","tier":"standard","summary":"Sum counts per replicate sample (culture, well or donor) and cell type, then test with bulk RNA-seq tools (edgeR, DESeq2, limma-voom) so the replicate, not the cell, is the unit of inference","recovers":"Calibrated p-values and bulk-concordant DE calls, from samples of any cell count, using mature small-n statistics","gain":"All six top-ranked of 14 DE methods by concordance with matched bulk RNA-seq (AUCC) were pseudobulk methods across 18 gold-standard datasets (Squair 2021); pseudobulk had the highest average AUROC and best F1 among 18 methods (Junttila 2022)","gain_source":"independent","requires":["filtered-matrix","replicates"],"caveats":"Needs genuine replicates; with one culture per condition there is no between-replicate variance to estimate. Sum vs mean aggregation is disputed (Junttila 2022 favour sum; Murphy & Skene 2022 favour mean but attribute it to a simulation normalisation flaw). Less sensitive than cell-level tests by design. Batch covariate modelling beats batch-corrected input (Nguyen 2023).","url":"https://www.sc-best-practices.org/conditions/differential_gene_expression.html","language":"multiple","doi":"10.1038/s41576-023-00586-w","pmid":"37002403","cite_title":"Best practices for single-cell analysis across modalities.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41576-023-00586-w","publication_url":"https://doi.org/10.1038/s41576-023-00586-w","publication_title":"Best practices for single-cell analysis across modalities.","publication_venue":"Nature Reviews Genetics","citations":1044,"citations_total":2304,"citations_papers":7,"benchmarks":["squair-2021-de-benchmark","junttila-2022-ds-benchmark","gagnon-2022-de-benchmark","hafner-2025-nested-de-benchmark"],"benchmark_refs":[{"id":"squair-2021-de-benchmark","name":"Squair et al. 2021, single-cell differential expression against matched bulk","url":"https://doi.org/10.1038/s41467-021-25960-2"},{"id":"junttila-2022-ds-benchmark","name":"Junttila et al. 2022, multi-subject differential state benchmark","url":"https://doi.org/10.1093/bib/bbac286"},{"id":"gagnon-2022-de-benchmark","name":"Gagnon et al. 2022, multi-subject DE benchmark","url":"https://doi.org/10.3390/life12060850"},{"id":"hafner-2025-nested-de-benchmark","name":"Hafner et al. 2025, DE in nested single-cell settings","url":"https://doi.org/10.1093/bib/bbaf397"}],"review":"03-low-cell-stats#pseudobulk-de","tags":["pseudoreplication","edgeR","DESeq2","limma","drug-screen"],"site":"https://www.sc-best-practices.org/conditions/differential_gene_expression.html"},{"id":"squair-2021","name":"Squair et al. 2021: confronting false discoveries","kind":"evidence","layer":"core","categories":["low-cell-stats","de-pseudobulk"],"side":"neutral","tier":"standard","summary":"Benchmark of 14 DE methods on 18 datasets with matched bulk RNA-seq showing that methods ignoring replicate-to-replicate variation are biased toward highly expressed genes and call hundreds of DE genes when there is no biological difference","gain":"Single-cell methods called hundreds of DE genes between randomly assigned replicates with no perturbation; pseudobulk methods abolished these; random-cell pseudo-replicates brought the bias and the false DE genes back","gain_source":"independent","requires":["replicates"],"caveats":"GLMMs could not be run on full datasets for compute reasons; on 25-50 cell subsets they were accurate only for specific parameter combinations. Directly relevant to split-well designs: aggregating random groups of cells into pseudo-replicates shrank variance most for highly expressed genes (46 datasets) and lost performance.","url":"https://doi.org/10.1038/s41467-021-25960-2","language":"R","doi":"10.1038/s41467-021-25960-2","pmid":"34584091","cite_title":"Confronting false discoveries in single-cell differential expression.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-021-25960-2","publication_url":"https://doi.org/10.1038/s41467-021-25960-2","publication_title":"Confronting false discoveries in single-cell differential expression.","publication_venue":"Nature Communications","citations":1031,"review":"03-low-cell-stats#squair-2021","tags":["benchmark","pseudoreplication","ground-truth-bulk"],"site":"https://doi.org/10.1038/s41467-021-25960-2"},{"id":"osca","name":"OSCA, Orchestrating Single-Cell Analysis with Bioconductor","kind":"evidence","layer":"core","categories":["qc-benchmarks"],"side":"neutral","tier":"standard","summary":"Paper and online book describing the Bioconductor single-cell workflow, including per-batch MAD outlier QC with scuttle, EmptyDrops cell calling, doublet scoring and ADT-specific QC","gain":"QC chapter flags 3-MAD outliers within batch and recommends checking discarded cells for lost cell types by comparing their average profile with kept cells","gain_source":"none","caveats":"The book is updated continuously, so its defaults may differ from the 2020 paper.","url":"https://bioconductor.org/books/release/OSCA/","doi":"10.1038/s41592-019-0654-x","pmid":"31792435","cite_title":"Orchestrating single-cell analysis with Bioconductor","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-019-0654-x","publication_url":"https://doi.org/10.1038/s41592-019-0654-x","publication_title":"Orchestrating single-cell analysis with Bioconductor","publication_venue":"Nature Methods","citations":943,"review":"13-metrics-guides-multimodal#osca","tags":["guide","best-practice","bioconductor"],"site":"https://bioconductor.org/books/release/OSCA/"},{"id":"milo","name":"Milo (miloR, pertpy)","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"neutral","tier":"benchmarked-sota","summary":"Differential abundance testing on partially overlapping k-nearest-neighbour neighbourhoods with a negative binomial GLM across replicates and a spatial FDR correction, so abundance shifts are found without predefined clusters","gain":"Yi 2024 (6 DA methods, synthetic and real data): Milo and Meld were robust and ranked top 2, and Milo performed best across a range of batch-effect magnitudes with the fewest hyperparameters to tune","gain_source":"independent","requires":["replicates","filtered-matrix"],"caveats":"Neighbourhoods depend on the kNN graph and its integration, so batch correction choices feed into results; needs replicates per condition; miloDE (PMID 39026254) extends the idea to cluster-free DE","url":"https://bioconductor.org/packages/miloR","repo_url":"https://github.com/MarioniLab/miloR","language":"multiple","doi":"10.1038/s41587-021-01033-z","pmid":"34594043","cite_title":"Differential abundance testing on single-cell data using k-nearest neighbor graphs.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-021-01033-z","publication_url":"https://doi.org/10.1038/s41587-021-01033-z","publication_title":"Differential abundance testing on single-cell data using k-nearest neighbor graphs.","publication_venue":"Nature Biotechnology","citations":933,"citations_total":956,"citations_papers":2,"repo_stars":450,"repo_pushed":"2026-08-25","benchmarks":["yi-2024-da-benchmark"],"benchmark_refs":[{"id":"yi-2024-da-benchmark","name":"Yi, Plotkin and Stanley 2024, differential abundance benchmark","url":"https://doi.org/10.1186/s13059-023-03143-0"}],"review":"22-concepts-downstream#milo","tags":["differential-abundance","knn-graph"],"site":"https://bioconductor.org/packages/miloR"},{"id":"bbknn","name":"BBKNN","kind":"tool","layer":"adjacent","categories":["integration","clustering-annotation"],"side":"subtractive","tier":"benchmarked","summary":"Builds the neighbour graph by taking each cell's nearest neighbours separately within every batch, so clustering and UMAP run on a batch-balanced graph without changing expression","gain":"Fast and graph-only; evaluated in Tran 2020 and scIB without being among the recommended or top-ranked methods","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Corrects only the graph, so downstream steps that read expression or PCA still see the batch effect.","url":"https://github.com/Teichlab/bbknn","repo_url":"https://github.com/Teichlab/bbknn","language":"Python","doi":"10.1093/bioinformatics/btz625","pmid":"31400197","cite_title":"BBKNN: fast batch alignment of single cell transcriptomes.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btz625","publication_url":"https://doi.org/10.1093/bioinformatics/btz625","publication_title":"BBKNN: fast batch alignment of single cell transcriptomes.","publication_venue":"Bioinformatics","citations":926,"repo_stars":180,"repo_pushed":"2023-10-11","benchmarks":["tran-2020-batch-benchmark","luecken-2022-scib-benchmark"],"benchmark_refs":[{"id":"tran-2020-batch-benchmark","name":"Tran et al. 2020, batch-effect correction benchmark","url":"https://doi.org/10.1186/s13059-019-1850-9"},{"id":"luecken-2022-scib-benchmark","name":"Luecken et al. 2022 (scIB), atlas-level integration benchmark","url":"https://doi.org/10.1038/s41592-021-01336-8"}],"review":"21-concepts-preprocessing#bbknn","tags":["graph","scanpy"]},{"id":"scanorama","name":"Scanorama","kind":"tool","layer":"adjacent","categories":["integration"],"side":"subtractive","tier":"benchmarked-sota","summary":"Finds mutual nearest neighbours across all datasets at once in a reduced space and stitches them panorama-style, returning a corrected embedding and corrected expression","gain":"scIB: among the four best methods overall; its corrected-expression output conserved cell-cycle variance and HVGs best together with ComBat and MNN","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Also tested by Tran 2020, which did not place it among its three recommended methods.","url":"https://github.com/brianhie/scanorama","repo_url":"https://github.com/brianhie/scanorama","language":"Python","doi":"10.1038/s41587-019-0113-3","pmid":"31061482","cite_title":"Efficient integration of heterogeneous single-cell transcriptomes using Scanorama.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-019-0113-3","publication_url":"https://doi.org/10.1038/s41587-019-0113-3","publication_title":"Efficient integration of heterogeneous single-cell transcriptomes using Scanorama.","publication_venue":"Nature Biotechnology","citations":893,"repo_stars":295,"repo_pushed":"2025-07-14","benchmarks":["luecken-2022-scib-benchmark","tran-2020-batch-benchmark"],"benchmark_refs":[{"id":"luecken-2022-scib-benchmark","name":"Luecken et al. 2022 (scIB), atlas-level integration benchmark","url":"https://doi.org/10.1038/s41592-021-01336-8"},{"id":"tran-2020-batch-benchmark","name":"Tran et al. 2020, batch-effect correction benchmark","url":"https://doi.org/10.1186/s13059-019-1850-9"}],"review":"21-concepts-preprocessing#scanorama","tags":["mnn","corrected-expression"]},{"id":"cellbender","name":"CellBender remove-background","kind":"tool","layer":"core","categories":["ambient-rna","cell-calling"],"side":"both","tier":"benchmarked-sota","summary":"Deep generative model of droplet counts that calls cell-containing droplets, learns the ambient profile and returns background-subtracted counts","recovers":"marker specificity in kept cells and cells that would otherwise be dropped or mislabelled because of ambient signal","gain":"Janssen 2023 (genotype-mixed mouse kidney): most precise per-cell noise estimate; Slc34a1 detected in ~60% of non-PT cells raw, 7% after CellBender (SoupX 54%, DecontX 2%); Cargnelli 2026: best overall trade-off of ambient removal and endogenous retention; Nie 2026: top decontamination efficacy, robust to cell number and depth; Schroeder 2026 (preprint, 6 tools, droplet and BD Rhapsody data): reliable removal with minimal count distortion; Meier 2026 (preprint): the only one of three ambient tools after which doublet detection was not worse than before correction","gain_source":"independent","requires":["raw-matrix"],"caveats":"Over-corrects when there is little or no ambient RNA (Cargnelli 2026); GPU strongly preferred; clustering gains are small and fine structure can be distorted (Janssen 2023); not independently benchmarked as a cell caller; in the EmptyNN paper (competitor) it kept 1,686 droplets against ~6,000 for other callers on genotype-labelled data (AUROC 58.02%).","url":"https://cellbender.readthedocs.io","repo_url":"https://github.com/broadinstitute/CellBender","language":"Python","doi":"10.1038/s41592-023-01943-7","pmid":"37550580","cite_title":"Unsupervised removal of systematic background noise from droplet-based single-cell experiments using CellBender","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-023-01943-7","publication_url":"https://doi.org/10.1038/s41592-023-01943-7","publication_title":"Unsupervised removal of systematic background noise from droplet-based single-cell experiments using CellBender","publication_venue":"Nature Methods","citations":846,"citations_total":913,"citations_papers":6,"repo_stars":426,"repo_pushed":"2026-09-12","benchmarks":["janssen-2023-background-noise","cargnelli-2026-ambient-benchmark","nie-2026-ambient-benchmark","schroeder-2026-ambient-benchmark","meier-2026-ambient-doublet-order"],"benchmark_refs":[{"id":"janssen-2023-background-noise","name":"Janssen et al. 2023, background noise and its removal","url":"https://doi.org/10.1186/s13059-023-02978-x"},{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"},{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"},{"id":"meier-2026-ambient-doublet-order","name":"Meier et al. 2026, ambient correction order and doublet detection (preprint)","url":"https://doi.org/10.64898/2026.10.13.758369"}],"review":"02-calling-qc-damaged#cellbender","tags":["droplet","deep-learning","gpu","cell-calling"],"site":"https://cellbender.readthedocs.io"},{"id":"unbalanced-ot-cell-loss","name":"Unbalanced optimal transport to model drug-induced cell loss","kind":"hypothesis","layer":"adjacent","categories":["perturbation-models","discarded-data"],"side":"additive","tier":"hypothesis","summary":"Proposes carrying the growth and death terms of unbalanced optimal transport, which Waddington-OT estimates from proliferation and apoptosis signatures, into control-to-treated drug-response maps so that cell loss is modelled instead of ignored","recovers":"a response model in which killed cells count as part of the effect","requires":["filtered-matrix","multiple-conditions"],"caveats":"untested for drug screens; growth and death priors from signatures are weak in short exposures; balanced maps such as CellOT move all control mass onto the treated survivors","url":"https://github.com/broadinstitute/wot","repo_url":"https://github.com/broadinstitute/wot","language":"Python","doi":"10.1016/j.cell.2019.01.006","pmid":"30712874","cite_title":"Optimal-Transport Analysis of Single-Cell Gene Expression Identifies Developmental Trajectories in Reprogramming","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cell.2019.01.006","publication_url":"https://doi.org/10.1016/j.cell.2019.01.006","publication_title":"Optimal-Transport Analysis of Single-Cell Gene Expression Identifies Developmental Trajectories in Reprogramming","publication_venue":"Cell","citations":824,"citations_total":1173,"citations_papers":3,"repo_stars":166,"repo_pushed":"2022-09-15","review":"05-discarded-data#unbalanced-ot-cell-loss","tags":["optimal-transport","cell-death","perturbation-model","drug-screen"]},{"id":"cellrank","name":"CellRank","kind":"tool","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"benchmarked","summary":"Combines a cell-cell similarity graph with directional information (RNA velocity, pseudotime or other kernels) in a Markov chain to find initial, intermediate and terminal states and per-cell fate probabilities","gain":"Self-reported: recovered reprogramming outcomes on lineage-traced data and predicted a dedifferentiation trajectory in lung regeneration that was confirmed experimentally; Luo 2026 evaluated it among 15 velocity methods with mixed agreement","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Inherits errors from the velocity or pseudotime kernel it is given, so quantification and QC choices upstream of velocity carry through to fate probabilities","url":"https://cellrank.org","repo_url":"https://github.com/theislab/cellrank","language":"Python","doi":"10.1038/s41592-021-01346-6","pmid":"35027767","cite_title":"CellRank for directed single-cell fate mapping.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-021-01346-6","publication_url":"https://doi.org/10.1038/s41592-021-01346-6","publication_title":"CellRank for directed single-cell fate mapping.","publication_venue":"Nature Methods","citations":777,"repo_stars":459,"repo_pushed":"2026-10-14","benchmarks":["luo-2026-velocity-benchmark"],"benchmark_refs":[{"id":"luo-2026-velocity-benchmark","name":"Luo et al. 2026, RNA velocity benchmark (15 methods, 17 datasets)","url":"https://doi.org/10.1016/j.crmeth.2026.101367"}],"review":"22-concepts-downstream#cellrank","tags":["fate-mapping","rna-velocity","scverse"],"site":"https://cellrank.org"},{"id":"cellity","name":"cellity","kind":"tool","layer":"core","categories":["damaged-cells","qc-metrics-thresholds"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Support vector machine trained on over 20 biological and technical features, with microscopy-annotated broken, empty and multiple-cell capture sites as labels, that classifies low-quality cells","recovers":"none; removes broken and empty captures that count thresholds miss","gain":"over 30% higher classification accuracy than traditional threshold methods on about 5,000 Fluidigm C1 cells (CD4+ T cells, BMDCs, mESCs); SVM specificity 20-30% higher than unsupervised alternatives","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Trained on C1 plate data with imaging ground truth; transfer to droplet data is untested. Repository last updated 2016, though the package remains in Bioconductor (release 3.23).","url":"https://bioconductor.org/packages/cellity","repo_url":"https://github.com/Teichlab/cellity","language":"R","doi":"10.1186/s13059-016-0888-1","pmid":"26887813","cite_title":"Classification of low quality cells from single-cell RNA-seq data","year":"2016","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-016-0888-1","publication_url":"https://doi.org/10.1186/s13059-016-0888-1","publication_title":"Classification of low quality cells from single-cell RNA-seq data","publication_venue":"Genome biology","citations":691,"repo_stars":38,"repo_pushed":"2016-07-26","review":"13-metrics-guides-multimodal#cellity","tags":["plate","supervised","ground-truth-imaging"],"site":"https://bioconductor.org/packages/cellity"},{"id":"denisenko-2020","name":"Denisenko et al. 2020 dissociation and storage biases","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Compared cold and warm dissociation, fresh, cryopreserved and methanol-fixed cells, and three single-nucleus workflows on adult mouse kidney","gain":"cold dissociation recovered 330 podocytes (2.78%) against 3 (0.03%) warm; warm dissociation induced stress genes; cryopreservation gave about 30% fewer high-quality cells; nuclei gave more genes (median 1,819 vs 981) but fewer immune cells (0.73% vs 6.03%)","gain_source":"independent","caveats":"One tissue (mouse kidney).","doi":"10.1186/s13059-020-02048-6","pmid":"32487174","cite_title":"Systematic assessment of tissue dissociation and storage biases in single-cell and single-nucleus RNA-seq workflows","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02048-6","publication_url":"https://doi.org/10.1186/s13059-020-02048-6","publication_title":"Systematic assessment of tissue dissociation and storage biases in single-cell and single-nucleus RNA-seq workflows","publication_venue":"Genome biology","citations":684,"review":"12-doublets-stress-batch#denisenko-2020","tags":["dissociation","cryopreservation","nuclei","kidney"]},{"id":"scdblfinder","name":"scDblFinder","kind":"tool","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"benchmarked-sota","summary":"Classifies cells against artificial doublets generated from cluster pairs with gradient-boosted trees, using the expected doublet rate as a prior","recovers":"singlets that a cruder doublet filter or a high-UMI cut-off would discard; cleaner clusters","gain":"Xi & Li 2021 protocol extension: highest mean AUPRC and AUROC on 16 real datasets with annotated doublets; singletCode 2024 replicated it as best on those datasets","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Targets heterotypic doublets (its vignette reports low performance on homotypic ones); on lineage-barcoded ground-truth singlets all detectors were weak (mean AUPRC 0.13-0.34) and scDblFinder lowest (singletCode 2024), so in single-line drug screens most doublets are homotypic and need tags or genotypes. Run per capture lane (vignette: doublets only arise within a capture). ATAC mode aggregates correlated peaks instead of selecting features; the authors compared it with AMULET on three snATAC datasets and offer a Fisher combination of the two (F1000 v2). Demuxafy 2024 found scDblFinder and Scrublet the detectors most affected by added ambient RNA. Call doublets before decontX or SoupX correction; ambient correction first lowered detection (Meier 2026, preprint).","url":"https://bioconductor.org/packages/scDblFinder","repo_url":"https://github.com/plger/scDblFinder","language":"R","doi":"10.12688/f1000research.73600.2","pmid":"35814628","cite_title":"Doublet identification in single-cell sequencing data using scDblFinder","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.12688/f1000research.73600.2","publication_url":"https://doi.org/10.12688/f1000research.73600.2","publication_title":"Doublet identification in single-cell sequencing data using scDblFinder","publication_venue":"F1000Research","citations":668,"citations_total":864,"citations_papers":4,"repo_stars":274,"repo_pushed":"2026-10-18","benchmarks":["xi-li-2021-doublet-protocol","neavin-2024-demuxafy-benchmark","zhang-2024-singletcode","ttoouli-2025-multiplets","meier-2026-ambient-doublet-order"],"benchmark_refs":[{"id":"xi-li-2021-doublet-protocol","name":"Xi and Li 2021, doublet-detection benchmark protocol (scDblFinder added)","url":"https://doi.org/10.1016/j.xpro.2021.100699"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"zhang-2024-singletcode","name":"Zhang et al. 2024 (singletCode), doublet detectors on barcoded ground truth","url":"https://doi.org/10.1016/j.xgen.2024.100592"},{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"},{"id":"meier-2026-ambient-doublet-order","name":"Meier et al. 2026, ambient correction order and doublet detection (preprint)","url":"https://doi.org/10.64898/2026.10.13.758369"}],"review":"02-calling-qc-damaged#scdblfinder","tags":["best-practice","heterotypic","atac"],"site":"https://bioconductor.org/packages/scDblFinder"},{"id":"abdelaal-2019","name":"Abdelaal et al. 2019, automatic cell identification benchmark","kind":"evidence","layer":"adjacent","categories":["clustering-annotation"],"side":"neutral","tier":"standard","summary":"Benchmark of 22 supervised cell-type classifiers on 27 datasets for intra-dataset and inter-dataset prediction, feature sensitivity, cell number and annotation depth","gain":"General-purpose linear SVM best overall; most classifiers did well but lost accuracy with overlapping classes and deep annotation; with stratified downsampling to under 500 cells most classifiers kept high performance","gain_source":"independent","requires":["reference"],"caveats":"Predates CellTypist and Azimuth; the SVM-with-rejection result shows that accuracy can be bought with unlabelled cells (28.9% unlabelled at full size).","url":"https://github.com/tabdelaal/scRNAseq_Benchmark","repo_url":"https://github.com/tabdelaal/scRNAseq_Benchmark","language":"multiple","doi":"10.1186/s13059-019-1795-z","pmid":"31500660","cite_title":"A comparison of automatic cell identification methods for single-cell RNA sequencing data.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1795-z","publication_url":"https://doi.org/10.1186/s13059-019-1795-z","publication_title":"A comparison of automatic cell identification methods for single-cell RNA sequencing data.","publication_venue":"Genome biology","citations":625,"repo_stars":195,"repo_pushed":"2022-06-09","review":"21-concepts-preprocessing#abdelaal-2019","tags":["benchmark","classifier"]},{"id":"decontx","name":"DecontX (celda / decontX)","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"benchmarked-sota","summary":"Bayesian mixture model that splits each cell's counts into native and contaminating parts using cell clusters, optionally with the empty-droplet profile","recovers":"cell-level native counts without discarding cells; works when only a filtered matrix exists","gain":"Cargnelli 2026: the only method of seven that did not reduce cell-type recovery; Nie 2026: best preservation of per-cell contamination ranking (with scAR) and named most accurate contamination estimate in the abstract; Janssen 2023: Slc34a1 outside PT 60% -> 2%; Schroeder 2026 (preprint): with scCDC, the only tool usable on non-droplet platforms without a raw matrix","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Default mode failed on one single-nucleus replicate (87% residual, Janssen 2023); under-corrects highly contaminating genes (scCDC 2024); over-corrects when no ambient is present in full mode (Cargnelli 2026); rank robustness falls with depth (Nie 2026). Correcting with decontX before doublet detection retained the largest share of doublets, because it removes proportionally more counts from doublets (Meier 2026, preprint).","url":"https://bioconductor.org/packages/decontX","repo_url":"https://github.com/campbio/decontX","language":"R","doi":"10.1186/s13059-020-1950-6","pmid":"32138770","cite_title":"Decontamination of ambient RNA in single-cell RNA-seq with DecontX","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-1950-6","publication_url":"https://doi.org/10.1186/s13059-020-1950-6","publication_title":"Decontamination of ambient RNA in single-cell RNA-seq with DecontX","publication_venue":"Genome biology","citations":624,"citations_total":691,"citations_papers":6,"repo_stars":69,"repo_pushed":"2026-10-09","benchmarks":["janssen-2023-background-noise","cargnelli-2026-ambient-benchmark","nie-2026-ambient-benchmark","schroeder-2026-ambient-benchmark","meier-2026-ambient-doublet-order"],"benchmark_refs":[{"id":"janssen-2023-background-noise","name":"Janssen et al. 2023, background noise and its removal","url":"https://doi.org/10.1186/s13059-023-02978-x"},{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"},{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"},{"id":"meier-2026-ambient-doublet-order","name":"Meier et al. 2026, ambient correction order and doublet detection (preprint)","url":"https://doi.org/10.64898/2026.10.13.758369"}],"review":"02-calling-qc-damaged#decontx","tags":["droplet","cpu"],"site":"https://bioconductor.org/packages/decontX"},{"id":"hicks-2018","name":"Hicks et al. 2018 technical variability and confounded batches","kind":"evidence","layer":"core","categories":["batch-and-plate-effects"],"side":"neutral","tier":"published-unbenchmarked","summary":"Reanalysed published scRNA-seq studies and showed that systematic technical variation, including batch confounded with biology, explains a substantial share of cell-to-cell variability and the proportion of zeros","gain":"none (cautionary finding)","gain_source":"independent","doi":"10.1093/biostatistics/kxx053","pmid":"29121214","cite_title":"Missing data and technical variability in single-cell RNA-sequencing experiments","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1093/biostatistics/kxx053","publication_url":"https://doi.org/10.1093/biostatistics/kxx053","publication_title":"Missing data and technical variability in single-cell RNA-sequencing experiments","publication_venue":"Biostatistics","citations":623,"review":"12-doublets-stress-batch#hicks-2018","tags":["design","confounding"]},{"id":"totalvi","name":"totalVI (scvi-tools)","kind":"tool","layer":"adjacent","categories":["multimodal","integration"],"side":"both","tier":"benchmarked-sota","summary":"Deep generative model of CITE-seq RNA and protein counts that models protein background and batch effects explicitly, for joint embedding, integration of panels, imputation and differential expression","gain":"Hu 2024 (14 prediction and 18 integration algorithms, 47 datasets): totalVI with scArches best overall for predicting protein abundance, and totalVI with UINMF best in horizontal and mosaic integration (abstract)","gain_source":"independent","requires":["protein","filtered-matrix"],"caveats":"Background is modelled per cell rather than measured from empty droplets as dsb does; GPU preferred for large data. Part of the scvi-tools library [[scvi-tools]]; Hu 2024 ran totalVI 0.17.4 for prediction and 0.19.0 for integration (authors' repository QuKunLab/MultiomeBenchmarking)","url":"https://scvi-tools.org","repo_url":"https://github.com/scverse/scvi-tools","language":"Python","doi":"10.1038/s41592-020-01050-x","pmid":"33589839","cite_title":"Joint probabilistic modeling of single-cell multi-omic data with totalVI.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-020-01050-x","publication_url":"https://doi.org/10.1038/s41592-020-01050-x","publication_title":"Joint probabilistic modeling of single-cell multi-omic data with totalVI.","publication_venue":"Nature Methods","citations":591,"repo_stars":1717,"repo_pushed":"2026-10-22","benchmarks":["hu-2024-multiomics-benchmark"],"benchmark_refs":[{"id":"hu-2024-multiomics-benchmark","name":"Hu et al. 2024, multi-omics prediction and integration benchmark","url":"https://doi.org/10.1038/s41592-024-02429-w"}],"review":"22-concepts-downstream#totalvi","tags":["cite-seq","scverse"],"site":"https://scvi-tools.org"},{"id":"voom-quality-weights","name":"voomWithQualityWeights (limma sample weights)","kind":"method","layer":"core","categories":["low-cell-stats"],"side":"additive","tier":"standard","summary":"limma models a variance factor per sample (or per group) and combines it with voom observation weights, so noisy samples such as pseudobulks from few cells are down-weighted instead of removed","recovers":"Power from samples that would otherwise be discarded as low quality","gain":"Down-weighting variable samples gave a more powerful analysis with fewer false discoveries than removing them or weighting equally, in simulations and RNA-seq data","gain_source":"self-reported","requires":["replicates"],"caveats":"Weights are estimated from residuals, so they need residual degrees of freedom; with 1-2 replicates per condition they are unstable. A sample that differs for biological reasons can be down-weighted. dreamlet's cell-count weights are an a priori alternative.","url":"https://bioconductor.org/packages/limma","language":"R","doi":"10.1093/nar/gkv412","pmid":"25925576","cite_title":"Why weight? Modelling sample and observational level variability improves power in RNA-seq analyses.","year":"2015","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkv412","publication_url":"https://doi.org/10.1093/nar/gkv412","publication_title":"Why weight? Modelling sample and observational level variability improves power in RNA-seq analyses.","publication_venue":"Nucleic Acids Research","citations":582,"review":"03-low-cell-stats#voom-quality-weights","tags":["precision-weights","limma"],"site":"https://bioconductor.org/packages/limma"},{"id":"concept-multimodal","name":"Multimodal single-cell data (CITE-seq, multiome)","kind":"concept","layer":"adjacent","categories":["multimodal"],"side":"neutral","tier":"standard","summary":"Measuring and jointly analysing more than one molecular layer per cell, such as RNA with surface protein (CITE-seq) or with chromatin accessibility (multiome), each with its own background, depth and QC metrics","caveats":"Each modality has its own noise model: antibody counts carry ambient and non-specific background, ATAC is sparse with a narrow dynamic range, so RNA-centred QC and doublet calling do not transfer directly","doi":"10.1038/s12276-020-0420-2","pmid":"32929225","cite_title":"Single-cell multiomics: technologies and data analysis methods.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s12276-020-0420-2","publication_url":"https://doi.org/10.1038/s12276-020-0420-2","publication_title":"Single-cell multiomics: technologies and data analysis methods.","publication_venue":"Experimental & Molecular Medicine","citations":522,"citations_total":17089,"citations_papers":4,"review":"22-concepts-downstream#concept-multimodal","tags":["concept","cite-seq","multiome"]},{"id":"kallisto-bustools","name":"kallisto | bustools (kb-python)","kind":"tool","layer":"core","categories":["alignment-quantification"],"side":"neutral","tier":"benchmarked","summary":"Pseudoalignment of reads to a transcriptome (or nascent plus mature, 'nac', index) written to BUS files, with barcode correction, UMI collapsing and counting in bustools, wrapped by kb-python","recovers":"speed and constant memory; higher gene detection per cell than Cell Ranger in many non-model organisms (Shainer 2021)","gain":"Shainer 2021 (22 public 10x datasets, 8 organisms): higher alignment and gene detection rates than Cell Ranger; in zebrafish pineal data it resolved an extra photoreceptor type; Bruning 2022: 4-6x faster than Cell Ranger 6; Du 2020: ~4x faster and 7.7x less memory than STAR","gain_source":"independent","requires":["fastq"],"caveats":"Older spliced-only indices gave spurious genes: extra Vmn and Olfr genes and many low-gene, unlabelled barcodes (Bruning 2022), mean relative false-positive expression 0.328 per cell in the alevin-fry simulation (competitor); v0.39.3 was unsuitable for 6-bp-UMI CEL-Seq2 data and emptyDrops on its 10x output called ~60,000 cells against ~3,000 expected (You 2021). Fewer genes and lower expression than STAR (Du 2020). The 2025 nac index with distinguishing flanking k-mers targets these problems but has no independent benchmark.","url":"https://www.kallistobus.tools","repo_url":"https://github.com/pachterlab/kb_python","language":"multiple","doi":"10.1038/s41587-021-00870-2","pmid":"33795888","cite_title":"Modular, efficient and constant-memory single-cell RNA-seq preprocessing","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-021-00870-2","publication_url":"https://doi.org/10.1038/s41587-021-00870-2","publication_title":"Modular, efficient and constant-memory single-cell RNA-seq preprocessing","publication_venue":"Nature Biotechnology","citations":511,"citation_note":"1 listed paper(s) had no citation count","citations_total":520,"citations_papers":2,"repo_stars":193,"repo_pushed":"2026-10-08","benchmarks":["bruning-2022-aligner-benchmark","you-2021-preprocessing-benchmark","du-2020-star-kallisto","shainer-2021-kallisto-cellranger"],"benchmark_refs":[{"id":"bruning-2022-aligner-benchmark","name":"Brüning et al. 2022, single-cell aligner comparison","url":"https://doi.org/10.1093/gigascience/giac001"},{"id":"you-2021-preprocessing-benchmark","name":"You et al. 2021, UMI preprocessing workflow benchmark","url":"https://doi.org/10.1186/s13059-021-02552-3"},{"id":"du-2020-star-kallisto","name":"Du et al. 2020, STAR versus kallisto on scRNA-seq","url":"https://doi.org/10.1534/g3.120.401160"},{"id":"shainer-2021-kallisto-cellranger","name":"Shainer & Stemmer 2021, kallisto versus Cell Ranger across organisms","url":"https://doi.org/10.1186/s12864-021-07930-6"}],"review":"11-quant-calling-ambient#kallisto-bustools","tags":["pseudoalignment","nuclei","low-memory","non-model"],"site":"https://www.kallistobus.tools"},{"id":"muscat","name":"muscat","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"additive","tier":"standard","summary":"Bioconductor package for differential state analysis in multi-sample, multi-condition data: pseudobulk aggregation with edgeR/DESeq2/limma, cell-level mixed models, and a reference-based simulator","recovers":"Subpopulation-specific condition effects tested at the replicate level","gain_source":"none","requires":["filtered-matrix","replicates"],"caveats":"pbDS default min_cells = 10 per cluster-sample, so small wells drop out unless lowered. Junttila 2022 found muscat_MM inferior; the dreamlet authors report inflated false positives for muscat's limma-voom path in permuted-label tests. Its simulator is used by several later benchmarks.","url":"https://bioconductor.org/packages/muscat","repo_url":"https://github.com/HelenaLC/muscat","language":"R","doi":"10.1038/s41467-020-19894-4","pmid":"33257685","cite_title":"muscat detects subpopulation-specific state transitions from multi-sample multi-condition single-cell transcriptomics data.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-020-19894-4","publication_url":"https://doi.org/10.1038/s41467-020-19894-4","publication_title":"muscat detects subpopulation-specific state transitions from multi-sample multi-condition single-cell transcriptomics data.","publication_venue":"Nature Communications","citations":511,"repo_stars":247,"repo_pushed":"2026-07-06","benchmarks":["squair-2021-de-benchmark","junttila-2022-ds-benchmark"],"benchmark_refs":[{"id":"squair-2021-de-benchmark","name":"Squair et al. 2021, single-cell differential expression against matched bulk","url":"https://doi.org/10.1038/s41467-021-25960-2"},{"id":"junttila-2022-ds-benchmark","name":"Junttila et al. 2022, multi-subject differential state benchmark","url":"https://doi.org/10.1093/bib/bbac286"}],"review":"03-low-cell-stats#muscat","tags":["pseudobulk","simulation","bioconductor"],"site":"https://bioconductor.org/packages/muscat"},{"id":"kbet","name":"kBET (k-nearest-neighbour batch-effect test)","kind":"tool","layer":"core","categories":["batch-and-plate-effects","integration"],"side":"neutral","tier":"standard","summary":"Tests whether the batch composition of each cell's neighbourhood matches the global composition and reports a rejection rate; the same package includes a principal-component regression on batch","gain_source":"none","requires":["filtered-matrix"],"caveats":"Sensitive to cell-type composition differences between batches, which it reads as batch effect; one of the scIB integration metrics; slow on large data without subsampling.","url":"https://github.com/theislab/kBET","repo_url":"https://github.com/theislab/kBET","language":"R","doi":"10.1038/s41592-018-0254-1","pmid":"30573817","cite_title":"A test metric for assessing single-cell RNA-seq batch correction","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-018-0254-1","publication_url":"https://doi.org/10.1038/s41592-018-0254-1","publication_title":"A test metric for assessing single-cell RNA-seq batch correction","publication_venue":"Nature Methods","citations":510,"repo_stars":181,"repo_pushed":"2024-01-26","review":"12-doublets-stress-batch#kbet","tags":["metric","diagnostic"]},{"id":"souporcell","name":"souporcell","kind":"tool","layer":"core","categories":["demux-genotype","doublets","ambient-rna"],"side":"both","tier":"benchmarked-sota","summary":"Genotype-free demultiplexer that calls variants from the pooled reads, clusters cells by allele counts with an explicit ambient-RNA term, and flags cross-genotype doublets","recovers":"donor or cell-line labels for every cell with enough variant reads, independent of tags; an ambient RNA estimate","gain":"Independent (Demuxafy): with vireo, unaffected by simulated ambient RNA in pools of up to 16 donors, but performance drops above 32 donors. Self-reported: 6 612 of 6 622 singlets and 415 of 451 doublets correct in a synthetic mixture; a minority sample resolved down to 0.6% of cells","gain_source":"independent","requires":["bam","genotypes"],"caveats":"Produced wrong genotype clusters at high true-doublet rates (HTOreader's 9-donor pool; a renal cancer dataset at 16-24% doublets in demuxSNP); the number of genotypes must be given; Fu 2025 rated it jointly best overall with vireo, though vireo was more accurate and faster, and hadge 2024 placed it in the consistent top group with vireo, demuxlet and freemuxlet; Souporcell3 (2026) targets up to 64 donors","url":"https://github.com/wheaton5/souporcell","repo_url":"https://github.com/wheaton5/souporcell","language":"multiple","doi":"10.1038/s41592-020-0820-1","pmid":"32366989","cite_title":"Souporcell: robust clustering of single-cell RNA-seq data by genotype without reference genotypes.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-020-0820-1","publication_url":"https://doi.org/10.1038/s41592-020-0820-1","publication_title":"Souporcell: robust clustering of single-cell RNA-seq data by genotype without reference genotypes.","publication_venue":"Nature Methods","citations":502,"citations_total":505,"citations_papers":2,"repo_stars":215,"repo_pushed":"2026-04-30","benchmarks":["fu-2025-snrna-genetic-benchmark","neavin-2024-demuxafy-benchmark","curion-2024-hadge-comparison","fiorini-2025-ensemblex-benchmark"],"benchmark_refs":[{"id":"fu-2025-snrna-genetic-benchmark","name":"Fu et al. 2025, genetic demultiplexing for snRNA-seq","url":"https://doi.org/10.1093/bib/bbaf371"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"},{"id":"fiorini-2025-ensemblex-benchmark","name":"Fiorini et al. 2025 (Ensemblex), genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-025-03643-1"}],"review":"01-demux-recovery#souporcell","tags":["genotype","reference-free","cell-lines","ambient"]},{"id":"concept-integration","name":"Data integration and batch correction","kind":"concept","layer":"adjacent","categories":["integration"],"side":"neutral","tier":"standard","summary":"Mapping cells from several samples, lanes, protocols or studies into a shared space so that technical batch differences are removed while cell identities and states are kept","caveats":"Integration removes whatever is declared as batch, and over-correction removes biology; scIB found that scaling raised batch removal in 79% of comparisons while lowering bio-conservation in 72%.","doi":"10.1038/s41587-021-00895-7","pmid":"33941931","cite_title":"Computational principles and challenges in single-cell data integration.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-021-00895-7","publication_url":"https://doi.org/10.1038/s41587-021-00895-7","publication_title":"Computational principles and challenges in single-cell data integration.","publication_venue":"Nature Biotechnology","citations":470,"citations_total":3735,"citations_papers":3,"review":"21-concepts-preprocessing#concept-integration","tags":["concept","batch-correction"]},{"id":"townes-2019","name":"scry deviance feature selection and GLM-PCA","kind":"tool","layer":"adjacent","categories":["feature-selection","normalisation"],"side":"neutral","tier":"benchmarked-sota","summary":"Ranks genes by binomial or multinomial deviance on raw UMI counts and reduces dimension with GLM-PCA, avoiding log-normalisation of counts","gain":"pipeComp: deviance gave the best gene ranking for feature selection (independent); self-reported: outperformed log-CPM plus HVG in ground-truth clustering","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Shows that the fraction of zeros per cell drives PC1 under log-CPM; GLM-PCA is slower than PCA. Zappia 2025 found Seurat-VST HVGs top-ranked for integration; scry's rank there not extracted.","url":"https://bioconductor.org/packages/scry","language":"R","doi":"10.1186/s13059-019-1861-6","pmid":"31870412","cite_title":"Feature selection and dimension reduction for single-cell RNA-Seq based on a multinomial model.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1861-6","publication_url":"https://doi.org/10.1186/s13059-019-1861-6","publication_title":"Feature selection and dimension reduction for single-cell RNA-Seq based on a multinomial model.","publication_venue":"Genome biology","citations":470,"citations_total":477,"citations_papers":2,"benchmarks":["germain-2020-pipecomp","zappia-2025-feature-selection-benchmark"],"benchmark_refs":[{"id":"germain-2020-pipecomp","name":"Germain et al. 2020 (pipeComp), preprocessing pipeline benchmark","url":"https://doi.org/10.1186/s13059-020-02136-7"},{"id":"zappia-2025-feature-selection-benchmark","name":"Zappia et al. 2025, feature selection for integration benchmark","url":"https://doi.org/10.1038/s41592-025-02624-3"}],"review":"21-concepts-preprocessing#townes-2019","tags":["deviance","glm-pca","bioconductor"],"site":"https://bioconductor.org/packages/scry"},{"id":"concept-normalisation","name":"Normalisation and variance-stabilising transformation","kind":"concept","layer":"adjacent","categories":["normalisation"],"side":"neutral","tier":"standard","summary":"Adjusting each cell's counts for its sampling efficiency (size factors) and transforming them so that variance is comparable across the expression range, usually by a shifted logarithm, Pearson residuals or a count model","caveats":"Ahlmann-Eltze and Huber 2023 found the shifted logarithm of size-factor-scaled counts followed by PCA as good as or better than 21 alternatives; method choice matters less than the input it receives from QC.","doi":"10.1038/nmeth.4292","pmid":"28504683","cite_title":"Normalizing single-cell RNA sequencing data: challenges and opportunities.","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1038/nmeth.4292","publication_url":"https://doi.org/10.1038/nmeth.4292","publication_title":"Normalizing single-cell RNA sequencing data: challenges and opportunities.","publication_venue":"Nature Methods","citations":436,"citations_total":4324,"citations_papers":4,"review":"21-concepts-preprocessing#concept-normalisation","tags":["concept","size-factors","transformation"]},{"id":"starsolo","name":"STARsolo","kind":"tool","layer":"core","categories":["alignment-quantification","cell-calling"],"side":"neutral","tier":"benchmarked-sota","summary":"Single-cell mode built into the STAR aligner that does barcode and UMI correction, gene, intron-inclusive (GeneFull) and velocity counting, optional multi-gene read allocation and Cell Ranger-like cell filtering in one pass","recovers":"reads from genes with multi-mapping loci (EM or uniform allocation) that unique-only counting drops; intronic counts for nuclei","gain":"Kuijpers 2024 (8 SPLiT-seq pipelines): nearly identical to Parse splitpipe and one of two recommended; Du 2020: STAR detected more genes and agreed better with RNA-FISH than kallisto on Drop-seq, Fluidigm and 10x data; preprint: replicates Cell Ranger and is considerably faster (self-reported)","gain_source":"independent","requires":["fastq"],"caveats":"Uses more memory than lightweight mappers (~6.3x alevin-fry in the alevin-fry paper); default --soloCellFilter is the Cell Ranger 2.2 knee, and its EmptyDrops_CR mode hard-codes Cell Ranger limits (umiMin 500) so very low-RNA barcodes are never tested; multi-gene reads are discarded unless --soloMultiMappers is set; lacks random-hexamer read collapsing for SPLiT-seq (Kuijpers 2024); primary paper is a preprint.","url":"https://github.com/alexdobin/STAR/blob/master/docs/STARsolo.md","repo_url":"https://github.com/alexdobin/STAR","language":"C++","doi":"10.1101/2021.05.05.442755","cite_title":"STARsolo: accurate, fast and versatile mapping/quantification of single-cell and single-nucleus RNA-seq data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1101/2021.05.05.442755","publication_url":"https://doi.org/10.1101/2021.05.05.442755","publication_is_preprint":true,"publication_title":"STARsolo: accurate, fast and versatile mapping/quantification of single-cell and single-nucleus RNA-seq data","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":432,"citations_total":554,"citations_papers":4,"repo_stars":2273,"repo_pushed":"2025-03-18","benchmarks":["bruning-2022-aligner-benchmark","du-2020-star-kallisto","kuijpers-2024-splitseq-pipelines"],"benchmark_refs":[{"id":"bruning-2022-aligner-benchmark","name":"Brüning et al. 2022, single-cell aligner comparison","url":"https://doi.org/10.1093/gigascience/giac001"},{"id":"du-2020-star-kallisto","name":"Du et al. 2020, STAR versus kallisto on scRNA-seq","url":"https://doi.org/10.1534/g3.120.401160"},{"id":"kuijpers-2024-splitseq-pipelines","name":"Kuijpers et al. 2024, SPLiT-seq pipeline comparison","url":"https://doi.org/10.1186/s12864-024-10285-3"}],"review":"11-quant-calling-ambient#starsolo","tags":["preprint","nuclei","multimapping","velocity","split-pool"]},{"id":"transcription-inhibitor-dissociation","name":"Transcription and translation inhibitors during dissociation (Act-seq, Marsh 2022 cocktail)","kind":"design","layer":"core","categories":["cell-cycle-and-stress","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Adds actinomycin D, triptolide and anisomycin (or actinomycin D alone in Act-seq) during enzymatic digestion so ex vivo immediate-early and stress genes cannot be induced","gain":"abolished the ex vivo activated microglia (exAM) cluster (Fos, Jun, Hspa1a, Dusp1, Ccl3, Ccl4) seen after inhibitor-free digestion; no differentially expressed genes between mechanical dissociation with and without inhibitors (self-reported)","gain_source":"self-reported","caveats":"The same signature appears in postmortem human snRNA-seq, where it cannot be prevented, and was induced in resected human brain by elevated temperature ex vivo; validated mainly in brain myeloid cells.","doi":"10.1038/s41593-022-01022-8","pmid":"35260865","cite_title":"Dissection of artifactual and confounding glial signatures by single-cell sequencing of mouse and human brain","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41593-022-01022-8","publication_url":"https://doi.org/10.1038/s41593-022-01022-8","publication_title":"Dissection of artifactual and confounding glial signatures by single-cell sequencing of mouse and human brain","publication_venue":"Nature Neuroscience","citations":432,"citations_total":870,"citations_papers":2,"review":"12-doublets-stress-batch#transcription-inhibitor-dissociation","tags":["dissociation","microglia","bench"]},{"id":"mashr","name":"mashr (multivariate adaptive shrinkage)","kind":"tool","layer":"core","categories":["low-cell-stats"],"side":"additive","tier":"published-unbenchmarked","summary":"Fits data-driven covariance patterns of effects across many conditions and returns shrunken effect estimates and local false sign rates per condition","recovers":"Effects in conditions that are underpowered alone but share effect patterns with related conditions (drugs of one class, doses of one drug)","gain":"GTEx eQTLs in 44 tissues: 47% of 707,036 top-SNP effects significant at lfsr < 0.05 with mash vs 13% for condition-by-condition ash and 39% for mash-bmalite","gain_source":"self-reported","requires":["multiple-conditions"],"caveats":"Needs per-condition effects and standard errors that are themselves valid, ideally from replicate-level pseudobulk. Contrasts against one shared vehicle control have correlated errors; mashr handles this through a reference condition in mash_update_data (common-baseline vignette). No single-cell drug-screen benchmark found.","url":"https://stephenslab.github.io/mashr/","repo_url":"https://github.com/stephenslab/mashr","language":"R","doi":"10.1038/s41588-018-0268-8","pmid":"30478440","cite_title":"Flexible statistical methods for estimating and testing effects in genomic studies with multiple conditions.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41588-018-0268-8","publication_url":"https://doi.org/10.1038/s41588-018-0268-8","publication_title":"Flexible statistical methods for estimating and testing effects in genomic studies with multiple conditions.","publication_venue":"Nature Genetics","citations":420,"repo_stars":102,"repo_pushed":"2024-11-07","review":"03-low-cell-stats#mashr","tags":["shrinkage","multi-condition","drug-screen"],"site":"https://stephenslab.github.io/mashr/"},{"id":"cyclone","name":"cyclone (scran)","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"standard","summary":"Pair-based classifier that assigns G1, S or G2/M from the sign of expression differences within marker gene pairs trained on sorted mouse ES cells; the OSCA default","gain":"a PCA-based approach and the custom pair-based predictor performed best of six classifiers on published data, given prior cell-cycle genes and rank-based normalisation (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Training set is mouse ES cells; CycleMix authors report poor performance on modern droplet data; slow on large datasets; not in the Guo & Chen 2024 comparison.","url":"https://bioconductor.org/packages/scran","repo_url":"https://github.com/MarioniLab/scran","language":"R","doi":"10.1016/j.ymeth.2015.06.021","pmid":"26142758","cite_title":"Computational assignment of cell-cycle stage from single-cell transcriptome data","year":"2015","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.ymeth.2015.06.021","publication_url":"https://doi.org/10.1016/j.ymeth.2015.06.021","publication_title":"Computational assignment of cell-cycle stage from single-cell transcriptome data","publication_venue":"Methods","citations":409,"citations_total":409,"citations_papers":2,"repo_stars":48,"repo_pushed":"2026-05-20","review":"12-doublets-stress-batch#cyclone","tags":["bioconductor","osca","classifier"],"site":"https://bioconductor.org/packages/scran"},{"id":"cell-recovery-viability","name":"Cell recovery per condition as a viability readout","kind":"method","layer":"core","categories":["discarded-data","screen-design"],"side":"additive","tier":"published-unbenchmarked","summary":"Fits dose-response curves to the number of cells recovered per hashed condition to estimate drug toxicity alongside the transcriptome, as done in sci-Plex","recovers":"a viability phenotype from cell counts that would otherwise only set DE power","gain":"sci-Plex: viability scores from recovered counts concordant with gold-standard measurements; 52 of 188 compounds (27%) cut viability by 50% or more at the top dose; K562 bosutinib sensitivity confirmed by cell counting","gain_source":"self-reported","requires":["tag-counts","doses-or-time","multiple-conditions"],"caveats":"counts reflect hashing efficiency, QC thresholds and loading as well as survival; relative shares need a stable reference (vehicle wells or spike-in cells); Tahoe-100M reports cytotoxicity phenotypes but the method was not checked here","url":"https://doi.org/10.1126/science.aax6234","doi":"10.1126/science.aax6234","pmid":"31806696","cite_title":"Massively multiplex chemical transcriptomics at single-cell resolution","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1126/science.aax6234","publication_url":"https://doi.org/10.1126/science.aax6234","publication_title":"Massively multiplex chemical transcriptomics at single-cell resolution","publication_venue":"Science","citations":398,"citations_total":1122,"citations_papers":3,"review":"05-discarded-data#cell-recovery-viability","tags":["drug-screen","viability","cell-counts","hashing"],"site":"https://doi.org/10.1126/science.aax6234"},{"id":"sci-plex","name":"sci-Plex","kind":"design","layer":"core","categories":["screen-design","demux-combinatorial"],"side":"additive","tier":"published-unbenchmarked","summary":"Nuclear hashing with unmodified polyadenylated oligos combined with sci-RNA-seq3 combinatorial indexing, used to read thousands of independently treated wells in one experiment","recovers":"conditions per experiment, collision (doublet) flags from well hashes, and cell number per well as a viability readout","gain":"4,992 independently treated wells (188 compounds x 4 doses x 3 cell lines, in duplicate) and 649,340 cells in one experiment; median 100-200 cells per condition; replicate-well pseudobulk Pearson r = 0.99; hashes flagged 95.5% of interspecies collisions at collision rates of 7-23%","gain_source":"self-reported","requires":["fastq","tag-counts","multiple-conditions","doses-or-time"],"caveats":"Nuclei rather than whole cells, median 1,071-2,407 mRNA UMIs per cell in the 188-compound screen; collision rate is set by nuclei per final PCR well; lab-built protocol rather than a kit; no independent benchmark","url":"https://github.com/cole-trapnell-lab/sci-plex","repo_url":"https://github.com/cole-trapnell-lab/sci-plex","language":"R","doi":"10.1126/science.aax6234","pmid":"31806696","cite_title":"Massively multiplex chemical transcriptomics at single-cell resolution","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1126/science.aax6234","publication_url":"https://doi.org/10.1126/science.aax6234","publication_title":"Massively multiplex chemical transcriptomics at single-cell resolution","publication_venue":"Science","citations":398,"repo_stars":40,"repo_pushed":"2020-04-09","review":"04-screen-design#sci-plex","tags":["drug-screen","nuclei","hashing","combinatorial-indexing","fixed","dose-response"]},{"id":"sccoda","name":"scCODA","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","discarded-data","low-cell-stats"],"side":"neutral","tier":"standard","summary":"Bayesian hierarchical Dirichlet-multinomial model that tests cell-type composition changes relative to a reference cell type, with spike-and-slab selection controlling the false discovery rate","recovers":"composition changes, including drug-driven depletion, from few samples","gain":"own simulations: mean Matthews correlation 0.64, ahead of non-Bayesian methods at low replicate numbers (n = 2 per group scenarios)","gain_source":"self-reported","requires":["filtered-matrix","replicates"],"caveats":"results depend on the reference type, which must be stable across conditions; measures relative not absolute change; named in a best-practice guide that also notes composition methods lack an independent benchmark","url":"https://github.com/theislab/scCODA","repo_url":"https://github.com/theislab/scCODA","language":"Python","doi":"10.1038/s41467-021-27150-6","pmid":"34824236","cite_title":"scCODA is a Bayesian model for compositional single-cell data analysis","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-021-27150-6","publication_url":"https://doi.org/10.1038/s41467-021-27150-6","publication_title":"scCODA is a Bayesian model for compositional single-cell data analysis","publication_venue":"Nature Communications","citations":382,"citations_total":1426,"citations_papers":2,"repo_stars":203,"repo_pushed":"2026-01-13","review":"05-discarded-data#sccoda","tags":["composition","differential-abundance","bayesian","pertpy"]},{"id":"zumis","name":"zUMIs","kind":"tool","layer":"core","categories":["alignment-quantification"],"side":"neutral","tier":"benchmarked","summary":"STAR-based pipeline for UMI protocols (plate and droplet) that counts exonic and intronic reads separately and together, with optional downsampling to equal depth","recovers":"more genes and counts per cell from intronic reads","gain":"You 2021: recovered the most genes and counts across datasets and, with salmon alevin and scPipe, slightly higher silhouette widths on cell-line mixtures","gain_source":"independent","requires":["fastq"],"caveats":"You 2021: intron counts lowered correlation with other workflows and did not improve clustering; more lncRNA and pseudogene counts; emptyDrops on its 10x output called ~60,000 cells against ~3,000 expected. Slow on large SPLiT-seq data (Kuijpers 2024). Last code push 2024-07.","url":"https://github.com/sdparekh/zUMIs","repo_url":"https://github.com/sdparekh/zUMIs","language":"multiple","doi":"10.1093/gigascience/giy059","pmid":"29846586","cite_title":"zUMIs - A fast and flexible pipeline to process RNA sequencing data with UMIs","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1093/gigascience/giy059","publication_url":"https://doi.org/10.1093/gigascience/giy059","publication_title":"zUMIs - A fast and flexible pipeline to process RNA sequencing data with UMIs","publication_venue":"GigaScience","citations":380,"repo_stars":298,"repo_pushed":"2024-07-12","benchmarks":["you-2021-preprocessing-benchmark","kuijpers-2024-splitseq-pipelines"],"benchmark_refs":[{"id":"you-2021-preprocessing-benchmark","name":"You et al. 2021, UMI preprocessing workflow benchmark","url":"https://doi.org/10.1186/s13059-021-02552-3"},{"id":"kuijpers-2024-splitseq-pipelines","name":"Kuijpers et al. 2024, SPLiT-seq pipeline comparison","url":"https://doi.org/10.1186/s12864-024-10285-3"}],"review":"11-quant-calling-ambient#zumis","tags":["plate","intronic","smart-seq"]},{"id":"chari-pachter-2023","name":"Chari & Pachter 2023, distortion in 2D embeddings","kind":"evidence","layer":"adjacent","categories":["clustering-annotation"],"side":"neutral","tier":"published-unbenchmarked","summary":"Showed that reducing single-cell data from hundreds or thousands of dimensions to two inevitably distorts it, and that t-SNE and UMAP views are unreliable for quantitative or exploratory biological conclusions","gain_source":"none","requires":["filtered-matrix"],"caveats":"An argument against reading distances and cluster sizes off 2D embeddings, not a ban on using them to look; an erratum was published in 2025 (PLoS Comput Biol 21:e1013655).","url":"https://doi.org/10.1371/journal.pcbi.1011288","doi":"10.1371/journal.pcbi.1011288","pmid":"37590228","cite_title":"The specious art of single-cell genomics.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pcbi.1011288","publication_url":"https://doi.org/10.1371/journal.pcbi.1011288","publication_title":"The specious art of single-cell genomics.","publication_venue":"PLoS Computational Biology","citations":378,"review":"21-concepts-preprocessing#chari-pachter-2023","tags":["umap","tsne","embedding-distortion"],"site":"https://doi.org/10.1371/journal.pcbi.1011288"},{"id":"propeller","name":"propeller (speckle) and Scanpro","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","discarded-data","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"Tests cell-type proportion differences with logit or arcsine-square-root transformed proportions and limma empirical Bayes across biological replicates; Scanpro reimplements it in Python and adds bootstrapped pseudo-replicates for unreplicated designs","recovers":"replicate-aware composition shifts per condition","requires":["filtered-matrix","replicates"],"caveats":"propeller needs biological replicates; Scanpro pseudo-replicates cannot reproduce biological variance, so unreplicated tests are likely anticonservative; relative shares only","url":"https://github.com/phipsonlab/speckle","repo_url":"https://github.com/phipsonlab/speckle","language":"R","doi":"10.1093/bioinformatics/btac582","pmid":"36005887","cite_title":"propeller: testing for differences in cell type proportions in single cell data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btac582","publication_url":"https://doi.org/10.1093/bioinformatics/btac582","publication_title":"propeller: testing for differences in cell type proportions in single cell data","publication_venue":"Bioinformatics","citations":374,"citations_total":390,"citations_papers":2,"repo_stars":71,"repo_pushed":"2022-12-08","review":"05-discarded-data#propeller","tags":["composition","differential-abundance","limma","unreplicated"]},{"id":"tung-2017","name":"Tung et al. 2017 batch effects and study design","kind":"evidence","layer":"core","categories":["batch-and-plate-effects","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Three Fluidigm C1 replicates from each of three iPSC lines showed genotype as the largest source of variation but substantial variation between technical replicates, with UMI counts themselves affected by batch","gain":"none (cautionary finding); recommends designs where each batch contains every individual or condition","gain_source":"independent","doi":"10.1038/srep39921","pmid":"28045081","cite_title":"Batch effects and the effective design of single-cell gene expression studies","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1038/srep39921","publication_url":"https://doi.org/10.1038/srep39921","publication_title":"Batch effects and the effective design of single-cell gene expression studies","publication_venue":"Scientific Reports","citations":354,"review":"12-doublets-stress-batch#tung-2017","tags":["design","plate-based","ipsc"]},{"id":"swappeddrops","name":"swappedDrops (DropletUtils) barcode-swapping removal","kind":"tool","layer":"core","categories":["batch-and-plate-effects","ambient-rna"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Removes molecules whose cell barcode and UMI appear in more than one sample sequenced together, which are products of index swapping on patterned flow cells","gain":"about 2.5% of reads were swapped between samples on a HiSeq 4000 in plate-based data; swapping produced complex artefactual cell libraries in 10x data (self-reported)","gain_source":"self-reported","requires":["bam"],"caveats":"Needs molecule information for every sample in the sequencing pool; matters when samples share a lane, as in multiplexed screens sequenced together.","url":"https://bioconductor.org/packages/DropletUtils","repo_url":"https://github.com/MarioniLab/DropletUtils","language":"R","doi":"10.1038/s41467-018-05083-x","pmid":"29991676","cite_title":"Detection and removal of barcode swapping in single-cell RNA-seq data","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-018-05083-x","publication_url":"https://doi.org/10.1038/s41467-018-05083-x","publication_title":"Detection and removal of barcode swapping in single-cell RNA-seq data","publication_venue":"Nature Communications","citations":344,"repo_stars":68,"repo_pushed":"2026-09-24","review":"12-doublets-stress-batch#swappeddrops","tags":["index-hopping","sequencing-lane","bioconductor"],"site":"https://bioconductor.org/packages/DropletUtils"},{"id":"vireo","name":"vireo (with cellSNP-lite)","kind":"tool","layer":"core","categories":["demux-genotype","doublets"],"side":"both","tier":"benchmarked-sota","summary":"Bayesian variational model that assigns cells to donors from allele counts (cellSNP-lite pileups) with full, partial or no reference genotypes and calls between-donor doublets","recovers":"donor or cell-line labels independent of tags; doublets between genotypes","gain":"Most accurate and fastest of vireo, souporcell, freemuxlet and scSplit on simulated snRNA-seq pools (Fu 2025); best single method without reference genotypes at 16 or more donors (Demuxafy); on pooled tumours, 99.0-99.9% singlet recall with bulk RNA-seq genotypes and 99.2% of its doublet calls true versus 31.9% for demuxlet (Weber 2021)","gain_source":"independent","requires":["bam","genotypes"],"caveats":"Precision falls with doublets (100%, 85.9%, 77.4% at 0, 20, 30% doublets in Weber 2021); clustering can stall in local optima above ~16 donors (Souporcell3 authors); variant-caller pairing matters (60% recall for one cellSNP setting in Fu 2025)","url":"https://vireosnp.readthedocs.io","repo_url":"https://github.com/single-cell-genetics/vireo","language":"Python","doi":"10.1186/s13059-019-1865-2","pmid":"31836005","cite_title":"Vireo: Bayesian demultiplexing of pooled single-cell RNA-seq data without genotype reference.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1865-2","publication_url":"https://doi.org/10.1186/s13059-019-1865-2","publication_title":"Vireo: Bayesian demultiplexing of pooled single-cell RNA-seq data without genotype reference.","publication_venue":"Genome biology","citations":344,"repo_stars":105,"repo_pushed":"2025-04-11","benchmarks":["fu-2025-snrna-genetic-benchmark","weber-2021-cancer-genetic-demux","neavin-2024-demuxafy-benchmark","curion-2024-hadge-comparison","fiorini-2025-ensemblex-benchmark"],"benchmark_refs":[{"id":"fu-2025-snrna-genetic-benchmark","name":"Fu et al. 2025, genetic demultiplexing for snRNA-seq","url":"https://doi.org/10.1093/bib/bbaf371"},{"id":"weber-2021-cancer-genetic-demux","name":"Weber et al. 2021, genetic demultiplexing in cancer","url":"https://doi.org/10.1093/gigascience/giab062"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"},{"id":"fiorini-2025-ensemblex-benchmark","name":"Fiorini et al. 2025 (Ensemblex), genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-025-03643-1"}],"review":"01-demux-recovery#vireo","tags":["genotype","reference-free","cancer","cell-lines"],"site":"https://vireosnp.readthedocs.io"},{"id":"cold-protease-dissociation","name":"Cold-active protease dissociation (6 C)","kind":"design","layer":"core","categories":["cell-cycle-and-stress","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Dissociates tissue with a protease purified from a psychrophilic microorganism at 6 C or colder, so transcription is largely stopped while cells are released","gain":"large reduction of 37 C dissociation artefacts in 20,424 P1 mouse kidney cells (self-reported); O'Flanagan 2019 and Denisenko 2020 independently confirmed lower stress signatures with cold dissociation","gain_source":"self-reported","caveats":"Slower and less complete digestion for some tissues; Denisenko found cell-type recovery shifts in both directions.","doi":"10.1242/dev.151142","pmid":"28851704","cite_title":"Psychrophilic proteases dramatically reduce single-cell RNA-seq artifacts: a molecular atlas of kidney development","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1242/dev.151142","publication_url":"https://doi.org/10.1242/dev.151142","publication_title":"Psychrophilic proteases dramatically reduce single-cell RNA-seq artifacts: a molecular atlas of kidney development","publication_venue":"Development","citations":343,"citations_total":1303,"citations_papers":3,"review":"12-doublets-stress-batch#cold-protease-dissociation","tags":["dissociation","bench","kidney"]},{"id":"pseudobulk-vs-mixed-debate","name":"Pseudobulk vs mixed models: Zimmerman 2021, Murphy & Skene 2022 and reply","kind":"evidence","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"Exchange over whether generalized linear mixed models with a random effect per sample or pseudobulk give more power at controlled type 1 error in hierarchical single-cell data","gain":"Murphy & Skene: at equal type 1 error, pseudobulk mean had sensitivity >0.9 while all other methods had <0.9 (hierarchicell simulation, 5-40 individuals, 50-500 cells); Zimmerman: pseudobulk conservative and underpowered vs GLMM/MAST_RE","gain_source":"independent","requires":["replicates"],"caveats":"Both sides used the same simulator. The reply notes MCC can reward tests whose type 1 error exceeds 0.50. All agree cell-level tests without a sample term inflate type 1 error, and ComBat on the sample variable makes it worse. Lee 2024 proved count pseudobulk with a proper offset has the same point estimates and standard errors as a GLMM, more than 10x faster.","url":"https://doi.org/10.1038/s41467-021-21038-1","doi":"10.1038/s41467-021-21038-1","pmid":"33531494","cite_title":"A practical solution to pseudoreplication bias in single-cell studies.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-021-21038-1","publication_url":"https://doi.org/10.1038/s41467-021-21038-1","publication_title":"A practical solution to pseudoreplication bias in single-cell studies.","publication_venue":"Nature Communications","citations":326,"citations_total":494,"citations_papers":5,"review":"03-low-cell-stats#pseudobulk-vs-mixed-debate","tags":["pseudoreplication","mixed-models","dispute"],"site":"https://doi.org/10.1038/s41467-021-21038-1"},{"id":"andrews-2021-tutorial","name":"Andrews et al. 2021 Nature Protocols scRNA-seq tutorial","kind":"evidence","layer":"core","categories":["qc-benchmarks"],"side":"neutral","tier":"standard","summary":"Tutorial and companion course (Hemberg lab) covering the computational workflow for scRNA-seq from QC to biological interpretation, with guidance on choosing tools at each step","gain":"none (guide)","gain_source":"none","caveats":"Course material predates the 2023 adaptive-QC and ambient benchmarks.","url":"https://www.singlecellcourse.org","doi":"10.1038/s41596-020-00409-w","pmid":"33288955","cite_title":"Tutorial: guidelines for the computational analysis of single-cell RNA sequencing data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41596-020-00409-w","publication_url":"https://doi.org/10.1038/s41596-020-00409-w","publication_title":"Tutorial: guidelines for the computational analysis of single-cell RNA sequencing data","publication_venue":"Nature Protocols","citations":306,"review":"13-metrics-guides-multimodal#andrews-2021-tutorial","tags":["guide","course"],"site":"https://www.singlecellcourse.org"},{"id":"cpa","name":"CPA and chemCPA (compositional perturbation autoencoder)","kind":"tool","layer":"adjacent","categories":["perturbation-models"],"side":"additive","tier":"benchmarked","summary":"Autoencoder that splits each cell into a basal latent state plus additive embeddings for perturbations and covariates, scaled by learned dose-response curves, to predict unseen doses, times and combinations; chemCPA adds molecular structure to reach unseen drugs","recovers":"Predicted responses for unmeasured drug-dose-combination conditions","gain":"Imputed 5,329 missing combinations (97.6% of all possibilities) in a combinatorial Perturb-seq screen and outperformed baseline models on unseen drug combinations in new A549 data","gain_source":"self-reported","requires":["multiple-conditions","doses-or-time"],"caveats":"The CPA paper assumes enough cells per condition to estimate the latent space with a large network. In the independent Ahlmann-Eltze 2025 benchmark CPA was particularly uncompetitive on double genetic perturbations (outside its design target). Predictions are not tests and carry no replicate-level uncertainty. scGen (2019) is the earlier latent-arithmetic model from the same group.","url":"https://cpa-tools.readthedocs.io/","repo_url":"https://github.com/theislab/cpa","language":"Python","doi":"10.15252/msb.202211517","pmid":"37154091","cite_title":"Predicting cellular responses to complex perturbations in high-throughput screens.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.15252/msb.202211517","publication_url":"https://doi.org/10.15252/msb.202211517","publication_title":"Predicting cellular responses to complex perturbations in high-throughput screens.","publication_venue":"Molecular Systems Biology","citations":306,"citations_total":1018,"citations_papers":3,"repo_stars":157,"repo_pushed":"2024-08-14","benchmarks":["ahlmann-eltze-2025-perturbation-benchmark","li-2026-perturbation-models"],"benchmark_refs":[{"id":"ahlmann-eltze-2025-perturbation-benchmark","name":"Ahlmann-Eltze et al. 2025, deep perturbation models versus linear baselines","url":"https://doi.org/10.1038/s41592-025-02772-6"},{"id":"li-2026-perturbation-models","name":"Li et al. 2026, single-cell perturbation response models","url":"https://doi.org/10.1126/sciadv.aed3414"}],"review":"03-low-cell-stats#cpa","tags":["deep-learning","drug-screen","combinations","preprint"],"site":"https://cpa-tools.readthedocs.io/"},{"id":"scds","name":"scds (cxds, bcds, hybrid)","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked-sota","summary":"Two doublet scores and their combination: cxds scores unlikely co-expression of gene pairs on binarised counts, bcds trains gradient boosting against artificial doublets, hybrid averages them","recovers":"fast doublet scoring for large datasets without clustering","gain":"Demuxafy 2024: scds, scDblFinder and Scrublet the top doublet detectors by MCC and balanced accuracy; Xi & Li 2021: cxds fastest and most resource-efficient, hybrid one of only two methods to beat the library-size and gene-count baselines on all 16 datasets","gain_source":"independent","requires":["filtered-matrix"],"caveats":"cxds alone has medium accuracy and cxds, bcds and hybrid were unstable at removing spurious clusters (Xi & Li 2021); bcds found the most unique multiplets but had the lowest accuracy against hashing (Ttoouli 2025).","url":"https://bioconductor.org/packages/scds","repo_url":"https://github.com/kostkalab/scds","language":"R","doi":"10.1093/bioinformatics/btz698","pmid":"31501871","cite_title":"scds: computational annotation of doublets in single-cell RNA sequencing data","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btz698","publication_url":"https://doi.org/10.1093/bioinformatics/btz698","publication_title":"scds: computational annotation of doublets in single-cell RNA sequencing data","publication_venue":"Bioinformatics","citations":306,"repo_stars":11,"repo_pushed":"2026-01-07","benchmarks":["xi-li-2021-doublet-benchmark","xi-li-2021-doublet-protocol","neavin-2024-demuxafy-benchmark","zhang-2024-singletcode","ttoouli-2025-multiplets"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"xi-li-2021-doublet-protocol","name":"Xi and Li 2021, doublet-detection benchmark protocol (scDblFinder added)","url":"https://doi.org/10.1016/j.xpro.2021.100699"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"zhang-2024-singletcode","name":"Zhang et al. 2024 (singletCode), doublet detectors on barcoded ground truth","url":"https://doi.org/10.1016/j.xgen.2024.100592"},{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"}],"review":"12-doublets-stress-batch#scds","tags":["bioconductor","co-expression","fast"],"site":"https://bioconductor.org/packages/scds"},{"id":"cell-subsample-pseudoreplicates","name":"Cell-subsample pseudoreplicates (one culture per condition)","kind":"evidence","layer":"core","categories":["low-cell-stats","screen-design"],"side":"neutral","tier":"standard","summary":"Splitting one well's cells into random subsets and treating them as replicates measures within-well sampling noise, so the resulting p-values test whether two wells differ, not whether a drug effect would reproduce in another culture","gain_source":"none","requires":["filtered-matrix"],"caveats":"Squair 2021: random-cell pseudo-replicates shrank variance most for highly expressed genes (46 datasets) and reintroduced false DE genes in null comparisons. Lazic 2018: only 22% of surveyed animal studies replicated the correct entity-intervention pair and 46% pseudoreplicated. Honest uses: effect sizes, rankings, and comparison with a well-to-well null built from replicate control wells.","url":"https://doi.org/10.1371/journal.pbio.2005282","doi":"10.1371/journal.pbio.2005282","pmid":"29617358","cite_title":"What exactly is 'N' in cell culture and animal experiments?","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pbio.2005282","publication_url":"https://doi.org/10.1371/journal.pbio.2005282","publication_title":"What exactly is 'N' in cell culture and animal experiments?","publication_venue":"PLoS Biology","citations":286,"citations_total":1684,"citations_papers":4,"benchmarks":["squair-2021-de-benchmark"],"benchmark_refs":[{"id":"squair-2021-de-benchmark","name":"Squair et al. 2021, single-cell differential expression against matched bulk","url":"https://doi.org/10.1038/s41467-021-25960-2"}],"review":"03-low-cell-stats#cell-subsample-pseudoreplicates","tags":["pseudoreplication","drug-screen","design"],"site":"https://doi.org/10.1371/journal.pbio.2005282"},{"id":"pic-seq","name":"PIC-seq","kind":"method","layer":"core","categories":["discarded-data","doublets"],"side":"additive","tier":"published-unbenchmarked","summary":"Sequences physically interacting cells (PICs) sorted as cell pairs and models each PIC transcriptome as a mixture of two singlet profiles, giving the mixing factor and the genes expressed above or below the mixture expectation","recovers":"interaction-specific transcription from cell pairs that QC would discard as doublets","gain":"re-use on human kidney allograft CITE-seq (31,203 libraries): 3 of 6 doublet clusters called physically interacting; two analysed clusters at 4.7x and 9.5x the expected artefactual-doublet frequency, mixing-factor regression R2 0.84 and 0.85","gain_source":"independent","requires":["filtered-matrix","reference"],"caveats":"designed for FACS-sorted pairs; on unsorted droplet data it needs an expected random-doublet frequency, which common heuristics underestimate; assumes two-cell PICs; singlet references must come from the same sample","url":"https://github.com/aygoldberg/PIC-seq","repo_url":"https://github.com/aygoldberg/PIC-seq","language":"R","doi":"10.1038/s41587-020-0442-2","pmid":"32152598","cite_title":"Dissecting cellular crosstalk by sequencing physically interacting cells","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-020-0442-2","publication_url":"https://doi.org/10.1038/s41587-020-0442-2","publication_title":"Dissecting cellular crosstalk by sequencing physically interacting cells","publication_venue":"Nature Biotechnology","citations":284,"citations_total":303,"citations_papers":2,"repo_stars":6,"repo_pushed":"2022-01-18","review":"05-discarded-data#pic-seq","tags":["doublets-as-signal","cell-interactions","sorting","mixture-model"]},{"id":"hashsolo","name":"HashSolo","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"standard","summary":"Bayesian hashing demultiplexer in scanpy (sc.external.pp.hashsolo) that models signal and noise tag counts and scores each droplet's top tags under negative, singlet and doublet hypotheses with user priors","recovers":"singlet calls with few negatives","gain":"Howitt 2023 (vireo truth): mean F 0.920, 0.783 and 0.737 on three BAL batches and fewer negatives than any caller except BFFcluster, but about 30% (BAL) and 60% (cell lines) of genetic doublets were called singlets","gain_source":"independent","requires":["tag-counts"],"caveats":"Doublet leakage makes it risky on super-loaded lanes; on hashed brain nuclei it called almost every droplet a singlet (hadge 2024); default priors (0.01, 0.8, 0.19) assume transcriptome QC has already been applied","url":"https://scanpy.readthedocs.io/en/stable/api/scanpy.external.pp.hashsolo.html","repo_url":"https://github.com/calico/solo","language":"Python","doi":"10.1016/j.cels.2020.05.010","pmid":"32592658","cite_title":"Solo: Doublet Identification in Single-Cell RNA-Seq via Semi-Supervised Deep Learning.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2020.05.010","publication_url":"https://doi.org/10.1016/j.cels.2020.05.010","publication_title":"Solo: Doublet Identification in Single-Cell RNA-Seq via Semi-Supervised Deep Learning.","publication_venue":"Cell Systems","citations":280,"repo_stars":98,"repo_pushed":"2024-12-28","repo_archived":true,"benchmarks":["howitt-2023-hto-benchmark","curion-2024-hadge-comparison"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"}],"review":"01-demux-recovery#hashsolo","tags":["hashing","scanpy","python"],"site":"https://scanpy.readthedocs.io/en/stable/api/scanpy.external.pp.hashsolo.html"},{"id":"solo","name":"Solo","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked-sota","summary":"Embeds cells with a variational autoencoder and trains a classifier head to separate simulated doublets from observed cells; now maintained inside scvi-tools","recovers":"singlets and cleaner clusters","gain":"Xi & Li 2021: highest mean AUROC on 16 real datasets, beat both baselines on every dataset, highest precision and TNR (with DoubletFinder) and recall (with hybrid) at matched doublet numbers; Demuxafy 2024: better than scds in pools of more than 16 donors","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Slowest and most memory-hungry detector in Demuxafy (median 13 h per ~20,000-cell pool) and the only one whose run time did not scale linearly (Xi & Li 2021); GPU preferred; the standalone calico/solo repository is archived in favour of scvi-tools.","url":"https://docs.scvi-tools.org","repo_url":"https://github.com/calico/solo","language":"Python","doi":"10.1016/j.cels.2020.05.010","pmid":"32592658","cite_title":"Solo: Doublet Identification in Single-Cell RNA-Seq via Semi-Supervised Deep Learning","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2020.05.010","publication_url":"https://doi.org/10.1016/j.cels.2020.05.010","publication_title":"Solo: Doublet Identification in Single-Cell RNA-Seq via Semi-Supervised Deep Learning","publication_venue":"Cell Systems","citations":280,"repo_stars":98,"repo_pushed":"2024-12-28","repo_archived":true,"benchmarks":["xi-li-2021-doublet-benchmark","neavin-2024-demuxafy-benchmark"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"}],"review":"12-doublets-stress-batch#solo","tags":["deep-learning","scvi-tools","gpu"],"site":"https://docs.scvi-tools.org"},{"id":"oflanagan-2019","name":"O'Flanagan et al. 2019 cold protease and dead/dying cells","kind":"evidence","layer":"core","categories":["damaged-cells","cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"Compares collagenase at 37 C with cold active protease at 6 C on tumours and cell lines and profiles FACS-sorted live, dying and dead TNF-alpha-treated cells","gain":"dying (annexin V+) cells had median mito 3.13%, like live cells (3.4%), while dead cells had 29.9%; only 885 dying and 1,280 dead cells were recovered against 3,000 targeted; 37 C collagenase induced a 512-gene core stress signature (FOS, FOSB, ATF3, heat shock genes) that cold protease minimised","gain_source":"independent","caveats":"One lymphoblastoid line for the death experiment; the dying cells were induced with TNF-alpha, not a drug panel.","doi":"10.1186/s13059-019-1830-0","pmid":"31623682","cite_title":"Dissociation of solid tumor tissues with cold active protease for single-cell RNA-seq minimizes conserved collagenase-associated stress responses","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-019-1830-0","publication_url":"https://doi.org/10.1186/s13059-019-1830-0","publication_title":"Dissociation of solid tumor tissues with cold active protease for single-cell RNA-seq minimizes conserved collagenase-associated stress responses","publication_venue":"Genome biology","citations":276,"review":"02-calling-qc-damaged#oflanagan-2019","tags":["apoptosis","dissociation","cold-protease","mito"]},{"id":"scifi-rna-seq","name":"scifi-RNA-seq","kind":"design","layer":"core","categories":["demux-combinatorial","screen-design"],"side":"additive","tier":"published-unbenchmarked","summary":"One round of in-cell preindexing followed by deliberately overloaded droplets, so several cells per droplet are resolved by the pair of preindex and droplet barcodes","recovers":"cells per channel: transcriptomes from multi-cell droplets are kept instead of discarded as doublets","gain":"Up to 150,000 cells per Chromium channel and over 1 million per chip; 100-fold overloading kept a stable emulsion; recovered transcriptomes scaled linearly from 15,300 to 765,000 loaded nuclei; no loss of complexity in droplets holding up to 15 nuclei","gain_source":"self-reported","requires":["fastq"],"caveats":"Preindexing lost about half the input before loading (nuclei recovery 53.3% for cell lines, 41.1% for primary material); uses 10x ATAC beads outside vendor support; no independent benchmark","repo_url":"https://github.com/epigen/scifiRNA-seq","language":"Python","doi":"10.1038/s41592-021-01153-z","pmid":"34059827","cite_title":"Ultra-high-throughput single-cell RNA sequencing and perturbation screening with combinatorial fluidic indexing","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-021-01153-z","publication_url":"https://doi.org/10.1038/s41592-021-01153-z","publication_title":"Ultra-high-throughput single-cell RNA sequencing and perturbation screening with combinatorial fluidic indexing","publication_venue":"Nature Methods","citations":270,"repo_stars":13,"repo_pushed":"2020-12-07","review":"04-screen-design#scifi-rna-seq","tags":["combinatorial-indexing","overloading","crispr"]},{"id":"concept-trajectories","name":"Trajectory inference, pseudotime and RNA velocity","kind":"concept","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"standard","summary":"Ordering cells along continuous processes such as differentiation or response (pseudotime, lineage trees) and inferring direction from spliced and unspliced RNA (RNA velocity) or fate probabilities","caveats":"Trajectory methods return a path on any input, so artefactual intermediates (doublets, damaged cells) and nuisance axes (cell cycle, stress) are fitted as biology unless removed or modelled first","doi":"10.1242/dev.170506","pmid":"31249007","cite_title":"Concepts and limitations for learning developmental trajectories from single cell genomics.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1242/dev.170506","publication_url":"https://doi.org/10.1242/dev.170506","publication_title":"Concepts and limitations for learning developmental trajectories from single cell genomics.","publication_venue":"Development","citations":242,"citations_total":6335,"citations_papers":5,"review":"22-concepts-downstream#concept-trajectories","tags":["concept","pseudotime","rna-velocity"]},{"id":"mixscape","name":"Mixscape (and perturbation-response scores)","kind":"tool","layer":"adjacent","categories":["perturbation-models","low-cell-stats"],"side":"additive","tier":"standard","summary":"Computes a local perturbation signature per cell by subtracting the mean of its 20 nearest control neighbours, then uses a mixture model to classify targeted cells as perturbed or non-perturbed before DE","recovers":"Effects diluted by non-responding cells; variation from replicate, cell cycle and stress removed from the signature","gain":"In the ECCITE-seq screen, 115 of 278 cells carrying an IFNGR2 gRNA appeared to escape perturbation; signatures substantially reduced replicate, cell-cycle and stress variation","gain_source":"self-reported","requires":["multiple-conditions"],"caveats":"Built for CRISPR, where escape is near-binary; drug responses are graded, which the perturbation-response score of Song 2025 models instead. Testing only on 'responders' inflates effect sizes and is circular unless the classification uses separate data. Needs enough cells per perturbation to fit the mixture.","url":"https://satijalab.org/seurat/articles/mixscape_vignette","repo_url":"https://github.com/satijalab/seurat","language":"multiple","doi":"10.1038/s41588-021-00778-2","pmid":"33649593","cite_title":"Characterizing the molecular regulation of inhibitory immune checkpoints with multimodal single-cell screens.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41588-021-00778-2","publication_url":"https://doi.org/10.1038/s41588-021-00778-2","publication_title":"Characterizing the molecular regulation of inhibitory immune checkpoints with multimodal single-cell screens.","publication_venue":"Nature Genetics","citations":235,"citations_total":266,"citations_papers":2,"repo_stars":2807,"repo_pushed":"2026-10-23","review":"03-low-cell-stats#mixscape","tags":["responders","crispr","pertpy"],"site":"https://satijalab.org/seurat/articles/mixscape_vignette"},{"id":"ahlmann-eltze-2025","name":"Ahlmann-Eltze et al. 2025: deep perturbation models vs linear baselines","kind":"evidence","layer":"adjacent","categories":["perturbation-models","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of five foundation models plus GEARS and CPA against 'no change', additive and linear baselines for predicting transcriptome changes after single and double genetic perturbations; none outperformed the baselines","gain":"On 62 held-out double perturbations every deep model had prediction error substantially higher than the additive baseline, and none beat the 'no change' baseline at finding genetic interactions","gain_source":"independent","caveats":"Disputed: Miller 2026 (Nat Biotechnol) argues common metrics such as MSE and Pearson delta are miscalibrated and that deep models can beat uninformative baselines on calibrated metrics across 14 datasets. Csendes 2025 and Wong 2025 also found simple baselines ahead. Li 2026 (13 methods, 25 datasets incl. two drug-response sets): models compress variance and underestimate synergy; none generalised across cell types. All concern genetic or immune perturbations, not low-cell drug screens.","url":"https://doi.org/10.1038/s41592-025-02772-6","doi":"10.1038/s41592-025-02772-6","pmid":"40759747","cite_title":"Deep-learning-based gene perturbation effect prediction does not yet outperform simple linear baselines.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-025-02772-6","publication_url":"https://doi.org/10.1038/s41592-025-02772-6","publication_title":"Deep-learning-based gene perturbation effect prediction does not yet outperform simple linear baselines.","publication_venue":"Nature Methods","citations":234,"citations_total":661,"citations_papers":6,"review":"03-low-cell-stats#ahlmann-eltze-2025","tags":["benchmark","deep-learning","foundation-models","dispute"],"site":"https://doi.org/10.1038/s41592-025-02772-6"},{"id":"methanol-fixation","name":"Methanol fixation","kind":"design","layer":"core","categories":["screen-design","damaged-cells"],"side":"additive","tier":"benchmarked-sota","summary":"Dissociated cells are fixed in 80% methanol and stored, then rehydrated for droplet scRNA-seq, which separates harvest from capture","recovers":"cells and states that would degrade while samples wait, including low-RNA cells after storage","gain":"Independent (Gutierrez-Franco 2023): on hiPSC-derived neural cells methanol kept cell composition closest to fresh with little expression bias, while DMSO cryopreservation shifted composition and induced stress and apoptosis genes; self-reported (Alles 2017): unchanged genes and UMIs per cell in human-mouse mixtures after storage for weeks","gain_source":"independent","caveats":"Wohnhaas 2019 preferred DMSO cryopreservation for other cell types, so the best choice depends on cell type; DMSO cryopreservation gave the highest library complexity in the neural comparison","doi":"10.1186/s12915-017-0383-5","pmid":"28526029","cite_title":"Cell fixation and preservation for droplet-based single-cell transcriptomics","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12915-017-0383-5","publication_url":"https://doi.org/10.1186/s12915-017-0383-5","publication_title":"Cell fixation and preservation for droplet-based single-cell transcriptomics","publication_venue":"BMC Biology","citations":218,"citations_total":347,"citations_papers":3,"benchmarks":["gutierrez-franco-2023-preservation","wohnhaas-2019-preservation","denisenko-2020-dissociation-storage"],"benchmark_refs":[{"id":"gutierrez-franco-2023-preservation","name":"Gutierrez-Franco et al. 2023, preservation methods for neural cells","url":"https://doi.org/10.1038/s42003-023-04834-x"},{"id":"wohnhaas-2019-preservation","name":"Wohnhaas et al. 2019, preservation methods for droplet scRNA-seq","url":"https://doi.org/10.1038/s41598-019-46932-z"},{"id":"denisenko-2020-dissociation-storage","name":"Denisenko et al. 2020, dissociation and storage biases","url":"https://doi.org/10.1186/s13059-020-02048-6"}],"review":"04-screen-design#methanol-fixation","tags":["fixed","preservation","methanol"]},{"id":"osorio-cai-2021","name":"Osorio & Cai 2021 mito reference values","kind":"evidence","layer":"core","categories":["qc-metrics-thresholds"],"side":"neutral","tier":"published-unbenchmarked","summary":"Survey of mito fraction in 5,530,106 cells from 1,349 PanglaoDB datasets giving reference values for 121 mouse and 44 human tissues","gain":"human cells carry more mito RNA than mouse; the 5% cut-off misclassifies healthy vs low-quality cells in 13 of 44 human tissues (29.5%)","gain_source":"independent","caveats":"Tissue-level values; cultured cancer lines and treated cells are not covered.","url":"https://github.com/dosorio/mtProportion","repo_url":"https://github.com/dosorio/mtProportion","doi":"10.1093/bioinformatics/btaa751","pmid":"32840568","cite_title":"Systematic determination of the mitochondrial proportion in human and mice tissues for single-cell RNA-sequencing data quality control","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btaa751","publication_url":"https://doi.org/10.1093/bioinformatics/btaa751","publication_title":"Systematic determination of the mitochondrial proportion in human and mice tissues for single-cell RNA-sequencing data quality control","publication_venue":"Bioinformatics","citations":210,"repo_stars":8,"repo_pushed":"2020-08-13","review":"02-calling-qc-damaged#osorio-cai-2021","tags":["mito","reference-values","survey"]},{"id":"doubletdecon","name":"DoubletDecon","kind":"tool","layer":"core","categories":["doublets","discarded-data"],"side":"both","tier":"benchmarked","summary":"Detects heterotypic doublets by deconvolution against cluster profiles, then returns putative doublet clusters with unique gene expression to the singlets as transitional or mixed-lineage states","recovers":"transitional and progenitor states that synthetic-doublet detectors flag as doublets","gain":"mouse bone marrow with validated transitional states: specificity 80.7% before and 95.0% after the rescue step","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"independent benchmark (Xi & Li 2021): no doublet score, did not beat library-size or gene-count baselines at matched doublet numbers, failed on 4 datasets and tended to over-call doublets; the rescue step itself was not benchmarked","url":"https://github.com/EDePasquale/DoubletDecon","repo_url":"https://github.com/EDePasquale/DoubletDecon","language":"R","doi":"10.1016/j.celrep.2019.09.082","pmid":"31693907","cite_title":"DoubletDecon: Deconvoluting Doublets from Single-Cell RNA-Sequencing Data","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.celrep.2019.09.082","publication_url":"https://doi.org/10.1016/j.celrep.2019.09.082","publication_title":"DoubletDecon: Deconvoluting Doublets from Single-Cell RNA-Sequencing Data","publication_venue":"Cell Reports","citations":207,"citations_total":413,"citations_papers":2,"repo_stars":75,"repo_pushed":"2020-12-02","benchmarks":["xi-li-2021-doublet-benchmark","neavin-2024-demuxafy-benchmark"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"}],"review":"05-discarded-data#doubletdecon","tags":["doublet-rescue","transitional-states","deconvolution"]},{"id":"xi-li-2021","name":"Xi & Li 2021 doublet-detection benchmark","kind":"evidence","layer":"core","categories":["doublets","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of nine RNA-based doublet detectors on 16 real datasets with experimentally annotated doublets and 112 synthetic datasets","gain":"DoubletFinder had the best detection accuracy and cxds the highest efficiency; no method was best everywhere; Solo had the highest mean AUROC; Solo and hybrid were the only methods to beat the library-size and gene-count baselines on all 16 datasets, and doubletCells did not beat them on most; doublets made spurious Slingshot branches in simulations, removed by every detector except doubletCells, and doublet removal by most methods improved DE gene and temporally DE gene recovery; the protocol extension (STAR Protocols 2021) found scDblFinder best on mean AUPRC and AUROC","gain_source":"independent","caveats":"Annotated doublets come from hashing or genotypes, which miss same-sample homotypic doublets.","doi":"10.1016/j.cels.2020.11.008","pmid":"33338399","cite_title":"Benchmarking Computational Doublet-Detection Methods for Single-Cell RNA Sequencing Data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2020.11.008","publication_url":"https://doi.org/10.1016/j.cels.2020.11.008","publication_title":"Benchmarking Computational Doublet-Detection Methods for Single-Cell RNA Sequencing Data","publication_venue":"Cell Systems","citations":206,"citations_total":242,"citations_papers":3,"review":"02-calling-qc-damaged#xi-li-2021","tags":["benchmark"]},{"id":"dsb","name":"dsb","kind":"tool","layer":"core","categories":["discarded-data","ambient-rna"],"side":"both","tier":"standard","summary":"Normalises and denoises antibody-derived tag counts using protein levels in empty droplets as the ambient background and a per-cell technical component from isotype controls and background proteins","recovers":"cleaner protein signal, using empty droplets that are usually thrown away","requires":["raw-matrix","protein"],"caveats":"needs the raw matrix with empty droplets; empty-drop calls from RNA can include protein-rich cells such as neutrophils (DecontPro); included in the 14-method comparison of [[adtnorm]], which ADTnorm led (self-reported); titrating antibody concentrations cut background from a median 26.3% to 14.9% of UMIs [[buus-2021]], so some of what dsb removes can be prevented at the bench","url":"https://github.com/niaid/dsb","repo_url":"https://github.com/niaid/dsb","language":"R","doi":"10.1038/s41467-022-29356-8","pmid":"35440536","cite_title":"Normalizing and denoising protein expression data from droplet-based single cell profiling","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-022-29356-8","publication_url":"https://doi.org/10.1038/s41467-022-29356-8","publication_title":"Normalizing and denoising protein expression data from droplet-based single cell profiling","publication_venue":"Nature Communications","citations":197,"citation_note":"1 listed paper(s) had no citation count","citations_total":1294,"citations_papers":3,"repo_stars":73,"repo_pushed":"2025-11-09","review":"05-discarded-data#dsb","tags":["empty-droplets","citeseq","protein","ambient"]},{"id":"lause-2021","name":"Analytic Pearson residuals","kind":"method","layer":"adjacent","categories":["normalisation","feature-selection"],"side":"neutral","tier":"benchmarked-sota","summary":"Closed-form Pearson residuals of a Poisson or fixed-overdispersion negative binomial model with depth offset, used both as the normalised matrix and to rank variable genes","gain":"Ahlmann-Eltze 2023: performed as well as the shifted log and better than latent-expression and factor-analysis transformations, and as well as exact residuals at lower cost; self-reported: strongly outperformed other methods at finding biologically variable genes","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Residuals are affine per gene, which may suit genes with a large dynamic range poorly (Ahlmann-Eltze 2023); negative control data in the paper were close to Poisson, so the choice of overdispersion matters little in UMI data.","url":"https://scanpy.readthedocs.io/en/stable/tutorials/experimental/pearson_residuals.html","repo_url":"https://github.com/scverse/scanpy","language":"Python","doi":"10.1186/s13059-021-02451-7","pmid":"34488842","cite_title":"Analytic Pearson residuals for normalization of single-cell RNA-seq UMI data.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-021-02451-7","publication_url":"https://doi.org/10.1186/s13059-021-02451-7","publication_title":"Analytic Pearson residuals for normalization of single-cell RNA-seq UMI data.","publication_venue":"Genome biology","citations":194,"repo_stars":2594,"repo_pushed":"2026-10-23","benchmarks":["ahlmann-eltze-2023-transformation-benchmark","zappia-2025-feature-selection-benchmark"],"benchmark_refs":[{"id":"ahlmann-eltze-2023-transformation-benchmark","name":"Ahlmann-Eltze and Huber 2023, transformation benchmark","url":"https://doi.org/10.1038/s41592-023-01814-1"},{"id":"zappia-2025-feature-selection-benchmark","name":"Zappia et al. 2025, feature selection for integration benchmark","url":"https://doi.org/10.1038/s41592-025-02624-3"}],"review":"21-concepts-preprocessing#lause-2021","tags":["scanpy","pearson-residuals"],"site":"https://scanpy.readthedocs.io/en/stable/tutorials/experimental/pearson_residuals.html"},{"id":"scperturb","name":"scPerturb","kind":"evidence","layer":"core","categories":["screen-design","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"Harmonised collection of 44 single-cell perturbation datasets with energy-distance statistics, used to derive cells-per-perturbation and depth guidelines","gain":"Significant perturbations fell as cells per perturbation were subsampled, and significance saturated near 500 UMIs per cell; guideline of at least 200-500 cells per perturbation and about 1,000 UMIs per cell; sci-Plex 3: 107 of 188 drugs significant by E-test","gain_source":"independent","requires":["multiple-conditions"],"caveats":"The guideline targets distinguishing a perturbation from control by E-test, a stricter goal than estimating a mean shift (MIX-Seq found tens of cells enough for that); E-distance itself grows as cells fall, so compare conditions at equal cell numbers","repo_url":"https://github.com/sanderlab/scPerturb","language":"Python","doi":"10.1038/s41592-023-02144-y","pmid":"38279009","cite_title":"scPerturb: harmonized single-cell perturbation data","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-023-02144-y","publication_url":"https://doi.org/10.1038/s41592-023-02144-y","publication_title":"scPerturb: harmonized single-cell perturbation data","publication_venue":"Nature Methods","citations":192,"repo_stars":192,"repo_pushed":"2025-02-25","review":"04-screen-design#scperturb","tags":["perturbation","resource","power","depth"]},{"id":"demuxem","name":"demuxEM","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"benchmarked-sota","summary":"Hashing demultiplexer built for nucleus hashing that estimates each tag's background from empty droplets and uses EM to split a droplet's tag counts into background and true signal before calling","recovers":"singlets from noisy nucleus hashing","gain":"Self-reported on hashed brain nuclei: 96% agreement with demuxlet versus 92% for Seurat, 94.8% agreement with Xist-based sex. In hadge 2024 it matched vireo donors best together with MULTI-seq on hashed brain nuclei (one dataset)","gain_source":"self-reported","requires":["tag-counts","raw-matrix"],"caveats":"Needs the unfiltered matrix to model background; errored on a MULTI-seq PBMC dataset (deMULTIplex2 authors) and gave no result on a CellPlex PDX dataset (CMDdemux authors); not in Howitt 2023; its only independent win is a single nuclei dataset","url":"https://github.com/lilab-bcb/demuxEM","repo_url":"https://github.com/lilab-bcb/demuxEM","language":"Python","doi":"10.1038/s41467-019-10756-2","pmid":"31266958","cite_title":"Nuclei multiplexing with barcoded antibodies for single-nucleus genomics.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-019-10756-2","publication_url":"https://doi.org/10.1038/s41467-019-10756-2","publication_title":"Nuclei multiplexing with barcoded antibodies for single-nucleus genomics.","publication_venue":"Nature Communications","citations":189,"repo_stars":2,"repo_pushed":"2026-06-10","benchmarks":["curion-2024-hadge-comparison"],"benchmark_refs":[{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"}],"review":"01-demux-recovery#demuxem","tags":["hashing","nuclei","empty-droplets"]},{"id":"nucleus-hashing","name":"Nucleus hashing (antibody)","kind":"design","layer":"core","categories":["screen-design","demux-hashing"],"side":"additive","tier":"benchmarked","summary":"Barcoded antibodies against nuclear pore complex proteins label nuclei by sample so nuclei can be pooled and overloaded, with DemuxEM calling sample of origin","recovers":"nuclei per lane through overloading with detectable inter-sample multiplets","gain":"Loading 500 to 4,500 nuclei per ul gave comparable cell types and genes per nucleus; DemuxEM agreed with demuxlet on 96% of nuclei; estimated multiplet rate 2.8% against 2.7% expected when 7,000 nuclei were loaded","gain_source":"self-reported","requires":["tag-counts","raw-matrix"],"caveats":"Extra labelling and washing steps left an average nuclei yield of about 33%; an independent comparison found antibody nuclei hashing less accurate than cholesterol-oligo hashing (OCA 0.51-0.65 against 0.84, Mylka 2022), so it has been benchmarked without winning; one sample can dominate ambient hashtags; calling tool is [[demuxem]]","doi":"10.1038/s41467-019-10756-2","pmid":"31266958","cite_title":"Nuclei multiplexing with barcoded antibodies for single-nucleus genomics","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-019-10756-2","publication_url":"https://doi.org/10.1038/s41467-019-10756-2","publication_title":"Nuclei multiplexing with barcoded antibodies for single-nucleus genomics","publication_venue":"Nature Communications","citations":189,"benchmarks":["mylka-2022-hashing-comparison"],"benchmark_refs":[{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022, antibody versus lipid hashing","url":"https://doi.org/10.1186/s13059-022-02628-8"}],"review":"04-screen-design#nucleus-hashing","tags":["hashing","nuclei","antibody","superloading"]},{"id":"snapatac2","name":"SnapATAC2","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"both","tier":"benchmarked-sota","summary":"Python and Rust package for single-cell epigenomics that computes fragment and TSS enrichment QC on genome bins and embeds cells with a matrix-free spectral method that scales linearly with cell number","recovers":"cell-type structure in complex datasets with less leakage of sequencing depth into the embedding","gain":"Luo 2024 (independent): with SnapATAC preferred for datasets with complex cell-type structure, among the most scalable, and its cosine embedding correlated only ~0.2 with library size versus 0.5-0.75 for Signac and ArchR","gain_source":"independent","requires":["bam"],"caveats":"Works on genome bins without peak calling, so peak-based QC such as FRiP is unavailable; Chromap's QC preprint reports low-quality cells SnapATAC2 missed ([[chromap-qc]]).","url":"https://scverse.org/SnapATAC2/","repo_url":"https://github.com/scverse/SnapATAC2","language":"multiple","doi":"10.1038/s41592-023-02139-9","pmid":"38191932","cite_title":"A fast, scalable and versatile tool for analysis of single-cell omics data","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-023-02139-9","publication_url":"https://doi.org/10.1038/s41592-023-02139-9","publication_title":"A fast, scalable and versatile tool for analysis of single-cell omics data","publication_venue":"Nature Methods","citations":183,"citations_total":196,"citations_papers":2,"repo_stars":329,"repo_pushed":"2026-09-12","benchmarks":["luo-2024-chromatin-benchmark"],"benchmark_refs":[{"id":"luo-2024-chromatin-benchmark","name":"Luo et al. 2024, scATAC feature-engineering benchmark","url":"https://doi.org/10.1186/s13059-024-03356-x"}],"review":"13-metrics-guides-multimodal#snapatac2","tags":["atac","multiome","scverse"],"site":"https://scverse.org/SnapATAC2/"},{"id":"nebula","name":"NEBULA","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"additive","tier":"benchmarked","summary":"Negative binomial mixed model with a random effect per subject, fitted with a large-sample approximation instead of the Laplace approximation, for cell-level DE and co-expression in multi-subject data","recovers":"Cell-level information (including expressing fraction) while still accounting for within-sample correlation","gain":"NEBULA-HL and glmmTMB outperformed the other methods, including pseudobulk, in a 12-method simulation benchmark of multi-subject 10x data (Gagnon 2022); orders of magnitude faster than earlier GLMM tools (self-reported)","gain_source":"independent","requires":["filtered-matrix","replicates"],"caveats":"Conflicting benchmarks: Junttila 2022 ranked pseudobulk above NEBULA-LN, and Squair 2021 found GLMMs accurate only in narrow settings. The approximation relies on many cells per subject, and its authors found tests of a subject-level variable highly sensitive to the subject variance estimate when subjects are few.","url":"https://github.com/lhe17/nebula","repo_url":"https://github.com/lhe17/nebula","language":"R","doi":"10.1038/s42003-021-02146-6","pmid":"34040149","cite_title":"NEBULA is a fast negative binomial mixed model for differential or co-expression analysis of large-scale multi-subject single-cell data.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s42003-021-02146-6","publication_url":"https://doi.org/10.1038/s42003-021-02146-6","publication_title":"NEBULA is a fast negative binomial mixed model for differential or co-expression analysis of large-scale multi-subject single-cell data.","publication_venue":"Communications Biology","citations":182,"citations_total":210,"citations_papers":2,"repo_stars":63,"repo_pushed":"2026-07-12","benchmarks":["junttila-2022-ds-benchmark","gagnon-2022-de-benchmark"],"benchmark_refs":[{"id":"junttila-2022-ds-benchmark","name":"Junttila et al. 2022, multi-subject differential state benchmark","url":"https://doi.org/10.1093/bib/bbac286"},{"id":"gagnon-2022-de-benchmark","name":"Gagnon et al. 2022, multi-subject DE benchmark","url":"https://doi.org/10.3390/life12060850"}],"review":"03-low-cell-stats#nebula","tags":["mixed-models","negative-binomial"]},{"id":"mix-seq","name":"MIX-Seq","kind":"design","layer":"core","categories":["screen-design","demux-genotype"],"side":"additive","tier":"published-unbenchmarked","summary":"Pools of 24-99 cancer cell lines are co-treated in one culture and each cell is assigned to its line from transcribed SNPs, with Cell Hashing layered on for time points or doses","recovers":"cell lines and conditions per lane without per-line tags; empty droplets and doublets recognised as SNP mixtures","gain":"99-line trametinib pool: average 130 cells per line per condition, 97 of 99 lines with at least 20 cells; 0 of 84,869 cells assigned to an out-of-pool line from a 494-line reference; classification robust with 50-100 detected SNP sites; downsampling suggested tens of cells per condition suffice for a per-line response profile; up to 40,000 cells loaded per 10x channel","gain_source":"self-reported","requires":["genotypes","bam","multiple-conditions"],"caveats":"Lines in one pool share one well, so they are contexts rather than independent replicates of the treatment; cytotoxic drugs deplete the most sensitive lines, so cells are fewest where effects are largest; needs reference SNP profiles (approach similar to [[demuxlet]])","url":"https://github.com/broadinstitute/mix_seq_ms","repo_url":"https://github.com/broadinstitute/mix_seq_ms","language":"R","doi":"10.1038/s41467-020-17440-w","pmid":"32855387","cite_title":"Multiplexed single-cell transcriptional response profiling to define cancer vulnerabilities and therapeutic mechanism of action","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-020-17440-w","publication_url":"https://doi.org/10.1038/s41467-020-17440-w","publication_title":"Multiplexed single-cell transcriptional response profiling to define cancer vulnerabilities and therapeutic mechanism of action","publication_venue":"Nature Communications","citations":172,"repo_stars":16,"repo_pushed":"2020-08-26","review":"04-screen-design#mix-seq","tags":["drug-screen","genotype","cell-line-pool","superloading","hashing"]},{"id":"survivor-bias","name":"Survivor bias in drug-response transcriptomes","kind":"evidence","layer":"core","categories":["discarded-data","damaged-cells"],"side":"additive","tier":"published-unbenchmarked","summary":"MIX-Seq found that the BCL-2 inhibitor navitoclax and the MCL1 inhibitor AZD5591 gave strong selective viability effects but no robust transcriptional signature in captured cells, the exceptions to transcriptome-based viability prediction","recovers":"an argument for reading drug effects from lost cells when surviving cells look unchanged","requires":["genotypes","multiple-conditions"],"caveats":"two compounds in one study; for other drugs a shared viability-related signature predicted long-term viability (single model R2 0.50 at 24 h); drug-induced drops in mRNA per cell (Smart-seq2 spike-in study) also bias which cells pass UMI floors","url":"https://doi.org/10.1038/s41467-020-17440-w","doi":"10.1038/s41467-020-17440-w","pmid":"32855387","cite_title":"Multiplexed single-cell transcriptional response profiling to define cancer vulnerabilities and therapeutic mechanism of action","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-020-17440-w","publication_url":"https://doi.org/10.1038/s41467-020-17440-w","publication_title":"Multiplexed single-cell transcriptional response profiling to define cancer vulnerabilities and therapeutic mechanism of action","publication_venue":"Nature Communications","citations":172,"citations_total":180,"citations_papers":2,"review":"05-discarded-data#survivor-bias","tags":["drug-screen","selection-bias","apoptosis","viability"],"site":"https://doi.org/10.1038/s41467-020-17440-w"},{"id":"machado-2021","name":"Machado et al. 2021 conserved tissue-damage stress response","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"Single-cell and single-nucleus atlases of intact (fixed in situ), dissociated and injured muscle and liver revealed a stress signature shared by many cell types, also present in published reference atlases","gain":"none (cautionary finding); the dissociation signature distorts reference atlases across tissues","gain_source":"none","caveats":"Abstract only checked (no open full text); the same programme is induced by real injury, so it is not purely artefact.","doi":"10.1016/j.stem.2021.01.017","pmid":"33609440","cite_title":"Tissue damage induces a conserved stress response that initiates quiescent muscle stem cell activation","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.stem.2021.01.017","publication_url":"https://doi.org/10.1016/j.stem.2021.01.017","publication_title":"Tissue damage induces a conserved stress response that initiates quiescent muscle stem cell activation","publication_venue":"Cell stem cell","citations":168,"review":"12-doublets-stress-batch#machado-2021","tags":["dissociation","muscle","liver","atlas"]},{"id":"lun-marioni-2017","name":"Lun & Marioni 2017 plate effects in DE","kind":"evidence","layer":"core","categories":["batch-and-plate-effects","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"When the groups compared were processed on separate plates, cell-level DE lost type I error control; summing counts per plate and testing plates restored it without loss of power in simulations","gain":"restored type I error control under plate effects and improved specificity and gene ranking on real data","gain_source":"self-reported","requires":["replicates"],"caveats":"Needs several plates per group; with one plate per condition, plate and condition cannot be separated by any method.","doi":"10.1093/biostatistics/kxw055","pmid":"28334062","cite_title":"Overcoming confounding plate effects in differential expression analyses of single-cell RNA-seq data","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1093/biostatistics/kxw055","publication_url":"https://doi.org/10.1093/biostatistics/kxw055","publication_title":"Overcoming confounding plate effects in differential expression analyses of single-cell RNA-seq data","publication_venue":"Biostatistics","citations":159,"review":"12-doublets-stress-batch#lun-marioni-2017","tags":["plate-based","pseudobulk","type-i-error"]},{"id":"imputation-de-evidence","name":"Imputation and smoothing before DE (Andrews & Hemberg 2018; Hou 2020)","kind":"evidence","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"Evaluations showing that imputation and smoothing (MAGIC, kNN-smoothing, DCA, SAVER, scImpute, DrImpute and others) create false-positive DE and correlations and mostly erase small effects","gain":"Hou 2020 (18 methods): with large DE, 13 of 16 methods raised overlap with bulk DEGs; with small DE, only 2 of 16 did. Andrews & Hemberg: MAGIC, knn-smooth and DCA produced many false positives; SAVER was least likely to","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Imputation reuses the data's own structure, so tests on imputed values are circular. Recommendation from both studies: test on un-imputed counts; use imputation for visualisation only.","url":"https://doi.org/10.12688/f1000research.16613.2","doi":"10.12688/f1000research.16613.2","pmid":"30906525","cite_title":"False signals induced by single-cell imputation.","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.12688/f1000research.16613.2","publication_url":"https://doi.org/10.12688/f1000research.16613.2","publication_title":"False signals induced by single-cell imputation.","publication_venue":"F1000Research","citations":156,"citations_total":455,"citations_papers":2,"review":"03-low-cell-stats#imputation-de-evidence","tags":["imputation","denoising","false-positives"],"site":"https://doi.org/10.12688/f1000research.16613.2"},{"id":"recat","name":"reCAT","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"Orders unsynchronised cells along the cell cycle with a travelling-salesman path and a hidden Markov model to call phases","gain_source":"none","requires":["filtered-matrix"],"caveats":"Last repository update 2019.","url":"https://github.com/tinglab/reCAT","repo_url":"https://github.com/tinglab/reCAT","language":"R","doi":"10.1038/s41467-017-00039-z","pmid":"28630425","cite_title":"Reconstructing cell cycle pseudo time-series via single-cell transcriptome data","year":"2017","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-017-00039-z","publication_url":"https://doi.org/10.1038/s41467-017-00039-z","publication_title":"Reconstructing cell cycle pseudo time-series via single-cell transcriptome data","publication_venue":"Nature Communications","citations":156,"repo_stars":22,"repo_pushed":"2019-03-16","review":"12-doublets-stress-batch#recat","tags":["pseudotime","unmaintained"]},{"id":"partial-dissociation-seq","name":"Partial-dissociation sequencing (ProximID, paired-cell sequencing, ClumpSeq)","kind":"design","layer":"core","categories":["discarded-data","doublets","screen-design"],"side":"additive","tier":"published-unbenchmarked","summary":"Designs that deliberately sequence attached cell pairs or small clumps and use one partner's identity or zonation to infer the other's neighbourhood","recovers":"spatial context and preferential interactions that full dissociation destroys","requires":["filtered-matrix","reference"],"caveats":"low throughput and tissue-specific protocols; clumps must be distinguished from random co-encapsulation; not designed for pooled multiplexed screens","url":"https://doi.org/10.1038/s41592-018-0009-z","doi":"10.1038/s41592-018-0009-z","pmid":"29786092","cite_title":"Mapping the physical network of cellular interactions","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-018-0009-z","publication_url":"https://doi.org/10.1038/s41592-018-0009-z","publication_title":"Mapping the physical network of cellular interactions","publication_venue":"Nature Methods","citations":155,"citations_total":597,"citations_papers":4,"review":"05-discarded-data#partial-dissociation-seq","tags":["doublets-as-signal","cell-interactions","spatial","design"],"site":"https://doi.org/10.1038/s41592-018-0009-z"},{"id":"pipecomp","name":"pipeComp","kind":"tool","layer":"core","categories":["qc-benchmarks","qc-metrics-thresholds","doublets"],"side":"neutral","tier":"published-unbenchmarked","summary":"R framework for benchmarking whole scRNA-seq pipelines, applied to filtering, doublet detection, normalisation, feature selection and clustering on data with known identities","gain":"stringent global MAD filtering removes subpopulations with extreme but healthy properties; accuracy plateaus and can fall with stringency; recommends 5 MADs or 3 MADs on at least 2 metrics; doublet calls and MAD outliers barely overlap","gain_source":"independent","caveats":"Benchmarks used FACS-sorted mixtures and simulations, not treated or damaged samples.","url":"https://github.com/plger/pipeComp","repo_url":"https://github.com/plger/pipeComp","language":"R","doi":"10.1186/s13059-020-02136-7","pmid":"32873325","cite_title":"pipeComp, a general framework for the evaluation of computational pipelines, reveals performant single cell RNA-seq preprocessing tools","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02136-7","publication_url":"https://doi.org/10.1186/s13059-020-02136-7","publication_title":"pipeComp, a general framework for the evaluation of computational pipelines, reveals performant single cell RNA-seq preprocessing tools","publication_venue":"Genome biology","citations":148,"repo_stars":44,"repo_pushed":"2026-05-20","review":"02-calling-qc-damaged#pipecomp","tags":["benchmark","filtering"]},{"id":"ahlmann-eltze-2023","name":"Ahlmann-Eltze and Huber 2023, comparison of transformations","kind":"evidence","layer":"adjacent","categories":["normalisation"],"side":"neutral","tier":"standard","summary":"Benchmark of 22 transformations from four families (delta method, model residuals, latent expression, factor analysis) on simulated and real data, scored by recovery of each cell's nearest neighbours","gain":"The shifted logarithm log(y/s + 1) followed by PCA performed as well as or better than the more sophisticated alternatives; Pearson residuals performed similarly well; shifted log on CPM performed poorly","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Scores k-NN recovery, not marker detection or DE; on one dataset cells with size factors outside 0.1-10x the median were removed before benchmarking. Advises against CPM input and against rescaling log values per cell.","url":"https://doi.org/10.1038/s41592-023-01814-1","repo_url":"https://github.com/const-ae/transformGamPoi","language":"R","doi":"10.1038/s41592-023-01814-1","pmid":"37037999","cite_title":"Comparison of transformations for single-cell RNA-seq data.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-023-01814-1","publication_url":"https://doi.org/10.1038/s41592-023-01814-1","publication_title":"Comparison of transformations for single-cell RNA-seq data.","publication_venue":"Nature Methods","citations":147,"repo_stars":22,"repo_pushed":"2023-04-11","review":"21-concepts-preprocessing#ahlmann-eltze-2023","tags":["benchmark","transformation","shifted-log"],"site":"https://doi.org/10.1038/s41592-023-01814-1"},{"id":"mattei-2020","name":"Mattei et al. 2020 enzymatic versus cold mechanical brain dissociation","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"Standard enzymatic digestion of mouse brain at 37 C caused profound, consistent changes in the transcriptome and proteotype of neurons and glia compared with mechanical dissociation at 4 C","gain":"none (cautionary finding)","gain_source":"none","doi":"10.3390/ijms21217944","pmid":"33114694","cite_title":"Enzymatic Dissociation Induces Transcriptional and Proteotype Bias in Brain Cell Populations","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.3390/ijms21217944","publication_url":"https://doi.org/10.3390/ijms21217944","publication_title":"Enzymatic Dissociation Induces Transcriptional and Proteotype Bias in Brain Cell Populations","publication_venue":"International Journal of Molecular Sciences","citations":143,"review":"12-doublets-stress-batch#mattei-2020","tags":["dissociation","brain"]},{"id":"concept-perturbation-models","name":"Perturbation response estimation and prediction","kind":"concept","layer":"adjacent","categories":["perturbation-models"],"side":"neutral","tier":"standard","summary":"Estimating the transcriptional effect of a genetic or chemical perturbation against controls, and predicting effects of unseen perturbations, doses or combinations, from pooled CRISPR screens and multiplexed drug screens","caveats":"Deep prediction models have not beaten additive or linear baselines on held-out genetic perturbations (Ahlmann-Eltze 2025); estimates are only as good as the cells left after guide assignment, demultiplexing and QC, which perturbations themselves change","doi":"10.1016/j.cels.2021.05.016","pmid":"34139164","cite_title":"Machine learning for perturbational single-cell omics.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2021.05.016","publication_url":"https://doi.org/10.1016/j.cels.2021.05.016","publication_title":"Machine learning for perturbational single-cell omics.","publication_venue":"Cell Systems","citations":137,"citation_note":"1 listed paper(s) had no citation count","citations_total":1166,"citations_papers":4,"review":"22-concepts-downstream#concept-perturbation-models","tags":["concept","perturb-seq","drug-screen"]},{"id":"caglayan-2022","name":"Caglayan et al. 2022 neuronal ambient RNA in brain nuclei","kind":"evidence","layer":"core","categories":["ambient-rna"],"side":"neutral","tier":"published-unbenchmarked","summary":"Shows that neuronal ambient RNA contaminates glial nuclei in brain snRNA-seq and that previously annotated immature oligodendrocytes are such contaminated glia","gain":"after in silico removal, rare committed oligodendrocyte progenitors not annotated in most adult human brain datasets were found","gain_source":"independent","caveats":"Brain nuclei; a cautionary result about annotation rather than a tool comparison.","doi":"10.1016/j.neuron.2022.09.010","pmid":"36240767","cite_title":"Neuronal ambient RNA contamination causes misinterpreted and masked cell types in brain single-nuclei datasets","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.neuron.2022.09.010","publication_url":"https://doi.org/10.1016/j.neuron.2022.09.010","publication_title":"Neuronal ambient RNA contamination causes misinterpreted and masked cell types in brain single-nuclei datasets","publication_venue":"Neuron","citations":131,"review":"11-quant-calling-ambient#caglayan-2022","tags":["nuclei","brain","cautionary"]},{"id":"tricycle","name":"tricycle","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"benchmarked","summary":"Projects cells onto a fixed reference cell-cycle embedding (mouse neurosphere PCA) by transfer learning and returns a continuous cell-cycle position","gain":"Guo & Chen 2024: relatively accurate on mouse data, less accurate on human data; no method consistently best","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Accuracy depends on how well the reference matches the data (Guo & Chen 2024); continuous output had to be discretised for that comparison, which may understate it.","url":"https://bioconductor.org/packages/tricycle","repo_url":"https://github.com/hansenlab/tricycle","language":"R","doi":"10.1186/s13059-021-02581-y","pmid":"35101061","cite_title":"Universal prediction of cell-cycle position using transfer learning","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-021-02581-y","publication_url":"https://doi.org/10.1186/s13059-021-02581-y","publication_title":"Universal prediction of cell-cycle position using transfer learning","publication_venue":"Genome biology","citations":126,"repo_stars":31,"repo_pushed":"2022-03-18","benchmarks":["guo-2024-cell-cycle-comparison"],"benchmark_refs":[{"id":"guo-2024-cell-cycle-comparison","name":"Guo and Chen 2024, cell-cycle phase identification comparison","url":"https://doi.org/10.1093/bib/bbad517"}],"review":"12-doublets-stress-batch#tricycle","tags":["bioconductor","transfer-learning","continuous"],"site":"https://bioconductor.org/packages/tricycle"},{"id":"scpipe","name":"scPipe","kind":"tool","layer":"core","categories":["alignment-quantification"],"side":"neutral","tier":"published-unbenchmarked","summary":"Bioconductor preprocessing pipeline (Rsubread alignment, barcode demultiplexing, UMI deduplication, gene counting, QC) for plate and droplet protocols, extended to scATAC-seq","recovers":"a fully R-based preprocessing path with per-cell QC statistics","gain":"You 2021 (same lab, so not independent): among workflows with the most optimal clustering combinations and slightly higher silhouette widths on cell-line mixtures","gain_source":"self-reported","requires":["fastq"],"caveats":"Assigned systematically more reads to pseudogenes and retained more library size variation than other workflows (You 2021); slow on large datasets.","url":"https://bioconductor.org/packages/scPipe","repo_url":"https://github.com/LuyiTian/scPipe","language":"multiple","doi":"10.1371/journal.pcbi.1006361","pmid":"30096152","cite_title":"scPipe: A flexible R/Bioconductor preprocessing pipeline for single-cell RNA-sequencing data","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pcbi.1006361","publication_url":"https://doi.org/10.1371/journal.pcbi.1006361","publication_title":"scPipe: A flexible R/Bioconductor preprocessing pipeline for single-cell RNA-sequencing data","publication_venue":"PLoS Computational Biology","citations":117,"citations_total":190,"citations_papers":2,"repo_stars":67,"repo_pushed":"2023-12-11","review":"11-quant-calling-ambient#scpipe","tags":["bioconductor","plate"],"site":"https://bioconductor.org/packages/scPipe"},{"id":"cell-village","name":"Cell villages (pooled genotypes in one dish)","kind":"design","layer":"core","categories":["screen-design","batch-and-plate-effects"],"side":"additive","tier":"published-unbenchmarked","summary":"Cells from many donors or lines are cultured together in one dish and assigned back to their donor from transcribed SNPs, so lines share one environment instead of one well each","recovers":"donors or lines per well without per-line tags, and removal of well-to-well confounding between lines","gain":"Neural progenitors from 44 donors cultured in one shared environment and assigned by Dropulation; the same pooling idea carries 50 cancer lines per well in Tahoe-100M and up to 99 lines in MIX-Seq","gain_source":"self-reported","requires":["genotypes"],"caveats":"Lines compete, so fast-growing and resistant lines dominate after treatment; the dish is one replicate of the environment; interactions between lines through the shared medium were not measured in these studies","repo_url":"https://github.com/broadinstitute/Drop-seq","language":"Java","doi":"10.1016/j.stem.2023.01.010","pmid":"36796362","cite_title":"Natural variation in gene expression and viral susceptibility revealed by neural progenitor cell villages","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.stem.2023.01.010","publication_url":"https://doi.org/10.1016/j.stem.2023.01.010","publication_title":"Natural variation in gene expression and viral susceptibility revealed by neural progenitor cell villages","publication_venue":"Cell stem cell","citations":113,"repo_stars":137,"repo_pushed":"2026-10-16","review":"04-screen-design#cell-village","tags":["genotype","pooling","cell-village","donors"]},{"id":"deepcycle","name":"DeepCycle","kind":"tool","layer":"core","categories":["cell-cycle-and-stress","trajectories"],"side":"neutral","tier":"published-unbenchmarked","summary":"Autoencoder that fits the cycling pattern of cell-cycle genes in unspliced-spliced space to assign each cell a cell-cycle angle","gain_source":"none","requires":["spliced-unspliced"],"url":"https://github.com/andreariba/DeepCycle","repo_url":"https://github.com/andreariba/DeepCycle","language":"Python","doi":"10.1038/s41467-022-30545-8","pmid":"35606383","cite_title":"Cell cycle gene regulation dynamics revealed by RNA velocity and deep-learning","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-022-30545-8","publication_url":"https://doi.org/10.1038/s41467-022-30545-8","publication_title":"Cell cycle gene regulation dynamics revealed by RNA velocity and deep-learning","publication_venue":"Nature Communications","citations":112,"repo_stars":52,"repo_pushed":"2023-04-25","review":"12-doublets-stress-batch#deepcycle","tags":["velocity","deep-learning"]},{"id":"alevin-fry","name":"alevin-fry / simpleaf (salmon alevin successor)","kind":"tool","layer":"core","categories":["alignment-quantification","cell-calling"],"side":"neutral","tier":"benchmarked","summary":"Lightweight mapping (pseudoalignment with structural constraints or selective alignment) to a spliced plus intronic (splici) reference, with EM resolution of gene-ambiguous UMIs and spliced, unspliced and ambiguous counts in one run; simpleaf wraps it","recovers":"gene-ambiguous UMIs allocated by EM rather than discarded; nascent counts for nuclei and velocity from the same run","gain":"You 2021: among the top 3 workflows (with Cell Ranger) on one downstream ranking, > 50x faster than dropSeqPipe at 600M reads; self-reported (simulated 10x): mean relative false-positive expression per cell 0.011 with splici vs 0.328 for kallisto|bustools on a spliced-only index; ~2.6x faster and ~6.3x less memory than STARsolo","gain_source":"independent","requires":["fastq"],"caveats":"Kuijpers 2024: on SPLiT-seq its downstream results were \"difficult to interpret\". You 2021: retained more biological noise among lowly expressed features and pseudogenes. The original salmon alevin used a putative whitelist that let through low-UMI barcodes absent from the 10x whitelist and found ~50% of the cardiac endothelial cells other tools found (Bruning 2022). Default cell filtering (knee) is permissive or strict depending on the mode chosen; QCatch (PMID 41987571) adds cell calling and QC reports.","url":"https://alevin-fry.readthedocs.io","repo_url":"https://github.com/COMBINE-lab/alevin-fry","language":"Rust","doi":"10.1038/s41592-022-01408-3","pmid":"35277707","cite_title":"Alevin-fry unlocks rapid, accurate and memory-frugal quantification of single-cell RNA-seq data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-022-01408-3","publication_url":"https://doi.org/10.1038/s41592-022-01408-3","publication_title":"Alevin-fry unlocks rapid, accurate and memory-frugal quantification of single-cell RNA-seq data","publication_venue":"Nature Methods","citations":111,"citation_note":"2 listed paper(s) had no citation count","citations_total":396,"citations_papers":3,"repo_stars":219,"repo_pushed":"2026-10-24","benchmarks":["bruning-2022-aligner-benchmark","you-2021-preprocessing-benchmark","kuijpers-2024-splitseq-pipelines"],"benchmark_refs":[{"id":"bruning-2022-aligner-benchmark","name":"Brüning et al. 2022, single-cell aligner comparison","url":"https://doi.org/10.1093/gigascience/giac001"},{"id":"you-2021-preprocessing-benchmark","name":"You et al. 2021, UMI preprocessing workflow benchmark","url":"https://doi.org/10.1186/s13059-021-02552-3"},{"id":"kuijpers-2024-splitseq-pipelines","name":"Kuijpers et al. 2024, SPLiT-seq pipeline comparison","url":"https://doi.org/10.1186/s12864-024-10285-3"}],"review":"11-quant-calling-ambient#alevin-fry","tags":["nuclei","multimapping","velocity","low-memory"],"site":"https://alevin-fry.readthedocs.io"},{"id":"sequencing-depth-allocation","name":"Sequencing depth allocation (one read per cell per gene)","kind":"evidence","layer":"core","categories":["screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Mathematical framework showing that, for a fixed read budget, gene distribution properties are estimated best at about one read per cell per gene with an empirical Bayes estimator","gain":"The optimal allocation gave about half the relative error of the depth used in a standard 10x PBMC 4k dataset","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Targets population-level gene properties, not per-cell calls or DE between conditions; assumes the empirical Bayes estimator is used rather than plug-in estimates","doi":"10.1038/s41467-020-14482-y","pmid":"32034137","cite_title":"Determining sequencing depth in a single-cell RNA-seq experiment","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-020-14482-y","publication_url":"https://doi.org/10.1038/s41467-020-14482-y","publication_title":"Determining sequencing depth in a single-cell RNA-seq experiment","publication_venue":"Nature Communications","citations":111,"review":"04-screen-design#sequencing-depth-allocation","tags":["depth","budget","design"]},{"id":"miqc","name":"miQC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","damaged-cells"],"side":"both","tier":"published-unbenchmarked","summary":"Fits a two-component mixture of regressions of mito fraction on genes detected and removes cells with high posterior probability of being compromised","recovers":"intact cells with naturally high mito fraction, especially in tumours","gain":"menstrual blood (10x): removes 13,499 cells (19.0%) vs 29,129 (41%) at a 10% mito cut; pancreas (C1): 7.8% vs 45.5%; six ovarian cancer samples: 8.1-49.0% vs 8.6-94.8% (miQC removed more in 1 of 6)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Assumes two populations along the genes-mito line; removed a cardiomyocyte cluster (median 15% mito) that ddqc kept; could not be evaluated on MitoChontrol's perturbation tests because they violate its model.","url":"https://bioconductor.org/packages/miQC","repo_url":"https://github.com/greenelab/miQC","language":"R","doi":"10.1371/journal.pcbi.1009290","pmid":"34428202","cite_title":"miQC: An adaptive probabilistic framework for quality control of single-cell RNA-sequencing data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pcbi.1009290","publication_url":"https://doi.org/10.1371/journal.pcbi.1009290","publication_title":"miQC: An adaptive probabilistic framework for quality control of single-cell RNA-sequencing data","publication_venue":"PLoS Computational Biology","citations":108,"repo_stars":23,"repo_pushed":"2026-05-27","review":"02-calling-qc-damaged#miqc","tags":["mito","mixture-model","tumour"],"site":"https://bioconductor.org/packages/miQC"},{"id":"scpower","name":"scPower","kind":"tool","layer":"core","categories":["screen-design","low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"R package and web tool that models detection power for multi-sample DE and eQTL designs from samples, cells per sample and reads per cell under a budget, including overloading-induced doublets","recovers":"power per unit budget by choosing samples, cells and depth together","gain":"Across platforms, shallow sequencing of many cells gave higher overall power than deep sequencing of fewer cells; with doublet detection, overloading lanes increased power despite discarding doublets","gain_source":"self-reported","requires":["replicates"],"caveats":"Built for comparisons between individuals (donors as replicates), not drug-by-line grids; its doublet model is a lower bound on observed rates; priors come from PBMC data unless re-fitted; Mandric 2020 reached the same more-samples-lower-depth conclusion for cell-type eQTL","repo_url":"https://github.com/heiniglab/scPower","language":"R","doi":"10.1038/s41467-021-26779-7","pmid":"34785648","cite_title":"scPower accelerates and optimizes the design of multi-sample single cell transcriptomic studies","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-021-26779-7","publication_url":"https://doi.org/10.1038/s41467-021-26779-7","publication_title":"scPower accelerates and optimizes the design of multi-sample single cell transcriptomic studies","publication_venue":"Nature Communications","citations":107,"citations_total":168,"citations_papers":2,"repo_stars":52,"repo_pushed":"2025-01-08","review":"04-screen-design#scpower","tags":["power","design","budget","depth"]},{"id":"amulet","name":"AMULET","kind":"tool","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Flags snATAC-seq nuclei with too many genomic loci covered by more than two reads, which a diploid nucleus cannot produce, so it detects homotypic as well as heterotypic multiplets without simulation","recovers":"homotypic multiplets that simulation-based ATAC callers miss","gain":"recall on simulated heterotypic multiplets 0.80 and 0.90 in two PBMC samples against 0.25 and 0.23 for ArchR; precision estimated from donor multiplexing (self-reported)","gain_source":"self-reported","requires":["bam"],"caveats":"Needs depth (works best above about 25K median valid reads per nucleus); on low-depth islet data recall fell to 0.35-0.37 and ArchR was higher on one sample; scDblFinder's authors found it good on only one of three datasets.","url":"https://github.com/UcarLab/AMULET","repo_url":"https://github.com/UcarLab/AMULET","language":"multiple","doi":"10.1186/s13059-021-02469-x","pmid":"34465366","cite_title":"AMULET: a novel read count-based method for effective multiplet detection from single nucleus ATAC-seq data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-021-02469-x","publication_url":"https://doi.org/10.1186/s13059-021-02469-x","publication_title":"AMULET: a novel read count-based method for effective multiplet detection from single nucleus ATAC-seq data","publication_venue":"Genome biology","citations":106,"citations_total":1067,"citations_papers":2,"repo_stars":35,"repo_pushed":"2023-01-03","review":"12-doublets-stress-batch#amulet","tags":["atac","multiome","fragments"]},{"id":"junttila-2022","name":"Junttila et al. 2022: multi-subject differential state benchmark","kind":"evidence","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"neutral","tier":"standard","summary":"Independent benchmark of 18 differential-state methods (6 pseudobulk, 3 mixed models, naive cell-level and latent-variable methods) on muscat simulations, reference-free simulations and mock comparisons of real PBMC data","gain":"Pseudobulk methods had the highest average AUROC and clearly the best F1; naive methods had the highest sensitivity but many false positives, and adding latent-variable subject terms did not fix them","gain_source":"independent","requires":["replicates"],"caveats":"Sum aggregation generally beat mean (opposite to Murphy & Skene 2022). muscat_MM was inferior on all four data types; MAST_RE slightly better than NEBULA-LN. Simulated 8-40 subjects and 500-4,000 cells per sample, so it does not cover 1-2 replicates per condition.","url":"https://doi.org/10.1093/bib/bbac286","doi":"10.1093/bib/bbac286","pmid":"35880426","cite_title":"Benchmarking methods for detecting differential states between conditions from multi-subject single-cell RNA-seq data.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/bib/bbac286","publication_url":"https://doi.org/10.1093/bib/bbac286","publication_title":"Benchmarking methods for detecting differential states between conditions from multi-subject single-cell RNA-seq data.","publication_venue":"Briefings in Bioinformatics","citations":106,"review":"03-low-cell-stats#junttila-2022","tags":["benchmark","pseudoreplication"],"site":"https://doi.org/10.1093/bib/bbac286"},{"id":"ccremover","name":"ccRemover","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Identifies components of the expression matrix driven by cell-cycle genes (by bootstrap on marker genes) and removes only those, rather than regressing on phase scores","gain":"improved clustering of cell types on simulations and three real datasets (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"CRAN package with no repository activity since 2017.","repo_url":"https://github.com/cran/ccRemover","language":"R","doi":"10.1038/srep33892","pmid":"27670849","cite_title":"Identifying and removing the cell-cycle effect from single-cell RNA-Sequencing data","year":"2016","verified":true,"citation_check":"verified","publication":"doi:10.1038/srep33892","publication_url":"https://doi.org/10.1038/srep33892","publication_title":"Identifying and removing the cell-cycle effect from single-cell RNA-Sequencing data","publication_venue":"Scientific Reports","citations":102,"repo_stars":4,"repo_pushed":"2017-08-19","review":"12-doublets-stress-batch#ccremover","tags":["cran","unmaintained"]},{"id":"t-cell-monocyte-complexes","name":"Circulating T cell-monocyte complexes","kind":"evidence","layer":"core","categories":["discarded-data","doublets"],"side":"additive","tier":"published-unbenchmarked","summary":"Shows that a sizeable share of T cell-monocyte doublets in human blood are biological complexes with polarised LFA1/ICAM1, whose frequency and phenotype change with infection and immunisation","recovers":"evidence that some events removed as doublets are real, condition-dependent biology","requires":["protein"],"caveats":"shown by flow and imaging cytometry, not by scRNA-seq doublet calling; complexes also hide in the live-singlet gate and can be misread as novel mixed-lineage cell types (Burel 2020); most dual-lineage events are still technical","url":"https://doi.org/10.7554/eLife.46045","doi":"10.7554/eLife.46045","pmid":"31237234","cite_title":"Circulating T cell-monocyte complexes are markers of immune perturbations","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.7554/eLife.46045","publication_url":"https://doi.org/10.7554/eLife.46045","publication_title":"Circulating T cell-monocyte complexes are markers of immune perturbations","publication_venue":"eLife","citations":102,"citation_note":"1 listed paper(s) had no citation count","citations_total":140,"citations_papers":3,"review":"05-discarded-data#t-cell-monocyte-complexes","tags":["doublets-as-signal","cell-interactions","blood","flow-cytometry"],"site":"https://doi.org/10.7554/eLife.46045"},{"id":"diem","name":"DIEM","kind":"tool","layer":"core","categories":["cell-calling","ambient-rna"],"side":"both","tier":"published-unbenchmarked","summary":"Semi-supervised multinomial mixture that fixes barcodes under 100 UMIs as debris and classifies the rest as nuclear or debris-contaminated, aimed at single-nucleus data","recovers":"nuclei that EmptyDrops discards, while removing debris droplets that pass count thresholds","gain":"six frozen adipose snRNA-seq samples: 95.7% of passing droplets nuclear vs 87.9% (EmptyDrops) and 84.5% (quantile); EmptyDrops removed 1,038 and 782 nuclear droplets in two samples where DIEM removed 63 and 36 (self-reported)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Nuclear vs debris labels in the paper come from spliced-read fraction, MT% and MALAT1, not ground truth; low code activity (last push 2022-12); no independent benchmark.","url":"https://github.com/marcalva/diem","repo_url":"https://github.com/marcalva/diem","language":"R","doi":"10.1038/s41598-020-67513-5","pmid":"32620816","cite_title":"Enhancing droplet-based single-nucleus RNA-seq resolution using the semi-supervised machine learning classifier DIEM","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41598-020-67513-5","publication_url":"https://doi.org/10.1038/s41598-020-67513-5","publication_title":"Enhancing droplet-based single-nucleus RNA-seq resolution using the semi-supervised machine learning classifier DIEM","publication_venue":"Scientific Reports","citations":92,"repo_stars":11,"repo_pushed":"2022-12-20","review":"11-quant-calling-ambient#diem","tags":["nuclei","droplet"]},{"id":"demuxafy","name":"Demuxafy","kind":"tool","layer":"core","categories":["demux-genotype","doublets","qc-benchmarks"],"side":"both","tier":"published-unbenchmarked","summary":"Containerised framework that runs 7 genotype demultiplexers and 7 transcriptional doublet detectors, combines them by intersection, and recommends combinations by pool design","recovers":"more correctly classified singlets and doublets than any single method","gain":"Self-reported on 74 PBMC pools (12-16 donors, ~20 000 droplets), fibroblast pools and 70 in silico pools of 2-128 donors: recommended combinations raised MCC by about 0.09 over single methods (FDR < 0.05); demultiplexing alone leaves 173 (16 donors) to 1 325 (2 donors) same-donor, different-cell-type doublets per 20 000-droplet capture","gain_source":"self-reported","requires":["bam","genotypes","filtered-matrix"],"caveats":"Built and tested on donor pools, not on hashing; intersections favour purity, so check singlet yield; with 16 or more donors and no reference genotypes vireo alone was best","url":"https://demultiplexing-doublet-detecting-docs.readthedocs.io","repo_url":"https://github.com/drneavin/Demultiplexing_Doublet_Detecting_Docs","language":"multiple","doi":"10.1186/s13059-024-03224-8","pmid":"38622708","cite_title":"Demuxafy: improvement in droplet assignment by integrating multiple single-cell demultiplexing and doublet detection methods.","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-024-03224-8","publication_url":"https://doi.org/10.1186/s13059-024-03224-8","publication_title":"Demuxafy: improvement in droplet assignment by integrating multiple single-cell demultiplexing and doublet detection methods.","publication_venue":"Genome biology","citations":87,"repo_stars":20,"repo_pushed":"2026-10-21","review":"01-demux-recovery#demuxafy","tags":["genotype","ensemble","doublets"],"site":"https://demultiplexing-doublet-detecting-docs.readthedocs.io"},{"id":"peco","name":"peco","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"Predicts continuous cell-cycle phase from a few cyclic genes, trained on iPSCs with FUCCI imaging-derived phase","gain":"five genes predicted position on the cycle to within 14% of the full cycle in iPSCs (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Trained on iPSCs (C1, plate-based); transfer to other cell types untested by others.","url":"https://github.com/jhsiao999/peco","repo_url":"https://github.com/jhsiao999/peco","language":"R","doi":"10.1101/gr.247759.118","pmid":"32312741","cite_title":"Characterizing and inferring quantitative cell cycle phase in single-cell RNA-seq data analysis","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1101/gr.247759.118","publication_url":"https://doi.org/10.1101/gr.247759.118","publication_title":"Characterizing and inferring quantitative cell cycle phase in single-cell RNA-seq data analysis","publication_venue":"Genome Research","citations":87,"repo_stars":14,"repo_pushed":"2020-11-14","review":"12-doublets-stress-batch#peco","tags":["fucci","continuous"]},{"id":"spotclean","name":"SpotClean","kind":"tool","layer":"core","categories":["ambient-rna","multimodal"],"side":"both","tier":"published-unbenchmarked","summary":"Probabilistic model of spot swapping in sequencing-based spatial transcriptomics (Visium) that uses off-tissue spots to estimate how UMIs bleed between spots and returns decontaminated counts","recovers":"spot-specific expression, sharper marker genes and tissue-region boundaries","gain":"in a tumour section over 13% of spots were labelled malignant in raw data but not after SpotClean, matching the H&E better (self-reported)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Needs at least 25% of spots off tissue to estimate contamination; built for Visium-style arrays.","url":"https://bioconductor.org/packages/SpotClean","repo_url":"https://github.com/zijianni/SpotClean","language":"R","doi":"10.1038/s41467-022-30587-y","pmid":"35624112","cite_title":"SpotClean adjusts for spot swapping in spatial transcriptomics data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-022-30587-y","publication_url":"https://doi.org/10.1038/s41467-022-30587-y","publication_title":"SpotClean adjusts for spot swapping in spatial transcriptomics data","publication_venue":"Nature Communications","citations":85,"repo_stars":40,"repo_pushed":"2026-01-13","review":"13-metrics-guides-multimodal#spotclean","tags":["spatial","visium","ambient"],"site":"https://bioconductor.org/packages/SpotClean"},{"id":"concept-feature-selection","name":"Feature selection (highly variable and deviant genes)","kind":"concept","layer":"adjacent","categories":["feature-selection"],"side":"neutral","tier":"standard","summary":"Choosing the genes, usually 2,000 to 4,000, whose variation across cells exceeds technical expectation, which then define the PCA, the neighbour graph, clusters and integration","caveats":"HVG lists computed on log-CPM pick up technical variability (Townes 2019); the number of genes and the method change integration and query mapping results (Zappia 2025).","doi":"10.1186/s13059-021-02544-3","pmid":"34847932","cite_title":"Feature selection revisited in the single-cell era.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-021-02544-3","publication_url":"https://doi.org/10.1186/s13059-021-02544-3","publication_title":"Feature selection revisited in the single-cell era.","publication_venue":"Genome biology","citations":83,"citations_total":3544,"citations_papers":4,"review":"21-concepts-preprocessing#concept-feature-selection","tags":["concept","hvg"]},{"id":"massoni-badosa-2020","name":"Massoni-Badosa et al. 2020 sampling-time artefacts","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress","batch-and-plate-effects"],"side":"both","tier":"published-unbenchmarked","summary":"Measured how hours at room temperature between blood draw and cryopreservation change single-cell profiles, built a time score to flag and regress the effect, and showed 4 C storage prevents it","recovers":"samples with long processing delays, by score regression or by cold storage","gain":"1,185 genes changed in PBMC (318 up, 867 down) and 1,868 in CLL beyond 2 h; the time score classified affected cells with AUC 0.888; regression restored mixing by kBET, mainly for delays under 8 h; at 4 C no global artefact up to 48 h","gain_source":"independent","caveats":"Regressing a signature can remove subtle biology and homogenise subpopulations (the authors' own caution); blood and CLL only.","doi":"10.1186/s13059-020-02032-0","pmid":"32393363","cite_title":"Sampling time-dependent artifacts in single-cell genomics studies","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02032-0","publication_url":"https://doi.org/10.1186/s13059-020-02032-0","publication_title":"Sampling time-dependent artifacts in single-cell genomics studies","publication_venue":"Genome biology","citations":83,"review":"12-doublets-stress-batch#massoni-badosa-2020","tags":["blood","sampling-time","signature-score","kbet"]},{"id":"sctk-qc","name":"SCTK-QC (singleCellTK)","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","cell-calling","doublets","ambient-rna"],"side":"neutral","tier":"published-unbenchmarked","summary":"Pipeline in the singleCellTK R package that runs empty-droplet detection, standard QC metrics, several doublet callers and ambient RNA estimation on one dataset and writes an HTML report, from the command line, R or a GUI","recovers":"nothing by itself; puts several callers side by side so that their disagreement is visible before filtering","gain":"none reported as cells retained; GUI benchmarked on 34k and 68k PBMC datasets for run time","gain_source":"none","requires":["raw-matrix"],"caveats":"A wrapper; each step has the caveats of the tool it calls (EmptyDrops, barcodeRanks, scDblFinder, cxds, bcds, DoubletFinder, scrublet, DecontX, SoupX). DoubletFinder dominates memory use on large data.","url":"https://bioconductor.org/packages/singleCellTK","repo_url":"https://github.com/compbiomed/singleCellTK","language":"R","doi":"10.1038/s41467-022-29212-9","pmid":"35354805","cite_title":"Comprehensive generation, visualization, and reporting of quality control metrics for single-cell RNA sequencing data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-022-29212-9","publication_url":"https://doi.org/10.1038/s41467-022-29212-9","publication_title":"Comprehensive generation, visualization, and reporting of quality control metrics for single-cell RNA sequencing data","publication_venue":"Nature Communications","citations":82,"repo_stars":190,"repo_pushed":"2026-10-09","review":"13-metrics-guides-multimodal#sctk-qc","tags":["report","wrapper","bioconductor","gui"],"site":"https://bioconductor.org/packages/singleCellTK"},{"id":"dropletqc","name":"DropletQC","kind":"tool","layer":"core","categories":["damaged-cells","cell-calling"],"side":"both","tier":"published-unbenchmarked","summary":"Computes each barcode's nuclear fraction (share of intronic, unspliced reads) and separates empty droplets, damaged cells and intact cells","recovers":"a damage call that does not depend on mito fraction, so high-mito intact cells need not be removed","gain":"after EmptyDrops, flagged cell-free droplets at 9.5% (mouse brain), 6.0% (Hodgkin), 4.0% (glioblastoma), 0.4% (PBMC) and damaged cells at 14.0%, 5.2%, 9.8% and one cell; damaged share rose from 4.1% to 13.8% after cryopreservation and rose with apoptosis in staurosporine-treated HEK293","gain_source":"self-reported","requires":["bam"],"caveats":"Nuclear fraction varies by cell type and chemistry (defaults: mean nuclear fraction + 0.15 and UMI < 50% of the population) and was tested on whole-cell data; removed 1,968 cells vs scQCenrich 1,185 on mouse brain (scQCenrich authors).","url":"https://github.com/powellgenomicslab/DropletQC","repo_url":"https://github.com/powellgenomicslab/DropletQC","language":"R","doi":"10.1186/s13059-021-02547-0","pmid":"34857027","cite_title":"DropletQC: improved identification of empty droplets and damaged cells in single-cell RNA-seq data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-021-02547-0","publication_url":"https://doi.org/10.1186/s13059-021-02547-0","publication_title":"DropletQC: improved identification of empty droplets and damaged cells in single-cell RNA-seq data","publication_venue":"Genome biology","citations":81,"citations_total":139,"citations_papers":3,"repo_stars":43,"repo_pushed":"2021-11-18","review":"02-calling-qc-damaged#dropletqc","tags":["nuclear-fraction","intronic-fraction","apoptosis"]},{"id":"dsp-fixation","name":"DSP reversible fixation","kind":"design","layer":"core","categories":["screen-design","damaged-cells"],"side":"additive","tier":"published-unbenchmarked","summary":"Reversible amine crosslinking with DSP (Lomant's reagent) stabilises single cells for later RNA-seq and is undone with a reducing agent","recovers":"the treated state at the moment of fixation, and a viability record because fixed cells keep propidium iodide","gain":"K562 cells: fresh against fixed bulk r above 0.93; fixed replicates stored 3 or 7 days r about 0.97, comparable to fresh replicates; less cell-to-cell variation in cDNA yield than fresh cells","gain_source":"self-reported","caveats":"Slightly lower cDNA yield and a detectable 3' bias; shown on the Fluidigm C1, later adopted in optimised sci-RNA-seq3 (DSP/methanol) and FixNCut","doi":"10.1038/s41598-018-20372-7","pmid":"29391536","cite_title":"A practical solution for preserving single cells for RNA sequencing","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41598-018-20372-7","publication_url":"https://doi.org/10.1038/s41598-018-20372-7","publication_title":"A practical solution for preserving single cells for RNA sequencing","publication_venue":"Scientific Reports","citations":80,"review":"04-screen-design#dsp-fixation","tags":["fixed","preservation","dsp","reversible"]},{"id":"signature-scoring-evidence","name":"Gene-set scoring benchmarks (cell-level and pseudobulk)","kind":"evidence","layer":"core","categories":["low-cell-stats"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmarks of gene-set and pathway scoring methods (AUCell, UCell, ssGSEA, GSVA, z-score, Pagoda2, PLAGE, JASMINE) showing that method choice changes the size and even the sign of program scores","gain_source":"none","requires":["filtered-matrix"],"caveats":"Zhang 2020: Pagoda2 best overall of 7 tools on 32 datasets, PLAGE most stable. Noureen 2022 (JASMINE): bulk-style scorers are biased by the number of detected genes per cell. PathwayBench (Research Square preprint, 8 pseudobulked case-control datasets, 682 donors): rank-based AUCell and UCell inverted the sign in 40% of simulated replicates under high competitor burden; no method met all five criteria.","url":"https://doi.org/10.1016/j.csbj.2020.10.007","doi":"10.1016/j.csbj.2020.10.007","pmid":"33209207","cite_title":"Benchmarking algorithms for pathway activity transformation of single-cell RNA-seq data.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.csbj.2020.10.007","publication_url":"https://doi.org/10.1016/j.csbj.2020.10.007","publication_title":"Benchmarking algorithms for pathway activity transformation of single-cell RNA-seq data.","publication_venue":"Computational and Structural Biotechnology Journal","citations":79,"citations_total":140,"citations_papers":3,"review":"03-low-cell-stats#signature-scoring-evidence","tags":["signatures","benchmark","preprint"],"site":"https://doi.org/10.1016/j.csbj.2020.10.007"},{"id":"revelio","name":"Revelio","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"benchmarked","summary":"Rotates the PCA space to the plane in which cycling cells trace a circle and orders cells in cell-cycle time, with five phase labels","gain":"Guo & Chen 2024: no method consistently best; Revelio assigns every cell to one of its five phases","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Assumes the data are dominated by cycling cells (built on immortalised lines).","url":"https://github.com/danielschw188/Revelio","repo_url":"https://github.com/danielschw188/Revelio","language":"R","doi":"10.15252/msb.20209946","pmid":"33205894","cite_title":"The transcriptome dynamics of single cells during the cell cycle","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.15252/msb.20209946","publication_url":"https://doi.org/10.15252/msb.20209946","publication_title":"The transcriptome dynamics of single cells during the cell cycle","publication_venue":"Molecular Systems Biology","citations":79,"repo_stars":11,"repo_pushed":"2021-04-29","benchmarks":["guo-2024-cell-cycle-comparison"],"benchmark_refs":[{"id":"guo-2024-cell-cycle-comparison","name":"Guo and Chen 2024, cell-cycle phase identification comparison","url":"https://doi.org/10.1093/bib/bbad517"}],"review":"12-doublets-stress-batch#revelio","tags":["continuous"]},{"id":"ddqc","name":"ddqc (data-driven QC)","kind":"tool","layer":"core","categories":["qc-metrics-thresholds"],"side":"both","tier":"published-unbenchmarked","summary":"Clusters cells after minimal filtering, then applies MAD thresholds on genes, UMIs, mito and ribo fractions within each cluster","recovers":"cell types with high mito or low complexity (neutrophils, metabolically active parenchymal cells) that global cut-offs remove","gain":"retained a median 95.4% of input cells vs 69.4% with a fixed <200 genes / >10% mito cut-off ('over a third more cells')","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"A cluster made mostly of damaged cells sets its own baseline and can survive; MitoChontrol's perturbation test found ddqc kept many mito-inflated cells and removed some unperturbed ones.","url":"https://github.com/ayshwaryas/ddqc","repo_url":"https://github.com/ayshwaryas/ddqc","language":"multiple","doi":"10.1186/s13059-022-02820-w","pmid":"36575523","cite_title":"Biology-inspired data-driven quality control for scientific discovery in single-cell transcriptomics","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-022-02820-w","publication_url":"https://doi.org/10.1186/s13059-022-02820-w","publication_title":"Biology-inspired data-driven quality control for scientific discovery in single-cell transcriptomics","publication_venue":"Genome biology","citations":77,"repo_stars":22,"repo_pushed":"2023-05-22","review":"02-calling-qc-damaged#ddqc","tags":["per-cluster","mito","ribo"]},{"id":"gruffi","name":"Gruffi","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Scores glycolysis and ER-stress pathway activity on granular neighbourhoods and removes the stressed subpopulation found in brain organoids but not in fetal tissue","gain":"identified an organoid-specific stressed population across about 190,000 cells and six validation datasets; removal improved resemblance to in vivo data (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Built for organoids, where the stress is culture-induced hypoxia rather than handling; removes cells.","url":"https://github.com/jn-goe/gruffi","repo_url":"https://github.com/jn-goe/gruffi","language":"R","doi":"10.15252/embj.2022111118","pmid":"35919947","cite_title":"Gruffi: an algorithm for computational removal of stressed cells from brain organoid transcriptomic datasets","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.15252/embj.2022111118","publication_url":"https://doi.org/10.15252/embj.2022111118","publication_title":"Gruffi: an algorithm for computational removal of stressed cells from brain organoid transcriptomic datasets","publication_venue":"The EMBO Journal","citations":77,"repo_stars":14,"repo_pushed":"2024-11-07","review":"12-doublets-stress-batch#gruffi","tags":["organoid","seurat"]},{"id":"gmm-demux","name":"GMM-Demux","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"benchmarked-sota","summary":"Command-line tool that fits a two-component Gaussian mixture to each CLR-normalised tag and models droplet formation to estimate multiplet rates and flag multiplet-induced (phony) clusters","recovers":"singlet calls with confidence scores; an estimate of undetectable same-sample multiplets for planning","gain":"Howitt 2023: mean F 0.905, 0.770, 0.720 (BAL) and 0.823 (cell lines), under 20% of genetic doublets called singlets, judged close to demuxmix and HTODemux. Self-reported: PBMC multiplet rate cut from 23.9% to 6.45%, then 3.29% after removing 9 phony clusters","gain_source":"independent","requires":["tag-counts"],"caveats":"Bimodality assumption: failed to recover many samples in a 30-sample imbalanced simulation and errored on low-cell PDX batches (deMULTIplex2 authors); over-assigned doublets on a high-background CMO dataset (CMDdemux authors)","url":"https://github.com/CHPGenetics/GMM-demux","repo_url":"https://github.com/CHPGenetics/GMM-demux","language":"Python","doi":"10.1186/s13059-020-02084-2","pmid":"32731885","cite_title":"GMM-Demux: sample demultiplexing, multiplet detection, experiment planning, and novel cell-type verification in single cell sequencing.","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02084-2","publication_url":"https://doi.org/10.1186/s13059-020-02084-2","publication_title":"GMM-Demux: sample demultiplexing, multiplet detection, experiment planning, and novel cell-type verification in single cell sequencing.","publication_venue":"Genome biology","citations":74,"repo_stars":19,"repo_pushed":"2026-08-22","benchmarks":["howitt-2023-hto-benchmark","mylka-2022-hashing-comparison","sayed-2025-hashtag-benchmark","curion-2024-hadge-comparison"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022, antibody versus lipid hashing","url":"https://doi.org/10.1186/s13059-022-02628-8"},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"}],"review":"01-demux-recovery#gmm-demux","tags":["hashing","multiplet-rate","planning"]},{"id":"pertpy","name":"pertpy","kind":"tool","layer":"adjacent","categories":["perturbation-models","de-pseudobulk"],"side":"neutral","tier":"published-unbenchmarked","summary":"scverse Python framework for single-cell perturbation experiments that bundles harmonized perturbation datasets, metadata annotation, perturbation distances and implementations of established methods (Mixscape, Milo, scCODA, Augur, scGen and others)","gain_source":"none","requires":["filtered-matrix","multiple-conditions"],"caveats":"A framework of re-implementations; each method keeps its own assumptions and benchmark record","url":"https://pertpy.readthedocs.io","repo_url":"https://github.com/scverse/pertpy","language":"Python","doi":"10.1038/s41592-025-02909-7","pmid":"41476114","cite_title":"Pertpy: an end-to-end framework for perturbation analysis.","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-025-02909-7","publication_url":"https://doi.org/10.1038/s41592-025-02909-7","publication_title":"Pertpy: an end-to-end framework for perturbation analysis.","publication_venue":"Nature Methods","citations":74,"repo_stars":352,"repo_pushed":"2026-10-23","review":"22-concepts-downstream#pertpy","tags":["scverse","perturb-seq","drug-screen"],"site":"https://pertpy.readthedocs.io"},{"id":"you-2021","name":"You et al. 2021 preprocessing workflow benchmark","kind":"evidence","layer":"core","categories":["alignment-quantification","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of 10 end-to-end preprocessing workflows (Cell Ranger, Optimus, salmon alevin, alevin-fry, kallisto bustools, dropSeqPipe, scPipe, zUMIs, celseq2, scruff) on CEL-Seq2 and 10x cell-line and tissue mixtures with known labels","gain":"preprocessing choice mattered less than later steps; almost all workflow and normalisation combinations clustered well; cells unique to a subset of workflows were < 5% of cells; kallisto bustools and alevin-fry were > 50x faster than dropSeqPipe at 600M reads","gain_source":"independent","caveats":"emptyDrops called ~60,000 cells on zUMIs and kallisto bustools output for a ~3,000-cell mixture, so Cell Ranger v2 filtering was used there; the authors develop scPipe, so its results are not independent; 2021 versions.","doi":"10.1186/s13059-021-02552-3","pmid":"34906205","cite_title":"Benchmarking UMI-based single-cell RNA-seq preprocessing workflows","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-021-02552-3","publication_url":"https://doi.org/10.1186/s13059-021-02552-3","publication_title":"Benchmarking UMI-based single-cell RNA-seq preprocessing workflows","publication_venue":"Genome biology","citations":73,"benchmarks":["you-2021-preprocessing-benchmark"],"benchmark_refs":[{"id":"you-2021-preprocessing-benchmark","name":"You et al. 2021, UMI preprocessing workflow benchmark","url":"https://doi.org/10.1186/s13059-021-02552-3"}],"review":"11-quant-calling-ambient#you-2021","tags":["benchmark","mixture","plate","10x"]},{"id":"sccomp","name":"sccomp","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","discarded-data"],"side":"neutral","tier":"published-unbenchmarked","summary":"Bayesian sum-constrained Beta-binomial model for differential composition and differential variability that models the proportion mean-variability association and identifies and excludes outlier observations","recovers":"composition and variability changes robust to outlier samples","requires":["filtered-matrix","replicates"],"caveats":"self-reported improvement over existing methods; outlier exclusion could hide a genuine extreme response, such as a highly cytotoxic well","url":"https://github.com/MangiolaLaboratory/sccomp","repo_url":"https://github.com/MangiolaLaboratory/sccomp","language":"R","doi":"10.1073/pnas.2203828120","pmid":"37549298","cite_title":"sccomp: Robust differential composition and variability analysis for single-cell data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1073/pnas.2203828120","publication_url":"https://doi.org/10.1073/pnas.2203828120","publication_title":"sccomp: Robust differential composition and variability analysis for single-cell data","publication_venue":"Proceedings of the National Academy of Sciences","citations":72,"repo_stars":135,"repo_pushed":"2026-10-15","review":"05-discarded-data#sccomp","tags":["composition","differential-variability","outliers","bayesian"]},{"id":"tn-test","name":"TN test (valid post-clustering differential analysis)","kind":"tool","layer":"adjacent","categories":["clustering-annotation","de-pseudobulk"],"side":"neutral","tier":"published-unbenchmarked","summary":"Truncated-normal test for marker genes between clusters that conditions on the clustering, so that the separation the clustering forced does not produce artificially low p-values","gain":"Showed that reusing the same cells for clustering and DE gives artificially low p-values and false discoveries, and corrected them","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Research code (notebooks), not maintained since 2019; the double-dipping problem it names is the lasting contribution.","url":"https://github.com/jessemzhang/tn_test","repo_url":"https://github.com/jessemzhang/tn_test","language":"Python","doi":"10.1016/j.cels.2019.07.012","pmid":"31521605","cite_title":"Valid Post-clustering Differential Analysis for Single-Cell RNA-Seq.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2019.07.012","publication_url":"https://doi.org/10.1016/j.cels.2019.07.012","publication_title":"Valid Post-clustering Differential Analysis for Single-Cell RNA-Seq.","publication_venue":"Cell Systems","citations":72,"repo_stars":38,"repo_pushed":"2019-05-28","review":"21-concepts-preprocessing#tn-test","tags":["double-dipping","marker-genes","selective-inference"]},{"id":"trade","name":"TRADE (transcriptome-wide analysis of differential expression)","kind":"tool","layer":"core","categories":["low-cell-stats","perturbation-models"],"side":"additive","tier":"published-unbenchmarked","summary":"Models the distribution of true DE effects from pseudobulk effect estimates and standard errors to estimate each perturbation's transcriptome-wide impact, including effects too small for per-gene significance","recovers":"A per-perturbation effect-size summary that remains estimable when few individual genes pass FDR","gain":"FDR-significant genes explained only 13-36% of estimated transcriptome-wide impact across five Perturb-seq screens (K562 genome-wide 36%, Jurkat essential 13%); a typical perturbation affected about 45 genes, essential genes over 500","gain_source":"self-reported","requires":["multiple-conditions","replicates"],"caveats":"Inputs are DESeq2 pseudobulk estimates per batch (perturbed vs unperturbed within batch), so validity rests on those standard errors. Downward bias for very small effects at finite sample size. Developed on CRISPR screens.","url":"https://github.com/ajaynadig/TRADEtools","repo_url":"https://github.com/ajaynadig/TRADEtools","language":"R","doi":"10.1038/s41588-025-02169-3","pmid":"40259084","cite_title":"Transcriptome-wide analysis of differential expression in perturbation atlases.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41588-025-02169-3","publication_url":"https://doi.org/10.1038/s41588-025-02169-3","publication_title":"Transcriptome-wide analysis of differential expression in perturbation atlases.","publication_venue":"Nature Genetics","citations":69,"repo_stars":42,"repo_pushed":"2026-06-08","review":"03-low-cell-stats#trade","tags":["effect-size","perturb-seq","drug-screen"]},{"id":"dreamlet","name":"dreamlet","kind":"tool","layer":"core","categories":["low-cell-stats","de-pseudobulk"],"side":"additive","tier":"published-unbenchmarked","summary":"R/Bioconductor pseudobulk workflow fitting precision-weighted linear mixed models per cell cluster, with initial weights from a Poisson model in which more cells and reads per sample mean higher precision","recovers":"Samples with few cells stay in the model at lower weight instead of being dropped; plates, pools and batches can enter as random effects","gain":"Poisson-initialised weights improved performance over the unweighted model; dreamlet controlled the permuted-label false positive rate (target 5%) across sample sizes where muscat limma-voom and glmer/MAST GLMMs were inflated; 2.2M cells from 1,000 donors x 12 cell types pseudobulked in 10 min with 20 GB","gain_source":"self-reported","requires":["filtered-matrix","replicates"],"caveats":"processAssays defaults: min.cells = 5 per sample-cluster, min.samples = 4 per cluster, min.prop = 0.4. Weights model measurement precision, not between-culture biological variance, so one culture per condition is still unreplicated. Built for cohorts of hundreds of donors. No independent benchmark of dreamlet itself; its engine dream (DREAM) was recommended as the quality/runtime compromise for atlas-level data by Hafner 2025.","url":"https://diseaseneurogenomics.github.io/dreamlet/","repo_url":"https://github.com/DiseaseNeurogenomics/dreamlet","language":"R","doi":"10.1038/s41467-026-75680-8","pmid":"42778542","cite_title":"Efficient differential expression analysis of large-scale single-cell transcriptomics data using Dreamlet.","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-026-75680-8","publication_url":"https://doi.org/10.1038/s41467-026-75680-8","publication_title":"Efficient differential expression analysis of large-scale single-cell transcriptomics data using Dreamlet.","publication_venue":"Nature Communications","citations":67,"citations_total":458,"citations_papers":4,"repo_stars":25,"repo_pushed":"2026-09-23","review":"03-low-cell-stats#dreamlet","tags":["pseudobulk","precision-weights","mixed-models","drug-screen"],"site":"https://diseaseneurogenomics.github.io/dreamlet/"},{"id":"janssen-2023","name":"Janssen et al. 2023 background-noise study","kind":"evidence","layer":"core","categories":["ambient-rna","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Genotype-mixed mouse kidney scRNA-seq and snRNA-seq used to measure background noise per cell and to benchmark CellBender, DecontX and SoupX","gain":"background made up 3-35% of UMIs per cell, mostly ambient RNA; CellBender gave the most precise estimates and the largest marker-gene improvement; clustering was fairly robust to noise","gain_source":"independent","caveats":"One tissue (kidney) and three methods; nuclei and cells differ in which method wins.","doi":"10.1186/s13059-023-02978-x","pmid":"37337297","cite_title":"The effect of background noise and its removal on the analysis of single-cell expression data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-023-02978-x","publication_url":"https://doi.org/10.1186/s13059-023-02978-x","publication_title":"The effect of background noise and its removal on the analysis of single-cell expression data","publication_venue":"Genome biology","citations":62,"review":"02-calling-qc-damaged#janssen-2023","tags":["benchmark","genotype-mixing","nuclei"]},{"id":"soneson-2021-velocity-preprocessing","name":"Soneson et al. 2021: preprocessing choices change RNA velocity","kind":"evidence","layer":"adjacent","categories":["trajectories"],"side":"neutral","tier":"published-unbenchmarked","summary":"Compared five quantification tools (13 approaches) for spliced and unspliced abundances in five droplet scRNA-seq datasets and showed that the differences propagate to estimated velocities and their biological interpretation","gain":"Substantial between-tool differences in unspliced and spliced counts, concentrated in identifiable gene types, with large effects on velocity; both the feature definitions and the quantification algorithm matter","gain_source":"independent","requires":["fastq","spliced-unspliced"],"caveats":"Shows sensitivity, not which pipeline is right; Wu 2026 later confirmed that most velocity methods are not robust to the quantifier","doi":"10.1371/journal.pcbi.1008585","pmid":"33428615","cite_title":"Preprocessing choices affect RNA velocity results for droplet scRNA-seq data.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pcbi.1008585","publication_url":"https://doi.org/10.1371/journal.pcbi.1008585","publication_title":"Preprocessing choices affect RNA velocity results for droplet scRNA-seq data.","publication_venue":"PLoS Computational Biology","citations":62,"citations_total":64,"citations_papers":2,"review":"22-concepts-downstream#soneson-2021-velocity-preprocessing","tags":["rna-velocity","quantification"]},{"id":"scatac-pro","name":"scATAC-pro","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal","cell-calling"],"side":"both","tier":"published-unbenchmarked","summary":"Workbench for scATAC-seq data from any protocol that computes QC metrics at each processing step, calls cells with a choice of methods and writes QC and analysis reports","recovers":"a protocol-agnostic QC report for non-10x scATAC data","gain":"none quantified","gain_source":"none","requires":["fastq"],"caveats":"Last code push September 2024; cell-calling options have not been independently compared.","url":"https://github.com/tanlabcode/scATAC-pro","repo_url":"https://github.com/tanlabcode/scATAC-pro","doi":"10.1186/s13059-020-02008-0","pmid":"32312293","cite_title":"scATAC-pro: a comprehensive workbench for single-cell chromatin accessibility sequencing data","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02008-0","publication_url":"https://doi.org/10.1186/s13059-020-02008-0","publication_title":"scATAC-pro: a comprehensive workbench for single-cell chromatin accessibility sequencing data","publication_venue":"Genome biology","citations":60,"repo_stars":24,"repo_pushed":"2024-09-23","review":"13-metrics-guides-multimodal#scatac-pro","tags":["atac","pipeline","report"]},{"id":"cellmixs","name":"CellMixS (cell-specific mixing score)","kind":"tool","layer":"core","categories":["batch-and-plate-effects"],"side":"neutral","tier":"published-unbenchmarked","summary":"Cell-level batch mixing score (cms) that compares distance distributions to each batch within a cell's neighbourhood, separating local batch bias from unbalanced batch composition","gain":"cell-specific metrics outperformed cell-type-level and global metrics on real and synthetic data (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"url":"https://bioconductor.org/packages/CellMixS","repo_url":"https://github.com/almutlue/CellMixS","language":"R","doi":"10.26508/lsa.202001004","pmid":"33758076","cite_title":"CellMixS: quantifying and visualizing batch effects in single-cell RNA-seq data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.26508/lsa.202001004","publication_url":"https://doi.org/10.26508/lsa.202001004","publication_title":"CellMixS: quantifying and visualizing batch effects in single-cell RNA-seq data","publication_venue":"Life Science Alliance","citations":58,"repo_stars":8,"repo_pushed":"2024-09-04","review":"12-doublets-stress-batch#cellmixs","tags":["bioconductor","metric","diagnostic"],"site":"https://bioconductor.org/packages/CellMixS"},{"id":"de-rop-2024","name":"De Rop et al. 2024 scATAC-seq protocol benchmark","kind":"evidence","layer":"core","categories":["qc-benchmarks","multimodal"],"side":"neutral","tier":"published-unbenchmarked","summary":"Independent comparison of eight scATAC-seq methods in 47 experiments on reference PBMCs, processed with one pipeline (PUMATAC), measuring library complexity, TSS enrichment and fraction of fragments in peaks","gain":"169,000 PBMC profiles; methods differed in library complexity and tagmentation specificity, which carried through to cell-type annotation, genotype demultiplexing, peak calling, differential accessibility and motif enrichment","gain_source":"independent","caveats":"One sample type (PBMC); protocols and kits change quickly, so rankings age.","repo_url":"https://github.com/aertslab/PUMATAC","doi":"10.1038/s41587-023-01881-x","pmid":"37537502","cite_title":"Systematic benchmarking of single-cell ATAC-sequencing protocols","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-023-01881-x","publication_url":"https://doi.org/10.1038/s41587-023-01881-x","publication_title":"Systematic benchmarking of single-cell ATAC-sequencing protocols","publication_venue":"Nature Biotechnology","citations":58,"repo_stars":29,"repo_pushed":"2025-09-23","review":"13-metrics-guides-multimodal#de-rop-2024","tags":["atac","benchmark","protocol"]},{"id":"phantompurger","name":"PhantomPurgeR (index-hopping model)","kind":"tool","layer":"core","categories":["batch-and-plate-effects","ambient-rna"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Estimates the sample index-hopping rate in multiplexed droplet libraries and assigns each hopped read to its sample of origin, purging phantom molecules","gain":"hopping probability 0.003-0.009, yet phantom molecules exceeded 8% in over 25% of samples and reached 85% in low-complexity samples; phantom molecules created phantom cells and turned empty droplets into apparent cells (self-reported)","gain_source":"self-reported","requires":["bam"],"caveats":"Last repository update 2020.","url":"https://github.com/rfarouni/PhantomPurgeR","repo_url":"https://github.com/rfarouni/PhantomPurgeR","language":"R","doi":"10.1038/s41467-020-16522-z","pmid":"32483174","cite_title":"Model-based analysis of sample index hopping reveals its widespread artifacts in multiplexed single-cell RNA-sequencing","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-020-16522-z","publication_url":"https://doi.org/10.1038/s41467-020-16522-z","publication_title":"Model-based analysis of sample index hopping reveals its widespread artifacts in multiplexed single-cell RNA-sequencing","publication_venue":"Nature Communications","citations":55,"repo_stars":0,"repo_pushed":"2020-08-24","review":"12-doublets-stress-batch#phantompurger","tags":["index-hopping","sequencing-lane","low-complexity"]},{"id":"mrvi","name":"MrVI (multi-resolution variational inference)","kind":"tool","layer":"adjacent","categories":["perturbation-models","de-pseudobulk"],"side":"additive","tier":"published-unbenchmarked","summary":"Deep generative model in scvi-tools with a sample-aware latent space that computes counterfactual cells to stratify samples and find cell-state-specific DE and differential abundance without predefined clusters","recovers":"Sample-level structure (which drugs or doses act alike) and local effects confined to cell subsets","gain":"On sci-Plex A549 (92 drugs x 4 doses as samples), MrVI sample distances agreed better with Connectivity Map drug similarity and placed doses of the same drug closer together than PCA- or scVI-based stratification","gain_source":"self-reported","requires":["multiple-conditions"],"caveats":"Requires training a neural network on all cells. Counterfactual DE is model-based, not a replicate-level test. With one well per drug-dose the 'sample' is the well, so drug and well effects are confounded. No independent benchmark found.","url":"https://docs.scvi-tools.org/en/stable/user_guide/models/mrvi.html","repo_url":"https://github.com/scverse/scvi-tools","language":"Python","doi":"10.1038/s41592-025-02808-x","pmid":"41083897","cite_title":"Deep generative modeling of sample-level heterogeneity in single-cell genomics.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-025-02808-x","publication_url":"https://doi.org/10.1038/s41592-025-02808-x","publication_title":"Deep generative modeling of sample-level heterogeneity in single-cell genomics.","publication_venue":"Nature Methods","citations":54,"repo_stars":1717,"repo_pushed":"2026-10-22","review":"03-low-cell-stats#mrvi","tags":["deep-generative","scvi-tools","sci-plex","drug-screen"],"site":"https://docs.scvi-tools.org/en/stable/user_guide/models/mrvi.html"},{"id":"uda-seq","name":"UDA-seq","kind":"design","layer":"core","categories":["demux-combinatorial"],"side":"additive","tier":"published-unbenchmarked","summary":"Overloaded droplets are barcoded first and a plate-based post-indexing round then splits each droplet barcode into single cells, across RNA, ATAC and multiome modalities","recovers":"cells and samples per channel at a low collision rate","gain":"Collision rate 1.23% with 96-well post-indexing against 6.29% expected from the droplet barcode alone; over 100,000 cells from three dozen frozen clinical biopsies in one channel","gain_source":"self-reported","requires":["fastq"],"caveats":"Cell recovery about 57% (3' RNA) and 37% (multiome); new method without independent benchmark","doi":"10.1038/s41592-024-02586-y","pmid":"39833568","cite_title":"UDA-seq: universal droplet microfluidics-based combinatorial indexing for massive-scale multimodal single-cell sequencing","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-024-02586-y","publication_url":"https://doi.org/10.1038/s41592-024-02586-y","publication_title":"UDA-seq: universal droplet microfluidics-based combinatorial indexing for massive-scale multimodal single-cell sequencing","publication_venue":"Nature Methods","citations":54,"review":"04-screen-design#uda-seq","tags":["combinatorial-indexing","overloading","multimodal","clinical"]},{"id":"buus-2021","name":"Buus et al. 2021 antibody titration for CITE-seq","kind":"design","layer":"core","categories":["ambient-rna","multimodal"],"side":"additive","tier":"published-unbenchmarked","summary":"Titrates antibody concentration, staining volume and cell number for a 52-antibody 5' CITE-seq panel and shows that recommended concentrations cause unnecessary background from unbound antibody","recovers":"protein signal and sequencing budget otherwise spent on background tags","gain":"adjusted panel gave a 57% higher median positive signal and 43% lower background (median 26.3% to 14.9% of UMIs assigned to background); HLA-DR used 9% of cell-containing UMIs in lung tumour and could be cut at least fourfold","gain_source":"self-reported","requires":["protein"],"caveats":"One panel and two samples (healthy PBMC, immune cells from a lung tumour); optimal titres depend on the antibody lot and the cell numbers stained.","doi":"10.7554/eLife.61973","pmid":"33861199","cite_title":"Improving oligo-conjugated antibody signal in multimodal single-cell analysis","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.7554/eLife.61973","publication_url":"https://doi.org/10.7554/eLife.61973","publication_title":"Improving oligo-conjugated antibody signal in multimodal single-cell analysis","publication_venue":"eLife","citations":53,"review":"13-metrics-guides-multimodal#buus-2021","tags":["citeseq","protein","titration","wet-lab"]},{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022 antibody versus lipid hashing comparison","kind":"evidence","layer":"core","categories":["qc-benchmarks","demux-hashing","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Comparison of antibody (TotalSeq-A, -B, -C), lipid (MULTI-seq, custom LMO, cholesterol CMO) and CellPlex hashing on cell lines, nuclei, PBMC and mouse tissues, scored against freemuxlet genotypes","recovers":"tells which tag chemistry loses fewest cells for a sample type","gain":"Overall classification accuracy 0.96 for antibody-hashed cell lines versus 0.68-0.84 for lipids (negatives 1.1-1.8% versus 7-21%); capturing 48% more cells raised doublets by 125% and unassigned barcodes by 325%; nuclei: cholesterol-oligo 0.84 versus antibody 0.51; brain cells: lipid 0.85-0.87 versus antibody 0.38; PBMC pre-sort labelling: TotalSeq-B 0.96, CellPlex 0.93","gain_source":"independent","requires":["tag-counts","genotypes"],"caveats":"Cell-line results may not transfer to fragile or treated cells; dying high-mito PBMC clusters hashed worse; hashtag swapping ranged from ~0.1% (antibody) to 2.68% (custom LMO); one lab, four cell lines and few tissues; accuracy depends on the caller's parameters (HTODemux positive.quantile 0.99 to 0.9 raised antibody-nuclei OCA from 0.54 to 0.65); the freemuxlet reference itself misses some doublets","url":"https://doi.org/10.1186/s13059-022-02628-8","doi":"10.1186/s13059-022-02628-8","pmid":"35172874","cite_title":"Comparative analysis of antibody- and lipid-based multiplexing methods for single-cell RNA-seq.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-022-02628-8","publication_url":"https://doi.org/10.1186/s13059-022-02628-8","publication_title":"Comparative analysis of antibody- and lipid-based multiplexing methods for single-cell RNA-seq.","publication_venue":"Genome biology","citations":53,"review":"01-demux-recovery#mylka-2022-hashing-comparison","tags":["benchmark","hashing","lipid","antibody","nuclei","cellplex"],"site":"https://doi.org/10.1186/s13059-022-02628-8"},{"id":"cyclum","name":"Cyclum","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"both","tier":"published-unbenchmarked","summary":"Autoencoder with a circular latent variable that infers cell-cycle pseudotime and can remove the cell-cycle component","gain":"more accurate and robust cell-cycle characterisation than existing approaches, and clearer subpopulations after removal (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"url":"https://github.com/KChen-lab/Cyclum","repo_url":"https://github.com/KChen-lab/Cyclum","language":"Python","doi":"10.1038/s41467-020-15295-9","pmid":"32188848","cite_title":"Latent periodic process inference from single-cell RNA-seq data","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-020-15295-9","publication_url":"https://doi.org/10.1038/s41467-020-15295-9","publication_title":"Latent periodic process inference from single-cell RNA-seq data","publication_venue":"Nature Communications","citations":52,"repo_stars":23,"repo_pushed":"2021-12-17","review":"12-doublets-stress-batch#cyclum","tags":["deep-learning","continuous"]},{"id":"du-2020","name":"Du et al. 2020 STAR vs kallisto evaluation","kind":"evidence","layer":"core","categories":["alignment-quantification","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Third-party comparison of STAR (STARsolo for 10x) and kallisto (with bustools) on Drop-seq, Fluidigm and 10x data, including mouse cortex nuclei, for gene abundance, accuracy against RNA-FISH and resources","gain":"STAR detected more genes with higher expression and agreed better with RNA-FISH Gini indices; similar or better cell-type annotation; kallisto ~4x faster with 7.7x less memory","gain_source":"independent","caveats":"2019-era versions (kallisto 0.45-0.46, bustools 0.39.3); small datasets.","doi":"10.1534/g3.120.401160","pmid":"32220951","cite_title":"Evaluation of STAR and Kallisto on Single Cell RNA-Seq Data Alignment","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1534/g3.120.401160","publication_url":"https://doi.org/10.1534/g3.120.401160","publication_title":"Evaluation of STAR and Kallisto on Single Cell RNA-Seq Data Alignment","publication_venue":"G3 Genes Genomes Genetics","citations":52,"benchmarks":["du-2020-star-kallisto"],"benchmark_refs":[{"id":"du-2020-star-kallisto","name":"Du et al. 2020, STAR versus kallisto on scRNA-seq","url":"https://doi.org/10.1534/g3.120.401160"}],"review":"11-quant-calling-ambient#du-2020","tags":["benchmark"]},{"id":"reference-optimisation","name":"Optimised transcriptomic references for scRNA-seq (Pool et al. 2023)","kind":"method","layer":"core","categories":["alignment-quantification"],"side":"additive","tier":"published-unbenchmarked","summary":"Rebuilds the gene annotation used for counting by extending poorly annotated 3' ends, adding a hybrid pre-mRNA mapping strategy and resolving overlapping genes, so reads lost as intergenic or ambiguous are counted","recovers":"genes and marker genes missing from droplet data, and cell types they define","gain":"recovered missing gene expression and revealed missing cell types and marker genes across mouse and human tissue datasets (self-reported, abstract)","gain_source":"self-reported","requires":["fastq"],"caveats":"Gains are specific to how badly the default annotation fits the tissue; requires re-running alignment; no independent comparison found. Related evidence that the annotation choice matters - Bruning 2022 found the unfiltered annotation (with pseudogenes) lowered mito fractions and gave up to 10% more cells per sample.","doi":"10.1038/s41592-023-02003-w","pmid":"37697162","cite_title":"Recovery of missing single-cell RNA-sequencing data with optimized transcriptomic references","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-023-02003-w","publication_url":"https://doi.org/10.1038/s41592-023-02003-w","publication_title":"Recovery of missing single-cell RNA-sequencing data with optimized transcriptomic references","publication_venue":"Nature Methods","citations":52,"citations_total":95,"citations_papers":2,"review":"11-quant-calling-ambient#reference-optimisation","tags":["annotation","non-model"]},{"id":"sinqc","name":"SinQC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Flags technical-artefact cells whose gene expression pattern is inconsistent with their data-quality metrics (mapping rate, library size, detected genes), for plate-based full-length data","recovers":"none; removes artefact cells","gain":"applied to nine datasets; no retention numbers in the abstract","gain_source":"none","requires":["filtered-matrix"],"caveats":"Built for early low-throughput plate data (2016); no public code repository found, only a lab web page.","url":"http://www.morgridge.net/SinQC.html","doi":"10.1093/bioinformatics/btw176","pmid":"27153613","cite_title":"Quality control of single-cell RNA-seq by SinQC","year":"2016","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btw176","publication_url":"https://doi.org/10.1093/bioinformatics/btw176","publication_title":"Quality control of single-cell RNA-seq by SinQC","publication_venue":"Bioinformatics","citations":51,"review":"13-metrics-guides-multimodal#sinqc","tags":["plate","legacy"],"site":"http://www.morgridge.net/SinQC.html"},{"id":"spike-in-reference-cells","name":"Spike-in reference cells","kind":"design","layer":"core","categories":["ambient-rna","screen-design","discarded-data"],"side":"both","tier":"published-unbenchmarked","summary":"Adds standardised cross-species reference cells to every sample so that reads from the sample's genome inside reference cells measure that sample's contamination profile, which then drives decontamination of drug-treated islet cells","recovers":"a per-sample ambient measurement and, in principle, an absolute denominator for cell counts","requires":["filtered-matrix","reference"],"caveats":"shown for decontamination in pancreatic islets (artemether, GABA, FoxO inhibitor, DMSO); use as an absolute cell-count reference in drug screens is untested","url":"https://doi.org/10.1186/s13059-020-02006-2","doi":"10.1186/s13059-020-02006-2","pmid":"32375897","cite_title":"Single-cell RNA-seq with spike-in cells enables accurate quantification of cell-specific drug effects in pancreatic islets","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02006-2","publication_url":"https://doi.org/10.1186/s13059-020-02006-2","publication_title":"Single-cell RNA-seq with spike-in cells enables accurate quantification of cell-specific drug effects in pancreatic islets","publication_venue":"Genome biology","citations":50,"review":"05-discarded-data#spike-in-reference-cells","tags":["spike-in","ambient","drug-screen","absolute-counts","design"],"site":"https://doi.org/10.1186/s13059-020-02006-2"},{"id":"scvi-de","name":"scVI differential expression (lvm-DE)","kind":"tool","layer":"adjacent","categories":["de-pseudobulk","low-cell-stats"],"side":"additive","tier":"benchmarked","summary":"Bayesian DE from scVI-family deep generative models: posterior log-fold-change estimates from the denoised model, with an empirical Bayes treatment of their uncertainty","recovers":"Denoised, depth-corrected effect estimates for sparse genes","gain":"Outperformed state-of-the-art methods at estimating log fold change and detecting DE genes between cell subpopulations","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Compares groups of cells; sample-level replication is not modelled (MrVI adds that). The independent nested benchmark of Hafner 2025 found single-cell-specific methods including scVI no better than pseudobulk DESeq2 on individual datasets, and slower.","url":"https://docs.scvi-tools.org/en/stable/user_guide/models/scvi.html","repo_url":"https://github.com/scverse/scvi-tools","language":"Python","doi":"10.1073/pnas.2209124120","pmid":"37192164","cite_title":"An empirical Bayes method for differential expression analysis of single cells with deep generative models.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1073/pnas.2209124120","publication_url":"https://doi.org/10.1073/pnas.2209124120","publication_title":"An empirical Bayes method for differential expression analysis of single cells with deep generative models.","publication_venue":"Proceedings of the National Academy of Sciences","citations":49,"citations_total":2579,"citations_papers":3,"repo_stars":1717,"repo_pushed":"2026-10-22","benchmarks":["hafner-2025-nested-de-benchmark"],"benchmark_refs":[{"id":"hafner-2025-nested-de-benchmark","name":"Hafner et al. 2025, DE in nested single-cell settings","url":"https://doi.org/10.1093/bib/bbaf397"}],"review":"03-low-cell-stats#scvi-de","tags":["deep-generative","scvi-tools"],"site":"https://docs.scvi-tools.org/en/stable/user_guide/models/scvi.html"},{"id":"concept-de-pseudobulk","name":"Differential expression and differential abundance between conditions","kind":"concept","layer":"adjacent","categories":["de-pseudobulk"],"side":"neutral","tier":"standard","summary":"Testing which genes change expression (differential state) or which cell populations change in abundance between conditions, with biological replicates as the unit of inference, usually by pseudobulk aggregation, mixed models or neighbourhood-level count models","caveats":"Cell-level tests that ignore the replicate structure call hundreds of false DE genes (Squair 2021); every QC step changes which cells are summed into each replicate, so QC losses that differ by condition become DE or abundance results","doi":"10.3390/e24070995","pmid":"35885218","cite_title":"Differential Expression Analysis of Single-Cell RNA-Seq Data: Current Statistical Approaches and Outstanding Challenges.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.3390/e24070995","publication_url":"https://doi.org/10.3390/e24070995","publication_title":"Differential Expression Analysis of Single-Cell RNA-Seq Data: Current Statistical Approaches and Outstanding Challenges.","publication_venue":"Entropy","citations":46,"citations_total":3160,"citations_papers":5,"review":"22-concepts-downstream#concept-de-pseudobulk","tags":["concept","pseudobulk","differential-abundance"]},{"id":"bruning-2022","name":"Brüning et al. 2022 single-cell aligner comparison","kind":"evidence","layer":"core","categories":["alignment-quantification","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Independent comparison of Cell Ranger 6, STARsolo, kallisto, salmon alevin and alevin-fry on three 10x datasets (human PBMC, mouse heart after infarction, mouse endothelial atlas) for whitelisting, cells, genes, clustering and DE","gain":"STARsolo, Cell Ranger 6, alevin and alevin-fry gave similar gene sets; kallisto reported the most cells but many were low-gene and unlabelled, and it detected extra Vmn and Olfr genes (likely artefacts); alevin found ~50% of cardiac endothelial cells; the unfiltered annotation gave up to 10% more cells per sample and lower mito fractions; STARsolo, alevin and kallisto were >= 3x faster than Cell Ranger 6","gain_source":"independent","caveats":"Three 10x datasets, default settings and 2021-era versions (kallisto before nac indices); no ground truth for cell identity beyond marker-based labels.","doi":"10.1093/gigascience/giac001","pmid":"35084033","cite_title":"Comparative analysis of common alignment tools for single-cell RNA sequencing","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/gigascience/giac001","publication_url":"https://doi.org/10.1093/gigascience/giac001","publication_title":"Comparative analysis of common alignment tools for single-cell RNA sequencing","publication_venue":"GigaScience","citations":43,"benchmarks":["bruning-2022-aligner-benchmark"],"benchmark_refs":[{"id":"bruning-2022-aligner-benchmark","name":"Brüning et al. 2022, single-cell aligner comparison","url":"https://doi.org/10.1093/gigascience/giac001"}],"review":"11-quant-calling-ambient#bruning-2022","tags":["benchmark","10x"]},{"id":"dropkick","name":"dropkick","kind":"tool","layer":"core","categories":["cell-calling","qc-metrics-thresholds"],"side":"both","tier":"published-unbenchmarked","summary":"Trains a sparse logistic regression per sample on confident high- and low-quality barcodes from heuristic thresholds, then scores every barcode as cell or empty and low-quality","recovers":"real cells below a knee cut-off in rare populations, while dropping dead and empty barcodes","gain":"high-background simulations: specificity 0.9999 vs 0.9910 (Cell Ranger v2) and 0.9838 (EmptyDrops); colorectal inDrop data: more rare-population cells kept and more dead cells removed; AUROC 0.9817 agreement with EmptyDrops on 46 samples (self-reported)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Called > 9,000 barcodes on a 10x 8k PBMC sample where most callers called ~8,000 (valiDrops paper); no independent benchmark; last code push 2023-11.","url":"https://github.com/KenLauLab/dropkick","repo_url":"https://github.com/KenLauLab/dropkick","language":"Python","doi":"10.1101/gr.271908.120","pmid":"33837131","cite_title":"Automated quality control and cell identification of droplet-based single-cell data using dropkick","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1101/gr.271908.120","publication_url":"https://doi.org/10.1101/gr.271908.120","publication_title":"Automated quality control and cell identification of droplet-based single-cell data using dropkick","publication_venue":"Genome Research","citations":43,"citations_total":53,"citations_papers":2,"repo_stars":26,"repo_pushed":"2023-11-14","review":"11-quant-calling-ambient#dropkick","tags":["droplet","machine-learning"]},{"id":"malat1-quality-marker","name":"MALAT1 as a cell-quality marker (Clarke & Bader 2024)","kind":"method","layer":"core","categories":["damaged-cells","qc-metrics-thresholds"],"side":"both","tier":"published-unbenchmarked","summary":"Uses expression of MALAT1, a nuclear-retained non-coding RNA expressed in nearly all cell types, as a cheap proxy for the spliced/unspliced ratio to spot empty droplets and cytoplasm-poor cells","recovers":"a damage signal without re-reading BAMs for spliced and unspliced counts","gain":"MALAT1 expression was strongly correlated with the splice-ratio measure (preprint; no number in the abstract)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Preprint; applies only to species with a conserved MALAT1; single-nucleus data are nuclear by design, so a high MALAT1 there does not mark damage.","url":"https://www.biorxiv.org/content/10.1101/2024.07.14.603469","doi":"10.1101/2024.07.14.603469","cite_title":"MALAT1 expression indicates cell quality in single-cell RNA sequencing data","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1101/2024.07.14.603469","publication_url":"https://doi.org/10.1101/2024.07.14.603469","publication_is_preprint":true,"publication_title":"MALAT1 expression indicates cell quality in single-cell RNA sequencing data","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":39,"citations_total":71,"citations_papers":2,"review":"13-metrics-guides-multimodal#malat1-quality-marker","tags":["preprint","malat1","nuclear-fraction"],"site":"https://www.biorxiv.org/content/10.1101/2024.07.14.603469"},{"id":"cellhashr","name":"cellhashR (BFF_raw, BFF_cluster, consensus)","kind":"tool","layer":"core","categories":["demux-hashing"],"side":"both","tier":"benchmarked","summary":"R package that runs several hashing callers, including its own bimodal flexible fitting (BFF_raw, BFF_cluster), with tag QC plots and a consensus call across callers","recovers":"singlets agreed by several callers, a hedge when no single caller is trusted","gain":"Self-reported: BFF accurate and consistent on two reference datasets; no independent test of the consensus mode found","gain_source":"self-reported","requires":["tag-counts"],"caveats":"BFF assumes bimodal counts: in Howitt 2023 BFFcluster fell to mean F 0.119 and 0.188 on the weaker BAL batches, called no cells in one ovarian batch, and called over half (BAL) to over 75% (cell lines) of genetic doublets singlets; both BFF modes missed a whole sample in HTOreader's 8-donor pool. BFF also failed on hadge's brain nuclei and both modes ranked among the lowest workflows in Sayed 2025; its one independent win was BFF cluster on Brown 2024's low signal-to-noise CellPlex set, with four-fold more false positives on that study's high-quality MULTI-seq set. The consensus mode was not benchmarked","url":"https://github.com/BimberLab/cellhashR","repo_url":"https://github.com/BimberLab/cellhashR","language":"R","doi":"10.1093/bioinformatics/btac213","pmid":"35561167","cite_title":"BFF and cellhashR: analysis tools for accurate demultiplexing of cell hashing data.","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btac213","publication_url":"https://doi.org/10.1093/bioinformatics/btac213","publication_title":"BFF and cellhashR: analysis tools for accurate demultiplexing of cell hashing data.","publication_venue":"Bioinformatics","citations":38,"repo_stars":32,"repo_pushed":"2026-10-10","benchmarks":["howitt-2023-hto-benchmark","sayed-2025-hashtag-benchmark","curion-2024-hadge-comparison","brown-2024-multiplexing-reagents"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"},{"id":"brown-2024-multiplexing-reagents","name":"Brown et al. 2024, multiplexing reagents and fixed kits","url":"https://doi.org/10.1016/j.ygeno.2024.110793"}],"review":"01-demux-recovery#cellhashr","tags":["hashing","consensus","wrapper"]},{"id":"weber-2021-cancer-genetic-demux","name":"Weber et al. 2021 genetic demultiplexing in cancer","kind":"evidence","layer":"core","categories":["qc-benchmarks","demux-genotype","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"In silico benchmark of genetic demultiplexing on pooled tumour scRNA-seq (high copy-number ovarian cancer, high mutation-burden lung adenocarcinoma) with a reusable Snakemake workflow","gain":"cellSNP/vireo with bulk RNA-seq genotypes recalled 99.0-99.9% of singlets (precision 100%, 85.9%, 77.4% at 0, 20, 30% doublets); 1000 Genomes reference recall 97.9-99.0%; 99.2% of vireo doublet calls were true versus 31.9% for demuxlet","gain_source":"independent","requires":["bam","genotypes"],"caveats":"In silico pools; ambient RNA from debris lowered performance; souporcell, scSplit and freemuxlet not tested; scDblFinder performed poorly on the remaining doublets","url":"https://github.com/lmweber/snp-dmx-cancer","repo_url":"https://github.com/lmweber/snp-dmx-cancer","doi":"10.1093/gigascience/giab062","pmid":"34553212","cite_title":"Genetic demultiplexing of pooled single-cell RNA-sequencing samples in cancer facilitates effective experimental design.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1093/gigascience/giab062","publication_url":"https://doi.org/10.1093/gigascience/giab062","publication_title":"Genetic demultiplexing of pooled single-cell RNA-sequencing samples in cancer facilitates effective experimental design.","publication_venue":"GigaScience","citations":37,"repo_stars":3,"repo_pushed":"2021-07-20","review":"01-demux-recovery#weber-2021-cancer-genetic-demux","tags":["benchmark","genotype","cancer"]},{"id":"spotsweeper","name":"SpotSweeper","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"both","tier":"published-unbenchmarked","summary":"Spatially aware QC for spatial transcriptomics that compares each spot's metrics with its local neighbourhood to find local outliers and regional artefacts instead of using dataset-wide thresholds","recovers":"spots in biologically low-count regions (for example white matter) that global thresholds remove","gain":"identified a consistent set of systematically low-quality Visium barcoded spots across public datasets and two distinct regional artefact types (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Neighbourhood size is a tuning choice; a Python port (Spotsweeper-py, 2025 preprint) exists.","url":"https://bioconductor.org/packages/SpotSweeper","repo_url":"https://github.com/MicTott/SpotSweeper","language":"R","doi":"10.1038/s41592-025-02713-3","pmid":"40481362","cite_title":"SpotSweeper: spatially aware quality control for spatial transcriptomics","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-025-02713-3","publication_url":"https://doi.org/10.1038/s41592-025-02713-3","publication_title":"SpotSweeper: spatially aware quality control for spatial transcriptomics","publication_venue":"Nature Methods","citations":36,"citations_total":73,"citations_papers":3,"repo_stars":17,"repo_pushed":"2026-10-16","review":"13-metrics-guides-multimodal#spotsweeper","tags":["spatial","visium","local-outliers"],"site":"https://bioconductor.org/packages/SpotSweeper"},{"id":"demultiplex2","name":"deMULTIplex2","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"benchmarked-sota","summary":"R package that models tag cross-contamination from its physical mechanism with two negative binomial GLMs (tag-count and cosine-similarity spaces) fitted by EM, giving each cell a posterior sample probability","recovers":"singlets from noisy, imbalanced or low-cell samples, including samples whose tag counts are not bimodal","gain":"Self-reported: 63.2% versus 50.8% of all cells correctly retrieved (deMULTIplex) on multiplexed breast-cancer PDX, including two samples other callers missed; over 99% recall versus 52% (HTODemux) and 73% (demuxmix naive) in a 30-sample imbalanced simulation; accuracy held with about 10 cells per sample and with 5% of tag reads (median 30 tags per cell) on clean data","gain_source":"self-reported","requires":["tag-counts"],"caveats":"Tier rests on Sayed 2025: highest average F over 12 real datasets among the established standalone callers, behind only that study's own clustering workflows (F 0.87 versus 0.9 on its most depth-variable dataset). Competitor comparisons: tied best with CMDdemux on poorly hashed ovarian tumours (79% versus 81% concordance with vireo, CMDdemux paper), but failed on an over-labelled CellPlex PDX dataset (CMDdemux paper); cell-type bias in tag capture is reduced, not removed","url":"https://github.com/Gartner-Lab/deMULTIplex2","repo_url":"https://github.com/Gartner-Lab/deMULTIplex2","language":"R","doi":"10.1186/s13059-024-03177-y","pmid":"38291503","cite_title":"deMULTIplex2: robust sample demultiplexing for scRNA-seq.","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-024-03177-y","publication_url":"https://doi.org/10.1186/s13059-024-03177-y","publication_title":"deMULTIplex2: robust sample demultiplexing for scRNA-seq.","publication_venue":"Genome biology","citations":34,"citations_total":68,"citations_papers":3,"repo_stars":21,"repo_pushed":"2026-03-12","benchmarks":["sayed-2025-hashtag-benchmark"],"benchmark_refs":[{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"}],"review":"01-demux-recovery#demultiplex2","tags":["hashing","lipid","antibody","imbalance","high-plex"]},{"id":"gsfa","name":"GSFA (guided sparse factor analysis)","kind":"tool","layer":"core","categories":["low-cell-stats","perturbation-models"],"side":"additive","tier":"published-unbenchmarked","summary":"Bayesian sparse factor model that infers co-regulated gene modules and each perturbation's effect on them, then propagates module effects back to individual genes","recovers":"Gene-level perturbation effects detectable through shared modules when cells per perturbation are few (hundreds or fewer)","gain":"In simulations GSFA calls at LFSR < 0.05 kept false discovery proportions well below 0.05 in most settings while edgeR-QLF and t-test calls were inflated in count-based scenarios, with higher power than t-test, edgeR-QLF and MAST","gain_source":"self-reported","requires":["multiple-conditions"],"caveats":"Cell-level model of CRISPR screens; well or culture replication is not modelled. Inference uses Gibbs sampling, which its authors note could be replaced by faster variational methods. No independent benchmark found.","url":"https://xinhe-lab.github.io/GSFA/","repo_url":"https://github.com/xinhe-lab/GSFA","language":"R","doi":"10.1038/s41592-023-02017-4","pmid":"37770710","cite_title":"A new Bayesian factor analysis method improves detection of genes and biological processes affected by perturbations in single-cell CRISPR screening.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-023-02017-4","publication_url":"https://doi.org/10.1038/s41592-023-02017-4","publication_title":"A new Bayesian factor analysis method improves detection of genes and biological processes affected by perturbations in single-cell CRISPR screening.","publication_venue":"Nature Methods","citations":34,"repo_stars":25,"repo_pushed":"2023-10-03","review":"03-low-cell-stats#gsfa","tags":["factor-model","perturb-seq"],"site":"https://xinhe-lab.github.io/GSFA/"},{"id":"split-pool-input-recovery","name":"Input-to-output recovery, split-pool versus droplet","kind":"evidence","layer":"core","categories":["screen-design","demux-combinatorial"],"side":"neutral","tier":"published-unbenchmarked","summary":"Independent comparisons that report cells recovered relative to cells put in for Parse split-pool barcoding and 10x droplet capture","gain":"PBMCs (Xie 2024): about 53% of input cells recovered with 10x against about 27% with Parse, valid-barcode reads about 98% against 85%; cerebellar organoids (Sarieva 2026): 42.7% against 16.5%, with post-QC retention 87.2% against 95.6%","gain_source":"independent","requires":["fastq"],"caveats":"Two studies on different samples; Parse kits accept far more input cells, so a lower fraction can still give more cells; recovery depends on fixation and washing; De Simone 2025 reports recovery against target instead (Parse 122%), so denominators differ between studies","doi":"10.3390/ijms25073828","pmid":"38612639","cite_title":"Comparative Analysis of Single-Cell RNA Sequencing Methods with and without Sample Multiplexing","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.3390/ijms25073828","publication_url":"https://doi.org/10.3390/ijms25073828","publication_title":"Comparative Analysis of Single-Cell RNA Sequencing Methods with and without Sample Multiplexing","publication_venue":"International Journal of Molecular Sciences","citations":34,"citations_total":51,"citations_papers":3,"review":"04-screen-design#split-pool-input-recovery","tags":["benchmark","recovery","split-pool","droplet"]},{"id":"scar","name":"scAR (single-cell Ambient Remover)","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"benchmarked","summary":"Variational autoencoder that learns the ambient profile from empty droplets and denoises RNA, protein, guide and ATAC counts","recovers":"clean counts for RNA, CITE-seq and CRISPR guide assignments in kept cells","gain":"Cargnelli 2026: highest ambient-removal score (0.679 vs CellBender 0.604); Nie 2026: most robust across conditions and, with CellBender, highest decontamination efficacy","gain_source":"independent","requires":["raw-matrix"],"caveats":"Overestimates contamination (Nie 2026) and removed on average 0.445 of endogenous signal, mostly from low-expressed genes, hurting label transfer when no ambient was present (Cargnelli 2026); reassigned ~17% of cells to other types in one Nie 2026 dataset; preprint only. Created cell types absent from the raw data, 3 coarse types in BD Rhapsody and up to 8 in prefrontal cortex nuclei (Schroeder 2026, preprint).","url":"https://scar-tutorials.readthedocs.io","repo_url":"https://github.com/Novartis/scar","language":"Python","doi":"10.1101/2022.01.14.476312","cite_title":"Probabilistic machine learning ensures accurate ambient denoising in droplet-based single-cell omics","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1101/2022.01.14.476312","publication_url":"https://doi.org/10.1101/2022.01.14.476312","publication_is_preprint":true,"publication_title":"Probabilistic machine learning ensures accurate ambient denoising in droplet-based single-cell omics","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":34,"citations_total":39,"citations_papers":4,"repo_stars":63,"repo_pushed":"2024-08-17","benchmarks":["cargnelli-2026-ambient-benchmark","nie-2026-ambient-benchmark","schroeder-2026-ambient-benchmark"],"benchmark_refs":[{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"},{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"}],"review":"02-calling-qc-damaged#scar","tags":["preprint","deep-learning","crispr","cite-seq"],"site":"https://scar-tutorials.readthedocs.io"},{"id":"de-simone-2025","name":"De Simone et al. 2025 nine-kit comparison","kind":"evidence","layer":"core","categories":["screen-design","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Nine commercial scRNA-seq kits run on PBMCs from one donor and scored on cost, time, cell recovery, read utilisation, sensitivity and cell-type resolution","gain":"Cell recovery against target ranged from about 70% (BD Rhapsody) to 122% (Parse); 10x Flex top tier for genes per cell and best overall; Flex, 10x 3' and BD gave the highest UMIs per cell","gain_source":"independent","requires":["fastq"],"caveats":"One donor and PBMCs only; Parse and Scale were run once each because of kit cost; recovery uses each kit's own cell caller, and the Honeycomb and Fluent callers depend on user parameters","doi":"10.1093/nar/gkae1186","pmid":"39675380","cite_title":"A comprehensive analysis framework for evaluating commercial single-cell RNA sequencing technologies","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkae1186","publication_url":"https://doi.org/10.1093/nar/gkae1186","publication_title":"A comprehensive analysis framework for evaluating commercial single-cell RNA sequencing technologies","publication_venue":"Nucleic Acids Research","citations":33,"review":"04-screen-design#de-simone-2025","tags":["benchmark","platforms","cost","recovery"]},{"id":"mito-filter-resistant-cells","name":"Mitochondrial filtering removes viable, drug-resistant malignant cells","kind":"evidence","layer":"core","categories":["discarded-data","qc-metrics-thresholds","damaged-cells"],"side":"additive","tier":"published-unbenchmarked","summary":"Shows across 9 tumour scRNA-seq datasets (441,445 cells, 134 patients) that malignant cells have higher mitochondrial fractions without more dissociation stress, and links high mitochondrial fraction to drug resistance in cell lines and resistant clones","recovers":"viable high-mitochondrial malignant cells, including resistant clones, that a fixed 10-20% filter removes","gain":"in 10-50% of tumour samples the malignant compartment had twice the high-mito share of the microenvironment, without higher dissociation-stress scores; across CCLE lines higher mito fraction associated with higher IC50 (drug resistance), median mito 4% (glioblastoma) to 14% (head and neck)","gain_source":"independent","requires":["filtered-matrix"],"caveats":"observational; drug link comes from bulk CCLE IC50 correlations and one ovarian line's lineage-traced clones, not single-cell drug screens; the 15% cut-off used to define high-mito is itself a convention","url":"https://doi.org/10.1186/s13059-025-03559-w","doi":"10.1186/s13059-025-03559-w","pmid":"40205439","cite_title":"Filtering cells with high mitochondrial content depletes viable metabolically altered malignant cell populations in cancer single-cell studies","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-025-03559-w","publication_url":"https://doi.org/10.1186/s13059-025-03559-w","publication_title":"Filtering cells with high mitochondrial content depletes viable metabolically altered malignant cell populations in cancer single-cell studies","publication_venue":"Genome biology","citations":32,"review":"05-discarded-data#mito-filter-resistant-cells","tags":["qc-bias","mitochondrial","drug-resistance","cancer","cell-lines","drug-screen"],"site":"https://doi.org/10.1186/s13059-025-03559-w"},{"id":"montserrat-ayuso-2024","name":"Montserrat-Ayuso & Esteve-Codina 2024 nuclear fraction in reference atlases","kind":"evidence","layer":"core","categories":["damaged-cells","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Re-analysis of six reference atlases using intronic (nuclear) fraction and MALAT1 expression to find nuclei-free, low-quality cells left in after the atlases' own QC","gain":"6 atlases (Tabula Muris, Tabula Muris Senis, Tabula Sapiens, HCA liver and retina, a mouse kidney atlas), over 500 samples, 150 cell types and 20 tissues; some organs carry up to 85% low-quality cells","gain_source":"independent","caveats":"Argues for stricter filtering, the opposite direction to the salvage literature; the two agree that the deciding metric should be nuclear fraction, not mito or counts.","doi":"10.1186/s12864-024-11015-5","pmid":"39574015","cite_title":"High content of nuclei-free low-quality cells in reference single-cell atlases: a call for more stringent quality control using nuclear fraction","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-024-11015-5","publication_url":"https://doi.org/10.1186/s12864-024-11015-5","publication_title":"High content of nuclei-free low-quality cells in reference single-cell atlases: a call for more stringent quality control using nuclear fraction","publication_venue":"BMC Genomics","citations":32,"review":"13-metrics-guides-multimodal#montserrat-ayuso-2024","tags":["nuclear-fraction","malat1","atlas","cautionary"]},{"id":"scdist","name":"scDist","kind":"tool","layer":"core","categories":["low-cell-stats"],"side":"additive","tier":"published-unbenchmarked","summary":"Mixed-effects model of the distance between condition means in a low-dimensional expression space, with a random effect per sample, to rank which cell types or conditions changed while controlling individual and cohort variation","recovers":"A replicate-aware answer to 'did anything change' when per-gene tests are underpowered","gain":"Outperformed current methods in simulated and real datasets even with limited sample sizes, with fewer false positives from individual and cohort variation","gain_source":"self-reported","requires":["replicates"],"caveats":"Needs replicate samples. A cell-level permutation alternative, the E-test of scPerturb, permutes cells, so with one well per condition it tests whether two wells differ.","url":"https://github.com/phillipnicol/scDist","repo_url":"https://github.com/phillipnicol/scDist","language":"R","doi":"10.1038/s41467-024-51649-3","pmid":"39218971","cite_title":"Robust identification of perturbed cell types in single-cell RNA-seq data.","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-024-51649-3","publication_url":"https://doi.org/10.1038/s41467-024-51649-3","publication_title":"Robust identification of perturbed cell types in single-cell RNA-seq data.","publication_venue":"Nature Communications","citations":31,"citations_total":223,"citations_papers":2,"repo_stars":44,"repo_pushed":"2025-11-10","review":"03-low-cell-stats#scdist","tags":["effect-size","distance","mixed-models"]},{"id":"demuxmix","name":"demuxmix","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"benchmarked-sota","summary":"Bioconductor package that fits negative binomial regression mixture models to raw tag counts, optionally with each droplet's detected-gene count as a covariate, and returns a posterior error probability for every assignment","recovers":"weakly tagged singlets with normal RNA; supports pooling one untagged sample with tagged ones","gain":"Best overall of 7 callers in Howitt 2023 (mean F 0.907, 0.833, 0.775 on BAL; under 20% of genetic doublets called singlets). Self-reported: 94% of singlets classified versus 87-93% for other callers (brain nuclei) and 85% versus 67-81% (cell-line mixture); untagged CSF cells pooled with tagged PBMC separated at sensitivity 0.980 and specificity 0.985","gain_source":"independent","requires":["tag-counts","filtered-matrix"],"caveats":"Weak on the poorly hashed ovarian tumour batches in Howitt 2023 (F 0.511 and 0.506) though with the fewest doublet errors; errored on all three low-cell PDX batches and reached 73% recall (naive mode) in a 30-sample imbalanced simulation (deMULTIplex2 authors); the RNA covariate gave no gain on Howitt's data","url":"https://bioconductor.org/packages/demuxmix","repo_url":"https://github.com/huklein/demuxmix","language":"R","doi":"10.1093/bioinformatics/btad481","pmid":"37527018","cite_title":"demuxmix: demultiplexing oligonucleotide-barcoded single-cell RNA sequencing data with regression mixture models.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btad481","publication_url":"https://doi.org/10.1093/bioinformatics/btad481","publication_title":"demuxmix: demultiplexing oligonucleotide-barcoded single-cell RNA sequencing data with regression mixture models.","publication_venue":"Bioinformatics","citations":30,"citations_total":61,"citations_papers":2,"repo_stars":5,"repo_pushed":"2024-01-29","benchmarks":["howitt-2023-hto-benchmark","sayed-2025-hashtag-benchmark"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"}],"review":"01-demux-recovery#demuxmix","tags":["hashing","probabilistic","rna-aware"],"site":"https://bioconductor.org/packages/demuxmix"},{"id":"arceneaux-2023","name":"Arceneaux et al. 2023 contamination metrics and wet-lab fixes","kind":"evidence","layer":"core","categories":["ambient-rna","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Contamination-based metrics computed before filtering (AmbientContaminationMetrics), tested in controlled experiments that vary dissociation, fixation, loading, dilution and cells vs nuclei","recovers":"less ambient RNA at the source, so fewer cells need correction or removal","gain":"metrics rose in proportion to spiked ambient level; cold protease, 0.1X DSP fixation, direct tip loading into the chip and ~1:1 dilution lowered contamination; 1% PFA failed QC; nuclei had universally higher contamination than cells","gain_source":"independent","caveats":"inDrop-centred experiments; dilution lowers cell recovery; the authors note many of these parameters are not adjustable on commercial platforms. Same lab as dropkick.","url":"https://github.com/Ken-Lau-Lab/AmbientContaminationMetrics","repo_url":"https://github.com/Ken-Lau-Lab/AmbientContaminationMetrics","language":"Python","doi":"10.1016/j.isci.2023.107242","pmid":"37496679","cite_title":"A contamination focused approach for optimizing the single-cell RNA-seq experiment","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.isci.2023.107242","publication_url":"https://doi.org/10.1016/j.isci.2023.107242","publication_title":"A contamination focused approach for optimizing the single-cell RNA-seq experiment","publication_venue":"iScience","citations":28,"repo_stars":2,"repo_pushed":"2025-04-21","review":"11-quant-calling-ambient#arceneaux-2023","tags":["fixation","nuclei","bench"]},{"id":"fastcar","name":"FastCAR","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"benchmarked","summary":"Subtracts, per gene, the ambient counts expected from empty-droplet libraries below a chosen UMI cut-off, aimed at keeping ambient genes out of cell-type differential expression between conditions","recovers":"condition comparisons not driven by sample-specific ambient RNA","gain":"Nie 2026: with CellBender, closest to the measured baseline for absolute contamination (mtDNA genotype experiment); self-reported: in asthma bronchial biopsies ambient RNA levels were highly sample-specific and uncorrected DE called ambient transcripts as disease genes","gain_source":"independent","requires":["raw-matrix"],"caveats":"Nie 2026: minimal per-cell correlation with true contamination and failed to remove MS4A1 from non-B cells; Cargnelli 2026: removes ambient mainly from highly expressed genes, eighth of nine in the overall ranking.","url":"https://github.com/LungCellAtlas/FastCAR","repo_url":"https://github.com/LungCellAtlas/FastCAR","language":"R","doi":"10.1186/s12864-023-09822-3","pmid":"38030970","cite_title":"FastCAR: fast correction for ambient RNA to facilitate differential gene expression analysis in single-cell RNA-sequencing datasets","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-023-09822-3","publication_url":"https://doi.org/10.1186/s12864-023-09822-3","publication_title":"FastCAR: fast correction for ambient RNA to facilitate differential gene expression analysis in single-cell RNA-sequencing datasets","publication_venue":"BMC Genomics","citations":28,"citations_total":32,"citations_papers":3,"repo_stars":12,"repo_pushed":"2026-10-14","benchmarks":["nie-2026-ambient-benchmark","cargnelli-2026-ambient-benchmark"],"benchmark_refs":[{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"}],"review":"11-quant-calling-ambient#fastcar","tags":["droplet","differential-expression"]},{"id":"velocycle","name":"VeloCycle","kind":"tool","layer":"core","categories":["cell-cycle-and-stress","trajectories"],"side":"neutral","tier":"published-unbenchmarked","summary":"Bayesian RNA velocity model constrained to a periodic manifold that infers cell-cycle phase and speed with uncertainty","gain":"cell-cycle periods validated against live imaging; detected speed differences between progenitors and after Perturb-seq knockdowns (self-reported)","gain_source":"self-reported","requires":["spliced-unspliced"],"caveats":"Speed estimates are of interest in perturbation screens where drugs slow the cycle.","url":"https://github.com/lamanno-epfl/velocycle","repo_url":"https://github.com/lamanno-epfl/velocycle","language":"Python","doi":"10.1038/s41592-024-02471-8","pmid":"39482463","cite_title":"Statistical inference with a manifold-constrained RNA velocity model uncovers cell cycle speed modulations","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-024-02471-8","publication_url":"https://doi.org/10.1038/s41592-024-02471-8","publication_title":"Statistical inference with a manifold-constrained RNA velocity model uncovers cell cycle speed modulations","publication_venue":"Nature Methods","citations":28,"repo_stars":36,"repo_pushed":"2024-06-25","review":"12-doublets-stress-batch#velocycle","tags":["velocity","perturb-seq","bayesian"]},{"id":"cylinter","name":"CyLinter","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Interactive QC tool for high-plex tissue imaging (CyCIF, CODEX and similar) that finds and removes cells affected by folds, debris, antibody aggregates, optical aberrations and segmentation errors","recovers":"none; removes artefact-derived cells that otherwise form spurious clusters","gain":"before cleaning, clustering of 25 TOPACIO specimens left ~29% of cells unclustered and many clusters traced to artefacts (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Protein imaging rather than transcriptomics; relies on visual review at several steps.","url":"https://labsyspharm.github.io/cylinter/","repo_url":"https://github.com/labsyspharm/cylinter","language":"Python","doi":"10.1038/s41592-024-02328-0","pmid":"39478175","cite_title":"Quality control for single-cell analysis of high-plex tissue profiles using CyLinter","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-024-02328-0","publication_url":"https://doi.org/10.1038/s41592-024-02328-0","publication_title":"Quality control for single-cell analysis of high-plex tissue profiles using CyLinter","publication_venue":"Nature Methods","citations":27,"repo_stars":36,"repo_pushed":"2026-08-28","review":"13-metrics-guides-multimodal#cylinter","tags":["spatial","imaging","protein"],"site":"https://labsyspharm.github.io/cylinter/"},{"id":"kuijpers-2024","name":"Kuijpers et al. 2024 SPLiT-seq pipeline comparison","kind":"evidence","layer":"core","categories":["alignment-quantification","demux-combinatorial","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Comparison of eight SPLiT-seq processing pipelines (alevin-fry splitp, LR-splitpipe, SCSit, splitpipe, splitpipeline, SPLiTseq-demultiplex, STARsolo, zUMIs) for speed, barcode calls and downstream results","gain":"STARsolo, splitpipe and alevin-fry splitp handled large data in reasonable time; STARsolo was nearly identical to splitpipe; recommends splitpipe or STARsolo","gain_source":"independent","caveats":"One combinatorial chemistry; STARsolo needs extra code to collapse random-hexamer reads.","doi":"10.1186/s12864-024-10285-3","pmid":"38609853","cite_title":"Split Pool Ligation-based Single-cell Transcriptome sequencing (SPLiT-seq) data processing pipeline comparison","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-024-10285-3","publication_url":"https://doi.org/10.1186/s12864-024-10285-3","publication_title":"Split Pool Ligation-based Single-cell Transcriptome sequencing (SPLiT-seq) data processing pipeline comparison","publication_venue":"BMC Genomics","citations":27,"benchmarks":["kuijpers-2024-splitseq-pipelines"],"benchmark_refs":[{"id":"kuijpers-2024-splitseq-pipelines","name":"Kuijpers et al. 2024, SPLiT-seq pipeline comparison","url":"https://doi.org/10.1186/s12864-024-10285-3"}],"review":"11-quant-calling-ambient#kuijpers-2024","tags":["benchmark","split-pool"]},{"id":"minimum-cells-rules","name":"Minimum-cells rules for pseudobulk samples","kind":"method","layer":"core","categories":["low-cell-stats","qc-metrics-thresholds"],"side":"both","tier":"standard","summary":"Per-sample cell-count floors applied before pseudobulk testing, for example muscat pbDS min_cells = 10 and dreamlet processAssays min.cells = 5 with min.samples = 4 per cluster","recovers":"Lowering the floor and weighting by cell count keeps small wells as replicates instead of discarding them","gain":"Matched scRNA-seq and bulk of the same cells: about 2,000 cells per cluster were needed to recover most DEGs with modest bulk differences, while 50-100 cells recovered most DEGs with extremely small bulk p-values or abundance above a few hundred TPM (Liu 2023)","gain_source":"independent","requires":["filtered-matrix"],"caveats":"The floors are software defaults, not values derived from a benchmark. Liu 2023 is a single-aliquot cell-level comparison, not a replicate-level test. Dropping a replicate costs a residual degree of freedom; whether a noisy kept sample at low weight beats dropping it is untested for drug screens.","url":"https://diseaseneurogenomics.github.io/dreamlet/reference/processAssays.html","language":"R","doi":"10.1186/s12864-023-09487-y","pmid":"37394518","cite_title":"Robustness of single-cell RNA-seq for identifying differentially expressed genes.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-023-09487-y","publication_url":"https://doi.org/10.1186/s12864-023-09487-y","publication_title":"Robustness of single-cell RNA-seq for identifying differentially expressed genes.","publication_venue":"BMC Genomics","citations":26,"review":"03-low-cell-stats#minimum-cells-rules","tags":["thresholds","pseudobulk","drug-screen"],"site":"https://diseaseneurogenomics.github.io/dreamlet/reference/processAssays.html"},{"id":"ccpe","name":"CCPE","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"both","tier":"published-unbenchmarked","summary":"Fits a discriminative helix to estimate cell-cycle pseudotime and phases and to remove cell-cycle effects","gain":"competitive with existing methods on simulated and real data and robust to dropout (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"MATLAB implementation.","url":"https://github.com/LiuJJ0327/CCPE","repo_url":"https://github.com/LiuJJ0327/CCPE","doi":"10.1093/nar/gkab1236","pmid":"34931240","cite_title":"CCPE: cell cycle pseudotime estimation for single cell RNA-seq data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkab1236","publication_url":"https://doi.org/10.1093/nar/gkab1236","publication_title":"CCPE: cell cycle pseudotime estimation for single cell RNA-seq data","publication_venue":"Nucleic Acids Research","citations":25,"repo_stars":8,"repo_pushed":"2022-01-21","review":"12-doublets-stress-batch#ccpe","tags":["matlab","pseudotime"]},{"id":"fixncut","name":"FixNCut","kind":"design","layer":"core","categories":["screen-design","cell-cycle-and-stress"],"side":"additive","tier":"published-unbenchmarked","summary":"Tissue is reversibly fixed with DSP before enzymatic dissociation, so dissociation-induced stress and necrosis are not written into the transcriptome","recovers":"cells and states lost or distorted during dissociation and transport","gain":"Preserved RNA integrity, library complexity and cell composition in human and mouse tissues while reducing stress-related signatures, on 10x 3' v3.1","gain_source":"self-reported","caveats":"Most relevant to tissues and organoids; cultured-cell screens can fix in the well instead; no independent benchmark yet","doi":"10.1186/s13059-024-03219-5","pmid":"38553769","cite_title":"FixNCut: single-cell genomics through reversible tissue fixation and dissociation","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-024-03219-5","publication_url":"https://doi.org/10.1186/s13059-024-03219-5","publication_title":"FixNCut: single-cell genomics through reversible tissue fixation and dissociation","publication_venue":"Genome biology","citations":25,"review":"04-screen-design#fixncut","tags":["fixed","preservation","dissociation","stress"]},{"id":"rautenstrauch-2026","name":"Rautenstrauch & Ohler 2026 silhouette shortcomings","kind":"evidence","layer":"core","categories":["batch-and-plate-effects","integration"],"side":"neutral","tier":"published-unbenchmarked","summary":"Showed that silhouette-based metrics (batch ASW, cell-type ASW) cannot reliably assess batch-effect removal or conservation of biological signal because their assumptions are violated in integration settings","gain":"none (cautionary finding)","gain_source":"independent","doi":"10.1038/s41587-025-02743-4","pmid":"40739072","cite_title":"Shortcomings of silhouette in single-cell integration benchmarking","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41587-025-02743-4","publication_url":"https://doi.org/10.1038/s41587-025-02743-4","publication_title":"Shortcomings of silhouette in single-cell integration benchmarking","publication_venue":"Nature Biotechnology","citations":25,"review":"12-doublets-stress-batch#rautenstrauch-2026","tags":["metric","silhouette"]},{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023 hashtag demultiplexing benchmark","kind":"evidence","layer":"core","categories":["qc-benchmarks","demux-hashing"],"side":"neutral","tier":"published-unbenchmarked","summary":"Independent benchmark of 7 hashtag callers against vireo genotype assignments in 6 tagging experiments (24 BAL donors, 8 ovarian tumours, 3 lung cancer cell lines; antibody and lipid tags)","recovers":"shows how many cells caller choice gains or loses when hashing is weak","gain":"Genotype calls kept 81-91% of droplets as singlets, more than any hashtag caller; mean F ranged from 0 to 0.935 across callers and batches; demuxmix best overall, HTODemux and GMM-Demux close; hashing quality and RNA quality were largely uncorrelated","gain_source":"independent","requires":["tag-counts","genotypes"],"caveats":"vireo is the truth, so genetic doublets and negatives are themselves imperfect; at most 8 tags per pool; deMULTIplex2 and demuxEM not included","url":"https://doi.org/10.1093/nargab/lqad086","doi":"10.1093/nargab/lqad086","pmid":"37829177","cite_title":"Benchmarking single-cell hashtag oligo demultiplexing methods.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/nargab/lqad086","publication_url":"https://doi.org/10.1093/nargab/lqad086","publication_title":"Benchmarking single-cell hashtag oligo demultiplexing methods.","publication_venue":"NAR Genomics and Bioinformatics","citations":24,"review":"01-demux-recovery#howitt-2023-hto-benchmark","tags":["benchmark","hashing","genotype-truth"],"site":"https://doi.org/10.1093/nargab/lqad086"},{"id":"guo-chen-2024","name":"Guo & Chen 2024 cell-cycle phase method comparison","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Compared Tricycle, Seurat CellCycleScoring, Revelio and CS1CC on four datasets with experimentally labelled phases (hESC and RPE1 FUCCI, mESC Quartz-Seq and Hoechst-sorted mESC) and on simulations","gain":"no method consistently best; accuracy depends on the fit between reference or marker list and the data; Tricycle better on mouse than human; adding cells of known phase to the query improved all methods","gain_source":"independent","caveats":"Small, plate-based datasets (35-288 cells each) of cycling stem and epithelial cells; no droplet data, no drug-treated or non-cycling cells; cyclone not included.","doi":"10.1093/bib/bbad517","pmid":"38261342","cite_title":"From G1 to M: a comparative study of methods for identifying cell cycle phases","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1093/bib/bbad517","publication_url":"https://doi.org/10.1093/bib/bbad517","publication_title":"From G1 to M: a comparative study of methods for identifying cell cycle phases","publication_venue":"Briefings in Bioinformatics","citations":23,"review":"12-doublets-stress-batch#guo-chen-2024","tags":["benchmark","fucci"]},{"id":"zappia-2025","name":"Zappia et al. 2025, feature selection for integration and querying","kind":"evidence","layer":"adjacent","categories":["feature-selection","integration"],"side":"neutral","tier":"standard","summary":"Benchmark of 24 feature selection methods and variants over ten datasets, scoring integration, query mapping, label transfer and detection of unseen populations with scVI, scANVI and Symphony","gain":"About 2,000 features worked well; Seurat-VST (scanpy seurat_v3) highly variable genes ranked top; no consistent advantage for batch-aware scanpy variants; scANVI improved every metric category over scVI for the same features","gain_source":"independent","caveats":"From the scIB group, so not independent of scIB; 1,700 feature sets and over 6,000 integration runs; Symphony failed to detect unseen populations that scVI and scANVI separated.","url":"https://doi.org/10.1038/s41592-025-02624-3","doi":"10.1038/s41592-025-02624-3","pmid":"40082610","cite_title":"Feature selection methods affect the performance of scRNA-seq data integration and querying.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-025-02624-3","publication_url":"https://doi.org/10.1038/s41592-025-02624-3","publication_title":"Feature selection methods affect the performance of scRNA-seq data integration and querying.","publication_venue":"Nature Methods","citations":23,"review":"21-concepts-preprocessing#zappia-2025","tags":["benchmark","hvg","atlas"],"site":"https://doi.org/10.1038/s41592-025-02624-3"},{"id":"sci-plex-gxe","name":"sci-Plex-GxE","kind":"design","layer":"core","categories":["screen-design","demux-combinatorial"],"side":"additive","tier":"published-unbenchmarked","summary":"sci-Plex extended with CROP-seq guide capture so drug, dose and CRISPR perturbation are read from the same nucleus, with two independent transductions per condition","recovers":"true replicates (independent transductions) and hash-based doublet removal in a gene-by-drug grid","gain":"1,052,205 cells over 28,242 conditions (14,121 gene-by-environment combinations x 2 independent transductions); 94.3% of cells assigned to a condition after doublet removal; about 35 cells per condition on average (calculated from the reported totals); pilot: 94.4% of 18,585 cells assigned to a well","gain_source":"self-reported","requires":["fastq","tag-counts","multiple-conditions","doses-or-time","replicates"],"caveats":"Few cells per gene-by-drug condition, so analyses pool guides per gene; guide assignment needed extra enrichment PCR cycles in complex libraries; no independent benchmark","doi":"10.1016/j.xgen.2023.100487","pmid":"38278156","cite_title":"Multiplex single-cell chemical genomics reveals the kinase dependence of the response to targeted therapy","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.xgen.2023.100487","publication_url":"https://doi.org/10.1016/j.xgen.2023.100487","publication_title":"Multiplex single-cell chemical genomics reveals the kinase dependence of the response to targeted therapy","publication_venue":"Cell Genomics","citations":22,"review":"04-screen-design#sci-plex-gxe","tags":["drug-screen","crispr","nuclei","hashing","replicates"]},{"id":"redeconv","name":"ReDeconv and CLTS normalisation (transcriptome size)","kind":"tool","layer":"adjacent","categories":["normalisation","de-pseudobulk"],"side":"neutral","tier":"published-unbenchmarked","summary":"Normalises scRNA-seq by Count based on Linearized Transcriptome Size (CLTS), keeping the differences in total transcript content between cell types that per-cell scaling to 10,000 counts removes, and uses the result for bulk deconvolution","gain":"Corrected DE genes that CP10K normalisation misidentified between cell types, with orthogonal validation, and improved deconvolution accuracy, notably for rare cell types","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Gains are the authors' own. The point stands on its own: transcriptome size differs between cell types, often several-fold, so per-cell scaling before cross-type DE turns size into expression differences.","url":"https://github.com/jyyulab/redeconv","repo_url":"https://github.com/jyyulab/redeconv","language":"Python","doi":"10.1038/s41467-025-56623-1","pmid":"39893178","cite_title":"Transcriptome size matters for single-cell RNA-seq normalization and bulk deconvolution.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-025-56623-1","publication_url":"https://doi.org/10.1038/s41467-025-56623-1","publication_title":"Transcriptome size matters for single-cell RNA-seq normalization and bulk deconvolution.","publication_venue":"Nature Communications","citations":21,"repo_stars":2,"repo_pushed":"2026-07-12","review":"21-concepts-preprocessing#redeconv","tags":["transcriptome-size","cross-cell-type-de","deconvolution"]},{"id":"scrnabatchqc","name":"scRNABatchQC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","batch-and-plate-effects"],"side":"neutral","tier":"published-unbenchmarked","summary":"R package that compares many samples at once on technical and biological features (library size, mito, highly variable genes, pathway enrichment) in one HTML report to find outlier samples and batch effects","recovers":"whole samples or lanes that would otherwise be judged one at a time and either kept with a defect or discarded","gain":"none quantified","gain_source":"none","requires":["filtered-matrix","replicates"],"caveats":"Diagnostic only, no filtering model; repository last updated 2021.","url":"https://github.com/liuqivandy/scRNABatchQC","repo_url":"https://github.com/liuqivandy/scRNABatchQC","language":"R","doi":"10.1093/bioinformatics/btz601","pmid":"31373345","cite_title":"scRNABatchQC: multi-samples quality control for single cell RNA-seq data","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btz601","publication_url":"https://doi.org/10.1093/bioinformatics/btz601","publication_title":"scRNABatchQC: multi-samples quality control for single cell RNA-seq data","publication_venue":"Bioinformatics","citations":21,"repo_stars":14,"repo_pushed":"2021-03-20","review":"13-metrics-guides-multimodal#scrnabatchqc","tags":["report","multi-sample"]},{"id":"voombygroup","name":"voomByGroup and voomQWB","kind":"tool","layer":"core","categories":["low-cell-stats","de-pseudobulk"],"side":"additive","tier":"published-unbenchmarked","summary":"limma-voom variants for pseudobulk data whose groups have unequal variances: voomByGroup fits a separate mean-variance trend per group, voomQWB fits one quality weight per group","recovers":"Power and error control lost when one high-variance group inflates (or a low-variance group deflates) the pooled variance","gain":"Better error control and power than voom, voomWithQualityWeights and other gold-standard methods when group variances differ (simulations and several pseudobulk datasets); common BCV ranged 0.338-0.495 across groups in a lung macrophage dataset","gain_source":"self-reported","requires":["replicates"],"caveats":"Group-specific trends need several replicates per group; with 1-2 wells per drug they cannot be estimated, but they can separate a replicated control group from pooled treated groups. No independent benchmark found.","url":"https://github.com/YOU-k/voomByGroup","repo_url":"https://github.com/YOU-k/voomByGroup","language":"R","doi":"10.1186/s13059-023-02949-2","pmid":"37147723","cite_title":"Modeling group heteroscedasticity in single-cell RNA-seq pseudo-bulk data.","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-023-02949-2","publication_url":"https://doi.org/10.1186/s13059-023-02949-2","publication_title":"Modeling group heteroscedasticity in single-cell RNA-seq pseudo-bulk data.","publication_venue":"Genome biology","citations":21,"repo_stars":5,"repo_pushed":"2023-04-20","review":"03-low-cell-stats#voombygroup","tags":["heteroscedasticity","limma","pseudobulk"]},{"id":"neighbor-seq","name":"Neighbor-seq","kind":"tool","layer":"core","categories":["discarded-data","doublets"],"side":"additive","tier":"published-unbenchmarked","summary":"Classifies every barcode into singlet or multiplet types with a random forest trained on artificial multiplets, then tests each cell-type pair for enrichment against re-simulated multiplets to build a physical interaction network from routine scRNA-seq","recovers":"cell-cell contact networks and neighbour-dependent expression from undissociated multiplets","gain":"FACS-sorted DC-T doublets: sensitivity 52.1% (in vitro) and 29.2% (in vivo) at 98.9-99.2% precision, measured by the ULMnet authors","gain_source":"independent","requires":["filtered-matrix"],"caveats":"the null re-draws observed cells and does not model loading-dependent random doublet rates; cannot separate homotypic interactions from random homotypic doublets; lost to ULMnet in the only external comparison; default calls need >10 counts and P<0.05 per pair","url":"https://github.com/sjdlabgroup/Neighborseq","repo_url":"https://github.com/sjdlabgroup/Neighborseq","language":"R","doi":"10.1093/nar/gkac333","pmid":"35536255","cite_title":"Reconstructing physical cell interaction networks from single-cell data using Neighbor-seq","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkac333","publication_url":"https://doi.org/10.1093/nar/gkac333","publication_title":"Reconstructing physical cell interaction networks from single-cell data using Neighbor-seq","publication_venue":"Nucleic Acids Research","citations":20,"citations_total":20,"citations_papers":2,"repo_stars":6,"repo_pushed":"2022-05-01","review":"05-discarded-data#neighbor-seq","tags":["doublets-as-signal","cell-interactions","random-forest","ligand-receptor"]},{"id":"cb2","name":"CB2 (scCB2)","kind":"tool","layer":"core","categories":["cell-calling"],"side":"additive","tier":"published-unbenchmarked","summary":"Extends EmptyDrops by clustering similar barcodes before testing them against the ambient profile, which raises power for small cells","recovers":"extra real cells, mostly in existing populations","gain":"24% more cells than EmptyDrops on average (range 4-81%), 88% of the extra cells joining existing subpopulations; +18% cells and a new 209-cell subpopulation in an Alzheimer snRNA-seq dataset","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"No independent benchmark; still needs post-filtering for damaged cells (valiDrops comparison, 2023).","url":"https://bioconductor.org/packages/scCB2","repo_url":"https://github.com/zijianni/scCB2","language":"R","doi":"10.1186/s13059-020-02054-8","pmid":"32513247","cite_title":"CB2 improves power of cell detection in droplet-based single-cell RNA sequencing data","year":"2020","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-020-02054-8","publication_url":"https://doi.org/10.1186/s13059-020-02054-8","publication_title":"CB2 improves power of cell detection in droplet-based single-cell RNA sequencing data","publication_venue":"Genome biology","citations":19,"citations_total":29,"citations_papers":2,"repo_stars":11,"repo_pushed":"2023-04-19","review":"02-calling-qc-damaged#cb2","tags":["droplet","low-rna"],"site":"https://bioconductor.org/packages/scCB2"},{"id":"double-jeopardy","name":"Double-jeopardy (multi-omic doublet detection)","kind":"method","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Labels droplets with impossible receptor or protein combinations (several BCR/TCR chains, mutually exclusive CITE-seq markers) as doublets and trains a classifier on their transcriptomes to find further doublets, including homotypic ones","recovers":"homotypic lymphocyte doublets that expression-only detectors miss","gain":"high sensitivity and specificity in inflammatory-cell-dominant samples (self-reported, qualitative in the abstract)","gain_source":"self-reported","requires":["filtered-matrix","protein"],"caveats":"Needs VDJ-seq or CITE-seq; anchored on immune cells.","doi":"10.1016/j.crmeth.2021.100008","pmid":"34278374","cite_title":"Double-jeopardy: scRNA-seq doublet/multiplet detection using multi-omic profiling","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.crmeth.2021.100008","publication_url":"https://doi.org/10.1016/j.crmeth.2021.100008","publication_title":"Double-jeopardy: scRNA-seq doublet/multiplet detection using multi-omic profiling","publication_venue":"Cell Reports Methods","citations":19,"review":"12-doublets-stress-batch#double-jeopardy","tags":["vdj","cite-seq","immune"]},{"id":"sccdc","name":"scCDC","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"benchmarked","summary":"Detects the genes that cause contamination and corrects only those, leaving lowly or non-contaminating genes untouched","recovers":"housekeeping and lowly expressed genes that global correction removes","gain":"self-reported: DecontX and CellBender under-correct highly contaminating genes and SoupX and scAR over-correct others, while scCDC corrects the former without the latter; Schroeder 2026 (preprint): with DecontX, the only tool usable on non-droplet platforms without a raw matrix","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Independent benchmarks are lukewarm: moderate absolute error (RMSLE ~0.1), minimal per-cell correlation and failure to remove MS4A1 from non-B cells (Nie 2026); removes ambient mainly from highly expressed genes (Cargnelli 2026). Needs cluster labels.","url":"https://github.com/ZJU-UoE-CCW-LAB/scCDC","repo_url":"https://github.com/ZJU-UoE-CCW-LAB/scCDC","language":"R","doi":"10.1186/s13059-024-03284-w","pmid":"38783325","cite_title":"scCDC: a computational method for gene-specific contamination detection and correction in single-cell and single-nucleus RNA-seq data","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-024-03284-w","publication_url":"https://doi.org/10.1186/s13059-024-03284-w","publication_title":"scCDC: a computational method for gene-specific contamination detection and correction in single-cell and single-nucleus RNA-seq data","publication_venue":"Genome biology","citations":19,"citations_total":24,"citations_papers":4,"repo_stars":19,"repo_pushed":"2025-01-15","benchmarks":["nie-2026-ambient-benchmark","cargnelli-2026-ambient-benchmark","schroeder-2026-ambient-benchmark"],"benchmark_refs":[{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"},{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"}],"review":"11-quant-calling-ambient#sccdc","tags":["droplet","nuclei"]},{"id":"adtnorm","name":"ADTnorm","kind":"tool","layer":"core","categories":["batch-and-plate-effects","multimodal","normalisation"],"side":"additive","tier":"published-unbenchmarked","summary":"Normalises antibody-derived tag counts by aligning the negative and positive peaks of each marker across samples and studies, with utilities for threshold gating and for scoring antibody staining quality","recovers":"protein markers that batch-specific staining makes unusable across samples, and titration guidance from the staining-quality score","gain":"against 14 scaling, normalisation and batch-correction methods (CLR, Arcsinh, logCPM, Harmony, fastMNN, CytofRUV, dsb, DecontPro, totalVI, sciPENN) on 13 public CITE-seq datasets, best alignment of positive and negative populations and cell-type separation","gain_source":"self-reported","requires":["protein"],"caveats":"Comparison is the authors' own; peak detection needs a visible negative population, which some markers lack; manual peak adjustment is sometimes needed.","url":"https://yezhengstat.github.io/ADTnorm/","repo_url":"https://github.com/yezhengSTAT/ADTnorm","language":"R","doi":"10.1038/s41467-025-61023-6","pmid":"40595741","cite_title":"ADTnorm: robust integration of single-cell protein measurement across CITE-seq datasets","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-025-61023-6","publication_url":"https://doi.org/10.1038/s41467-025-61023-6","publication_title":"ADTnorm: robust integration of single-cell protein measurement across CITE-seq datasets","publication_venue":"Nature Communications","citations":18,"citations_total":36,"citations_papers":2,"repo_stars":32,"repo_pushed":"2025-07-08","review":"13-metrics-guides-multimodal#adtnorm","tags":["citeseq","protein","normalisation"],"site":"https://yezhengstat.github.io/ADTnorm/"},{"id":"demuxalot","name":"Demuxalot","kind":"tool","layer":"core","categories":["demux-genotype","doublets"],"side":"both","tier":"benchmarked-sota","summary":"Reference-genotype demultiplexer that refines donor genotypes from the pooled reads before assigning cells, built for large pools","recovers":"donor labels with the lowest error among genotype tools in Demuxafy","gain":"Independent (Demuxafy): Demuxalot (refined) had the fewest wrong droplets, about 1% at 2 donors and 3% at 16 or more, and the best detection of between-donor doublets; combined with Dropulation it raised MCC by about 0.09 over single methods","gain_source":"independent","requires":["bam","genotypes"],"caveats":"Preprint only; needs reference genotypes; high memory use (Demuxafy)","url":"https://github.com/arogozhnikov/demuxalot","repo_url":"https://github.com/arogozhnikov/demuxalot","language":"Python","doi":"10.1101/2021.05.22.443646","cite_title":"Demuxalot: scaled up genetic demultiplexing for single-cell sequencing","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1101/2021.05.22.443646","publication_url":"https://doi.org/10.1101/2021.05.22.443646","publication_is_preprint":true,"publication_title":"Demuxalot: scaled up genetic demultiplexing for single-cell sequencing","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":18,"repo_stars":27,"repo_pushed":"2025-07-20","benchmarks":["neavin-2024-demuxafy-benchmark","fiorini-2025-ensemblex-benchmark"],"benchmark_refs":[{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"fiorini-2025-ensemblex-benchmark","name":"Fiorini et al. 2025 (Ensemblex), genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-025-03643-1"}],"review":"01-demux-recovery#demuxalot","tags":["genotype","reference-genotypes","preprint"]},{"id":"hierarchicell","name":"hierarchicell","kind":"tool","layer":"core","categories":["low-cell-stats","screen-design"],"side":"neutral","tier":"published-unbenchmarked","summary":"Simulates hierarchical scRNA-seq data with within-sample correlation estimated from real data to estimate DE power by number of independent units and cells per unit","gain_source":"none","requires":["replicates"],"caveats":"Its authors show that calculators counting cells instead of independent units grossly overestimate power. Murphy & Skene 2022 found the simulator omits a normalisation step that affects sum-pseudobulk results. powsimR (Vieth 2017) is an older simulation-based calculator.","url":"https://github.com/kdzimm/hierarchicell","repo_url":"https://github.com/kdzimm/hierarchicell","language":"R","doi":"10.1186/s12864-021-07635-w","pmid":"33932993","cite_title":"Hierarchicell: an R-package for estimating power for tests of differential expression with single-cell data.","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-021-07635-w","publication_url":"https://doi.org/10.1186/s12864-021-07635-w","publication_title":"Hierarchicell: an R-package for estimating power for tests of differential expression with single-cell data.","publication_venue":"BMC Genomics","citations":18,"repo_stars":10,"repo_pushed":"2021-03-24","review":"03-low-cell-stats#hierarchicell","tags":["power","simulation","design"]},{"id":"chord","name":"Chord","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked","summary":"Ensemble that trains a gradient-boosting model on the scores of several doublet detectors (by default DoubletFinder, scds and others) against simulated doublets","gain":"higher accuracy and stability than its component methods on real and synthetic data (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Independent tests did not confirm the ensemble gain: Demuxafy (scds plus DoubletFinder intersection) outperformed Chord in pools of 8 or more donors, with Chord making more false singlet and false doublet calls; on singletCode barcoded data the ensembles (hybrid, Chord) did not always beat their components.","url":"https://github.com/13308204545/Chord","repo_url":"https://github.com/13308204545/Chord","language":"R","doi":"10.1038/s42003-022-03476-9","pmid":"35637301","cite_title":"Chord: an ensemble machine learning algorithm to identify doublets in single-cell RNA sequencing data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1038/s42003-022-03476-9","publication_url":"https://doi.org/10.1038/s42003-022-03476-9","publication_title":"Chord: an ensemble machine learning algorithm to identify doublets in single-cell RNA sequencing data","publication_venue":"Communications Biology","citations":17,"repo_stars":21,"repo_pushed":"2022-06-03","benchmarks":["neavin-2024-demuxafy-benchmark","zhang-2024-singletcode"],"benchmark_refs":[{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"zhang-2024-singletcode","name":"Zhang et al. 2024 (singletCode), doublet detectors on barcoded ground truth","url":"https://doi.org/10.1016/j.xgen.2024.100592"}],"review":"12-doublets-stress-batch#chord","tags":["ensemble"]},{"id":"composite","name":"COMPOSITE","kind":"tool","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Compound Poisson model that combines multiplet evidence from RNA, ATAC and protein in multiomic data","gain":"on 17 trimodal DOGMA-seq datasets (280,123 droplets) with hashing truth it removed multiplet clusters that single-omic detectors left (self-reported)","gain_source":"self-reported","requires":["filtered-matrix","protein"],"url":"https://github.com/CHPGenetics/COMPOSITE","repo_url":"https://github.com/CHPGenetics/COMPOSITE","language":"Python","doi":"10.1038/s41467-024-49448-x","pmid":"38956023","cite_title":"A unified model-based framework for doublet or multiplet detection in single-cell multiomics data","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-024-49448-x","publication_url":"https://doi.org/10.1038/s41467-024-49448-x","publication_title":"A unified model-based framework for doublet or multiplet detection in single-cell multiomics data","publication_venue":"Nature Communications","citations":15,"repo_stars":18,"repo_pushed":"2026-03-05","review":"12-doublets-stress-batch#composite","tags":["multiome","dogma-seq","hashing-truth"]},{"id":"sampleqc","name":"SampleQC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds"],"side":"both","tier":"published-unbenchmarked","summary":"Fits a robust Gaussian mixture to per-cell QC metrics jointly across groups of samples with similar QC distributions, so each QC cell type gets its own component and outliers are called per component","recovers":"rare cell types whose QC metrics differ from the dominant type, which single-population outlier rules remove","gain":"in simulations the good cells wrongly excluded by miQC and scater-style MAD rules came almost entirely from one cell type, while SampleQC better preserved rare QC cell-type proportions; ran on 867k nuclei from 172 brain snRNA-seq samples","gain_source":"self-reported","requires":["filtered-matrix","replicates"],"caveats":"The authors note the simulation result depends on their design choices; the number of mixture components k is chosen per sample group by the user; QClus' own comparison on heart nuclei included SampleQC among seven alternatives it outperformed (self-reported by QClus). Repository last updated 2022.","url":"https://github.com/wmacnair/SampleQC","repo_url":"https://github.com/wmacnair/SampleQC","language":"R","doi":"10.1186/s13059-023-02859-3","pmid":"36765378","cite_title":"SampleQC: robust multivariate, multi-cell type, multi-sample quality control for single-cell data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-023-02859-3","publication_url":"https://doi.org/10.1186/s13059-023-02859-3","publication_title":"SampleQC: robust multivariate, multi-cell type, multi-sample quality control for single-cell data","publication_venue":"Genome biology","citations":15,"repo_stars":42,"repo_pushed":"2022-11-14","review":"13-metrics-guides-multimodal#sampleqc","tags":["mixture-model","multi-sample","nuclei"]},{"id":"singletcode-2024","name":"singletCode (Zhang et al. 2024)","kind":"evidence","layer":"core","categories":["doublets","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Uses lineage-tracing DNA barcodes to extract ground-truth singlets and evaluate RNA-based doublet detectors on less heterogeneous data","gain":"mean AUPRC 0.13-0.34 across DoubletFinder, scDblFinder, hybrid and Scrublet on barcoded datasets, with scDblFinder lowest there, although it was best on the original non-barcoded benchmark data","gain_source":"independent","caveats":"Barcoded datasets are mostly cell lines and lineage experiments, close to a single-line drug screen but with their own doublet structure.","doi":"10.1016/j.xgen.2024.100592","pmid":"38925122","cite_title":"Synthetic DNA barcodes identify singlets in scRNA-seq datasets and evaluate doublet algorithms","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.xgen.2024.100592","publication_url":"https://doi.org/10.1016/j.xgen.2024.100592","publication_title":"Synthetic DNA barcodes identify singlets in scRNA-seq datasets and evaluate doublet algorithms","publication_venue":"Cell Genomics","citations":15,"review":"02-calling-qc-damaged#singletcode-2024","tags":["benchmark","cell-lines","homotypic"]},{"id":"shainer-2021","name":"Shainer & Stemmer 2021 kallisto vs Cell Ranger across organisms","kind":"evidence","layer":"core","categories":["alignment-quantification","cell-calling","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Reprocessing of 22 public 10x datasets from 8 organisms with kallisto and with Cell Ranger, comparing alignment rates, gene detection, cell numbers and clustering","gain":"kallisto gave higher alignment and gene detection rates in most samples; Cell Ranger called more cells, but outside human and mouse the extra cells were low quality; kallisto processing of zebrafish pineal gland revealed an additional photoreceptor type","gain_source":"independent","caveats":"No ground truth; the cell-number difference reflects each pipeline's own cell calling as much as alignment.","doi":"10.1186/s12864-021-07930-6","pmid":"34521337","cite_title":"Choice of pre-processing pipeline influences clustering quality of scRNA-seq datasets","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-021-07930-6","publication_url":"https://doi.org/10.1186/s12864-021-07930-6","publication_title":"Choice of pre-processing pipeline influences clustering quality of scRNA-seq datasets","publication_venue":"BMC Genomics","citations":14,"benchmarks":["shainer-2021-kallisto-cellranger"],"benchmark_refs":[{"id":"shainer-2021-kallisto-cellranger","name":"Shainer & Stemmer 2021, kallisto versus Cell Ranger across organisms","url":"https://doi.org/10.1186/s12864-021-07930-6"}],"review":"11-quant-calling-ambient#shainer-2021","tags":["benchmark","non-model"]},{"id":"emptynn","name":"EmptyNN","kind":"tool","layer":"core","categories":["cell-calling"],"side":"both","tier":"published-unbenchmarked","summary":"Neural network trained by positive-unlabelled learning that separates cell-free from cell-containing droplets, using high-count barcodes as positives and the rest as unlabelled","recovers":"cell clusters lost below a UMI cut-off, such as platelets","gain":"hashing ground truth: AUROC 94.73% vs Cell Ranger v2 86.88%, v3 90.16%, EmptyDrops 79.87%, CellBender 88.80%; genotype ground truth: 96.30% vs 82.94-86.43% (CellBender 58.02%); recovered 885 barcodes below a 200-UMI cut, platelets with a median of 93.5 UMIs (self-reported)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Called > 9,000 barcodes on a 10x 8k PBMC sample where most callers called ~8,000, and needs post-filtering for low-quality cells (valiDrops paper); no independent benchmark; last code push 2024-01.","url":"https://github.com/lkmklsmn/empty_nn","repo_url":"https://github.com/lkmklsmn/empty_nn","language":"R","doi":"10.1016/j.patter.2021.100311","pmid":"34430929","cite_title":"EmptyNN: A neural network based on positive and unlabeled learning to remove cell-free droplets and recover lost cells in scRNA-seq data","year":"2021","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.patter.2021.100311","publication_url":"https://doi.org/10.1016/j.patter.2021.100311","publication_title":"EmptyNN: A neural network based on positive and unlabeled learning to remove cell-free droplets and recover lost cells in scRNA-seq data","publication_venue":"Patterns","citations":13,"citations_total":23,"citations_papers":2,"repo_stars":6,"repo_pushed":"2024-01-04","review":"11-quant-calling-ambient#emptynn","tags":["droplet","deep-learning","hashing"]},{"id":"ccafv2","name":"ccAFv2","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"Neural-network classifier of six cell-cycle states plus a quiescent-like neural G0 state, with a confidence threshold that leaves uncertain cells unclassified","gain":"better than or equal to other methods while calling more states (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Preprint; G0, G1 and late G1 calls are less accurate outside neuroepithelial cell types.","url":"https://github.com/plaisier-lab/ccAFv2","repo_url":"https://github.com/plaisier-lab/ccAFv2","language":"multiple","doi":"10.1101/2024.04.16.589816","pmid":"38659838","cite_title":"Classifying cell cycle states and a quiescent-like G0 state using single-cell transcriptomics","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1101/2024.04.16.589816","publication_url":"https://doi.org/10.1101/2024.04.16.589816","publication_is_preprint":true,"publication_title":"Classifying cell cycle states and a quiescent-like G0 state using single-cell transcriptomics","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":12,"repo_stars":4,"repo_pushed":"2024-11-21","review":"12-doublets-stress-batch#ccafv2","tags":["preprint","g0","classifier"]},{"id":"cellcounts","name":"cellCounts (Rsubread)","kind":"tool","layer":"core","categories":["alignment-quantification"],"side":"neutral","tier":"published-unbenchmarked","summary":"Rsubread function that aligns 10x Chromium reads by seed-and-vote, collapses UMIs and assigns them to genes with featureCounts, all inside R","recovers":"an R-native alternative to Cell Ranger for 10x data","gain":"compared favourably with Cell Ranger and STARsolo on simulated and real data (self-reported)","gain_source":"self-reported","requires":["fastq"],"caveats":"No independent benchmark; 10x Chromium formats only.","url":"https://bioconductor.org/packages/Rsubread","language":"R","doi":"10.1093/bioinformatics/btad439","pmid":"37462540","cite_title":"cellCounts: an R function for quantifying 10x Chromium single-cell RNA sequencing data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btad439","publication_url":"https://doi.org/10.1093/bioinformatics/btad439","publication_title":"cellCounts: an R function for quantifying 10x Chromium single-cell RNA sequencing data","publication_venue":"Bioinformatics","citations":11,"review":"11-quant-calling-ambient#cellcounts","tags":["bioconductor","10x"],"site":"https://bioconductor.org/packages/Rsubread"},{"id":"gte-batch-genes","name":"GTE (group technical effects) per-gene batch metric","kind":"method","layer":"core","categories":["batch-and-plate-effects"],"side":"neutral","tier":"published-unbenchmarked","summary":"Quantifies how much batch affects each gene, identifying a small set of highly batch-sensitive genes that dominate the batch effect","gain":"as few as three highly batch-sensitive genes were enough to create a substantial batch effect; cell-level GTE outperformed existing batch quantification methods (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Repository not checked.","doi":"10.1038/s43588-025-00824-7","pmid":"40579473","cite_title":"Quantifying batch effects for individual genes in single-cell data","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s43588-025-00824-7","publication_url":"https://doi.org/10.1038/s43588-025-00824-7","publication_title":"Quantifying batch effects for individual genes in single-cell data","publication_venue":"Nature Computational Science","citations":11,"review":"12-doublets-stress-batch#gte-batch-genes","tags":["metric","gene-level"]},{"id":"htoreader-hybrid","name":"HTOreader and hybrid hashing-genotype demultiplexing","kind":"tool","layer":"core","categories":["demux-hashing","demux-genotype","discarded-data"],"side":"additive","tier":"published-unbenchmarked","summary":"Hashing caller whose cut-offs resist many tags and unequal sample sizes, plus a hybrid strategy that names souporcell genotype clusters by their dominant hashtag and labels every cell that either method calls a singlet","recovers":"hashing negatives and false hashing doublets in genetically distinct pools; one unhashed sample, or unstained aliquots of hashed donors","gain":"Self-reported, 8-donor B and T cell pool: the hybrid added 5.2% singlets, mostly cells hashing had called doublets (715) or negatives (166); 88.03% of cells (13 777 of 15 650) assigned across a hashed and an unhashed pool sharing donors; about 100 hashtagged cells per donor sufficed to name clusters","gain_source":"self-reported","requires":["tag-counts","bam","genotypes"],"caveats":"Needs genetically distinct samples, so it cannot split conditions applied to one cell line; inherits souporcell's errors at high doublet rates","url":"https://github.com/WilsonImmunologyLab/HTOreader","repo_url":"https://github.com/WilsonImmunologyLab/HTOreader","language":"R","doi":"10.1093/bib/bbae254","pmid":"38828640","cite_title":"A hybrid demultiplexing strategy that improves performance and robustness of cell hashing.","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1093/bib/bbae254","publication_url":"https://doi.org/10.1093/bib/bbae254","publication_title":"A hybrid demultiplexing strategy that improves performance and robustness of cell hashing.","publication_venue":"Briefings in Bioinformatics","citations":11,"citations_total":22,"citations_papers":2,"repo_stars":3,"repo_pushed":"2024-08-14","review":"01-demux-recovery#htoreader-hybrid","tags":["hashing","genotype","hybrid","rescue"]},{"id":"skewc","name":"SkewC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","damaged-cells"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Flags cells whose gene-body read coverage is skewed relative to the protocol's typical profile, a QC signal independent of counts and mito fraction","recovers":"none; removes cells that would otherwise form false clusters","gain":"none quantified in the abstract","gain_source":"none","requires":["bam"],"caveats":"Most informative for full-length protocols (Smart-seq); 3' tag protocols have coverage piled at one end by design. Repository last updated 2023.","url":"https://github.com/LSBDT/SkewC","repo_url":"https://github.com/LSBDT/SkewC","doi":"10.1016/j.isci.2022.103777","pmid":"35146392","cite_title":"SkewC: Identifying cells with skewed gene body coverage in single-cell RNA sequencing data","year":"2022","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.isci.2022.103777","publication_url":"https://doi.org/10.1016/j.isci.2022.103777","publication_title":"SkewC: Identifying cells with skewed gene body coverage in single-cell RNA sequencing data","publication_venue":"iScience","citations":11,"citations_total":14,"citations_papers":2,"repo_stars":11,"repo_pushed":"2023-08-02","review":"13-metrics-guides-multimodal#skewc","tags":["full-length","coverage"]},{"id":"socube","name":"SoCube","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Deep-learning doublet detector that embeds gene expression into a 3D composite feature cube and classifies with an ensemble of multi-kernel CNNs","gain":"better performance than existing detectors on benchmark datasets and downstream tasks (self-reported, no single headline number in the abstract)","gain_source":"self-reported","requires":["filtered-matrix"],"url":"https://github.com/idrblab/socube","repo_url":"https://github.com/idrblab/socube","language":"Python","doi":"10.1093/bib/bbad104","pmid":"36941114","cite_title":"SoCube: an innovative end-to-end doublet detection algorithm for analyzing scRNA-seq data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/bib/bbad104","publication_url":"https://doi.org/10.1093/bib/bbad104","publication_title":"SoCube: an innovative end-to-end doublet detection algorithm for analyzing scRNA-seq data","publication_venue":"Briefings in Bioinformatics","citations":11,"repo_stars":10,"repo_pushed":"2023-03-30","review":"12-doublets-stress-batch#socube","tags":["deep-learning","cnn"]},{"id":"cicada","name":"CIcADA","kind":"tool","layer":"core","categories":["discarded-data","doublets"],"side":"additive","tier":"published-unbenchmarked","summary":"Calls heterotypic doublets as cells scoring above 0.75 for two cell types, clusters them with synthetic doublets of the same type pair and keeps only clusters made entirely of observed doublets as biological, then tests them for differential expression against the synthetic pairs","recovers":"transcriptional programmes specific to juxtacrine contacts, from doublets","gain":"FACS-sorted DC-T doublets: sensitivity 21.7% (in vitro) and 15.1% (in vivo), measured by the ULMnet authors","gain_source":"independent","requires":["filtered-matrix"],"caveats":"the synthetic-doublet contrast assumes random doublets equal the sum of two singlets; ambient RNA or shared state can push singlets over the two-score threshold; higher-order multiplets ignored (<3% of cells had >2 types above 0.75)","url":"https://github.com/schiebout/CAMML","repo_url":"https://github.com/schiebout/CAMML","language":"R","doi":"10.1093/bioadv/vbad120","pmid":"37745004","cite_title":"Cell type-specific interaction analysis using doublets in scRNA-seq","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioadv/vbad120","publication_url":"https://doi.org/10.1093/bioadv/vbad120","publication_title":"Cell type-specific interaction analysis using doublets in scRNA-seq","publication_venue":"Bioinformatics Advances","citations":10,"citations_total":13,"citations_papers":3,"repo_stars":3,"repo_pushed":"2024-02-05","review":"05-discarded-data#cicada","tags":["doublets-as-signal","cell-interactions","synthetic-doublets","tumour-immune"]},{"id":"intronic-read-counting","name":"Counting intronic (nascent) reads, especially for nuclei","kind":"method","layer":"core","categories":["alignment-quantification","cell-calling"],"side":"additive","tier":"standard","summary":"Counting reads that fall in introns towards the gene (Cell Ranger include-introns, default from v7.0; STARsolo GeneFull; alevin-fry splici/USA mode; kb nac index) instead of discarding them","recovers":"library size and genes in single-nucleus data, where much of the RNA is unspliced; cell types that exon-only counting blurs","gain":"Kuo 2024 (independent, 10x mouse cortex nuclei): exon-only references gave significantly smaller library sizes and discordant SingleR labels for astrocytes vs neural stem cells; Pool 2023: intronic read handling is one of three causes of missing genes in droplet data","gain_source":"independent","requires":["fastq"],"caveats":"Adds a gene-length bias, plausibly from internal priming in introns (Kuo 2024); in whole-cell data intron counts lowered cross-workflow correlation without improving clustering (You 2021). Switching it on changes UMI totals, so cell calling and QC thresholds from older runs no longer apply. The split into spliced, unspliced and ambiguous differs between tools (DFK index vs splici and spliceu references).","doi":"10.1093/biostatistics/kxad010","pmid":"37257175","cite_title":"Quantification and statistical modeling of droplet-based single-nucleus RNA-sequencing data","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1093/biostatistics/kxad010","publication_url":"https://doi.org/10.1093/biostatistics/kxad010","publication_title":"Quantification and statistical modeling of droplet-based single-nucleus RNA-sequencing data","publication_venue":"Biostatistics","citations":10,"citations_total":83,"citations_papers":4,"review":"11-quant-calling-ambient#intronic-read-counting","tags":["nuclei","intronic","best-practice"]},{"id":"validrops","name":"valiDrops","kind":"tool","layer":"core","categories":["cell-calling","damaged-cells"],"side":"both","tier":"published-unbenchmarked","summary":"Filters barcodes with data-adaptive thresholds on standard QC metrics, keeps those whose clusters carry distinct marker signal, and flags dead cells with a trained classifier","recovers":"a cell call that does not need post-filtering for low-quality barcodes, plus a dead-cell label that can be kept as a readout","gain":"cell-type signals more distinct and consistent than after EmptyDrops, CB2, DIEM, dropkick, CellBender or EmptyNN filtering; dead-cell prediction median MCC >= 0.75 with as little as 0.1% dead cells (self-reported)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Dead-cell MCC fell to a median of ~0.66 in one dataset when half the true dead cells were removed; comparison is by its authors; no independent benchmark.","url":"https://github.com/madsen-lab/valiDrops","repo_url":"https://github.com/madsen-lab/valiDrops","language":"R","doi":"10.1093/nargab/lqad101","pmid":"38025048","cite_title":"Automatic quality control of single-cell and single-nucleus RNA-seq using valiDrops","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/nargab/lqad101","publication_url":"https://doi.org/10.1093/nargab/lqad101","publication_title":"Automatic quality control of single-cell and single-nucleus RNA-seq using valiDrops","publication_venue":"NAR Genomics and Bioinformatics","citations":10,"repo_stars":16,"repo_pushed":"2025-03-18","review":"11-quant-calling-ambient#validrops","tags":["droplet","nuclei","dead-cells"]},{"id":"cleanser","name":"CLEANSER","kind":"tool","layer":"core","categories":["ambient-rna","demux-hashing"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Mixture model, built on CRISPR barnyard assays, that gives the probability that each gRNA-cell assignment in a perturb-seq screen comes from the native rather than the ambient gRNA distribution, with gRNA- and cell-specific normalisation","recovers":"correct guide assignments and the differential expression calls that depend on them","gain":"self-reported: ambient gRNAs are a major source of false-positive guide assignments; the choice of ambient filter changed differential expression outcomes, and CLEANSER raised gRNA-cell assignment accuracy across CROP-seq and direct-capture formats against a strict UMI cut-off and the 10x mixture model","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"No independent benchmark; the authors note that gRNAs with greater coverage and larger UMI counts are assigned more accurately, and that hits found downstream still depend on the DE design.","url":"https://github.com/Gersbachlab-Bioinformatics/CLEANSER","repo_url":"https://github.com/Gersbachlab-Bioinformatics/CLEANSER","language":"Python","doi":"10.1016/j.xgen.2025.100766","pmid":"39914388","cite_title":"Characterization and bioinformatic filtering of ambient gRNAs in single-cell CRISPR screens using CLEANSER","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.xgen.2025.100766","publication_url":"https://doi.org/10.1016/j.xgen.2025.100766","publication_title":"Characterization and bioinformatic filtering of ambient gRNAs in single-cell CRISPR screens using CLEANSER","publication_venue":"Cell Genomics","citations":9,"repo_stars":12,"repo_pushed":"2026-07-31","review":"11-quant-calling-ambient#cleanser","tags":["crispr","perturb-seq","guide-assignment"]},{"id":"decontpro","name":"DecontPro","kind":"tool","layer":"core","categories":["discarded-data","ambient-rna"],"side":"both","tier":"published-unbenchmarked","summary":"Bayesian hierarchical model that removes ambient and spongelet contamination from antibody-derived tag counts, after finding that some RNA-called empty droplets held high tag levels consistent with neutrophils","recovers":"protein-defined cells hidden among RNA-called empty droplets, and cleaner protein signal","requires":["raw-matrix","protein"],"caveats":"self-reported superiority; spongelets (medium-tag empty droplets) are a newly described artefact; recommends calling empty drops separately for RNA and tags","url":"https://github.com/campbio/decontX","repo_url":"https://github.com/campbio/decontX","language":"R","doi":"10.1093/nar/gkad1032","pmid":"37973397","cite_title":"Characterization and decontamination of background noise in droplet-based single-cell protein expression data with DecontPro","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkad1032","publication_url":"https://doi.org/10.1093/nar/gkad1032","publication_title":"Characterization and decontamination of background noise in droplet-based single-cell protein expression data with DecontPro","publication_venue":"Nucleic Acids Research","citations":9,"repo_stars":69,"repo_pushed":"2026-10-09","review":"05-discarded-data#decontpro","tags":["empty-droplets","citeseq","protein","ambient","low-rna-cells"]},{"id":"arora-2025","name":"Arora et al. 2025 ambient mRNA and differential expression","kind":"evidence","layer":"core","categories":["ambient-rna"],"side":"neutral","tier":"published-unbenchmarked","summary":"Shows on dengue PBMC and fetal liver data that uncorrected ambient transcripts enter cell-type DEGs and produce spurious pathways, and how CellBender and SoupX change this","gain":"T cells: 17 significant GO terms before correction, all driven by immunoglobulin genes (13 found only before correction), 191 after CellBender and 46 after SoupX; Ig expression in T cells 0.54 -> 0.10 (CellBender) and 0.06 (SoupX)","gain_source":"independent","caveats":"Two correction tools, no ground truth; pathway counts depend on a rank-based DEG cut.","doi":"10.1371/journal.pone.0332440","pmid":"40991648","cite_title":"Understanding and mitigating the impact of ambient mRNA contamination in single-cell RNA-sequencing analysis","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pone.0332440","publication_url":"https://doi.org/10.1371/journal.pone.0332440","publication_title":"Understanding and mitigating the impact of ambient mRNA contamination in single-cell RNA-sequencing analysis","publication_venue":"PLoS ONE","citations":8,"review":"11-quant-calling-ambient#arora-2025","tags":["differential-expression","cautionary"]},{"id":"cellbouncer","name":"CellBouncer","kind":"tool","layer":"core","categories":["ambient-rna","demux-genotype","demux-hashing"],"side":"both","tier":"published-unbenchmarked","summary":"Toolkit for pooled experiments that demultiplexes by species, donor, mitochondrial haplotype, lipid tags or sgRNAs, and estimates per-cell ambient fraction and each source's contribution to the ambient pool","recovers":"a per-donor or per-condition ambient profile in pooled lanes, and a doublet rate harmonised across data types","gain":"outperformed existing methods at separating multi-species and multi-individual mixtures (self-reported, abstract)","gain_source":"self-reported","requires":["bam"],"caveats":"New (2026); ambient estimation needs genetically distinct sources in the pool; no independent benchmark.","url":"https://github.com/nkschaefer/cellbouncer","repo_url":"https://github.com/nkschaefer/cellbouncer","language":"C++","doi":"10.1016/j.xgen.2026.101275","pmid":"42269616","cite_title":"CellBouncer, a unified toolkit for single-cell demultiplexing and ambient RNA analysis, reveals hominid mitochondrial incompatibilities","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.xgen.2026.101275","publication_url":"https://doi.org/10.1016/j.xgen.2026.101275","publication_title":"CellBouncer, a unified toolkit for single-cell demultiplexing and ambient RNA analysis, reveals hominid mitochondrial incompatibilities","publication_venue":"Cell Genomics","citations":8,"repo_stars":8,"repo_pushed":"2026-08-14","review":"11-quant-calling-ambient#cellbouncer","tags":["pooled","genotype","hashing","crispr"]},{"id":"hadge","name":"hadge (nf-core/hadge)","kind":"tool","layer":"core","categories":["demux-hashing","demux-genotype","discarded-data"],"side":"additive","tier":"published-unbenchmarked","summary":"Nextflow pipeline running 7 hashing and 5 genotype demultiplexers, scoring their agreement, with a rescue mode that labels genotype clusters by their matched hashtags","recovers":"hashing negatives and whole weakly tagged samples when donors differ genetically","gain":"Self-reported on hashed multiple sclerosis brain nuclei: rescue mode called 90% of droplets singlets and rescued 89.7% of hashing negatives, doubling singlets for the weakest hashtags; after the original study's QC, 3 208 cells were kept, 952 of them previously excluded","gain_source":"self-reported","requires":["tag-counts","bam","genotypes"],"caveats":"Two neuronal clusters were mostly or wholly rescued cells, so hashing loss was cell-type biased and rescue changes composition; needs genetically distinct donors","url":"https://nf-co.re/hadge","repo_url":"https://github.com/nf-core/hadge","language":"multiple","doi":"10.1186/s13059-024-03249-z","pmid":"38671451","cite_title":"hadge: a comprehensive pipeline for donor deconvolution in single-cell studies.","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-024-03249-z","publication_url":"https://doi.org/10.1186/s13059-024-03249-z","publication_title":"hadge: a comprehensive pipeline for donor deconvolution in single-cell studies.","publication_venue":"Genome biology","citations":8,"repo_stars":26,"repo_pushed":"2026-10-22","review":"01-demux-recovery#hadge","tags":["hashing","genotype","pipeline","nextflow","rescue","nuclei"],"site":"https://nf-co.re/hadge"},{"id":"qclus","name":"QClus","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","cell-calling","ambient-rna"],"side":"both","tier":"published-unbenchmarked","summary":"Droplet filter for difficult single-nucleus samples that clusters nuclei on unspliced fraction, mito fraction and cell-type marker scores and removes empty and highly contaminated droplets","recovers":"usable nuclei from high-ambient tissue (human heart) where count thresholds either keep contaminated droplets or remove too many nuclei","gain":"against seven alternatives (Cell Ranger 7, CellBender, SampleQC, DIEM, DecontX, DropletQC, EmptyNN) on 6 datasets, 252 samples and over 1.9 million nuclei, highest quality in the most samples on all metrics and no processing failures","gain_source":"self-reported","requires":["raw-matrix","spliced-unspliced"],"caveats":"The comparison is the authors' own; default marker set and the initial filter (>= 500 genes, mito < 40%) are tuned for cardiac tissue and need changing elsewhere.","url":"https://github.com/linnalab/qclus","repo_url":"https://github.com/linnalab/qclus","language":"Python","doi":"10.1093/nar/gkae1145","pmid":"39656909","cite_title":"QClus: a droplet filtering algorithm for enhanced snRNA-seq data quality in challenging samples","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkae1145","publication_url":"https://doi.org/10.1093/nar/gkae1145","publication_title":"QClus: a droplet filtering algorithm for enhanced snRNA-seq data quality in challenging samples","publication_venue":"Nucleic Acids Research","citations":7,"repo_stars":10,"repo_pushed":"2026-10-08","review":"13-metrics-guides-multimodal#qclus","tags":["nuclei","heart","nuclear-fraction"]},{"id":"vaeda","name":"vaeda","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Combines a variational autoencoder with positive-unlabeled learning to give doublet scores and binary calls","gain":"competitive with seven existing methods on the 16 Xi & Li benchmark datasets and ahead of the other Python-based methods (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"From the scds authors; not yet in an independent benchmark.","url":"https://github.com/kostkalab/vaeda","repo_url":"https://github.com/kostkalab/vaeda","language":"Python","doi":"10.1093/bioinformatics/btac720","pmid":"36342203","cite_title":"Vaeda computationally annotates doublets in single-cell RNA sequencing data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btac720","publication_url":"https://doi.org/10.1093/bioinformatics/btac720","publication_title":"Vaeda computationally annotates doublets in single-cell RNA sequencing data","publication_venue":"Bioinformatics","citations":7,"repo_stars":21,"repo_pushed":"2026-02-01","review":"12-doublets-stress-batch#vaeda","tags":["deep-learning","pu-learning"]},{"id":"ge-2025","name":"Ge et al. 2025, normalisation benchmark","kind":"evidence","layer":"adjacent","categories":["normalisation"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of six normalisation methods (Seurat log, LIGER, Dino, SCnorm, sctransform, scran) on seven real and four simulated datasets, scored on clustering, DE and memory and run time","gain":"Dino best for clustering 10x and large datasets; sctransform strong on full-length protocols; SCnorm suited to small datasets but averaged over 200 GB peak memory","gain_source":"independent","requires":["filtered-matrix"],"caveats":"Small benchmark; it describes the Seurat default as log10(x + 1), which is not what LogNormalize does, and counts LIGER (an integration method) as a normaliser. Weigh below Ahlmann-Eltze and Huber 2023.","url":"https://doi.org/10.1371/journal.pone.0335102","doi":"10.1371/journal.pone.0335102","pmid":"41411311","cite_title":"Single-cell RNA-seq data normalization: A benchmarking study.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pone.0335102","publication_url":"https://doi.org/10.1371/journal.pone.0335102","publication_title":"Single-cell RNA-seq data normalization: A benchmarking study.","publication_venue":"PLoS ONE","citations":5,"review":"21-concepts-preprocessing#ge-2025","tags":["benchmark","normalisation"],"site":"https://doi.org/10.1371/journal.pone.0335102"},{"id":"scqcea","name":"scQCEA","kind":"tool","layer":"core","categories":["qc-metrics-thresholds"],"side":"neutral","tier":"published-unbenchmarked","summary":"R package that writes an interactive QC report across sets of 10x samples and adds expression-based QC through cell-type enrichment against 2,348 marker genes for 95 human and mouse cell types","recovers":"a check that a library carries recognisable cell types before it is judged on counts alone","gain":"used 342 shallow-sequenced profiles to set minimum sequencing for its enrichment function; no retention numbers","gain_source":"none","requires":["filtered-matrix","reference"],"caveats":"Report and annotation tool rather than a filter; repository last updated 2023.","url":"https://isarnassiri.github.io/scQCEA/","repo_url":"https://github.com/isarnassiri/scQCEA","language":"R","doi":"10.1186/s12864-023-09447-6","pmid":"37415108","cite_title":"scQCEA: a framework for annotation and quality control report of single-cell RNA-sequencing data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-023-09447-6","publication_url":"https://doi.org/10.1186/s12864-023-09447-6","publication_title":"scQCEA: a framework for annotation and quality control report of single-cell RNA-sequencing data","publication_venue":"BMC Genomics","citations":5,"repo_stars":7,"repo_pushed":"2023-07-06","review":"13-metrics-guides-multimodal#scqcea","tags":["report","annotation"],"site":"https://isarnassiri.github.io/scQCEA/"},{"id":"cargnelli-2026","name":"Cargnelli et al. 2026 ambient benchmark","kind":"evidence","layer":"core","categories":["ambient-rna","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Independent benchmark of seven ambient RNA removal methods on simulated, species-mixing, genotype-mixing and contamination-free control data","gain":"7 datasets, 64 samples, 135,561 cells; 81.56% of cells carry some ambient RNA (mean 7.79% of UMIs in cells, 11.80% in nuclei); no single best method; recommends CellBender, DecontX (full mode) or SoupX (reduced mode)","gain_source":"independent","caveats":"Methods that remove most ambient (scAR, CellBender) also remove endogenous signal or over-correct clean samples; all methods but CellClear inflated marker fold changes beyond ground truth.","doi":"10.3389/fbinf.2026.1844838","pmid":"42688285","cite_title":"Benchmarking computational decontamination of ambient RNA","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.3389/fbinf.2026.1844838","publication_url":"https://doi.org/10.3389/fbinf.2026.1844838","publication_title":"Benchmarking computational decontamination of ambient RNA","publication_venue":"Frontiers in Bioinformatics","citations":4,"review":"02-calling-qc-damaged#cargnelli-2026","tags":["benchmark","species-mixing","genotype-mixing"]},{"id":"scibd","name":"scIBD","kind":"tool","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Self-supervised, iterative heterotypic doublet detector for single-cell chromatin accessibility data that adapts which simulated doublets it trusts","gain":"outperformed other detectors on simulated and real scCAS datasets (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"url":"https://github.com/Ying-Lab/scIBD","repo_url":"https://github.com/Ying-Lab/scIBD","language":"Python","doi":"10.1186/s13059-023-03072-y","pmid":"37814314","cite_title":"scIBD: a self-supervised iterative-optimizing model for boosting the detection of heterotypic doublets in single-cell chromatin accessibility data","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1186/s13059-023-03072-y","publication_url":"https://doi.org/10.1186/s13059-023-03072-y","publication_title":"scIBD: a self-supervised iterative-optimizing model for boosting the detection of heterotypic doublets in single-cell chromatin accessibility data","publication_venue":"Genome biology","citations":4,"repo_stars":8,"repo_pushed":"2026-05-19","review":"12-doublets-stress-batch#scibd","tags":["atac"]},{"id":"siftcell","name":"SiftCell","kind":"tool","layer":"core","categories":["cell-calling"],"side":"both","tier":"published-unbenchmarked","summary":"Identifies cell-containing droplets by comparing barcodes with randomised (shuffled) counterparts in manifold space (SiftCell-Shuffle), then models each barcode as a mixture of cell and ambient profiles (SiftCell-Mix)","recovers":"a visual and statistical check on which barcodes are ambient-like, across droplet platforms","gain":"described as more comprehensive and accurate than existing methods across several platforms (self-reported, abstract; no numbers in the abstract)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"No independent benchmark; repository inactive since 2023-07.","url":"https://github.com/jyxi7676/SiftCell","repo_url":"https://github.com/jyxi7676/SiftCell","language":"multiple","doi":"10.1016/j.cels.2023.06.002","pmid":"37473732","cite_title":"SiftCell: A robust framework to detect and isolate cell-containing droplets from single-cell RNA sequence reads","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cels.2023.06.002","publication_url":"https://doi.org/10.1016/j.cels.2023.06.002","publication_title":"SiftCell: A robust framework to detect and isolate cell-containing droplets from single-cell RNA sequence reads","publication_venue":"Cell Systems","citations":4,"repo_stars":2,"repo_pushed":"2023-07-24","review":"11-quant-calling-ambient#siftcell","tags":["droplet"]},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025 normalisation x caller benchmark (hashDemux)","kind":"evidence","layer":"core","categories":["qc-benchmarks","demux-hashing"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of tag normalisations crossed with hashing callers on 12 real and simulated datasets, introducing hashDemux (per-cell CLR followed by clustering)","recovers":"cells called negative only because their tag library was shallow","gain":"Per-cell (sequencing-depth) CLR instead of per-tag CLR recovered ~97% (clustering) and ~56% (MULTI-seq workflow) of cells wrongly called negative for the most variable tag; best workflows F 0.9 versus 0.87 for deMULTIplex2 on that dataset; clustering with per-cell CLR had the highest average F over 12 datasets","gain_source":"self-reported","requires":["tag-counts"],"caveats":"At most 12 tags per dataset, mostly cell lines; the clustering workflow calls doublets poorly, so RNA-based doublet filtering is advised afterwards","url":"https://github.com/hwlim/hashDemux","repo_url":"https://github.com/hwlim/hashDemux","language":"R","doi":"10.1093/bfgp/elae039","pmid":"39387404","cite_title":"Systematic benchmark of single-cell hashtag demultiplexing approaches reveals robust performance of a clustering-based method.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1093/bfgp/elae039","publication_url":"https://doi.org/10.1093/bfgp/elae039","publication_title":"Systematic benchmark of single-cell hashtag demultiplexing approaches reveals robust performance of a clustering-based method.","publication_venue":"Briefings in Functional Genomics","citations":3,"repo_stars":0,"repo_pushed":"2026-02-23","review":"01-demux-recovery#sayed-2025-hashtag-benchmark","tags":["benchmark","hashing","normalisation"]},{"id":"tahoe-100m","name":"Tahoe-100M","kind":"design","layer":"core","categories":["screen-design","demux-combinatorial","batch-and-plate-effects"],"side":"additive","tier":"published-unbenchmarked","summary":"Atlas of about 100 million cells from 50 cancer lines pooled as balanced cell villages in each well, treated with 1,100 drug-dose conditions and read with Parse split-pool barcoding plus SNP demultiplexing","recovers":"cells per condition at atlas scale: each drug-dose well yields one condition per pooled line","gain":"Preprint figures: 153 million barcoded cells, 95.6 million (about 62%) passed full filters; 52,886 line-drug-dose conditions with a median of 1,287 cells each; demuxlet benchmark accuracy above 98% with over 90% of cells called singlets; median correlation 0.975 for matched versus 0.915 for unmatched conditions","gain_source":"self-reported","requires":["fastq","genotypes","multiple-conditions","doses-or-time"],"caveats":"One well per drug-dose (plate 14 duplicated plate 6 and was held out for validation), so treatment is not replicated across wells; 3 of 50 lines dropped for consistently low counts; conditions under 50 cells excluded; control-media wells at fixed positions H11 and H12 of each plate, DMSO well count per plate not stated; design details read from the bioRxiv preprint","url":"https://huggingface.co/datasets/tahoebio/Tahoe-100M","language":"web","doi":"10.1016/j.cell.2026.08.035","pmid":"42753697","cite_title":"Tahoe-100M: Mapping drug-induced molecular phenotypes at single-cell resolution","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.cell.2026.08.035","publication_url":"https://doi.org/10.1016/j.cell.2026.08.035","publication_title":"Tahoe-100M: Mapping drug-induced molecular phenotypes at single-cell resolution","publication_venue":"Cell","citations":3,"citations_total":110,"citations_papers":2,"review":"04-screen-design#tahoe-100m","tags":["drug-screen","cell-village","genotype","split-pool","fixed","atlas"],"site":"https://huggingface.co/datasets/tahoebio/Tahoe-100M"},{"id":"cellclear","name":"CellClear","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"benchmarked","summary":"Estimates ambient expression programs by matrix factorisation using empty droplets and removes them from each cell","recovers":"separation of closely related subtypes blurred by ambient RNA","gain":"Nie 2026: top composite score at cell-subtype level; olfactory neurons with several receptor genes fell from 71 to 11; with scAR, most effective removal across tissues; Cargnelli 2026: the only method that did not inflate marker fold changes beyond ground truth","gain_source":"independent","requires":["raw-matrix"],"caveats":"Schroeder 2026 (preprint): replaced > 93% of counts with factorisation-derived values and failed to scale to 172,000 nuclei; Cargnelli 2026: removed about as much endogenous RNA as ambient, mostly from lowly expressed genes; Nie 2026: overestimates contamination (RMSLE > 0.25) and missed 21 consensus B-cell markers. Preprint only.","url":"https://github.com/WhiteRabBio/CellClear","repo_url":"https://github.com/WhiteRabBio/CellClear","language":"Python","doi":"10.1101/2024.08.05.606571","cite_title":"CellClear: Enhancing Single-cell RNA Data Quality via Biologically-Informed Ambient RNA Correction","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1101/2024.08.05.606571","publication_url":"https://doi.org/10.1101/2024.08.05.606571","publication_is_preprint":true,"publication_title":"CellClear: Enhancing Single-cell RNA Data Quality via Biologically-Informed Ambient RNA Correction","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":2,"citations_total":7,"citations_papers":4,"repo_stars":6,"repo_pushed":"2025-01-03","benchmarks":["nie-2026-ambient-benchmark","cargnelli-2026-ambient-benchmark","schroeder-2026-ambient-benchmark"],"benchmark_refs":[{"id":"nie-2026-ambient-benchmark","name":"Nie et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.1038/s41467-026-77458-4"},{"id":"cargnelli-2026-ambient-benchmark","name":"Cargnelli et al. 2026, ambient RNA decontamination benchmark","url":"https://doi.org/10.3389/fbinf.2026.1844838"},{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"}],"review":"11-quant-calling-ambient#cellclear","tags":["preprint","droplet"]},{"id":"fu-2025-snrna-genetic-benchmark","name":"Fu et al. 2025 genetic demultiplexing benchmark for snRNA-seq","kind":"evidence","layer":"core","categories":["qc-benchmarks","demux-genotype"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of vireo, souporcell, freemuxlet and scSplit with three variant callers on simulated snRNA-seq pools of 2-6 samples at 0-30% doublets, checked against sex-linked genes","gain":"All tools except scSplit reached 80-85% accuracy with high recall and precision; vireo was most accurate and fastest; scSplit recall was under 50%; accuracy fell as doublets rose","gain_source":"independent","requires":["bam","genotypes"],"caveats":"Simulated pools of few samples; results depend on the variant caller paired with each tool","url":"https://doi.org/10.1093/bib/bbaf371","doi":"10.1093/bib/bbaf371","pmid":"40702707","cite_title":"Benchmarking of computational demultiplexing methods for single-nucleus RNA sequencing data.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1093/bib/bbaf371","publication_url":"https://doi.org/10.1093/bib/bbaf371","publication_title":"Benchmarking of computational demultiplexing methods for single-nucleus RNA sequencing data.","publication_venue":"Briefings in Bioinformatics","citations":2,"review":"01-demux-recovery#fu-2025-snrna-genetic-benchmark","tags":["benchmark","genotype","nuclei"],"site":"https://doi.org/10.1093/bib/bbaf371"},{"id":"multi-round-doublet-removal","name":"Multi-round doublet removal (MRDR)","kind":"method","layer":"core","categories":["doublets"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Runs a doublet detector two or more times, removing calls between rounds, to offset the randomness of artificial-doublet simulation","gain":"two rounds of DoubletFinder raised recall by 50% over one round on 14 real datasets; cxds twice was best on 29 barcoded and 106 synthetic datasets, with ROC up by at least 0.05 for all four tools tested (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"More rounds remove more barcodes, so the recall gain is partly a higher removal rate; singlet loss per round not reported in the abstract.","doi":"10.1016/j.csbj.2025.01.009","pmid":"39911841","cite_title":"Improving doublet cell removal efficiency through multiple algorithm runs","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.csbj.2025.01.009","publication_url":"https://doi.org/10.1016/j.csbj.2025.01.009","publication_title":"Improving doublet cell removal efficiency through multiple algorithm runs","publication_venue":"Computational and Structural Biotechnology Journal","citations":2,"review":"12-doublets-stress-batch#multi-round-doublet-removal","tags":["strategy"]},{"id":"ambimux","name":"ambimux","kind":"tool","layer":"core","categories":["ambient-rna","demux-genotype","multimodal"],"side":"both","tier":"published-unbenchmarked","summary":"Read-level likelihood model that demultiplexes genotype-pooled RNA+ATAC multiome data while estimating each droplet's ambient fraction in each modality and classifying empty droplets","recovers":"singlets at high ambient fractions that ambient-unaware demultiplexers lose","gain":"simulations: ambient fraction MAE 0.048 (RNA) and 0.042 (ATAC); > 95% specificity with correct singlets up to 60% ambient, against ~25% for ambient-unaware models; 4,986 singlets from seven adipose biopsies in one channel (self-reported)","gain_source":"self-reported","requires":["bam","genotypes"],"caveats":"Preprint; needs donor genotypes; same group as DIEM.","url":"https://github.com/marcalva/ambimux","repo_url":"https://github.com/marcalva/ambimux","doi":"10.1101/2025.08.21.671671","pmid":"40909685","cite_title":"Integrated ambient modeling and genetic demultiplexing of single-cell RNA+ATAC multiome experiments with Ambimux","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1101/2025.08.21.671671","publication_url":"https://doi.org/10.1101/2025.08.21.671671","publication_is_preprint":true,"publication_title":"Integrated ambient modeling and genetic demultiplexing of single-cell RNA+ATAC multiome experiments with Ambimux","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":1,"citations_total":2,"citations_papers":2,"repo_stars":3,"repo_pushed":"2025-09-19","review":"11-quant-calling-ambient#ambimux","tags":["preprint","multiome","atac","nuclei"]},{"id":"demuxsnp","name":"demuxSNP","kind":"tool","layer":"core","categories":["demux-hashing","demux-genotype","discarded-data"],"side":"additive","tier":"published-unbenchmarked","summary":"Bioconductor package that trains a nearest-neighbour classifier (Jaccard distance on SNP profiles) on confident hashing singlets and simulated doublets, then reassigns negative, uncertain and doublet cells","recovers":"hashing negatives and uncertain cells with good RNA when samples differ genetically","gain":"Self-reported: beat hashing-only callers on a low-quality hashing benchmark and recovered more high-RNA-quality cells; in a renal cancer dataset HTODemux had left 2 582 cells (over 10%) negative; more robust than genotype-free and hybrid methods under class imbalance at 5-50% doublets","gain_source":"self-reported","requires":["tag-counts","bam","genotypes"],"caveats":"Needs genetically distinct samples and enough confident singlets per group; SNP coverage limits low-RNA cells","url":"https://bioconductor.org/packages/demuxSNP","repo_url":"https://github.com/michaelplynch/demuxSNP","language":"R","doi":"10.1093/gigascience/giae090","pmid":"39607981","cite_title":"demuxSNP: supervised demultiplexing single-cell RNA sequencing using cell hashing and SNPs.","year":"2024","verified":true,"citation_check":"verified","publication":"doi:10.1093/gigascience/giae090","publication_url":"https://doi.org/10.1093/gigascience/giae090","publication_title":"demuxSNP: supervised demultiplexing single-cell RNA sequencing using cell hashing and SNPs.","publication_venue":"GigaScience","citations":1,"repo_stars":9,"repo_pushed":"2024-10-16","review":"01-demux-recovery#demuxsnp","tags":["hashing","genotype","hybrid","supervised","rescue"],"site":"https://bioconductor.org/packages/demuxSNP"},{"id":"imagedoubler","name":"ImageDoubler","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Detects doublets and empty capture sites from the capture-chamber images of Fluidigm C1 runs instead of from expression","gain":"detection rate up to 93.87% and at least 33.1% higher F1 than expression-based detectors (self-reported)","gain_source":"self-reported","caveats":"Needs the per-site images of image-capturing platforms (Fluidigm C1); not applicable to droplet data.","url":"https://github.com/GuanLab/ImageDoubler","repo_url":"https://github.com/GuanLab/ImageDoubler","language":"Python","doi":"10.1038/s41467-024-55434-0","pmid":"39747095","cite_title":"ImageDoubler: image-based doublet identification in single-cell sequencing","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-024-55434-0","publication_url":"https://doi.org/10.1038/s41467-024-55434-0","publication_title":"ImageDoubler: image-based doublet identification in single-cell sequencing","publication_venue":"Nature Communications","citations":1,"repo_stars":1,"repo_pushed":"2024-11-04","review":"12-doublets-stress-batch#imagedoubler","tags":["imaging","fluidigm","plate-based"]},{"id":"omnidoublet","name":"OmniDoublet","kind":"tool","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Combines per-modality doublet scores from RNA and chromatin, weighting each by the Jaccard agreement of neighbourhoods across modalities, and thresholds the result with a Gaussian mixture","gain":"superior accuracy, robustness and scalability against existing methods (self-reported, no number in the abstract)","gain_source":"self-reported","requires":["filtered-matrix"],"doi":"10.1093/bib/bbaf538","pmid":"41081728","cite_title":"OmniDoublet: a method for doublet detection in multimodal single-cell sequencing data","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1093/bib/bbaf538","publication_url":"https://doi.org/10.1093/bib/bbaf538","publication_title":"OmniDoublet: a method for doublet detection in multimodal single-cell sequencing data","publication_venue":"Briefings in Bioinformatics","citations":1,"review":"12-doublets-stress-batch#omnidoublet","tags":["multiome"]},{"id":"rado","name":"RADO","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Doublet detector trained to maximise the area under the precision-recall curve on simulated doublets, for RNA and ATAC data","gain_source":"none","requires":["filtered-matrix"],"caveats":"Preprint only (bioRxiv 2023); no PubMed record found.","url":"https://github.com/poseidonchan/RADO","repo_url":"https://github.com/poseidonchan/RADO","language":"Python","doi":"10.1101/2023.10.30.564840","cite_title":"Robust and Accurate Doublet Detection of Single-Cell Sequencing Data via Maximizing Area Under Precision-Recall Curve","year":"2023","verified":true,"citation_check":"verified","publication":"doi:10.1101/2023.10.30.564840","publication_url":"https://doi.org/10.1101/2023.10.30.564840","publication_is_preprint":true,"publication_title":"Robust and Accurate Doublet Detection of Single-Cell Sequencing Data via Maximizing Area Under Precision-Recall Curve","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":1,"repo_stars":5,"repo_pushed":"2024-03-20","review":"12-doublets-stress-batch#rado","tags":["preprint","atac"]},{"id":"ruviii-pbps","name":"RUVIII with pseudobulk pseudosamples (RUVIII-PBPS)","kind":"method","layer":"core","categories":["low-cell-stats","batch-and-plate-effects"],"side":"additive","tier":"published-unbenchmarked","summary":"Resample cells with replacement within biology-by-batch groups and pseudobulk them into artificial pseudosamples used only to estimate unwanted-variation factors for RUVIII when technical replicates or negative-control genes are missing","recovers":"Removal of plate or processing effects from pseudobulk DE when only one single-cell sample per group exists to define replicates for RUV","gain":"Processing-cohort ASW on 2 PCs fell from 0.17 to 0.06; FDR controlled where standard RUV could not be used; per-cell-type RUV2/RUVIII controlled FDR even under confounding","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"The pseudosamples feed factor estimation, not the DE test; the test still needs genuine replicates. Requires a known batch that crosses the biology of interest. Improper RUV on pseudobulk can remove biology.","url":"https://github.com/esprietol/ruvPBPS","repo_url":"https://github.com/esprietol/ruvPBPS","language":"R","doi":"10.1093/nargab/lqaf179","pmid":"41368194","cite_title":"Removal of unwanted variation in pseudobulk analysis of single-cell RNA sequencing data and the leveraging of pseudoreplicates.","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1093/nargab/lqaf179","publication_url":"https://doi.org/10.1093/nargab/lqaf179","publication_title":"Removal of unwanted variation in pseudobulk analysis of single-cell RNA sequencing data and the leveraging of pseudoreplicates.","publication_venue":"NAR Genomics and Bioinformatics","citations":1,"repo_stars":2,"repo_pushed":"2025-07-14","review":"03-low-cell-stats#ruviii-pbps","tags":["RUV","batch","pseudoreplicates","plate"]},{"id":"schroeder-2026","name":"Schroeder et al. 2026 ambient benchmark across platforms","kind":"evidence","layer":"core","categories":["ambient-rna","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Preprint benchmark of CellBender, DecontX, SoupX, scCDC, scAR and CellClear on six human-mouse mixtures, PBMC, prefrontal cortex nuclei and a BD Rhapsody well-plate dataset, adding a count-integrity check","gain":"CellBender and SoupX removed contamination reliably with minimal count distortion; CellClear replaced > 93% of counts; scAR created spurious cell types (3 coarse types in BD Rhapsody, up to 8 in cortex); DecontX and scCDC the only tools usable without a raw droplet matrix","gain_source":"independent","caveats":"Preprint (April 2026); species-mixing ground truth is partial (within-species ambient is invisible).","doi":"10.64898/2026.04.08.717130","cite_title":"Benchmarking ambient RNA removal across droplet and well-plate platforms reveals artificial count generation as a critical failure mode of scAR and CellClear","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.64898/2026.04.08.717130","publication_url":"https://doi.org/10.64898/2026.04.08.717130","publication_title":"Benchmarking ambient RNA removal across droplet and well-plate platforms reveals artificial count generation as a critical failure mode of scAR and CellClear","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":1,"benchmarks":["schroeder-2026-ambient-benchmark"],"benchmark_refs":[{"id":"schroeder-2026-ambient-benchmark","name":"Schroeder et al. 2026, ambient RNA removal across droplet and well-plate platforms (preprint)","url":"https://doi.org/10.64898/2026.04.08.717130"}],"review":"11-quant-calling-ambient#schroeder-2026","tags":["benchmark","preprint","species-mixing"]},{"id":"10x-flex","name":"10x Chromium Flex (fixed RNA profiling)","kind":"design","layer":"core","categories":["screen-design","demux-hashing"],"side":"additive","tier":"benchmarked-sota","summary":"Probe-based whole-transcriptome assay on formaldehyde-fixed cells or nuclei in which probe barcodes multiplex samples before droplet partitioning","recovers":"fragile cells and queued samples through fixation and storage, and samples per run through probe barcodes","gain":"Independent: best overall of nine commercial kits on PBMCs and top tier for genes per cell (De Simone 2025); fixation retained fragile granulocytes better than fresh 10x 3' across nine sites after 4 weeks at -80 C (ABRF 2026); vendor-reported: up to 384 samples and 100 million cells per week in a 96-well plate format (October 2025 release)","gain_source":"independent","requires":["fastq"],"caveats":"Human and mouse probe sets only; probes miss most mitochondrial transcripts, so the mitochondrial fraction loses its usual QC meaning; more cross-site variation from on-site processing than other preserved workflows (ABRF 2026); core-facility guidance relaying 10x protocol CG000782: at least 25,000 (10x support advises 75,000) cells per fixation and over about 13,000 targeted cells per sample pushes multiplets above 5%","url":"https://www.10xgenomics.com/products/flex","citation_note":"no publication recorded","benchmarks":["de-simone-2025-kit-comparison","abrf-2026-preservation-multisite","brown-2024-multiplexing-reagents"],"benchmark_refs":[{"id":"de-simone-2025-kit-comparison","name":"De Simone et al. 2025, nine commercial scRNA-seq kits","url":"https://doi.org/10.1093/nar/gkae1186"},{"id":"abrf-2026-preservation-multisite","name":"ABRF multisite preservation study 2026 (Kolling et al.)","url":"https://doi.org/10.7171/001c.162768"},{"id":"brown-2024-multiplexing-reagents","name":"Brown et al. 2024, multiplexing reagents and fixed kits","url":"https://doi.org/10.1016/j.ygeno.2024.110793"}],"review":"04-screen-design#10x-flex","tags":["fixed","probe-based","kit","multiplexing","vendor"],"site":"https://www.10xgenomics.com/products/flex"},{"id":"abrf-preservation-2026","name":"ABRF multisite preservation study 2026","kind":"evidence","layer":"core","categories":["screen-design","qc-benchmarks","batch-and-plate-effects"],"side":"neutral","tier":"published-unbenchmarked","summary":"Nine core facilities processed the same fixed or cryopreserved leukocytes with 10x Flex, Parse Evercode WT v2 and Honeycomb HIVE and compared them with fresh 10x 3'","gain":"After 4 weeks at -80 C, fixation (Flex) and cryopreservation (HIVE) retained granulocytes, about half of leukocytes, better than fresh 10x 3' processing; Flex showed more cross-site technical variation than the other preserved workflows","gain_source":"independent","requires":["fastq"],"caveats":"Comparisons are not symmetric (Flex against fresh 3', HIVE day 1 against day 28); leukocytes and PBMCs only; the Flex mitochondrial fraction is low by probe design","doi":"10.7171/001c.162768","pmid":"42281660","cite_title":"Multisite Assessment of Methods for Cell Preservation Upstream of Single-Cell RNA Sequencing","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.7171/001c.162768","publication_url":"https://doi.org/10.7171/001c.162768","publication_title":"Multisite Assessment of Methods for Cell Preservation Upstream of Single-Cell RNA Sequencing","publication_venue":"Journal of Biomolecular Techniques JBT","citations":0,"review":"04-screen-design#abrf-preservation-2026","tags":["benchmark","fixed","cryopreservation","multisite","granulocytes"]},{"id":"ambidose","name":"AmbiDose","kind":"tool","layer":"core","categories":["ambient-rna"],"side":"both","tier":"published-unbenchmarked","summary":"Combines an empty-droplet ambient profile with a per-cell removal budget and protects lineage-enriched genes, using the ambient dose to guide count removal rather than to estimate a calibrated contamination fraction","recovers":"endogenous counts that global or overly aggressive correction removes","gain":"held-out human-mouse GEM-X mixture: removed 92.0% of cross-species UMIs while retaining 99.6% of same-species UMIs; lowest proximal-tubule marker leakage across five strain-mixed kidney libraries (self-reported)","gain_source":"self-reported","requires":["raw-matrix"],"caveats":"Preprint (September 2026); simulations showed reduced retention or incomplete removal when ambient and endogenous expression overlap; no independent benchmark.","url":"https://github.com/leelieber2025/AmbiDose","repo_url":"https://github.com/leelieber2025/AmbiDose","language":"Python","doi":"10.64898/2026.09.27.754849","cite_title":"AmbiDose: per-cell removal budgets for ambient RNA contamination","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.64898/2026.09.27.754849","publication_url":"https://doi.org/10.64898/2026.09.27.754849","publication_title":"AmbiDose: per-cell removal budgets for ambient RNA contamination","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":0,"repo_stars":2,"repo_pushed":"2026-10-24","review":"11-quant-calling-ambient#ambidose","tags":["preprint","scanpy"]},{"id":"ambientmapper","name":"AmbientMapper (scifi-demux)","kind":"tool","layer":"core","categories":["ambient-rna","demux-combinatorial","cell-calling"],"side":"both","tier":"published-unbenchmarked","summary":"Maps reads competitively to several references, learns the ambient profile from empty and low-complexity barcodes and separates nuclei from background and singlets from doublets in combinatorial-indexing (scifi) data","recovers":"low-depth nuclei discarded by read-count cell calling","gain":"wrong-genome rate 0.19% on a 26-genome reference panel; calls robust across parameters and designs (self-reported, interspecies, multi-genotype and simulated read-level data)","gain_source":"self-reported","requires":["bam"],"caveats":"Preprint; shown for scifi-ATAC (ambient chromatin) and needs multiple references or genotypes.","doi":"10.64898/2026.09.11.750809","pmid":"42779630","cite_title":"Empirical Estimation of Ambient Contamination in Combinatorial Single-Cell Methods Using Multi-Reference Mapping","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.64898/2026.09.11.750809","publication_url":"https://doi.org/10.64898/2026.09.11.750809","publication_title":"Empirical Estimation of Ambient Contamination in Combinatorial Single-Cell Methods Using Multi-Reference Mapping","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":0,"review":"11-quant-calling-ambient#ambientmapper","tags":["preprint","atac","split-pool"]},{"id":"boloori-2026","name":"Boloori et al. 2026 gamma delta T cell counts vs QC choices","kind":"evidence","layer":"core","categories":["qc-metrics-thresholds","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Re-analysis of a public 3' snRNA-seq dataset of 33,600 small-intestine nuclei showing how calling strategy and QC stringency change the recovered fraction of one rare cell type","gain":"gamma delta T fraction ranged 3.38-12.49% on the deposited matrix and 5.46-21.62% under strict filtering, a 3.70- to 4.08-fold spread; within one QC stratum the call rate rose from 0.51% to 12.17% across deciles of genes per nucleus","gain_source":"independent","caveats":"One dataset and one cell type; abstract-level numbers (no open full text found).","doi":"10.1016/j.jim.2026.114126","pmid":"42802005","cite_title":"How many gamma delta T cells are there? Calling strategy, quality control and receptor-locus specificity in 3-prime single-nucleus RNA sequencing of human small intestine","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.jim.2026.114126","publication_url":"https://doi.org/10.1016/j.jim.2026.114126","publication_title":"How many gamma delta T cells are there? Calling strategy, quality control and receptor-locus specificity in 3-prime single-nucleus RNA sequencing of human small intestine","publication_venue":"Journal of Immunological Methods","citations":0,"review":"13-metrics-guides-multimodal#boloori-2026","tags":["nuclei","rare-cell-type","cautionary"]},{"id":"chromap-qc","name":"Chromap peak-free scATAC QC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Extension of the Chromap aligner that reports peak-based QC metrics such as fraction of reads in peaks during alignment, without a separate peak-calling step","recovers":"none; restores FRiP filtering to bin-based pipelines","gain":"captured additional low-quality cells missed by SnapATAC2's QC and improved downstream results without extra compute (preprint, self-reported)","gain_source":"self-reported","requires":["fastq"],"caveats":"Preprint; no number of extra cells removed in the abstract.","url":"https://github.com/haowenz/chromap","repo_url":"https://github.com/haowenz/chromap","language":"C++","doi":"10.1101/2025.07.15.664951","pmid":"40791457","cite_title":"Quality control of single-cell ATAC-seq data without peak calling using Chromap","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1101/2025.07.15.664951","publication_url":"https://doi.org/10.1101/2025.07.15.664951","publication_is_preprint":true,"publication_title":"Quality control of single-cell ATAC-seq data without peak calling using Chromap","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":0,"repo_stars":229,"repo_pushed":"2026-03-20","review":"13-metrics-guides-multimodal#chromap-qc","tags":["atac","preprint","alignment"]},{"id":"clusterde","name":"ClusterDE","kind":"tool","layer":"adjacent","categories":["clustering-annotation","de-pseudobulk"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Removes false-positive cluster markers caused by double dipping by repeating clustering and DE on a synthetic null dataset that matches the real gene means, variances and gene-gene rank correlations but holds one population","gain":"Flags markers and clusters that over-clustering creates from one homogeneous population","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Tests whether two clusters are distinct, not whether they are biologically meaningful; cite the published package paper rather than its preprint and Research Square versions.","url":"https://jsb-ucla.github.io/ClusterDE/","repo_url":"https://github.com/JSB-UCLA/ClusterDE","language":"R","doi":"10.1177/15578666251383562","pmid":"41060830","cite_title":"ClusterDE: A Statistical Software Package for Removing Double-Dipping Bias in Post-Clustering Differential Expression Analysis.","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1177/15578666251383562","publication_url":"https://doi.org/10.1177/15578666251383562","publication_title":"ClusterDE: A Statistical Software Package for Removing Double-Dipping Bias in Post-Clustering Differential Expression Analysis.","publication_venue":"Journal of Computational Biology","citations":0,"citations_total":16,"citations_papers":2,"repo_stars":30,"repo_pushed":"2026-10-20","review":"21-concepts-preprocessing#clusterde","tags":["double-dipping","marker-genes","synthetic-null","over-clustering"],"site":"https://jsb-ucla.github.io/ClusterDE/"},{"id":"cmddemux","name":"CMDdemux","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"published-unbenchmarked","summary":"Demultiplexer that CLR-normalises tags within each cell, clusters with K-medoids and classifies by Mahalanobis distance using hashtag and mRNA data, with plots for checking doubtful droplets","recovers":"singlets on low-quality or over-labelled hashing data","gain":"Self-reported: 81% concordance with vireo versus 79% for deMULTIplex2 on poorly hashed ovarian tumours, both ahead of other callers; on an over-labelled CellPlex PDX dataset recovered CMO301 singlets that HTODemux and demuxmix under-called while deMULTIplex2 and BFF failed","gain_source":"self-reported","requires":["tag-counts","filtered-matrix"],"caveats":"New (2026); no independent benchmark yet","url":"https://github.com/jiananwehi/CMDdemux","repo_url":"https://github.com/jiananwehi/CMDdemux","language":"R","doi":"10.1093/nar/gkag360","pmid":"42033230","cite_title":"CMDdemux: an efficient single cell demultiplexing method.","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1093/nar/gkag360","publication_url":"https://doi.org/10.1093/nar/gkag360","publication_title":"CMDdemux: an efficient single cell demultiplexing method.","publication_venue":"Nucleic Acids Research","citations":0,"repo_stars":0,"repo_pushed":"2026-04-07","review":"01-demux-recovery#cmddemux","tags":["hashing","cmo","rna-aware"]},{"id":"condition-aware-qc-audit","name":"Condition-aware QC audit (thresholds per cell type x batch, losses per condition)","kind":"hypothesis","layer":"core","categories":["qc-metrics-thresholds","screen-design"],"side":"both","tier":"hypothesis","summary":"Set QC thresholds per cell type and batch (lane, plate), never per drug or dose, and tabulate cells removed by each QC step for every condition before any differential test","recovers":"cells of treatments that shift mito fraction or RNA content and would otherwise be removed at a treatment-dependent rate","gain":"none measured; drugs move the metrics QC relies on (paclitaxel and celecoxib repress global transcription per cell; mito fraction tracks drug resistance across CCLE lines)","gain_source":"none","requires":["filtered-matrix","multiple-conditions","tag-counts"],"caveats":"Per-condition adaptive thresholds would normalise away a toxic drug's damage; a global fixed threshold removes cells at a rate the drug sets. Both bias pseudobulk comparisons; the loss table makes the bias visible.","citation_note":"no publication recorded","review":"02-calling-qc-damaged#condition-aware-qc-audit","tags":["drug-screen","pseudobulk","audit"]},{"id":"count-then-balance-input","name":"Count cells per well, then balance input","kind":"hypothesis","layer":"core","categories":["screen-design","low-cell-stats"],"side":"additive","tier":"hypothesis","summary":"Record the number of cells or nuclei in each treated well before pooling, then pool similar numbers per well, so viability is kept as a phenotype while every condition gets comparable cell counts","recovers":"cells per condition in cytotoxic wells, and the viability readout that equal-input pooling would otherwise erase","gain":"No direct test; sci-Plex used hash-based nucleus counts per well as a viability measure, Tahoe-100M put roughly equal cell numbers per sample into barcoding, and scPerturb found that unequal cells per condition bias E-distance","gain_source":"none","requires":["tag-counts","doses-or-time"],"caveats":"Equal input cannot add cells to wells that died, so highly cytotoxic doses still need more seeding or pooled replicate wells; counting adds a step, and losses before counting may differ by treatment","citation_note":"no publication recorded","review":"04-screen-design#count-then-balance-input","tags":["viability","input-normalisation","drug-screen"]},{"id":"cyclemix","name":"CycleMix","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"both","tier":"published-unbenchmarked","summary":"Gaussian mixture model over marker-gene scores that assigns any number of cell-cycle states and can call cells non-cycling","recovers":"non-cycling cells that Seurat-style scoring forces into a phase","gain":"better assignment and regression than Seurat and cyclone on six droplet datasets (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"url":"https://github.com/tallulandrews/CycleMix","repo_url":"https://github.com/tallulandrews/CycleMix","language":"R","doi":"10.1093/bioadv/vbag179","pmid":"42609984","cite_title":"CycleMix: Gaussian mixture modeling of the cell cycle","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioadv/vbag179","publication_url":"https://doi.org/10.1093/bioadv/vbag179","publication_title":"CycleMix: Gaussian mixture modeling of the cell cycle","publication_venue":"Bioinformatics Advances","citations":0,"repo_stars":3,"repo_pushed":"2026-08-12","review":"12-doublets-stress-batch#cyclemix","tags":["bioconductor","mixture-model","non-cycling"]},{"id":"cyclevi","name":"CycleVI","kind":"tool","layer":"core","categories":["cell-cycle-and-stress"],"side":"both","tier":"published-unbenchmarked","summary":"Deep generative model with a circular latent subspace that separates cell-cycle variation from the rest, giving a continuous phase and a residual space free of cell-cycle effects","recovers":"signals entangled with proliferation, including drug responses, that score regression removes","gain":"phase validated against protein-level measurements; preserved drug-response signals better than standard cell-cycle regression (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"url":"https://github.com/jeuken/CycleVI","repo_url":"https://github.com/jeuken/CycleVI","language":"Python","doi":"10.1093/bioinformatics/btag372","pmid":"42334940","cite_title":"CycleVI: isolating cell cycle variation with an interpretable deep generative model","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btag372","publication_url":"https://doi.org/10.1093/bioinformatics/btag372","publication_title":"CycleVI: isolating cell cycle variation with an interpretable deep generative model","publication_venue":"Bioinformatics","citations":0,"repo_stars":6,"repo_pushed":"2026-07-21","review":"12-doublets-stress-batch#cyclevi","tags":["deep-learning","drug-response","scvi"]},{"id":"dostalova-2026","name":"Dostalova et al. 2026 dissociation workflow and reactive astrocytes","kind":"evidence","layer":"core","categories":["cell-cycle-and-stress"],"side":"neutral","tier":"published-unbenchmarked","summary":"A widely used commercial brain dissociation kit under-represented reactive astrocytes after ischaemic stroke compared with a low-shear workflow, selectively losing remodelling signatures","gain":"none (cautionary finding); dissociation choice changed which disease-associated cells survived","gain_source":"none","caveats":"One stroke model, with a preliminary similar trend in tauopathy.","doi":"10.1007/s12035-026-06278-w","pmid":"42886297","cite_title":"Tissue Dissociation Workflows Influence Reactive Astrocyte Recovery in Single-Cell Transcriptomics","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1007/s12035-026-06278-w","publication_url":"https://doi.org/10.1007/s12035-026-06278-w","publication_title":"Tissue Dissociation Workflows Influence Reactive Astrocyte Recovery in Single-Cell Transcriptomics","publication_venue":"Molecular Neurobiology","citations":0,"review":"12-doublets-stress-batch#dostalova-2026","tags":["dissociation","brain","survivor-bias"]},{"id":"doubletdetection","name":"DoubletDetection","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"benchmarked-sota","summary":"Repeatedly adds synthetic doublets, clusters with PhenoGraph or Louvain and scores cells by how often they fall in doublet-rich clusters, giving p-value based calls","recovers":"singlets and cleaner clusters","gain":"Demuxafy 2024: lowest share of wrongly classified droplets among doublet detectors (about 1% at 2 donors, about 3% at 16 or more); Xi & Li 2021: with DoubletFinder the most robust at restoring the correct number of clusters; Ttoouli 2025: among the top three by clustering quality","gain_source":"independent","requires":["filtered-matrix"],"caveats":"No peer-reviewed paper (cited by Zenodo DOI); failed on one of 16 datasets and among the slower methods (Xi & Li 2021).","url":"https://github.com/JonathanShor/DoubletDetection","repo_url":"https://github.com/JonathanShor/DoubletDetection","language":"Python","doi":"10.5281/zenodo.2678041","cite_title":"JonathanShor/DoubletDetection: doubletdetection v4.3.0.post1","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.5281/zenodo.2678041","publication_url":"https://doi.org/10.5281/zenodo.2678041","publication_title":"JonathanShor/DoubletDetection: doubletdetection v4.3.0.post1","citation_note":"no citation count yet (run make enrich; or not indexed by OpenAlex)","repo_stars":102,"repo_pushed":"2025-02-06","benchmarks":["xi-li-2021-doublet-benchmark","xi-li-2021-doublet-protocol","neavin-2024-demuxafy-benchmark","ttoouli-2025-multiplets"],"benchmark_refs":[{"id":"xi-li-2021-doublet-benchmark","name":"Xi and Li 2021, doublet-detection benchmark","url":"https://doi.org/10.1016/j.cels.2020.11.008"},{"id":"xi-li-2021-doublet-protocol","name":"Xi and Li 2021, doublet-detection benchmark protocol (scDblFinder added)","url":"https://doi.org/10.1016/j.xpro.2021.100699"},{"id":"neavin-2024-demuxafy-benchmark","name":"Neavin et al. 2024 (Demuxafy), genetic demultiplexer and doublet detector comparison","url":"https://doi.org/10.1186/s13059-024-03224-8"},{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"}],"review":"12-doublets-stress-batch#doubletdetection","tags":["clustering","zenodo"]},{"id":"expected-doublet-rate","name":"Expected doublet rate from loading (Poisson / vendor table)","kind":"method","layer":"core","categories":["doublets","screen-design"],"side":"neutral","tier":"standard","summary":"Sets the number of barcodes a detector calls from the expected multiplet rate for the number of cells loaded, about 0.8% per 1,000 recovered cells on 10x Chromium","gain_source":"none","requires":["filtered-matrix"],"caveats":"Ttoouli 2025 found the 10x rule consistently underestimates the multiplets marked by hashing; the rate covers all doublets, so in hashed or genotype-pooled data the within-sample (undetectable by tags) share is only about 1/N of it for N equal pools; Demuxafy ran Scrublet with R = N x 0.008 / 1000.","url":"https://www.10xgenomics.com/support","citation_note":"no publication recorded","benchmarks":["ttoouli-2025-multiplets"],"benchmark_refs":[{"id":"ttoouli-2025-multiplets","name":"Ttoouli and Hoffmann 2025, multiplet detection against cell hashing","url":"https://doi.org/10.1371/journal.pone.0333687"}],"review":"12-doublets-stress-batch#expected-doublet-rate","tags":["10x","loading","threshold"],"site":"https://www.10xgenomics.com/support"},{"id":"expression-label-recovery","name":"Expression-based label recovery for untagged cells","kind":"hypothesis","layer":"core","categories":["discarded-data","demux-hashing","low-cell-stats"],"side":"additive","tier":"hypothesis","summary":"Assigning hashing negatives to a sample with a classifier trained on confidently tagged cells' transcriptomes; sound when the label is a fixed identity (cell line, donor), circular when the label is the treatment whose effect is being measured","recovers":"negatives and uncertain cells when no genotype difference separates the samples","gain":"Identity labels only: MIX-Seq expression-based and SNP-based cell-line calls agreed over 99% (McFarland 2020); expression-aware demultiplexing reached mean accuracy 0.98 combined with genetics and added 1.4% on top of barcoding (Nassiri 2024). Treatment labels: no validated gain found","gain_source":"self-reported","requires":["tag-counts","filtered-matrix","multiple-conditions"],"caveats":"Cells assigned to a drug because they look treated inflate effect sizes and hide non-responders; keep such cells out of any comparison between the conditions the classifier separates, or use them only for condition-independent questions","citation_note":"no publication recorded","review":"01-demux-recovery#expression-label-recovery","tags":["label-transfer","circularity","drug-screen"]},{"id":"hasheddrops","name":"hashedDrops (DropletUtils)","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"standard","summary":"DropletUtils function that removes ambient tag levels and calls singlets and doublets from the log-fold change between a droplet's top and second tag, with MAD-based outlier thresholds","recovers":"more singlets when its confidence threshold is lowered","gain":"With confident.min lowered from 2 to 0.5 it had the highest mean F in 4 of 6 batches in Howitt 2023 (BAL batch 2: 0.847 versus 0.613 at the default), at the cost of roughly doubling genetic doublets called singlets (about 3 000 extra in BAL batch 3)","gain_source":"independent","requires":["tag-counts"],"caveats":"Output hinges on hard thresholds and the default is too strict for weak hashing; on hashed brain nuclei it called 32 singlets out of 4 048 droplets (hadge 2024); no dedicated publication","url":"https://bioconductor.org/packages/DropletUtils","repo_url":"https://github.com/MarioniLab/DropletUtils","language":"R","doi":"10.18129/B9.bioc.DropletUtils","cite_title":"DropletUtils","year":"2018","verified":true,"citation_check":"verified","publication":"doi:10.18129/B9.bioc.DropletUtils","publication_url":"https://doi.org/10.18129/B9.bioc.DropletUtils","publication_title":"DropletUtils","citation_note":"no citation count yet (run make enrich; or not indexed by OpenAlex)","repo_stars":68,"repo_pushed":"2026-09-24","benchmarks":["howitt-2023-hto-benchmark","sayed-2025-hashtag-benchmark","curion-2024-hadge-comparison"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"}],"review":"01-demux-recovery#hasheddrops","tags":["hashing","bioconductor","threshold"],"site":"https://bioconductor.org/packages/DropletUtils"},{"id":"replicate-wells","name":"Independent replicate wells or cultures per condition","kind":"design","layer":"core","categories":["screen-design","batch-and-plate-effects","low-cell-stats"],"side":"additive","tier":"standard","summary":"Each condition is applied to at least two independently seeded and treated wells or cultures, so the replicate unit for statistics is the well and not the cell","recovers":"true replicates for pseudobulk testing and an estimate of well-to-well variance","gain":"Cells within one sample are pseudoreplicates and treating them as independent inflates type 1 error (Zimmerman 2021, see also [[squair-2021]]); sci-Plex duplicate wells on randomised plates agreed at pseudobulk r = 0.99; sci-Plex-GxE used two independent transductions per condition","gain_source":"independent","requires":["replicates"],"caveats":"Doubles wells per condition; in pooled designs (MIX-Seq, Tahoe-100M) lines in one well share that well and are not replicates of the treatment; replicate plates confound plate with replicate unless layouts are randomised","citation_note":"no publication recorded","review":"04-screen-design#replicate-wells","tags":["replicates","pseudobulk","design"]},{"id":"knee-cell-calling","name":"Knee / inflection-point cell calling (barcodeRanks, Cell Ranger 2 style)","kind":"method","layer":"core","categories":["cell-calling"],"side":"subtractive","tier":"standard","summary":"Keeps barcodes above the knee or inflection of the ranked total-UMI curve, or above a fraction of a high quantile of expected cells; the default in STARsolo, kb and many alevin-fry runs","gain":"none; simple and fast","gain_source":"none","requires":["raw-matrix"],"caveats":"Cannot tell a small or RNA-poor cell from an empty droplet, so low-RNA types are lost ([[emptydrops]]); in nuclei data a quantile threshold kept debris (only 84.5% of passing droplets nuclear vs 95.7% with DIEM, 6 adipose samples, PMID 32620816); the knee moves with intronic counting and depth, so the same sample processed two ways keeps different cells.","url":"https://bioconductor.org/packages/DropletUtils","citation_note":"no publication recorded","review":"11-quant-calling-ambient#knee-cell-calling","tags":["droplet","best-practice"],"site":"https://bioconductor.org/packages/DropletUtils"},{"id":"martinez-de-morentin-2026","name":"Martinez-de-Morentin et al. 2026 spatial segmentation benchmark","kind":"evidence","layer":"core","categories":["qc-benchmarks","multimodal"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of 11 image-based, transcript-based and multimodal cell segmentation methods on 15 datasets from 5 imaging spatial transcriptomics technologies and 12 tissue types","gain":"performance varied widely across datasets, technologies and metrics; segmentation choice changed cell-type specificity, transcript contamination between neighbouring cells and ligand-receptor inference","gain_source":"independent","caveats":"No single method wins; segmentation is the cell-calling step of imaging spatial data, so its errors look like doublets and ambient contamination downstream.","doi":"10.1038/s41592-026-03272-x","pmid":"42919952","cite_title":"Benchmarking segmentation methods for spatial transcriptomics","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-026-03272-x","publication_url":"https://doi.org/10.1038/s41592-026-03272-x","publication_title":"Benchmarking segmentation methods for spatial transcriptomics","publication_venue":"Nature Methods","citations":0,"review":"13-metrics-guides-multimodal#martinez-de-morentin-2026","tags":["spatial","segmentation","benchmark"]},{"id":"mitochontrol","name":"MitoChontrol","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","damaged-cells"],"side":"both","tier":"published-unbenchmarked","summary":"Fits a Gaussian mixture to the mito fraction within each transcriptionally coherent cluster and sets a cluster-specific cut where the posterior probability of compromise exceeds a chosen level","recovers":"viable cell populations with elevated mito fraction","gain":"on HEK293 data with mtRNA inflated in 10% of cells it removed the inflated subset and kept the baseline; ddqc kept many inflated cells (qualitative, self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Preprint; no removal counts reported; depends on clustering; a global mito shift (all cells) is treated as biology, which is right for metabolic drugs but wrong if a whole condition is damaged.","url":"https://github.com/uttamLab/mitochontrol","repo_url":"https://github.com/uttamLab/mitochontrol","language":"Python","doi":"10.64898/2026.04.04.716517","pmid":"41993278","cite_title":"MitoChontrol: Adaptive mitochondrial filtering for robust single-cell RNA sequencing quality control","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.64898/2026.04.04.716517","publication_url":"https://doi.org/10.64898/2026.04.04.716517","publication_title":"MitoChontrol: Adaptive mitochondrial filtering for robust single-cell RNA sequencing quality control","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":0,"repo_stars":4,"repo_pushed":"2026-07-03","review":"02-calling-qc-damaged#mitochontrol","tags":["preprint","mito","per-cluster","scanpy"]},{"id":"multi-seq","name":"MULTI-seq (lipid and cholesterol tags)","kind":"design","layer":"core","categories":["screen-design","demux-hashing"],"side":"additive","tier":"benchmarked-sota","summary":"Lipid- and cholesterol-modified oligos insert into membranes to barcode live cells or nuclei of any species before pooling","recovers":"low-RNA cells that a UMI threshold would discard, and doublets including transcriptionally similar ones","gain":"Independent (Mylka 2022): cholesterol-oligo hashing of nuclei reached overall classification accuracy 0.84 against 0.51-0.65 for antibody nuclei hashing, and lipids beat antibodies on mouse brain cells; self-reported: in a PDX tumour, 90.8% of sequenced neutrophils fell below the Cell Ranger UMI threshold and were kept by MULTI-seq classification","gain_source":"independent","requires":["tag-counts","raw-matrix"],"caveats":"On cell lines lipid tags left more cells unassigned than antibodies (7% MULTI-seq LMO and 21% custom LMO against 1.1-1.8% TotalSeq) and swapped tags in 0.89% of singlets (Mylka 2022); BSA quenches LMO labelling of nuclei; calling with [[multiseqdemux]] or other T1 tools","repo_url":"https://github.com/chris-mcginnis-ucsf/MULTI-seq","language":"R","doi":"10.1038/s41592-019-0433-8","pmid":"31209384","cite_title":"MULTI-seq: sample multiplexing for single-cell RNA sequencing using lipid-tagged indices","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-019-0433-8","publication_url":"https://doi.org/10.1038/s41592-019-0433-8","publication_title":"MULTI-seq: sample multiplexing for single-cell RNA sequencing using lipid-tagged indices","publication_venue":"Nature Methods","citation_note":"primary publication shared by 3 records","repo_stars":66,"repo_pushed":"2023-11-22","benchmarks":["mylka-2022-hashing-comparison","brown-2024-multiplexing-reagents"],"benchmark_refs":[{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022, antibody versus lipid hashing","url":"https://doi.org/10.1186/s13059-022-02628-8"},{"id":"brown-2024-multiplexing-reagents","name":"Brown et al. 2024, multiplexing reagents and fixed kits","url":"https://doi.org/10.1016/j.ygeno.2024.110793"}],"review":"04-screen-design#multi-seq","tags":["hashing","lipid","nuclei","low-rna-rescue"]},{"id":"multi-tcr-doublets","name":"Multiple TCR chains as a doublet marker in superloaded runs (Sserwadda 2025)","kind":"evidence","layer":"core","categories":["doublets","screen-design"],"side":"subtractive","tier":"published-unbenchmarked","summary":"In standard and superloaded multiplexed thymus and blood runs, over half of the T cells expressing multiple TCR chains were doublets, so receptor configuration adds a doublet filter that expression-based tools lack","gain":"superloading caused minimal transcriptomic differences; over 50% of multi-TCR-chain T cells were doublets regardless of loading","gain_source":"independent","caveats":"Immune cells with paired VDJ data only.","doi":"10.1080/08820139.2025.2457039","pmid":"39882751","cite_title":"Superloaded Multiplexed scRNA-seq Data Preserves Primary Immune Cell Heterogeneity but Necessitates Stringent Doublet Removal","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1080/08820139.2025.2457039","publication_url":"https://doi.org/10.1080/08820139.2025.2457039","publication_title":"Superloaded Multiplexed scRNA-seq Data Preserves Primary Immune Cell Heterogeneity but Necessitates Stringent Doublet Removal","publication_venue":"Immunological Investigations","citations":0,"review":"12-doublets-stress-batch#multi-tcr-doublets","tags":["vdj","superloading","immune"]},{"id":"multiseqdemux","name":"MULTIseqDemux / deMULTIplex","kind":"tool","layer":"core","categories":["demux-hashing","doublets"],"side":"both","tier":"benchmarked","summary":"Classifier released with MULTI-seq (deMULTIplex R package, ported to Seurat as MULTIseqDemux) that sets each tag's threshold between kernel-density peaks by a quantile sweep that maximises singlets, iterating after removing negatives","recovers":"sample labels for lipid- or antibody-tagged cells and nuclei","gain":"Preferred caller in Mylka 2022 (freemuxlet truth): overall classification accuracy 0.96 on antibody-hashed cell lines and 0.84 versus 0.74 for HTODemux on cholesterol-oligo-hashed nuclei; with demuxEM, the closest match to vireo donors on hashed brain nuclei in hadge 2024","gain_source":"independent","requires":["tag-counts"],"caveats":"Assumes bimodal tag counts: deMULTIplex scored mean F 0.218 on a poorly hashed ovarian tumour batch (Howitt 2023) and missed whole PDX samples that its successor recovered (deMULTIplex2 authors); per-cell CLR before the sweep recovered ~56% of false negatives in Sayed 2025","url":"https://github.com/chris-mcginnis-ucsf/MULTI-seq","repo_url":"https://github.com/chris-mcginnis-ucsf/MULTI-seq","language":"R","doi":"10.1038/s41592-019-0433-8","pmid":"31209384","cite_title":"MULTI-seq: sample multiplexing for single-cell RNA sequencing using lipid-tagged indices.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-019-0433-8","publication_url":"https://doi.org/10.1038/s41592-019-0433-8","publication_title":"MULTI-seq: sample multiplexing for single-cell RNA sequencing using lipid-tagged indices.","publication_venue":"Nature Methods","citation_note":"primary publication shared by 3 records","repo_stars":66,"repo_pushed":"2023-11-22","benchmarks":["howitt-2023-hto-benchmark","mylka-2022-hashing-comparison","sayed-2025-hashtag-benchmark","curion-2024-hadge-comparison"],"benchmark_refs":[{"id":"howitt-2023-hto-benchmark","name":"Howitt et al. 2023, hashtag demultiplexing benchmark","url":"https://doi.org/10.1093/nargab/lqad086"},{"id":"mylka-2022-hashing-comparison","name":"Mylka et al. 2022, antibody versus lipid hashing","url":"https://doi.org/10.1186/s13059-022-02628-8"},{"id":"sayed-2025-hashtag-benchmark","name":"Sayed et al. 2025, tag normalisation x caller benchmark","url":"https://doi.org/10.1093/bfgp/elae039"},{"id":"curion-2024-hadge-comparison","name":"Curion et al. 2024 (hadge), hashing and genetic demultiplexer comparison","url":"https://doi.org/10.1186/s13059-024-03249-z"}],"review":"01-demux-recovery#multiseqdemux","tags":["hashing","lipid","seurat"]},{"id":"nie-2026","name":"Nie et al. 2026 ambient benchmark","kind":"evidence","layer":"core","categories":["ambient-rna","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Benchmark of seven ambient RNA tools (DecontX, SoupX, scAR, CellBender, FastCAR, scCDC, CellClear) for estimation accuracy, robustness and subtype sensitivity on simulated and experimental data","gain":"DecontX named most accurate contamination estimate (abstract); scAR most robust but overestimates; CellClear best for close subtypes; in the mtDNA-genotype experiment CellBender and FastCAR were closest to the empirical baseline (mean RMSLE < 0.06)","gain_source":"independent","caveats":"The abstract names DecontX most accurate for contamination level, while the mtDNA-genotype experiment in the results favours CellBender and FastCAR; robustness to fewer cells and lower depth differs by tool.","doi":"10.1038/s41467-026-77458-4","pmid":"42844284","cite_title":"Systematic benchmarking of ambient RNA decontamination tools to advance precision in single-cell transcriptomic analysis","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41467-026-77458-4","publication_url":"https://doi.org/10.1038/s41467-026-77458-4","publication_title":"Systematic benchmarking of ambient RNA decontamination tools to advance precision in single-cell transcriptomic analysis","publication_venue":"Nature Communications","citations":0,"review":"02-calling-qc-damaged#nie-2026","tags":["benchmark","genotype-mixing"]},{"id":"optimus","name":"Optimus (HCA / WARP pipeline)","kind":"tool","layer":"core","categories":["alignment-quantification"],"side":"neutral","tier":"benchmarked","summary":"Human Cell Atlas WDL pipeline for 10x data, STARsolo-based in current versions (multi-mappers allocated Uniform by default), that returns count matrices with emptyDrops results (lower bound 100 UMIs) and QC metrics attached rather than a pre-filtered matrix","recovers":"an unfiltered matrix with per-barcode QC, so the user and not the pipeline decides which barcodes are cells","gain":"You 2021: with kallisto|bustools, top 2 workflows on one downstream ranking (linear-model coefficients)","gain_source":"independent","requires":["fastq"],"caveats":"Assigned more counts to pseudogenes than Cell Ranger (You 2021, Optimus v1.3.6 and v2.0.0, older versions); fails when fewer than ~50 cells are called (WARP docs); designed for Terra/Cromwell execution; no dedicated paper.","url":"https://broadinstitute.github.io/warp/docs/Pipelines/Optimus_Pipeline/README","repo_url":"https://github.com/broadinstitute/warp","language":"multiple","citation_note":"no publication recorded","repo_stars":232,"repo_pushed":"2026-10-23","benchmarks":["you-2021-preprocessing-benchmark"],"benchmark_refs":[{"id":"you-2021-preprocessing-benchmark","name":"You et al. 2021, UMI preprocessing workflow benchmark","url":"https://doi.org/10.1186/s13059-021-02552-3"}],"review":"11-quant-calling-ambient#optimus","tags":["10x","atlas"],"site":"https://broadinstitute.github.io/warp/docs/Pipelines/Optimus_Pipeline/README"},{"id":"meier-2026","name":"Order of ambient correction and doublet detection (Meier et al. 2026)","kind":"evidence","layer":"core","categories":["ambient-rna","doublets","qc-benchmarks"],"side":"neutral","tier":"published-unbenchmarked","summary":"Preprint testing decontX, SoupX and CellBender before or after six doublet detectors on engineered and multiplexed data with known doublets","gain":"doublet detection worked best before ambient correction, except with CellBender; decontX first retained the largest share of doublets; decontX and SoupX removed proportionally more ambient RNA from undetected doublets","gain_source":"independent","caveats":"Preprint (October 2026); conflicts with pipelines that correct ambient first.","doi":"10.64898/2026.10.13.758369","cite_title":"Order Matters: Ambient RNA correction confounds doublet detection in single-cell RNA sequencing","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.64898/2026.10.13.758369","publication_url":"https://doi.org/10.64898/2026.10.13.758369","publication_title":"Order Matters: Ambient RNA correction confounds doublet detection in single-cell RNA sequencing","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":0,"benchmarks":["meier-2026-ambient-doublet-order"],"benchmark_refs":[{"id":"meier-2026-ambient-doublet-order","name":"Meier et al. 2026, ambient correction order and doublet detection (preprint)","url":"https://doi.org/10.64898/2026.10.13.758369"}],"review":"11-quant-calling-ambient#meier-2026","tags":["benchmark","preprint"]},{"id":"batch-composition-diagnostic","name":"Per-batch QC distributions and per-cluster batch composition","kind":"method","layer":"core","categories":["batch-and-plate-effects","qc-metrics-thresholds"],"side":"neutral","tier":"standard","summary":"Plots QC metrics by lane, plate or batch and tabulates each cluster's share of cells from each batch before integration, flagging clusters made of one batch and batches with shifted QC","gain_source":"none","requires":["filtered-matrix"],"caveats":"A cluster from one batch can be real biology when batches differ in condition, which is why batch and condition must not be confounded by design.","url":"https://bioconductor.org/books/release/OSCA/","citation_note":"no publication recorded","review":"12-doublets-stress-batch#batch-composition-diagnostic","tags":["osca","diagnostic"],"site":"https://bioconductor.org/books/release/OSCA/"},{"id":"pooled-variance-unreplicated-drugs","name":"Pooled residual variance for unreplicated drugs","kind":"hypothesis","layer":"core","categories":["low-cell-stats","screen-design"],"side":"additive","tier":"hypothesis","summary":"Fit one linear model across all wells so that drugs with a single well are tested against a residual variance estimated from replicated wells, such as several vehicle wells or a replicated subset of drugs","recovers":"A replicate-level test for unreplicated drugs without inventing replicates from cell subsets","gain_source":"none","requires":["multiple-conditions","replicates"],"caveats":"Assumes unreplicated drugs share the variance of the replicated wells; voomByGroup shows group variances often differ in pseudobulk data. Residual degrees of freedom come only from replicated conditions. Untested in single-cell drug screens.","citation_note":"no publication recorded","review":"03-low-cell-stats#pooled-variance-unreplicated-drugs","tags":["drug-screen","limma","design"]},{"id":"qcatch","name":"QCatch","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","cell-calling"],"side":"neutral","tier":"published-unbenchmarked","summary":"Command-line tool that takes alevin-fry or simpleaf output, calls cells and writes an interactive HTML QC report (UMI distributions, sequencing saturation, splicing status) plus an annotated h5ad","recovers":"none by itself; gives alevin-fry users the cell calling and QC report Cell Ranger users get by default","gain":"none quantified","gain_source":"none","requires":["spliced-unspliced"],"caveats":"Tied to the alevin-fry ecosystem; its cell calling has not been benchmarked against EmptyDrops-style callers.","url":"https://github.com/COMBINE-lab/QCatch","repo_url":"https://github.com/COMBINE-lab/QCatch","language":"Python","doi":"10.1093/bioinformatics/btag184","pmid":"41987571","cite_title":"QCatch: a framework for quality control assessment and analysis of single-cell sequencing data","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1093/bioinformatics/btag184","publication_url":"https://doi.org/10.1093/bioinformatics/btag184","publication_title":"QCatch: a framework for quality control assessment and analysis of single-cell sequencing data","publication_venue":"Bioinformatics","citations":0,"citations_total":0,"citations_papers":2,"repo_stars":6,"repo_pushed":"2026-09-06","review":"13-metrics-guides-multimodal#qcatch","tags":["report","alevin-fry"]},{"id":"cell-cycle-regression","name":"Regressing out cell-cycle scores (all phases or the S minus G2M difference)","kind":"method","layer":"core","categories":["cell-cycle-and-stress"],"side":"subtractive","tier":"standard","summary":"Removes cell-cycle variation by regressing gene expression on S and G2M scores, or only on their difference so that cycling and non-cycling cells stay separated","gain_source":"none","requires":["filtered-matrix"],"caveats":"Removes any biology correlated with the scores, including proliferation changes that are a treatment effect; ccRemover and CycleVI authors report that score regression removes other signal (self-reported by competing methods); Massoni-Badosa note the same risk for any signature regression.","url":"https://satijalab.org/seurat/articles/cell_cycle_vignette.html","citation_note":"no publication recorded","review":"12-doublets-stress-batch#cell-cycle-regression","tags":["seurat","regression"],"site":"https://satijalab.org/seurat/articles/cell_cycle_vignette.html"},{"id":"scattered-vehicle-controls","name":"Scattered vehicle controls and randomised plate layout","kind":"hypothesis","layer":"core","categories":["batch-and-plate-effects","screen-design"],"side":"neutral","tier":"hypothesis","summary":"Vehicle (DMSO) wells are spread across rows, columns and edges of every plate and drug positions are randomised between replicate plates, so position and plate effects can be modelled instead of being confounded with treatment","recovers":"unbiased within-plate controls and the ability to separate plate position from drug effect","gain":"Bulk high-throughput screening, not single-cell: with active-drug plates above about 20% hit rate, normalisation using edge-placed controls failed while scattered controls plus Loess reduced row, column and edge effects (Mpindi 2015, simulated 384-well plates); not yet measured for single-cell transcriptomic readouts","gain_source":"independent","requires":["multiple-conditions","replicates"],"caveats":"Transfer from viability screens to scRNA-seq is assumed; sci-Plex randomised positions between replicate plates and Tahoe-100M placed control-media wells at fixed positions H11 and H12, and neither reported a position-effect analysis; how many DMSO wells per plate are enough is untested","citation_note":"no publication recorded","review":"04-screen-design#scattered-vehicle-controls","tags":["plate-layout","controls","dmso","randomisation"]},{"id":"cell-cycle-as-readout","name":"Score cell cycle as a response readout, regress it only within condition","kind":"hypothesis","layer":"core","categories":["cell-cycle-and-stress","perturbation-models"],"side":"additive","tier":"hypothesis","summary":"In drug and genetic screens, phase shifts and arrest are part of the response, so phase fractions per condition should be reported and modelled, and any cell-cycle removal done within condition or by disentangling (CycleVI) rather than by global score regression","recovers":"proliferation and arrest effects that global regression removes","gain":"none measured for global regression in screens; CycleVI reports better preservation of drug-response signals than standard regression (self-reported); VeloCycle detected cycle-speed changes after Perturb-seq knockdowns","gain_source":"none","requires":["multiple-conditions","filtered-matrix"],"caveats":"Phase calls themselves are uncertain (no method consistently best, Guo & Chen 2024), so condition differences in phase should be checked with a second caller.","citation_note":"no publication recorded","review":"12-doublets-stress-batch#cell-cycle-as-readout","tags":["drug-screen","perturbation"]},{"id":"scqcenrich","name":"scQCenrich","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","damaged-cells","cell-cycle-and-stress"],"side":"both","tier":"published-unbenchmarked","summary":"Multi-metric post-cell-calling QC that adds intronic fraction, MALAT1 enrichment, dissociation-stress features and optional splicing to counts, genes and mito","recovers":"neuronal, cardiomyocyte, erythroid and malignant cells that single-metric thresholds over-filter","gain":"10x mouse brain: removed 1,185 cells vs Seurat-style 2,520, scater 1,801, miQC 2,770, DropletQC 1,968","gain_source":"self-reported","requires":["filtered-matrix","spliced-unspliced"],"caveats":"New (2026); comparisons are by its authors; whole-cell data only. For MALAT1 as a quality signal see [[malat1-quality-marker]] (preprint).","url":"https://github.com/lemonlyy755/scQCenrich","repo_url":"https://github.com/lemonlyy755/scQCenrich","language":"R","doi":"10.1038/s42003-026-10382-x","pmid":"42342867","cite_title":"ScQCenrich enables multi-metric quality control for single-cell RNA sequencing","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s42003-026-10382-x","publication_url":"https://doi.org/10.1038/s42003-026-10382-x","publication_title":"ScQCenrich enables multi-metric quality control for single-cell RNA sequencing","publication_venue":"Communications Biology","citations":0,"repo_stars":5,"repo_pushed":"2026-05-06","review":"02-calling-qc-damaged#scqcenrich","tags":["malat1","intronic-fraction","stress"]},{"id":"sebula","name":"SEBULA","kind":"tool","layer":"core","categories":["doublets","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Semi-parametric empirical Bayes multiplet caller for snATAC-seq that models the singlet background from fragments, gives FDR-controlled probabilities and can add evidence from paired RNA","gain":"better sensitivity and specificity than snATAC-seq methods across simulations and seven multimodal datasets with hashing truth (self-reported)","gain_source":"self-reported","requires":["bam"],"caveats":"No synthetic doublets, so no dependence on cluster structure; new (2026).","doi":"10.1371/journal.pcbi.1013653","pmid":"42054434","cite_title":"Semi-parametric empirical bayes method for multiplet detection in snATAC-seq with probabilistic multi-omic integration","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1371/journal.pcbi.1013653","publication_url":"https://doi.org/10.1371/journal.pcbi.1013653","publication_title":"Semi-parametric empirical bayes method for multiplet detection in snATAC-seq with probabilistic multi-omic integration","publication_venue":"PLoS Computational Biology","citations":0,"review":"12-doublets-stress-batch#sebula","tags":["atac","multiome","fdr"]},{"id":"handling-vs-drug-stress","name":"Separate handling stress from drug-induced stress with matched vehicle wells","kind":"hypothesis","layer":"core","categories":["cell-cycle-and-stress","screen-design"],"side":"both","tier":"hypothesis","summary":"Many drugs induce the same immediate-early and heat-shock genes as dissociation, so a stress score should be compared with vehicle wells handled in the same lane and time, and only the vehicle-matched excess read as response","recovers":"genuine stress responses that a global stress-score regression or filter would remove, and drug calls that are really handling artefacts","gain":"none measured; handling time alone changed 1,185 PBMC genes (Massoni-Badosa 2020) and enzymatic digestion created a stress cluster (Marsh 2022)","gain_source":"none","requires":["multiple-conditions","replicates"],"caveats":"Needs vehicle controls in every lane or plate and matched handling time; cultured lines have less dissociation stress than tissue but trypsinisation and wait times still apply.","citation_note":"no publication recorded","review":"12-doublets-stress-batch#handling-vs-drug-stress","tags":["drug-screen","controls"]},{"id":"singlecellmqc","name":"SingleCellMQC","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"both","tier":"published-unbenchmarked","summary":"R package for QC at sample, cell, feature and batch level across scRNA-seq, antibody-derived tags and TCR/BCR data, combining fixed thresholds, tissue-specific reference ranges and data-driven outliers in an HTML report","recovers":"one QC pass over all modalities, so a cell is not dropped for one modality's failure without that being visible","gain":"demonstrated on a 28,498-cell PBMC multi-omics dataset, a 137,214-cell PBMC dataset and a breast atlas of over 1 million cells; no comparison of cells retained","gain_source":"none","requires":["filtered-matrix","protein"],"caveats":"New (2026); built on Seurat and BPCells; its ADT doublet and threshold choices have not been independently evaluated.","url":"https://github.com/WenZhong-Lab/SingleCellMQC","repo_url":"https://github.com/WenZhong-Lab/SingleCellMQC","language":"R","doi":"10.1016/j.isci.2026.117398","pmid":"42733637","cite_title":"SingleCellMQC: A comprehensive quality control workflow for single-cell multi-omics","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1016/j.isci.2026.117398","publication_url":"https://doi.org/10.1016/j.isci.2026.117398","publication_title":"SingleCellMQC: A comprehensive quality control workflow for single-cell multi-omics","publication_venue":"iScience","citations":0,"repo_stars":6,"repo_pushed":"2026-10-19","review":"13-metrics-guides-multimodal#singlecellmqc","tags":["citeseq","protein","vdj","report"]},{"id":"spatialartifacts","name":"SpatialArtifacts","kind":"tool","layer":"core","categories":["qc-metrics-thresholds","multimodal"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Finds spatially contiguous tissue artefacts (dry patches, tissue lifting, uneven reagent) in Visium and VisiumHD by combining MAD outliers with morphological operations and classifying them as edge or interior, large or small","recovers":"none; removes or flags artefact regions for review while keeping true low-count domains","gain":"demonstrated on human hippocampus, dorsolateral prefrontal cortex and colorectal cancer; no counts in the abstract","gain_source":"none","requires":["filtered-matrix"],"caveats":"Preprint (2026).","url":"https://bioconductor.org/packages/SpatialArtifacts","repo_url":"https://github.com/CambridgeCat13/SpatialArtifacts","language":"multiple","doi":"10.64898/2026.05.15.725260","pmid":"42239246","cite_title":"SpatialArtifacts: a computational framework for tissue artifact detection in spatial transcriptomics data","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.64898/2026.05.15.725260","publication_url":"https://doi.org/10.64898/2026.05.15.725260","publication_title":"SpatialArtifacts: a computational framework for tissue artifact detection in spatial transcriptomics data","publication_venue":"bioRxiv (Cold Spring Harbor Laboratory)","citations":0,"repo_stars":5,"repo_pushed":"2026-05-20","review":"13-metrics-guides-multimodal#spatialartifacts","tags":["spatial","visium","preprint"],"site":"https://bioconductor.org/packages/SpatialArtifacts"},{"id":"stealth-multiplets","name":"Stealth multiplets in sample multiplexing (Nakaki & Sharpe 2025)","kind":"evidence","layer":"core","categories":["doublets","demux-hashing"],"side":"neutral","tier":"published-unbenchmarked","summary":"Models four classes of multiplet in sample-multiplexed droplet data (homogeneous stealth, partial stealth, multilabelled, unlabelled) and shows partial-stealth multiplets, where one cell's label is lost, in real hashed and genotype-pooled datasets","gain":"none (cautionary finding)","gain_source":"none","requires":["tag-counts"],"caveats":"Probabilities are model-based; partial-stealth multiplets matter most when labelling or demultiplexing is weak.","doi":"10.1186/s12864-025-11835-z","pmid":"40702454","cite_title":"Probability of stealth multiplets in sample-multiplexing for droplet-based single-cell analysis","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.1186/s12864-025-11835-z","publication_url":"https://doi.org/10.1186/s12864-025-11835-z","publication_title":"Probability of stealth multiplets in sample-multiplexing for droplet-based single-cell analysis","publication_venue":"BMC Genomics","citations":0,"review":"12-doublets-stress-batch#stealth-multiplets","tags":["hashing","genotype","theory"]},{"id":"sat-gene-panels","name":"Stress-altered transcription gene panels (Yan 2026)","kind":"method","layer":"core","categories":["cell-cycle-and-stress"],"side":"both","tier":"published-unbenchmarked","summary":"Tissue-specific dissociation-stress gene panels for brain and skull bone marrow, refined by random forest from paired gentle and conventional preparations, used to detect and remove the artefact retrospectively","recovers":"published datasets prepared with conventional dissociation","gain":"the optimised protocol cut stress-altered transcription by about 95%; the panels alone cut it by 60-64% (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Neuroimmune tissues only; repository not checked.","doi":"10.1038/s42003-026-10609-x","pmid":"42410134","cite_title":"A two-pronged strategy eliminates dissociation artifacts for high-fidelity neuroimmune single-cell transcriptomics","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1038/s42003-026-10609-x","publication_url":"https://doi.org/10.1038/s42003-026-10609-x","publication_title":"A two-pronged strategy eliminates dissociation artifacts for high-fidelity neuroimmune single-cell transcriptomics","publication_venue":"Communications Biology","citations":0,"review":"12-doublets-stress-batch#sat-gene-panels","tags":["dissociation","brain","bone-marrow"]},{"id":"superloading","name":"Superloading with sample multiplexing","kind":"design","layer":"core","categories":["screen-design","doublets"],"side":"additive","tier":"published-unbenchmarked","summary":"Loading a droplet lane well above the standard concentration when cells carry sample tags or genotypes, so cross-sample multiplets are removed and more singlets are kept per lane","recovers":"singlets per lane and per unit cost","gain":"scPower cost-power model (independent of the hashing authors): with doublet detection, overloading lanes raised DE and eQTL power under a fixed budget even after doublets were discarded; Cell Hashing (self-reported, modelled): about 4x more singlets at a matched unresolved multiplet rate","gain_source":"independent","requires":["tag-counts","genotypes"],"caveats":"Needs either tags or genotypes; same-sample multiplets stay undetected (about 1/N of multiplets for N equal samples); Mylka 2022 saw 48% more captured cells give 125% more doublets and 325% more unassigned barcodes; scPower notes observed doublet rates above its model, so modelled gains are upper bounds; calling with [[demuxlet]], [[htodemux]] or similar T1 tools","citation_note":"no publication recorded","review":"04-screen-design#superloading","tags":["superloading","doublets","hashing","genotype","cost"]},{"id":"tag-guided-cell-rescue","name":"Tag-guided rescue of low-RNA cells","kind":"method","layer":"core","categories":["demux-hashing","cell-calling","discarded-data"],"side":"additive","tier":"published-unbenchmarked","summary":"Using a confident sample tag as independent evidence that a barcode holds a cell, to keep low-RNA barcodes that RNA-only cell calling or UMI floors would discard","recovers":"cells with little RNA (neutrophils, small or stressed cells) below the usual UMI cut-off","gain":"Self-reported in MULTI-seq: in cryopreserved PDX samples, 90.8% of sequenced neutrophils were below the CellRanger UMI inflection (1 350) and were kept because their barcodes classified; low-RNA barcodes that did not classify looked like broken cells","gain_source":"self-reported","requires":["tag-counts","raw-matrix"],"caveats":"Free or ambient tags can make debris droplets look tagged, so a tag floor plus RNA checks are still needed; hashing negatives had ~2x fewer UMIs than singlets (Mylka 2022), so tag and RNA failure partly co-occur; no independent benchmark","doi":"10.1038/s41592-019-0433-8","pmid":"31209384","cite_title":"MULTI-seq: sample multiplexing for single-cell RNA sequencing using lipid-tagged indices.","year":"2019","verified":true,"citation_check":"verified","publication":"doi:10.1038/s41592-019-0433-8","publication_url":"https://doi.org/10.1038/s41592-019-0433-8","publication_title":"MULTI-seq: sample multiplexing for single-cell RNA sequencing using lipid-tagged indices.","publication_venue":"Nature Methods","citation_note":"primary publication shared by 3 records","review":"01-demux-recovery#tag-guided-cell-rescue","tags":["hashing","low-rna","cell-calling","rescue"]},{"id":"ulmnet","name":"ULMnet","kind":"method","layer":"core","categories":["discarded-data","doublets"],"side":"additive","tier":"published-unbenchmarked","summary":"Scores each barcode against cell-type marker signatures with univariate linear models to identify multiplets, predict their composition and build physical cell-cell interaction networks","recovers":"multiplet composition and contact networks from routine and partially dissociated scRNA-seq","gain":"FACS-sorted DC-T doublets: sensitivity 56% in vitro and 39% in vivo at 99.7-99.9% precision, against 52.1%/29.2% for Neighbor-seq and 21.7%/15.1% for CIcADA","gain_source":"self-reported","requires":["filtered-matrix","reference"],"caveats":"comparison run by the method's own authors on two sorted-doublet datasets; sensitivity drops in vivo; no packaged repository named in the paper (built on decoupleR run_ulm)","url":"https://doi.org/10.3389/fimmu.2025.1722504","language":"R","doi":"10.3389/fimmu.2025.1722504","pmid":"41583424","cite_title":"ULMnet: inferring physical cell-cell communication networks from scRNAseq data using univariate linear models","year":"2025","verified":true,"citation_check":"verified","publication":"doi:10.3389/fimmu.2025.1722504","publication_url":"https://doi.org/10.3389/fimmu.2025.1722504","publication_title":"ULMnet: inferring physical cell-cell communication networks from scRNAseq data using univariate linear models","publication_venue":"Frontiers in Immunology","citations":0,"review":"05-discarded-data#ulmnet","tags":["doublets-as-signal","cell-interactions","signature-scoring"],"site":"https://doi.org/10.3389/fimmu.2025.1722504"},{"id":"control-well-null","name":"Well-to-well null from replicate control wells","kind":"hypothesis","layer":"core","categories":["low-cell-stats","screen-design"],"side":"additive","tier":"hypothesis","summary":"Compare each drug-vs-vehicle statistic (DE count, effect distance, program shift) with its distribution across vehicle-vs-vehicle well pairs, so the significance threshold reflects real culture-to-culture variation","recovers":"Calibrated calls in screens where most conditions have one well, using the null-comparison logic of the Squair 2021 and Junttila 2022 mock analyses","gain_source":"none","requires":["multiple-conditions"],"caveats":"Needs several vehicle wells spread across plates and positions; assumes drug wells vary like vehicle wells; summary statistics must be computed identically (same cell numbers, subsampled if needed). Not validated in a published drug screen.","citation_note":"no publication recorded","review":"03-low-cell-stats#control-well-null","tags":["drug-screen","calibration","design"]},{"id":"xoublet","name":"Xoublet","kind":"tool","layer":"core","categories":["doublets"],"side":"subtractive","tier":"published-unbenchmarked","summary":"Scrublet-like doublet scoring with a hierarchical tree for fast neighbour search, built for atlas-scale data","gain":"2,479,674 HeartMap profiles scored in 574.8 s and 4.14 GiB peak memory against 1060.6 s and 22.81 GiB for the Scrublet core (self-reported)","gain_source":"self-reported","requires":["filtered-matrix"],"caveats":"Its own paper reports accuracy similar to Scrublet on cell-line hashing data but less discriminative on human-mouse and PBMC benchmarks.","doi":"10.1177/15578666261489802","pmid":"42781809","cite_title":"Xoublet: An Extreme-Scale Doublet Detection Algorithm for Cardiac Single-Cell Transcriptomics","year":"2026","verified":true,"citation_check":"verified","publication":"doi:10.1177/15578666261489802","publication_url":"https://doi.org/10.1177/15578666261489802","publication_title":"Xoublet: An Extreme-Scale Doublet Detection Algorithm for Cardiac Single-Cell Transcriptomics","publication_venue":"Journal of Computational Biology","citations":0,"review":"12-doublets-stress-batch#xoublet","tags":["scalability","atlas"]}];
